// Buf — a growable byte buffer.
//
// Shared because `gzip` and `json` had written the same type twice. It exists as
// a package rather than a copy per consumer for the reason the monorepo exists:
// wac has no generics, so a container cannot be written once over its element
// type, but it can at least be written once over `u8`.
//
// Capacity doubles, so appending n bytes is amortised O(n).
//
// Shape notes, because they are load-bearing rather than stylistic:
//
//   `len` is a public field, not a method. It is read once per pushed byte in
//   gzip's inner loops, and a method call there is measurable.
//
//   `reserve()` takes no argument and only checks for one byte. That keeps the
//   common `push` path to a single comparison. Bulk appends use `reserveFor(n)`
//   so they grow once instead of doubling repeatedly.

export struct Buf {
  u8[] data;
  i32 len;

  Buf create() {
    return Buf(u8[16](), 0);
  }

  /**
   * A buffer pre-sized to `capacity`.
   *
   * Worth it when the final length is known up front — inflate reads it from the
   * gzip trailer — because it skips the doubling reallocations *and* lets `take`
   * hand back the array without a copy.
   */
  Buf withCapacity(i32 capacity) {
    if (capacity < 16) { capacity = 16; }
    return Buf(u8[capacity](), 0);
  }

  i32 get(const this, i32 i) {
    if (i < 0 || i >= this.len) { trap; }
    return this.data[i];
  }

  // Make room for at least one more byte.
  void reserve(this) {
    if (this.len < this.data.len()) { return; }
    // Doubling zero is zero, so the floor is load-bearing rather than defensive:
    // without it an empty buffer grows to nothing and the store below goes out of
    // bounds. Unreachable while every constructor started at 16, and reachable as
    // soon as `take` began leaving the buffer empty.
    i32 cap = this.data.len() * 2;
    if (cap < 16) { cap = 16; }
    u8[] next = u8[cap]();
    next.copyFrom(this.data, 0, 0, this.len);
    this.data = next;
  }

  /**
   * Make room for at least `extra` more bytes, growing once.
   *
   * Repeated `push` would reach the same capacity through a series of doublings,
   * each copying everything written so far.
   */
  /**
   * Make room for `extra` more bytes.
   *
   * **The arithmetic is i64.** In i32 both halves wrapped: `this.len + extra` past the ceiling went
   * negative, `need <= data.len()` was then true and the buffer silently did not grow; and once the
   * doubling passed the ceiling `cap` went negative too, so `while (cap < need)` doubled a negative
   * number for ever. A hang and a silent under-allocation from the same two lines.
   *
   * A `need` beyond what an array can hold is impossible rather than merely large — an array's
   * length is an i32 — so the request is made at that ceiling and the allocation refuses it. That
   * is the honest end of the path: better a trap saying the array is too large than a buffer that
   * quietly did not grow.
   */
  void reserveFor(this, i32 extra) {
    i64 need = (this.len as i64) + (extra as i64);
    if (need <= (this.data.len() as i64)) { return; }
    i64 cap = (this.data.len() as i64) * 2;
    if (cap < 16) { cap = 16; }
    while (cap < need) { cap = cap * 2; }
    if (cap > 2147483647) { cap = 2147483647; }
    u8[] next = u8[cap as! i32]();
    next.copyFrom(this.data, 0, 0, this.len);
    this.data = next;
  }

  void push(this, i32 v) {
    this.reserve();
    this.data[this.len] = v;
    this.len++;
  }

  // gzip and DEFLATE are little-endian throughout.
  // Unsigned, because a header field is a bit pattern rather than a magnitude.
  // `>>` is the logical shift on an unsigned type, so no `>>>` is needed.
  void pushU16(this, u32 v) {
    this.push((v & 0xFF) as@ i32);
    this.push(((v >> 8) & 0xFF) as@ i32);
  }

  void pushU32(this, u32 v) {
    this.push((v & 0xFF) as@ i32);
    this.push(((v >> 8) & 0xFF) as@ i32);
    this.push(((v >> 16) & 0xFF) as@ i32);
    this.push(((v >> 24) & 0xFF) as@ i32);
  }

  // `start`, not `from` — `from` is a keyword (import ... from "...").
  void pushBytes(this, u8[] src, i32 start, i32 count) {
    this.reserveFor(count);
    this.data.copyFrom(src, start, this.len, count);
    this.len += count;
  }

  /** The whole of `src`. */
  void pushAll(this, u8[] src) {
    this.pushBytes(src, 0, src.len());
  }

  /**
   * Append a Unicode scalar as UTF-8.
   *
   * Callers must have resolved surrogate pairs already — a lone surrogate has no
   * UTF-8 form. Kept here rather than in `json` because the encoding is a
   * property of UTF-8, not of JSON.
   */
  /**
   * Append one code point as UTF-8.
   *
   * **Anything that is not a Unicode scalar becomes U+FFFD**: negative, above U+10FFFF, or in the
   * surrogate range D800..DFFF, which UTF-8 cannot encode at all. It used to encode them anyway —
   * `0x110000` produced a five-byte-shaped sequence and a surrogate produced the CESU-8 form that
   * strict decoders reject — so a `Buf` could end up holding bytes that are not text. Replacing is
   * what encoders conventionally do, and it keeps this method's promise that what it appends is
   * valid UTF-8; a caller that wants to know can check the value first.
   */
  void pushCodepoint(this, i32 cp0) {
    i32 cp = (cp0 < 0 || cp0 > 0x10FFFF || (cp0 >= 0xD800 && cp0 <= 0xDFFF)) ? 0xFFFD : cp0;
    if (cp < 0x80) {
      this.push(cp);
    } else if (cp < 0x800) {
      this.push(0xC0 | (cp >> 6));
      this.push(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
      this.push(0xE0 | (cp >> 12));
      this.push(0x80 | ((cp >> 6) & 0x3F));
      this.push(0x80 | (cp & 0x3F));
    } else {
      this.push(0xF0 | (cp >> 18));
      this.push(0x80 | ((cp >> 12) & 0x3F));
      this.push(0x80 | ((cp >> 6) & 0x3F));
      this.push(0x80 | (cp & 0x3F));
    }
  }

  /**
   * Hand over the contents, avoiding the copy when the buffer is exactly full.
   *
   * The returned array is the buffer's own storage in that case, so the Buf must not
   * be used afterwards. That is why this is separate from `bytes()`: callers that
   * keep appending need the copy.
   *
   * The buffer is emptied to enforce it. Without that, a caller who kept pushing
   * would be writing through a value it had already handed away, and nothing would
   * say so — the array it returned would change under its new owner. Reusing a taken
   * Buf now traps on the next `get`, and pushes land in fresh storage.
   */
  u8[] take(this) {
    if (this.len == this.data.len()) {
      u8[] out = this.data;
      this.data = u8[0]();
      this.len = 0;
      return out;
    }
    // The copy path has to empty the buffer too. It did not, so `take` kept its contents
    // whenever the buffer was not exactly full — which is almost always — and the next push
    // appended to bytes the caller thought it had handed away. Nothing here notices, because
    // every caller in this repo used to take once and drop the Buf; `packages/url` reuses one
    // across a parse and got its scheme glued to the front of its path.
    u8[] out = this.bytes();
    this.data = u8[0]();
    this.len = 0;
    return out;
  }

  /**
   * Copy `count` bytes from position `at` to the end of the buffer.
   *
   * For a back-reference: LZ77 and its descendants encode a run as a match that overlaps what it
   * is writing, so a copy of five bytes from three back is a legitimate way to spell a repeating
   * triple. Byte at a time for exactly that reason — a bulk move would read the source before the
   * loop had written it.
   *
   * The point is the call, not the loop: a decoder that writes `push(get(i))` per byte pays two
   * calls for every byte of every match, which measured as a third of zstd's decode time here.
   */
  void pushRepeat(this, i32 at, i32 count) {
    // Only the *start* has to be inside what is written. A copy may run past the old end, and
    // routinely does — that is what an overlapping match is — because the read index trails the
    // write index by a fixed distance and every byte it reads was written earlier in this loop.
    // Requiring `at + count` to fit would refuse every run, which is most of what this is for.
    if (count < 0 || at < 0) { trap; }
    if (count > 0 && at >= this.len) { trap; }
    this.reserveFor(count);
    i32 to = this.len;

    // `copyFrom` moves like `memmove`, which is right for a copy whose ranges do not overlap and
    // *wrong* for one whose do: a run wants the bytes this loop is writing, not the ones that
    // were there before. So the bulk instruction is used exactly when the source ends before the
    // destination begins, and the loop stays for the overlapping case it exists to serve.
    if (at + count <= to) {
      this.data.copyFrom(this.data, at, to, count);
    } else {
      u8[] d = this.data;
      for (i32 k = 0; k < count; k++) {
        d[to + k] = d[at + k];
      }
    }
    this.len = to + count;
  }

  /**
   * Discard the first `n` bytes and shift the rest to the front.
   *
   * For a sliding window: a decoder that has emitted the front of its output still needs the
   * tail addressable for back-references, and needs the buffer to stop growing. Shifts in
   * place rather than reallocating, because bounding what is held is the whole point.
   *
   * Indices move. A caller holding absolute positions has to track how much has been
   * dropped — `Window` in `packages/gzip/src/inflate.wac` is the worked example.
   */
  void dropFront(this, i32 n) {
    if (n <= 0) { return; }
    if (n >= this.len) { this.len = 0; return; }
    // A self-copy towards the front, which `copyFrom` handles: it moves like `memmove`, so the
    // source is read before it is overwritten.
    i32 keep = this.len - n;
    this.data.copyFrom(this.data, n, 0, keep);
    this.len = keep;
  }

  // Exact-length copy — the internal array is over-allocated.
  u8[] bytes(const this) {
    u8[] out = u8[this.len]();
    out.copyFrom(this.data, 0, 0, this.len);
    return out;
  }

  /** The contents as a string, taking them to be UTF-8. */
  string toStr(const this) {
    return string.fromBytes(this.bytes());
  }
}
// The wacc entry points that cross the JavaScript boundary.
//
// Everything else in this package traffics in structs and sum types, which bindgen
// cannot marshal — and should not, since an AST is not a value to hand across a
// boundary. So the surface is bytes in, text out: the caller passes source and gets
// the canonical dump that `test/parse.test.ts` compares against the reference.

import { lex, Lexed, tokenStride } from "./lex.wac";
import { checkMessage, lexMessage, parseMessage, warnMessage, hintFor, parseHintFor } from "./diag.wac";
import { P, parseProgram } from "./parse.wac";
import { Program, Ty } from "./ast.wac";
import { Pr, printProgram } from "./print.wac";
import { C, checkModule, checkProgram, declareModule, errorsOf, notesOf, warningsOf, widthsOf,
         errNoSuchExport } from "./check.wac";
import { emitModule, emitBlocked, emitNames, emitLinked, emitLinkedChecked, emitLinkedCovered,
         emitLinkedTraced, emitLinkedTracedSlots, traceTableLinked,
         covTableLinked, exportSigsLinked, bindTypesLinked, blockedLinked, namesLinked,
         describeLinked, describeSep, buildLinked, Built,
         sourceOf, tokenTextOf, resolveImport, numText, coreSource,
         emitDeclineLinked, lambdaReportLinked } from "./emit.wac";
import { manifestOf, withManifestSection } from "./manifest.wac";
import { renderDiagnostics } from "./render.wac";
import { importSpecs, resolveFrom } from "./files.wac";
import { bindgenDeclined, bindgenOf } from "./bindgen.wac";

/** Lex, parse, and render the AST in canonical form. */
export string dump(u8[] src) {
  Lexed lexed = lex(src);
  P p = P.create(src, lexed.tokens, lexed.tokenCount);
  Program prog = parseProgram(p);
  Pr w = Pr.create(src, lexed.tokens, lexed.tokenCount);
  return printProgram(w, prog);
}

/**
 * The parser's errors, as (code, line, col) triples.
 *
 * Separate from `dump` because a caller comparing ASTs and a caller comparing
 * diagnostics want different things, and returning both would mean a struct.
 */
/**
 * The **parser's** errors alone, with the lexer's left out.
 *
 * `dumpErrors` is the front end's answer — what a caller asking *is this a program?* wants, and
 * lexical errors belong in it. This one exists for the instrument next to it: `parse_errors.test.ts`
 * compares this parser against the reference's parser, and asserts of every code that some `perr*`
 * constant declares it. The lexer's codes are a space of their own (1–7), so mixing them in makes a
 * parser instrument fail on a lexer's answer.
 */
export i32[] dumpParseErrors(u8[] src) {
  Lexed lexed = lex(src);
  P p = P.create(src, lexed.tokens, lexed.tokenCount);
  parseProgram(p);
  i32[] out = i32[p.errorCount * 3]();
  for (i32 i = 0; i < p.errorCount * 3; i++) { out[i] = p.errors[i]; }
  return out;
}

export i32[] dumpErrors(u8[] src) {
  Lexed lexed = lex(src);
  P p = P.create(src, lexed.tokens, lexed.tokenCount);
  parseProgram(p);
  // **The lexer's errors are errors too**, and this function dropped them. An unterminated block
  // comment, an unterminated string, an unknown escape and an unterminated character literal were
  // all found by `lex` and then thrown away with the `Lexed` that held them — no caller of this
  // package could see one, because every caller comes through here. They go first: a lexical
  // complaint is about text the parser never got to see. `spec/cases/0081`.
  i32 lexCount = lexed.errorCount * 3;
  i32[] out = i32[lexCount + p.errorCount * 3]();
  for (i32 i = 0; i < lexCount; i++) { out[i] = lexed.errors[i]; }
  for (i32 i = 0; i < p.errorCount * 3; i++) { out[lexCount + i] = p.errors[i]; }
  return out;
}

/**
 * The type checker's diagnostics, as `(code, line, col)` triples — rung 3's oracle surface.
 *
 * The same shape `dumpErrors` returns for the parser, and for the same reason: our side reports
 * numeric codes and the reference reports English, so the comparison is by code, order and position.
 */
export i32[] dumpTypeErrors(u8[] src) {
  Lexed lexed = lex(src);
  P p = P.create(src, lexed.tokens, lexed.tokenCount);
  Program prog = parseProgram(p);
  return checkProgram(src, lexed.tokens, lexed.tokenCount, prog);
}

/**
 * Rung 4's surface: a wasm module for the program, as bytes.
 *
 * Bytes out rather than a structure, for the same reason everything else here is bytes in — and
 * because the oracle for this rung is that the caller can *run* what comes back.
 */
export u8[] emit(u8[] src) {
  return emitModule(src);
}

/** Why a module was not emitted in full — the feature that stopped it, or `""`. */
export string blocked(u8[] src) {
  return emitBlocked(src);
}

/** The emitted functions in order, so a wasm "function #N" can be turned back into a name. */
export string names(u8[] src) {
  return emitNames(src);
}

/**
 * Rung 4 across files: one module for an entry and everything it imports.
 *
 * The file set comes from the caller because this compiler is a wasm module with no filesystem —
 * the same reason the reference takes a map of path to source rather than a directory. Passing more
 * files than the entry needs is fine; what is emitted is the closure, not the table.
 */
export u8[] emitFiles(string[] paths, string[] sources, string entry) {
  return emitLinked(paths, sources, entry);
}

/**
 * The same module with `--checked` arithmetic: `+`, `-` and `*` on an integer trap where the value
 * does not fit, instead of wrapping.
 *
 * A separate entry point rather than a parameter, because every existing caller wants the default
 * and the flag is the *build's* — whole-module, as the reference has it.
 */
export u8[] emitFilesChecked(string[] paths, string[] sources, string entry) {
  return emitLinkedChecked(paths, sources, entry);
}

/**
 * The same module instrumented for coverage: a counter per branch point, read through
 * `__cov_init()`, `__cov_len()` and `__cov_get(i)`.
 */
export u8[] emitFilesCovered(string[] paths, string[] sources, string entry) {
  return emitLinkedCovered(paths, sources, entry);
}

/**
 * The exported functions and their wac types: `name\tret\tparam,param` per line.
 *
 * The metadata half of bindgen — which functions a host may call and what they take — which only the
 * compiler can answer. `packages/wacc/tools/waccBindgen.ts` turns it into TypeScript.
 */
export string exportSigsFiles(string[] paths, string[] sources, string entry) {
  return exportSigsLinked(paths, sources, entry);
}

/** The structs and enums a host can hold — see `bindTypesLinked` for the shape. */
export string bindTypesFiles(string[] paths, string[] sources, string entry) {
  return bindTypesLinked(paths, sources, entry);
}

/**
 * `blockedFiles`, `exportSigsFiles` and `bindTypesFiles` in one answer, separated by
 * `describeSep()`.
 *
 * A build wants both and used to ask twice, and each ask rebuilt the entire front end — link, lex,
 * parse, and the `settleEmittable` fixed point over every declaration. `issues/lang/0129`.
 */
export string describeFiles(string[] paths, string[] sources, string entry) {
  return describeLinked(paths, sources, entry);
}

/**
 * The module and its description in one answer — one front end for the whole build.
 * `issues/lang/0129`.
 */
export Built buildFiles(string[] paths, string[] sources, string entry) {
  return buildLinked(paths, sources, entry);
}

/** The line `describeFiles` puts between its two halves. */
export string describeSeparator() { return describeSep(); }

/**
 * The manifest a native host reads, as JSON — `packages/platform/native.ts` in wac.
 *
 * The module is a parameter rather than something this emits, because the caller building an
 * application wants both and compiling twice to answer one question is the kind of thing that makes
 * a self-hosted build slower than the one it replaces. `grants` is the bitmask `platform.wac` uses:
 * 1 read, 2 write, 4 net, 8 env.
 */
export string manifestFiles(u8[] wasm, string[] paths, string[] sources, string entry,
                            string wasmName, i32 grants) {
  return manifestOf(wasm, bindTypesLinked(paths, sources, entry),
                    exportSigsLinked(paths, sources, entry), entry, wasmName, grants);
}

/**
 * The glue a host calls this module through — `packages/wacc/tools/waccBindgen.ts` in wac.
 *
 * `lang` is `"ts"` or `"js"`. The module is a parameter for the same reason `manifestFiles` takes
 * one: the caller building an application wants both, and compiling twice to answer one question is
 * what makes a self-hosted build slower than the one it replaces.
 */
export string bindgenFiles(u8[] wasm, string[] paths, string[] sources, string entry, string lang) {
  return bindgenOf(wasm, exportSigsLinked(paths, sources, entry),
                   bindTypesLinked(paths, sources, entry), lang, false);
}

/** What bindgen could not write glue for, one `name(params) -> ret` per line. */
export string bindgenDeclinedFiles(string[] paths, string[] sources, string entry) {
  return bindgenDeclined(exportSigsLinked(paths, sources, entry),
                         bindTypesLinked(paths, sources, entry));
}

/** The module with its manifest inside it, which is what makes it one artefact rather than two. */
export u8[] emitFilesSelfDescribing(string[] paths, string[] sources, string entry,
                                    string wasmName, i32 grants) {
  u8[] wasm = emitLinked(paths, sources, entry);
  return withManifestSection(wasm, manifestFiles(wasm, paths, sources, entry, wasmName, grants));
}

/** What each counter is: `index\tline\tcol\tkind` per line, in counter order. */
export string covTableFiles(string[] paths, string[] sources, string entry) {
  return covTableLinked(paths, sources, entry);
}

/**
 * The same module instrumented for a *trace* rather than for coverage — `harness/ctTrace.ts`.
 *
 * Read through the same three accessors, because a consumer written against one compiler should
 * work against the other: `__cov_init()` clears the journal, `__cov_len()` is its capacity, and
 * `__cov_get(i)` reads a slot. Slot 0 is the cursor and events follow in `(site, value)` pairs.
 */
export u8[] emitFilesTraced(string[] paths, string[] sources, string entry) {
  return emitLinkedTraced(paths, sources, entry);
}

/**
 * The same with the journal sized by the caller: `slots` i32s, or 0 for the default 2^22.
 *
 * The last slot counts events whether or not there was room for them, so a run that overflows says
 * how large it needed to be — `__cov_get(__cov_len() - 1)`. `issues/lang/0059`.
 */
export u8[] emitFilesTracedSlots(string[] paths, string[] sources, string entry, i32 slots) {
  return emitLinkedTracedSlots(paths, sources, entry, slots);
}

/** What each *trace* point is, including the `index` ones a counter build does not have. */
export string traceTableFiles(string[] paths, string[] sources, string entry) {
  return traceTableLinked(paths, sources, entry);
}

/** Why a linked module was not emitted in full, or `""`. */
export string blockedFiles(string[] paths, string[] sources, string entry) {
  return blockedLinked(paths, sources, entry);
}

/**
 * Why the **emit** path gave up — the question `blockedFiles` cannot answer.
 *
 * The two walk different `Env`s, so a decline raised during emission reaches `blockedFiles` only as
 * the fallback "a type this emitter names only while emitting", whatever the real cause was. That
 * message cost four wrong guesses in a row while landing `design/lang/0002` tier two.
 *
 * `emitDeclineLinked` was written then, to end that — and was reachable only from inside `emit.wac`,
 * so the first program to hit the fallback message afterwards (`packages/platform`\'s substitute
 * capabilities) got the useless sentence again. An instrument nothing can call is not an instrument.
 */
export string emitDeclineFiles(string[] paths, string[] sources, string entry) {
  return emitDeclineLinked(paths, sources, entry);
}

/**
 * Every lambda the walk recorded: where it is, which instantiation it belongs to, its signature and
 * what it captures.
 *
 * The same reasoning as `emitDeclineFiles` — it existed and was reachable only from inside
 * `emit.wac`, so the first thing it would have explained had to be diagnosed without it twice.
 */
export string lambdaReportFiles(string[] paths, string[] sources, string entry) {
  return lambdaReportLinked(paths, sources, entry);
}

/** The emitted functions of a linked program, in order, so a wasm "function #N" has a name. */
export string namesFiles(string[] paths, string[] sources, string entry) {
  return namesLinked(paths, sources, entry);
}

/**
 * The type checker's diagnostics for one file **with the names it imports in scope**.
 *
 * Every diagnostic missed on this repository's own code — thirty-eight of thirty-eight — was in a
 * file that imports something, and none was in a file that does not. A checker given one file cannot
 * know what `Buf.create` takes or whether a `Node` has the field being read, and says nothing about
 * either. That is a ceiling rather than a rule, and this is the way through it.
 *
 * **Exactly the names the file asked for.** Letting an import contribute everything it declares put
 * another file's `Rng` in front of this file's — every table here is keyed by a bare name and the
 * first declaration wins — and reported forty working files. `import { X } from "…"` says which
 * names cross, so that list is the filter, and a name the file did not ask for cannot shadow one it
 * declares itself.
 */
/**
 * Does this file declare and export `name` under its own roof?
 *
 * An `Import` decl never answers yes, which is the whole of `§wac-no-reexport-f7kn4wq`: a file that
 * merely imports a symbol does not pass it on, and the fix is to import it from the file that
 * declares it. An exported enum answers for its variants as well as its own name, because a variant
 * imports like any other name (`§wac-type-name-scope-8vqk3mn`) — a check that missed that would
 * refuse most of the repository rather than find anything wrong with it.
 */
bool exportsName(u8[] src, Lexed lexed, Program prog, string name) {
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (exported && tokenTextOf(src, lexed, nameTok) == name) { return true; }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (exported && tokenTextOf(src, lexed, nameTok) == name) { return true; }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (exported) {
          if (tokenTextOf(src, lexed, nameTok) == name) { return true; }
          for (i32 v = 0; v < variants.len(); v++) {
            if (tokenTextOf(src, lexed, variants[v].nameTok) == name) { return true; }
          }
        }
      }
      case ConstDecl(nameTok, type, init, exported): {
        if (exported && tokenTextOf(src, lexed, nameTok) == name) { return true; }
      }
      else: { }
    }
  }
  return false;
}

/**
 * Every diagnostic for an import graph, as text: one per line, `file\tline\tcol\tphase\tmessage`.
 *
 * Tab-separated because the boundary carries strings and not structures, and a caller that has to
 * parse something should parse the dullest thing available. `spec/spec/errors.md` asks for `span`,
 * `annotation` and `hint` as well; none of them can be filled from what `report` records, which is a
 * code and a position. That is the next thing to build rather than something to invent here.
 *
 * The parse phase answers first and alone: a file the parser could not read has no type errors worth
 * reporting, only the ones its unreadable shape would invent.
 */
/**
 * Every file's diagnostics, not just the entry's.
 *
 * `checkFiles` walks **only the entry's bodies** — every imported file contributes its signatures and
 * nothing else — so `export i32 helper() { return "x"; }` in an imported file is silent, and the
 * emitter then compiles it into a module that fails validation with a wasm-level type mismatch
 * instead of a source line. `issues/lang/0118`.
 *
 * Each file is checked *as an entry*, which is what makes this correct rather than approximate: a
 * file gets exactly the scope it would get if you named it on the command line, its own private
 * declarations included. The cost is a whole-graph parse per file — 0.9s for wacc's own 13, 9.9s for
 * box's 179 — which is why this is what `check` calls and `diagnoseFiles` is what a build calls. The
 * issue records the measurement and what it would take to make both affordable.
 */
export string diagnoseGraph(string[] paths, string[] sources, string entry) {
  string out = "";
  // **Counted once for the whole graph.** Every closure below overlaps almost every other, so
  // letting each one size its own tables parsed a widely-imported file once per importer — 54% of
  // what this call cost, measured. `issues/lang/0133`.
  Lexed?[] lexes = Lexed?[paths.len() + 1]();
  Program?[] progs = Program?[paths.len() + 1]();
  i32[] counts = declCountsInto(paths, sources, lexes, progs);
  for (i32 i = 0; i < paths.len(); i++) {
    // **Each file is checked against its own closure, not against the whole list.** Handing
    // `checkFilesWith` 179 files to check one that imports three is the whole of why the naive
    // loop costs `n ×` a full parse. Nothing is lost: a file cannot be affected by a file it does
    // not reach.
    string[] seen = string[paths.len()](fill: "");
    i32 n = closureOf(paths, sources, paths[i], seen);
    string[] subPaths = string[n](fill: "");
    string[] subSources = string[n](fill: "");
    // One longer than the closure: `checkFilesWith` keeps `core`'s count in the last slot.
    i32[] subCounts = i32[n + 1]();
    Lexed?[] subLexes = Lexed?[n + 1]();
    Program?[] subProgs = Program?[n + 1]();
    for (i32 k = 0; k < n; k++) {
      // One scan for both. `sourceAt` and `countAt` each walked every path looking for the same
      // name, on the same line — the second was mine and it doubled a lookup that is already
      // O(files) inside a loop over files.
      i32 at = indexOfPath(paths, seen[k]);
      subPaths[k] = seen[k];
      subSources[k] = at >= 0 && at < sources.len() ? sources[at] : "";
      subCounts[k] = at >= 0 && at < counts.len() ? counts[at] : 0;
      subLexes[k] = at >= 0 && at < lexes.len() ? lexes[at] : null;
      subProgs[k] = at >= 0 && at < progs.len() ? progs[at] : null;
    }
    subCounts[n] = counts[paths.len()];
    subLexes[n] = lexes[paths.len()];
    subProgs[n] = progs[paths.len()];
    out = out + diagnoseFilesWith(subPaths, subSources, paths[i], subCounts, subLexes, subProgs);
  }
  return out;
}

/** Where `path` sits in `paths`, or -1. */
i32 indexOfPath(string[] paths, string path) {
  for (i32 i = 0; i < paths.len(); i++) {
    if (paths[i] == path) { return i; }
  }
  return -1;
}

/** What `path` was given as, or "". */
string sourceAt(string[] paths, string[] sources, string path) {
  for (i32 i = 0; i < paths.len(); i++) {
    if (paths[i] == path) { return i < sources.len() ? sources[i] : ""; }
  }
  return "";
}

/**
 * The files `entry` reaches, itself first, into `seen` — and how many there are.
 *
 * `seen` is the caller's because an array is sized where it is made, and the caller already has the
 * only bound that matters: no closure is larger than the graph. A path this graph does not contain
 * is skipped rather than guessed at — a missing file is the caller's to report, and
 * `example/wacc.wac` does, by name, before anything here is asked.
 */
i32 closureOf(string[] paths, string[] sources, string entry, string[] seen) {
  i32 n = 0;
  seen[0] = entry;
  n = 1;
  i32 at = 0;
  while (at < n) {
    string path = seen[at];
    string[] specs = importSpecs(sourceAt(paths, sources, path).toBytes());
    for (i32 s = 0; s < specs.len(); s++) {
      string next = resolveFrom(path, specs[s]);
      bool known = false;
      for (i32 i = 0; i < paths.len(); i++) { if (paths[i] == next) { known = true; } }
      if (!known) { continue; }
      bool have = false;
      for (i32 k = 0; k < n; k++) { if (seen[k] == next) { have = true; } }
      if (have || n >= seen.len()) { continue; }
      seen[n] = next;
      n = n + 1;
    }
    at = at + 1;
  }
  return n;
}

/** The whole graph's diagnostics, laid out for a person. What `example/wacc.wac` prints. */
export string diagnoseGraphRendered(string[] paths, string[] sources, string entry) {
  return renderDiagnostics(diagnoseGraph(paths, sources, entry), paths, sources);
}

/**
 * Whether a wire holds anything that is **not** a warning.
 *
 * For a caller that has to decide whether a compile failed. `diagnoseGraphRendered` used to filter
 * warnings out, so that a caller deciding on the string's emptiness could not be handed one — which
 * protected `example/wacc.wac` at the cost of that binary never printing a warning at all. It asks
 * this instead now, so the filter is gone and both reach the reader.
 *
 * Field 3 is the phase, found by counting tabs: this file has no split, and a warning line is
 * otherwise indistinguishable from an error's.
 */
export bool wireHasErrors(string wire) {
  i32 from = 0;
  for (i32 i = 0; i <= wire.len(); i++) {
    if (i < wire.len() && wire[i] != "\n") { continue; }
    string line = wire.slice(from, i);
    from = i + 1;
    if (line == "") { continue; }
    // Severity is the last field, so this is a suffix test rather than a walk to the ninth tab.
    bool warn = line.len() >= 8 && line.slice(line.len() - 8, line.len()) == "\twarning";
    if (!warn) { return true; }
  }
  return false;
}



/**
 * The same diagnostics, laid out for a person — `src/render.wac`, and what `waccx` prints.
 *
 * The wire is for a program and this is for a reader, and a compiler that only answers the first is
 * usable exactly where nothing is wrong. `example/wacc.wac` prints this.
 */
export string diagnoseFilesRendered(string[] paths, string[] sources, string entry) {
  return renderDiagnostics(diagnoseFiles(paths, sources, entry), paths, sources);
}

export string diagnoseFiles(string[] paths, string[] sources, string entry) {
  Lexed?[] lexes = Lexed?[paths.len() + 1]();
  Program?[] progs = Program?[paths.len() + 1]();
  i32[] counts = declCountsInto(paths, sources, lexes, progs);
  return diagnoseFilesWith(paths, sources, entry, counts, lexes, progs);
}

/** The same, with the declaration counts already taken — see `declCountsOf`. */
string diagnoseFilesWith(string[] paths, string[] sources, string entry, i32[] counts,
                         Lexed?[] lexes, Program?[] progs) {
  string out = "";
  bool parseFailed = false;
  for (i32 i = 0; i < paths.len(); i++) {
    u8[] src = sources[i].toBytes();
    Lexed lexed = lex(src);
    P p = P.create(src, lexed.tokens, lexed.tokenCount);
    parseProgram(p);
    // A lexical complaint names its own phase — the reference has four (`lex`, `parse`, `resolve`,
    // `typecheck`) and this package emitted two, because it never had a lex error to emit.
    for (i32 e = 0; e < lexed.errorCount; e++) {
      out = out + paths[i] + "\t" + numText(lexed.errors[e * 3 + 1]) + "\t"
          + numText(lexed.errors[e * 3 + 2]) + "\tlex\t" + lexMessage(lexed.errors[e * 3])
          + "\t\t\t1\n";
      parseFailed = true;
    }
    for (i32 e = 0; e < p.errorCount; e++) {
      string note = e < p.errorNotes.len() ? p.errorNotes[e] : "";
      // The span is the token the parser stopped on. A checker diagnostic has no width to give — it
      // reports at an expression, and nothing records how far that expression ran.
      i32 width = p.errorWidths[e];
      out = out + paths[i] + "\t" + numText(p.errors[e * 3 + 1]) + "\t" + numText(p.errors[e * 3 + 2])
          + "\tparse\t" + parseMessage(p.errors[e * 3]) + "\t" + note + "\t"
          + parseHintFor(p.errors[e * 3]) + "\t" + numText(width) + "\n";
      parseFailed = true;
    }
  }
  if (parseFailed) { return out; }

  C c = checkFilesWith(paths, sources, entry, counts, lexes, progs);
  i32[] terrs = errorsOf(c);
  string[] notes = notesOf(c);
  // **Zero where nothing measured it.** A width of one is a claim — that the diagnostic really is
  // one character wide, as it is for `;` — and the checker only knows that where it reported at a
  // token. The renderer reads a zero as one; a *measurement* of how many diagnostics carry a real
  // span must be able to tell the two apart.
  i32[] widths = widthsOf(c);
  for (i32 e = 0; e + 2 < terrs.len(); e = e + 3) {
    string note = e / 3 < notes.len() ? notes[e / 3] : "";
    i32 w = e / 3 < widths.len() ? widths[e / 3] : 0;
    out = out + entry + "\t" + numText(terrs[e + 1]) + "\t" + numText(terrs[e + 2])
        + "\tcheck\t" + checkMessage(terrs[e]) + "\t" + note + "\t" + hintFor(terrs[e])
        + "\t" + numText(w) + "\n";
  }
  // **Warnings after the errors, with a severity in a field of its own.**
  //
  // A ninth field rather than a fourth `phase` value, which is what this did first: `spec/spec/
  // errors.md` gives a diagnostic a `severity` *and* a `phase`, and they are different questions — a
  // warning found while type-checking is `check` and `warning`, and overloading the phase leaves a
  // parse-time warning unable to say either thing truthfully. Additive, since a consumer that splits
  // on tabs reads an absent ninth field as empty, which is what an error has.
  //
  // What must not happen is a warning reaching a *count* that decides whether a compile succeeded,
  // which is why it has its own table and its own loop rather than a column on the errors.
  // `issues/lang/0126`.
  i32[] warns = warningsOf(c);
  for (i32 w2 = 0; w2 + 2 < warns.len(); w2 = w2 + 3) {
    out = out + entry + "\t" + numText(warns[w2 + 1]) + "\t" + numText(warns[w2 + 2])
        + "\tcheck\t" + warnMessage(warns[w2]) + "\t\t\t0\twarning\n";
  }
  return out;
}

export i32[] dumpTypeErrorsFiles(string[] paths, string[] sources, string entry) {
  return errorsOf(checkFiles(paths, sources, entry));
}

/** The checker, run over an import graph, with its tables still in hand for whatever wants them. */
/**
 * How many rows a file will add to the checker's module-wide tables.
 *
 * One per declaration, plus what a struct or an enum brings with it: its fields, its methods, its
 * variants and each variant's payload. Counted from the parse rather than estimated from the text,
 * because the whole point of `issues/lang/0099` is that a guess in either direction is a defect —
 * too small overflows silently, too large costs hundreds of megabytes. The `+ 8` is slack for the
 * rows a declaration adds beside itself, like an enum's tag.
 */
i32 declarationsIn(u8[] src, Lexed lexed, Program prog) {
  i32 n = 8;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    n = n + 8;
    match (prog.decls[d].kind) {
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        n = n + fields.len() + methods.len() * 2 + typeParams.len();
        for (i32 m = 0; m < methods.len(); m++) { n = n + methods[m].params.len(); }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        n = n + variants.len() * 2 + methods.len() * 2 + typeParams.len();
        for (i32 v = 0; v < variants.len(); v++) { n = n + variants[v].fields.len(); }
        for (i32 m = 0; m < methods.len(); m++) { n = n + methods[m].params.len(); }
      }
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        n = n + params.len() + typeParams.len();
      }
      else: { }
    }
  }
  return n;
}

/** The name `core` resolves to: a file no caller supplies, which the compiler carries. */
string corePath() { return " core"; }

/** Every named type mentioned anywhere in a `Ty`, appended to `out` with `n[0]` as the count. */
void tyNames(u8[] src, Lexed lx, Ty t, string[] out, i32[] n) {
  match (t.kind) {
    case Named(tok, typeArgs): {
      if (n[0] < out.len()) {
        out[n[0]] = tokenTextOf(src, lx, tok);
        n[0] = n[0] + 1;
      }
      for (i32 i = 0; i < typeArgs.len(); i++) { tyNames(src, lx, typeArgs[i], out, n); }
    }
    case Arr(elem): { tyNames(src, lx, elem, out, n); }
    case Nullable(inner): { tyNames(src, lx, inner, out, n); }
    case Funcref(ret, params): {
      tyNames(src, lx, ret, out, n);
      for (i32 i = 0; i < params.len(); i++) { tyNames(src, lx, params[i], out, n); }
    }
    else: { }
  }
}

/** Whether `list`'s first `n` entries hold `name`. */
/**
 * Whether some file *other* than `selfIndex` also declares a type called `name`.
 *
 * **`selfIndex` rather than `self`**, which is what it was called: a wac parameter named `self` has
 * no wapy rendering, so `compiler/wapyRoundTrip.test.ts` refused this file — *"a parameter is written
 * `name: Type`"* — and the whole suite was red on it. `issues/lang/0077` is the underlying gap; this
 * is the two-line way around it, and the name is no worse for it.
 *
 * The question `issues/lang/0128`'s fix turns on. Renaming every type that reaches a file only
 * through a signature is wrong: `packages/tor` declares `Link` in `link.wac`, `bootstrap.wac` puts it
 * in `Session.link` without declaring it, and `hsfetch.wac` imports `fetchOverCircuit` without
 * importing `Link` — so a blanket rename gave the parameter a name the field did not have and
 * reported three working files. A name is only ambiguous when two files actually declare it.
 *
 * Reads the programs already parsed for the whole graph and **never parses one itself** — a file
 * whose program is absent is skipped rather than re-read, because this runs inside the loop over
 * imports and re-parsing there is what `issues/lang/0133` was about. Skipping is safe in the
 * direction that matters: it can only make this answer `false`, which leaves the name alone.
 */
bool typeDeclaredElsewhere(string[] paths, string[] sources, Lexed?[] lexes, Program?[] progs,
                           i32 selfIndex, string name) {
  for (i32 j = 0; j < paths.len(); j++) {
    if (j == selfIndex) { continue; }
    if (j >= progs.len() || (progs[j] is null)) { continue; }
    if (j >= lexes.len() || (lexes[j] is null)) { continue; }
    Program jp = progs[j]!;
    Lexed jlx = lexes[j]!;
    u8[] jsrc = sources[j].toBytes();
    for (i32 d = 0; d < jp.decls.len(); d++) {
      match (jp.decls[d].kind) {
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (tokenTextOf(jsrc, jlx, nameTok) == name) { return true; }
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (tokenTextOf(jsrc, jlx, nameTok) == name) { return true; }
        }
        else: { }
      }
    }
  }
  return false;
}

bool listHas(string[] list, i32 n, string name) {
  for (i32 i = 0; i < n; i++) {
    if (list[i] == name) { return true; }
  }
  return false;
}

/**
 * The names a file must declare so that what the entry asked for is fully typed.
 *
 * `only` is what the entry wrote in its import list, and that is not enough: a struct's field can
 * hold `fn[Pending<i32>()]`, so calling it answers a `Pending<i32>` in a file that never named
 * `Pending`. Undeclared, that type has no members — `.wait()` on it answers nothing and every rule
 * downstream goes quiet, which built a module the engine refused to load (`issues/lang/0132`).
 *
 * So the wanted set is closed over the *signatures* of what is wanted: field types, method return
 * types and method parameter types, transitively, and only over types this file itself declares.
 * Bodies are deliberately not walked — a local variable's type inside somebody else's method is not
 * something the entry can reach, and walking them would pull in most of a large module for nothing.
 *
 * The extras are returned after the originals so the caller can tell them apart: they are declared
 * for their members and must not enter the entry's scope as names.
 */
string[] closeOverSignatures(u8[] src, Lexed lx, Program prog, string[] only) {
  i32 cap = only.len();
  for (i32 d = 0; d < prog.decls.len(); d++) { cap = cap + 1; }
  string[] want = string[cap](fill: "");
  i32 n = 0;
  for (i32 i = 0; i < only.len() && n < cap; i++) {
    if (listHas(want, n, only[i])) { continue; }
    want[n] = only[i];
    n = n + 1;
  }

  // Names this file declares, so a signature mentioning `i32` or a type from a third module adds
  // nothing — this file could not declare those even if asked.
  string[] mine = string[prog.decls.len()](fill: "");
  i32 mn = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        mine[mn] = tokenTextOf(src, lx, nameTok);
        mn = mn + 1;
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        mine[mn] = tokenTextOf(src, lx, nameTok);
        mn = mn + 1;
      }
      else: { }
    }
  }

  // To a fixpoint: a reached type's own signature can reach further. Bounded by `cap`, and the loop
  // makes progress or stops, so the bound is a safety net rather than the thing that ends it.
  bool grew = true;
  while (grew) {
    grew = false;
    for (i32 d = 0; d < prog.decls.len(); d++) {
      string[] found = string[64](fill: "");
      i32[] seen = i32[1]();
      match (prog.decls[d].kind) {
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (!listHas(want, n, tokenTextOf(src, lx, nameTok))) { continue; }
          for (i32 i = 0; i < fields.len(); i++) { tyNames(src, lx, fields[i].type, found, seen); }
          for (i32 i = 0; i < methods.len(); i++) {
            tyNames(src, lx, methods[i].returnType, found, seen);
            for (i32 p = 0; p < methods[i].params.len(); p++) {
              tyNames(src, lx, methods[i].params[p].type, found, seen);
            }
          }
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (!listHas(want, n, tokenTextOf(src, lx, nameTok))) { continue; }
          for (i32 v = 0; v < variants.len(); v++) {
            for (i32 i = 0; i < variants[v].fields.len(); i++) {
              tyNames(src, lx, variants[v].fields[i].type, found, seen);
            }
          }
          for (i32 i = 0; i < methods.len(); i++) {
            tyNames(src, lx, methods[i].returnType, found, seen);
            for (i32 p = 0; p < methods[i].params.len(); p++) {
              tyNames(src, lx, methods[i].params[p].type, found, seen);
            }
          }
        }
        // **A function's signature reaches as far as a field's does.** `export Pending<i32> later()`
        // hands the caller a type it never named, exactly as `Cli`'s fields do — this arm was
        // missing from the first version of the fix, and the silence it left was identical.
        case Func(nameTok, returnType, params, body, exported, typeParams): {
          if (!listHas(want, n, tokenTextOf(src, lx, nameTok))) { continue; }
          tyNames(src, lx, returnType, found, seen);
          for (i32 p = 0; p < params.len(); p++) {
            tyNames(src, lx, params[p].type, found, seen);
          }
        }
        // A module-level `const`'s type, for the same reason and by the same reach.
        case ConstDecl(nameTok, type, init, exported): {
          if (!listHas(want, n, tokenTextOf(src, lx, nameTok))) { continue; }
          tyNames(src, lx, type, found, seen);
        }
        else: { continue; }
      }
      for (i32 i = 0; i < seen[0]; i++) {
        if (!listHas(mine, mn, found[i])) { continue; }
        if (listHas(want, n, found[i])) { continue; }
        if (n >= cap) { continue; }
        want[n] = found[i];
        n = n + 1;
        grew = true;
      }
    }
  }

  string[] out = string[n](fill: "");
  for (i32 i = 0; i < n; i++) { out[i] = want[i]; }
  return out;
}

/**
 * How many declarations each of `paths` contributes, plus `core`'s in a final slot.
 *
 * One parse per file. `checkFilesWith` sums these instead of parsing its closure to count them,
 * which is the whole of `issues/lang/0133`: `diagnoseGraph` checks every file against its own
 * closure, the closures overlap almost entirely, and so the sizing pass parsed a core file once for
 * every file that reached it. Counted here once for the whole graph instead.
 */
i32[] declCountsOf(string[] paths, string[] sources) {
  return declCountsInto(paths, sources, Lexed?[paths.len() + 1](), Program?[paths.len() + 1]());
}

/**
 * The same, keeping what it parsed.
 *
 * `checkFilesWith`'s second loop lexes and parses again for every file the entry wants a name from,
 * and across a graph that is the same file re-parsed once per importer — ~210 ms on
 * `packages/box`, 25% of `diagnoseGraph` (`issues/lang/0133`). These are the programs it needs.
 */
i32[] declCountsInto(string[] paths, string[] sources, Lexed?[] lexes, Program?[] progs) {
  i32[] counts = i32[paths.len() + 1]();
  for (i32 i = 0; i < paths.len(); i++) {
    u8[] csrc = (i < sources.len() ? sources[i] : "").toBytes();
    Lexed clexed = lex(csrc);
    P cp = P.create(csrc, clexed.tokens, clexed.tokenCount);
    Program cprog = parseProgram(cp);
    counts[i] = declarationsIn(csrc, clexed, cprog);
    if (i < lexes.len()) { lexes[i] = clexed; }
    if (i < progs.len()) { progs[i] = cprog; }
  }
  u8[] ksrc = coreSource().toBytes();
  Lexed klexed = lex(ksrc);
  P kp = P.create(ksrc, klexed.tokens, klexed.tokenCount);
  Program kprog = parseProgram(kp);
  counts[paths.len()] = declarationsIn(ksrc, klexed, kprog);
  if (paths.len() < lexes.len()) { lexes[paths.len()] = klexed; }
  if (paths.len() < progs.len()) { progs[paths.len()] = kprog; }
  return counts;
}

C checkFiles(string[] callerPaths, string[] callerSources, string entry) {
  Lexed?[] lexes = Lexed?[callerPaths.len() + 1]();
  Program?[] progs = Program?[callerPaths.len() + 1]();
  i32[] counts = declCountsInto(callerPaths, callerSources, lexes, progs);
  return checkFilesWith(callerPaths, callerSources, entry, counts, lexes, progs);
}

/** `counts` runs parallel to `callerPaths`, with `core`'s count in one extra slot at the end. */
C checkFilesWith(string[] callerPaths, string[] callerSources, string entry, i32[] counts,
                 Lexed?[] lexes, Program?[] progs) {
  // **`core` is a file, and the checker had never read it.** An import from `core` used to declare
  // each name as *unknown*, so a `Node` or a `Read` had no enum behind it — and every rule that asks
  // what an enum holds went quiet: a `match` missing a variant, an arm naming a variant that does
  // not exist, two arms for one variant, an `else` that nothing reaches. All four were silent for
  // the two types the compiler itself ships, and the emitter had core's source the whole time.
  // `issues/lang/0109`. Adding it here rather than in the checker keeps one answer to "what does
  // core declare": `coreSource`, which is also what the emitter compiles.
  string[] paths = string[callerPaths.len() + 1](fill: "");
  string[] sources = string[callerSources.len() + 1](fill: "");
  for (i32 i = 0; i < callerPaths.len(); i++) {
    paths[i] = callerPaths[i];
    sources[i] = i < callerSources.len() ? callerSources[i] : "";
  }
  paths[callerPaths.len()] = corePath();
  sources[callerSources.len()] = coreSource();

  u8[] esrc = sourceOf(paths, sources, entry).toBytes();
  Lexed elexed = lex(esrc);
  P ep = P.create(esrc, elexed.tokens, elexed.tokenCount);
  Program eprog = parseProgram(ep);
  // **Sized for what will go in it, and in the unit it goes in.** The tables here hold two kinds of
  // thing: the name table is per *function* and `clearScope` empties it between them, while structs,
  // fields, methods, variants and functions accumulate across every file the entry imports. So the
  // first is the entry's own token count — only its bodies are walked — and the second is a count of
  // the declarations each contributing file actually contributes.
  //
  // It was one number, and it was the entry's tokens; a small file with a large closure ran out of
  // room silently and answered *no such field* about correct code (`issues/lang/0098`). Sizing both
  // by the closure's *tokens* fixed that and cost 230 MB of peak resident set, because a token is
  // the wrong unit for a table of declarations (`issues/lang/0099`).
  i32 declCap = declarationsIn(esrc, elexed, eprog);
  // Summed, not parsed. The count has to stay exact — `C.create` allocates from it, and a loose
  // cap costs far more in allocation than any parse it saves (`issues/lang/0098`, `0099`, and a
  // measurement in `0133`: a fixed cap makes `diagnoseGraph` six times slower).
  for (i32 i = 0; i < paths.len(); i++) {
    if (paths[i] == entry) { continue; }
    declCap = declCap + (i < counts.len() ? counts[i] : 0);
  }
  C c = C.create(esrc, elexed.tokens, elexed.tokenCount, declCap);

  // **Which names, and from which file.** Filtering by name alone is not enough: `rlp.wac` exports a
  // `decode` and so does `codec/src/hex.wac`, and a closure holding both let the wrong one answer —
  // the entry asked `rlp.wac` for it. So each import is resolved to the path it names, and a file
  // contributes only what that file was asked for.
  string[] wantFrom = string[512]();
  string[] wantName = string[512]();
  // What this file calls it, which is the name it must be declared under — `Dup as DupB` brings in a
  // `DupB`, and two modules' `Dup` are two types rather than one that overwrote the other.
  string[] wantAlias = string[512]();
  // Where the *import* is written, taken here because the loop below retargets `c` at each imported
  // file in turn: a diagnostic about `main.wac`'s import must not carry `b.wac`'s line numbers.
  i32[] wantLine = i32[512]();
  i32[] wantCol = i32[512]();
  i32 n = 0;
  for (i32 d = 0; d < eprog.decls.len(); d++) {
    match (eprog.decls[d].kind) {
      case Import(pathTok, prefixTok, items): {
        // A bare `core` names the compiler's own file; everything else is a path beside this one.
        string quoted = tokenTextOf(esrc, elexed, pathTok);
        string target = pathTok < 0 || quoted.len() < 2
          ? corePath()
          : resolveImport(entry, quoted.slice(1, quoted.len() - 1));
        for (i32 i = 0; i < items.len(); i++) {
          if (n >= wantName.len()) { continue; }
          wantFrom[n] = target;
          wantName[n] = tokenTextOf(esrc, elexed, items[i].nameTok);
          wantAlias[n] = tokenTextOf(esrc, elexed, items[i].aliasTok);
          wantLine[n] = elexed.tokens[items[i].nameTok * tokenStride() + 3];
          wantCol[n] = elexed.tokens[items[i].nameTok * tokenStride() + 4];
          n = n + 1;
        }
      }
      else: { }
    }
  }

  for (i32 i = 0; i < paths.len(); i++) {
    if (paths[i] == entry) { continue; }
    i32 want = 0;
    for (i32 k = 0; k < n; k++) {
      if (wantFrom[k] == paths[i]) { want = want + 1; }
    }
    if (want == 0) { continue; }
    string[] only = string[want]();
    i32 at = 0;
    for (i32 k = 0; k < n; k++) {
      if (wantFrom[k] != paths[i]) { continue; }
      only[at] = wantName[k];
      at = at + 1;
    }
    // **Already parsed, once, for the whole graph.** Lexing and parsing here again is the same file
    // re-read once per importer — ~210 ms on `packages/box`, 25% of `diagnoseGraph`.
    // `issues/lang/0133`. Falls back when a caller supplied nothing.
    u8[] isrc = sources[i].toBytes();
    Lexed ilexed = i < lexes.len() && (lexes[i] is not null) ? lexes[i]! : lex(isrc);
    Program iprog = i < progs.len() && (progs[i] is not null)
      ? progs[i]!
      : parseProgram(P.create(isrc, ilexed.tokens, ilexed.tokenCount));
    // **A file's exports are its own to state.** Asked for a name it does not export, the import is
    // the error — whether the name is declared without `export` or merely imported from somewhere
    // else, which does not pass it on (`§wac-no-reexport-f7kn4wq`).
    for (i32 k = 0; k < n; k++) {
      if (wantFrom[k] != paths[i]) { continue; }
      if (!exportsName(isrc, ilexed, iprog, wantName[k])) {
        c.report(errNoSuchExport(), wantLine[k], wantCol[k]);
      }
    }

    c.src = isrc;
    c.toks = ilexed.tokens;
    c.renameCount = 0;
    for (i32 k = 0; k < n; k++) {
      if (wantFrom[k] != paths[i]) { continue; }
      if (wantAlias[k] != wantName[k]) { c.addRename(wantName[k], wantAlias[k]); }
    }
    // **Closed over what the wanted names reach**, so a type that arrives only through somebody
    // else's field signature still has its members. Everything past `only.len()` was added here
    // rather than asked for, so it is declared and *not* put in scope: writing its name stays the
    // error the reference reports. `issues/lang/0132`.
    string[] reach = closeOverSignatures(isrc, ilexed, iprog, only);
    // **A type that reached this file only through a signature is still its own type.**
    // `issues/lang/0128`. Every table in this checker is keyed by a bare name and the first
    // declaration of one wins, so two modules each exporting an `S` collapse into a single type the
    // moment neither is imported *by name*: `takesA(S)` and `makeB() -> S` both carry the string
    // `"S"`, they compare equal, nothing is reported, and the emitter — which does tell them apart —
    // writes a call that fails to validate with an index and no names in it.
    //
    // `spec/cases/0117` is the same two modules and works, because there both are imported *with
    // aliases*, and an alias is exactly a rename. So this synthesises the alias the program did not
    // write. `typeOfTy` already resolves every type name through `renamed`, which is what makes one
    // `addRename` reach the signatures as well as the declaration.
    //
    // Only this file's *own* declarations are renamed, which is also the reason a type shared through
    // a third module does not become two: `closeOverSignatures` adds a name only when the file
    // declares it, so a `Point` that a.wac merely imports is never in `reach` and is renamed once,
    // where it is declared.
    for (i32 d = 0; d < iprog.decls.len(); d++) {
      string tname = "";
      match (iprog.decls[d].kind) {
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          tname = tokenTextOf(isrc, ilexed, nameTok);
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          tname = tokenTextOf(isrc, ilexed, nameTok);
        }
        else: { }
      }
      if (tname == "") { continue; }
      // Asked for by name: the entry's own spelling wins, aliased or not, and renaming it here would
      // rename the thing the programmer wrote.
      if (listHas(only, only.len(), tname)) { continue; }
      if (!listHas(reach, reach.len(), tname)) { continue; }
      // **Only when the name is actually ambiguous.** One file declaring `Link` and three others
      // passing it around is the ordinary case, and renaming there gives a parameter a name the
      // field it is handed does not have — three working files in `packages/tor` reported that way.
      if (!typeDeclaredElsewhere(paths, sources, lexes, progs, i, tname)) { continue; }
      c.addRename(tname, tname + "#" + numText(i));
    }
    declareModule(c, iprog, reach);
    for (i32 k = only.len(); k < reach.len(); k++) {
      // **A name the entry imported is in scope, wherever it came from.** This list is global across
      // every imported file, so hiding by the current file's `only` alone marked a name that another
      // import brought in legitimately — one false alarm on `packages/sh`'s `Word` and two spec
      // cases about same-named structs in two modules. What may not be written is a name the entry
      // never asked anybody for; `wantAlias` is exactly that set, under the entry's own spelling.
      if (listHas(wantAlias, n, c.renamed(reach[k]))) { continue; }
      c.markUnnameable(c.renamed(reach[k]));
      // **An enum carries more than one name into scope.** Its variants are declared beside it and
      // `is Circle` writes one bare, so hiding only the enum's own name lets every variant in — and
      // `§wac-type-name-scope-8vqk3mn` says a type name must be in scope in the file that writes it,
      // variants included. Two spec cases said so the moment functions and consts joined the
      // closure and started reaching enums.
      for (i32 d = 0; d < iprog.decls.len(); d++) {
        match (iprog.decls[d].kind) {
          case EnumDecl(nameTok, variants, exported, methods, typeParams): {
            if (tokenTextOf(isrc, ilexed, nameTok) != reach[k]) { continue; }
            for (i32 v = 0; v < variants.len(); v++) {
              string vn = tokenTextOf(isrc, ilexed, variants[v].nameTok);
              if (listHas(wantAlias, n, c.renamed(vn))) { continue; }
              c.markUnnameable(c.renamed(vn));
            }
          }
          else: { }
        }
      }
    }
    c.renameCount = 0;
  }

  c.src = esrc;
  c.toks = elexed.tokens;
  checkModule(c, eprog);
  return c;
}
// The wac AST, as sum types.
//
// This file replaces a flat integer node pool. That pool was not a bad design —
// real compilers use one deliberately, and it removed an allocation per node — but
// it was chosen here because wac had no sum types, and the cost landed on every
// line that touched a node rather than once at the definition:
//
//   * `a`, `b`, `c` meant something different per tag, and nothing checked it. The
//     comments were the only schema.
//   * Three fields was the hard limit, so `sFor` and `dFunc` packed two node indices
//     into one i32 (`pack2`/`unpackLo`/`unpackHi`, with `none()` standing in for -1
//     because -1 does not survive packing). Four references needed a bit-layout
//     convention.
//   * Everything shared one tag space, so `sCase` had to be a statement and `dParam`
//     a declaration, though neither is one.
//   * A missing case in a walk was silent.
//
// All four are gone. `pack2`, `unpackLo`, `unpackHi` and `none` are deleted rather
// than ported — the three-field limit was their only reason to exist. Case clauses,
// parameters, fields and import items are now their own types instead of squatting
// in a tag range. And `match` is exhaustive, so a walk that misses a variant does not
// compile.
//
// Positions live on the wrapper structs rather than being repeated in every variant:
// `Expr` carries line and col, `Expr.kind` says what it is. That keeps 2 fields in
// one place instead of 98 across 49 variants, and matches how the reference nests
// its discriminant inside an object that always has a position.

// ── Types ─────────────────────────────────────────────────────────────────────

export struct Ty {
  TyKind kind;
  i32 line;
  i32 col;
}

export enum TyKind {
  /** `i32`, `bool`, `string`, … — `tok` is the name token. */
  Prim(i32 tok),
  /**
   * A named struct, enum or variant, with its type arguments.
   *
   * `Vec<i32>` is one of these with one argument, `Map<string, Vec<i32>>` with two. Empty for a plain
   * name, which is what every non-generic reference is. The resolver substitutes them and nothing after
   * it sees a non-empty list — but a *parser* has to record them, which is the whole of wac-mono 0003.
   */
  Named(i32 tok, Ty[] typeArgs),
  Arr(Ty elem),
  Nullable(Ty inner),
  Funcref(Ty ret, Ty[] params),
}

export Ty tyPrim(i32 tok, i32 line, i32 col) {
  return Ty(TyKind.Prim(tok), line, col);
}
export Ty tyNamed(i32 tok, Ty[] typeArgs, i32 line, i32 col) {
  return Ty(TyKind.Named(tok, typeArgs), line, col);
}
export Ty tyArr(Ty elem, i32 line, i32 col) {
  return Ty(TyKind.Arr(elem), line, col);
}
export Ty tyNullable(Ty inner, i32 line, i32 col) {
  return Ty(TyKind.Nullable(inner), line, col);
}
export Ty tyFuncref(Ty ret, Ty[] params, i32 line, i32 col) {
  return Ty(TyKind.Funcref(ret, params), line, col);
}

// ── Expressions ───────────────────────────────────────────────────────────────

export struct Expr {
  ExprKind kind;
  i32 line;
  i32 col;
}

/** A named argument in a struct literal: `Point(x: 1, y: 2)`. */
export struct NamedArg {
  i32 nameTok;
  Expr value;
}

export enum ExprKind {
  /**
   * `match (x) { case A: 1, else: 2 }` in expression position.
   *
   * The statement form is `StmtKind.Match`; this one has a value per arm rather than a body, which is
   * what `Arm.value` is for. `packages/std`'s `Option<T>` is written with it, and nothing here could
   * read that file — the parser had the statement and not the expression.
   */
  MatchExpr(Expr subject, Arm[] arms),
  /** `tok` is the literal token; the value is read from the source span. */
  IntLit(i32 tok),
  FloatLit(i32 tok),
  StrLit(i32 tok),
  /**
   * `<div class="a">{kid}</div>` — one element, its attributes and its children.
   *
   * **Lowered by the emitter, not by the parser.** `design/lang/0004` writes the meaning as wac
   * source — `Node.Element("div", Attr[](…), Node[](…))` — and that is what it *means*, but it
   * cannot be what the parser builds: every name in this tree is a token, and the desugaring needs
   * `Node`, `Attr` and the string `"div"`, none of which the source wrote. Synthesising tokens moves
   * every line and column in every diagnostic, because they are measured against the lexer's array.
   * The emitter names types by *string*, so it can write the tree with no token at all.
   */
  Jsx(i32 tagTok, i32 closeTok, JsxAttr[] attrs, Expr[] kids),
  /**
   * Text between a JSX element's tags — `hello` in `<p>hello {name}</p>`.
   *
   * **A span of the source, not tokens.** The text `hello world` is two identifier tokens with a
   * space between them that no token holds, so the run is recorded as byte offsets and read back
   * whole. It is an `Expr` because it stands where a child stands, and the emitter turns it into
   * `Node.Text`. `design/lang/0004`.
   */
  JsxText(i32 startOff, i32 endOff),
  BoolLit(bool value),
  NullLit,
  Ident(i32 tok),
  /** `op` is the operator token. */
  Unary(i32 op, Expr operand),
  Binary(i32 op, Expr left, Expr right),
  /** One of `as`, `as!`, `as~`, `as@` — which is in `op`. */
  Cast(i32 op, Expr operand, Ty target),
  /**
   * `x is T`, `x is null`, or `x is y` — reference identity against a value.
   *
   * Which of the three is encoded by what is present: `target` for a type test,
   * `other` for an identity test, neither for a null test. The reference stores the
   * right side in one field of a union type; there is no union of a type and an
   * expression here, so they are separate optional fields and at most one is set.
   */
  Is(Expr left, Ty? target, Expr? other, bool negated),
  Ternary(Expr cond, Expr then, Expr els),
  Call(Expr callee, Expr[] args),
  Index(Expr arr, Expr index),
  Member(Expr obj, i32 nameTok),
  /** `x!` — the non-null assertion. */
  Unwrap(Expr operand),
  /** `Point(1, 2)` or `Point(x: 1, y: 2)`; one of the two lists is empty. */
  Construct(Ty ctype, Expr[] args, NamedArg[] named),
  /** `++`/`--`; `prefix` distinguishes `++i` from `i++`. */
  Incr(Lvalue target, i32 op, bool prefix),
  /**
   * `i32[n]()`, `i32[n](fill: v)`, or `i32[](1, 2, 3)`.
   *
   * `size` and `elements` are exclusive. `fill` accompanies `size` and gives every
   * element that value, which is the only way to size an array dynamically when the
   * element type has no default — as anything reachable from an enum does not.
   */
  ArrNew(Ty elem, Expr? size, Expr? fill, Expr[] elements),
  /**
   * `(i32 a) => a + 1` and `() => { … }` — `design/lang/0002` tier two.
   *
   * **One form, because the parser desugars the other.** The note defines `() => e` as
   * `() => { return e; }`, so an expression body arrives here as a single `Return` statement built
   * on the arrow's own line and column. Everything downstream — the capture walk, the checker, the
   * emitter — then has a body that is a statement list, exactly as a function does, rather than two
   * shapes each of which could be forgotten in a different pass.
   *
   * There is no return type and no name. The return type comes from the `fn[…]` this is checked
   * against, which the language always supplies: wac has no `var`, so a lambda is written into an
   * assignment, an argument or a `return`, and never floats.
   */
  Lambda(Param[] params, Stmt[] body),
}

// ── Lvalues ───────────────────────────────────────────────────────────────────
//
// Kept a separate type from `Expr`, as in the reference: an assignment target is a
// narrower grammar than an expression, and making that a type rather than a
// validation pass means an unassignable target cannot be constructed.

export struct Lvalue {
  LvalueKind kind;
  i32 line;
  i32 col;
}

export enum LvalueKind {
  LIdent(i32 tok),
  LField(Lvalue base, i32 nameTok),
  LIndex(Lvalue base, Expr index),
  LUnwrap(Lvalue base),
}

// ── Statements ────────────────────────────────────────────────────────────────

export struct Stmt {
  StmtKind kind;
  i32 line;
  i32 col;
}

/**
 * One `case` or `default` clause.
 *
 * Its own type now. In the pool it had to be tag `sCase` in the statement range,
 * which meant every statement walk saw a node that is not a statement.
 */
export struct Case {
  /** null for `default`. */
  Expr? value;
  Stmt[] body;
  /**
   * The `case` or `default` keyword's own position.
   *
   * A `Case` is not a `Stmt` and has no position otherwise, and *"case value must be i32"* names the
   * keyword rather than the value — the same exception `override` is, and for the same reason: the
   * complaint is about the arm rather than about the expression in it.
   */
  i32 line;
  i32 col;
}

/**
 * One `case Pattern:` or `else:` arm of a `match`.
 *
 * `variantTok` is -1 for the `else` arm. A binding of `_` is a discard and is kept as
 * the token so the printer can reproduce it.
 */
/** One JSX attribute: `class="a"` or `id={x}`. The value is always an expression. */
export struct JsxAttr {
  i32 nameTok;
  Expr value;
}

export struct Arm {
  i32 variantTok;
  i32[] bindingToks;
  Stmt[] body;
  /**
   * The arm's value, for a `match` used as an *expression* — null for the statement form.
   *
   * One arm type for both, as the reference has it: an expression arm has a value and no body, a
   * statement arm a body and no value. Two types would mean two of everything that walks them.
   */
  Expr? value;
}

export enum StmtKind {
  /** `isConst` folds what the pool needed two tags for. */
  Var(Ty type, i32 nameTok, Expr init, bool isConst),
  Assign(Lvalue target, i32 op, Expr rhs),
  IncrStmt(Lvalue target, i32 op),
  /** `els` is empty for no else; an `else if` is a single-statement block. */
  If(Expr cond, Stmt[] then, Stmt[] els),
  While(Expr cond, Stmt[] body),
  /** Four references, which the pool could not hold without bit-packing. */
  For(Stmt? init, Expr? cond, Stmt? update, Stmt[] body),
  DoWhile(Stmt[] body, Expr cond),
  Switch(Expr subject, Case[] cases),
  Return(Expr? value),
  Break,
  Continue,
  /** `trap;` or `trap <expr>;` — the message the host is told, in place of a bare unreachable. */
  Trap(Expr? value),
  Match(Expr subject, Arm[] arms),
  Block(Stmt[] body),
  ExprStmt(Expr expr),
}

// ── Declarations ──────────────────────────────────────────────────────────────

/** `import { a, b as c } from "./m.wac"` — one item. */
export struct ImportItem {
  i32 nameTok;
  /** The same token as `nameTok` when there is no `as`. */
  i32 aliasTok;
}

export struct Param {
  i32 nameTok;
  Ty type;
  /** A leading `const`, which forbids writing through the parameter. */
  bool isConst;
}

export struct Field {
  i32 nameTok;
  Ty type;
  bool isConst;
}

export struct Method {
  i32 nameTok;
  Ty returnType;
  Param[] params;
  Stmt[] body;
  bool isOverride;
  /**
   * The `override` keyword's own token, or -1 when there is none.
   *
   * A method has no position of its own — a diagnostic about one names its return type, which is
   * where the declaration starts. `override` is the exception: *"'override' on 'foo' but no parent
   * method to override"* names the keyword, because the keyword is the part that is wrong.
   */
  i32 overrideTok;
  /** A method without `this` is static. */
  bool hasThis;
  bool thisConst;
}

/** One variant of an `enum` declaration. Payload fields are shaped like params. */
export struct Variant {
  i32 nameTok;
  Param[] fields;
}

export struct Decl {
  DeclKind kind;
  i32 line;
  i32 col;
}

export enum DeclKind {
  /**
   * `prefixTok` is the bare word in `import { Read } from core;` and -1 for an ordinary quoted
   * import, where `pathTok` is the string instead. Exactly one of the two is set: `core` is not a
   * path, so there is nothing to quote and nothing to resolve it against.
   */
  Import(i32 pathTok, i32 prefixTok, ImportItem[] items),
  /**
   * `typeParams` are the name tokens of `<T, U>` after the declaration's name, empty when there are
   * none. A generic function, struct or enum is the same declaration with those recorded.
   */
  Func(i32 nameTok, Ty returnType, Param[] params, Stmt[] body, bool exported,
       i32[] typeParams),
  /** `parentTok` is -1 when the struct has no parent. */
  StructDecl(i32 nameTok, i32 parentTok, Field[] fields, Method[] methods,
             bool exported, bool isConst, i32[] typeParams),
  /**
   * An enum's methods are held and not printed, exactly as the reference holds them: `Option<T>` has
   * six, and a parser that stopped at the first one could not read the file at all.
   */
  EnumDecl(i32 nameTok, Variant[] variants, bool exported, Method[] methods,
           i32[] typeParams),
  /** `[export] const <type> <name> = <expr>;` at file scope. */
  ConstDecl(i32 nameTok, Ty type, Expr init, bool exported),
}

export struct Program {
  Decl[] decls;
}

/** A run of JSX text, after the whitespace rule has been applied to it. */
export struct JsxSpan {
  i32 from;
  i32 to;

  bool isEmpty(const this) { return this.to <= this.from; }
}

/**
 * What a run of JSX text between two tags *means*, as a span of the source.
 *
 * **Trimmed at an end only where the whitespace there contains a newline.** A line break is layout —
 * the indentation of markup written over several lines — and a space is content: `<h1>hello {who}</h1>`
 * says "hello world", and a rule that trimmed both ends of every run said "helloworld". A renderer
 * found that in its first line of output, which is what writing one was for.
 *
 * It lives here rather than in the emitter because the parser needs the same rule to answer a
 * different question: a run that this leaves empty is not a child at all, so the whitespace between
 * two elements on separate lines adds nothing and the space in `<b>a</b> <b>b</b>` is a `Text(" ")`.
 * Two copies of the rule would answer those two questions differently on the first day one changed.
 *
 * (Written as a loop over bytes rather than with a helper predicate because `u8` is packed and
 * cannot be a parameter type.)
 */
export JsxSpan jsxTrim(u8[] src, i32 startOff, i32 endOff) {
  i32 from = startOff;
  i32 to = endOff;

  i32 lead = from;
  bool leadBreaks = false;
  while (lead < to
         && (src[lead] == ' ' || src[lead] == '\n' || src[lead] == '\r' || src[lead] == '\t')) {
    if (src[lead] == '\n') { leadBreaks = true; }
    lead = lead + 1;
  }
  if (leadBreaks) { from = lead; }

  i32 tail = to;
  bool tailBreaks = false;
  while (tail > from
         && (src[tail - 1] == ' ' || src[tail - 1] == '\n' || src[tail - 1] == '\r'
             || src[tail - 1] == '\t')) {
    if (src[tail - 1] == '\n') { tailBreaks = true; }
    tail = tail - 1;
  }
  if (tailBreaks) { to = tail; }

  return JsxSpan(from, to);
}
// The glue a host calls the module through, written by the compiler.
//
// `packages/wacc/tools/waccBindgen.ts` is the generator every tool here uses, and it is the last
// piece of the toolchain that exists only in TypeScript: `waccx bindgen` writes glue and the `wac`
// binary cannot, which is a tooling-parity gap rather than a missing language feature. This is that
// generator in wac.
//
// **Byte-identical to the TypeScript one, or it is not a port.** `test/bindgenWac.test.ts` compares
// the two outputs character for character over a corpus that grows as this covers more; a generator
// that emitted *equivalent* glue would be a second implementation to keep in step, which is the thing
// this repository spends its time avoiding. The wire formats and the conversion rules are shared with
// `src/manifest.wac`, and the shapes below are named after their counterparts there.
//
// What it emits, in order: the module as base64, a dispatcher per callback signature, the instance,
// the staging-buffer helpers, one function per reference array and per numeric array, a class per
// struct and enum, a function per export, and the aliases. That order is the TypeScript generator's
// and is load-bearing — a helper used by a class has to exist before the class that calls it.

import { splitTop } from "./manifest.wac";

/** What one run needs to know: the wires, taken apart, and which language to write. */
struct G {
  bool js;
  // The `S` and `E` lines: a bind type each.
  string[] tName;
  string[] tBind;
  string[] tKind;
  string[] tPayload;
  i32 tCount;
  // The `M` lines, kept whole and scanned by owner — a method belongs to the type it names.
  string[] mLines;
  i32 mCount;
  // The `C` lines: a callback the module imports a dispatcher for.
  string[] cRet;
  string[] cParams;
  string[] cWac;
  i32 cCount;
  // The `O` lines: a funcref handed out.
  string[] oRet;
  string[] oParams;
  string[] oWac;
  i32 oCount;
  // The `A` lines: another spelling for a type already here.
  string[] aOf;
  string[] aName;
  i32 aCount;
  // The exports, from `exportSigsFiles`.
  string[] sName;
  string[] sRet;
  string[] sParams;
  i32 sCount;
}

/** Everything that is not a type name, so `arrSuffix` and `classNameOf` can reduce one. */
bool isIdentChar(string ch) {
  return (ch >= "A" && ch <= "Z") || (ch >= "a" && ch <= "z") || (ch >= "0" && ch <= "9")
      || ch == "_";
}

bool startsWith(string s, string p) {
  return s.len() >= p.len() && s.slice(0, p.len()) == p;
}

bool endsWith(string s, string p) {
  return s.len() >= p.len() && s.slice(s.len() - p.len(), s.len()) == p;
}

/** The scalars that cross as numbers, `bool` and `void` among them. */
bool isScalar(string t) {
  return t == "i32" || t == "u32" || t == "i64" || t == "u64" || t == "f32" || t == "f64"
      || t == "bool" || t == "void";
}

/** The arrays that cross through the staging buffer, which is where `_to_mem`/`_from_mem` exist. */
bool isBulk(string t) {
  return t == "u8[]" || t == "i8[]" || t == "i32[]" || t == "u32[]" || t == "i64[]" || t == "u64[]"
      || t == "f32[]" || t == "f64[]";
}

i32 typeIndex(G g, string name) {
  for (i32 i = 0; i < g.tCount; i++) { if (g.tName[i] == name) { return i; } }
  return -1;
}

i32 callbackIndex(G g, string wac) {
  for (i32 i = 0; i < g.cCount; i++) { if (g.cWac[i] == wac) { return i; } }
  return -1;
}

i32 outRefIndex(G g, string wac) {
  for (i32 i = 0; i < g.oCount; i++) { if (g.oWac[i] == wac) { return i; } }
  return -1;
}

/** An array whose elements are references — a `string[]` or an array of arrays. */
bool isRefArray(G g, string t) {
  if (!endsWith(t, "[]") || isBulk(t)) { return false; }
  string el = t.slice(0, t.len() - 2);
  return el == "string" || endsWith(el, "[]") || typeIndex(g, el) >= 0;
}

/** Whether a value of this type crosses as a reference, which is what may be null. */
bool isRefType(G g, string t) {
  return t == "string" || endsWith(t, "[]") || typeIndex(g, t) >= 0 || callbackIndex(g, t) >= 0
      || outRefIndex(g, t) >= 0;
}

/**
 * The helper suffix an array's family is exported under — `string[]` is `string`, `u8[][]` is
 * `u8Arr`. The module builds the same name from the same rule, and the two have to agree or the glue
 * calls a function that is not there.
 */
string arrSuffix(string t) {
  string el = t.slice(0, t.len() - 2);
  if (endsWith(el, "[]")) { return arrSuffix(el) + "Arr"; }
  bool plain = true;
  for (i32 i = 0; i < el.len(); i++) { if (!isIdentChar(el.slice(i, i + 1))) { plain = false; } }
  if (plain) { return el; }
  return dollared(el);
}

/** Every run of non-identifier characters becomes one `$`, and a trailing run is dropped. */
string dollared(string s) {
  string out = "";
  bool pending = false;
  for (i32 i = 0; i < s.len(); i++) {
    string ch = s.slice(i, i + 1);
    if (isIdentChar(ch)) {
      if (pending) { out = out + "$"; pending = false; }
      out = out + ch;
    } else {
      pending = true;
    }
  }
  return out;
}

/**
 * The class name for a bind type.
 *
 * A monomorphisation's name is its *type*, `Vec<Setting>`, which is not a name a TypeScript file can
 * declare — so `[]` reads as `Arr` and `?` as `Opt`, and everything else that is not an identifier
 * becomes `$`, which wac's lexer rejects and so cannot collide with a name somebody wrote.
 */
string classNameOf(string name) {
  string out = "";
  i32 i = 0;
  while (i < name.len()) {
    if (i + 1 < name.len() && name.slice(i, i + 2) == "[]") { out = out + "Arr"; i = i + 2; continue; }
    if (name.slice(i, i + 1) == "?") { out = out + "Opt"; i = i + 1; continue; }
    out = out + name.slice(i, i + 1);
    i = i + 1;
  }
  return dollared(out);
}

/** The TypeScript type a wac type crosses as. */
string tsType(G g, string t) {
  if (endsWith(t, "?")) { return tsType(g, t.slice(0, t.len() - 1)) + " | null"; }
  i32 n = typeIndex(g, t);
  if (n >= 0) { return classNameOf(g.tName[n]); }
  i32 c = callbackIndex(g, t);
  i32 o = c < 0 ? outRefIndex(g, t) : -1;
  if (c >= 0 || o >= 0) {
    string ret = c >= 0 ? g.cRet[c] : g.oRet[o];
    string params = c >= 0 ? g.cParams[c] : g.oParams[o];
    string[] ps = params == "" ? string[0](fill: "") : splitTop(params, ",");
    string args = "";
    for (i32 i = 0; i < ps.len(); i++) {
      if (i > 0) { args = args + ", "; }
      args = args + "a" + itoa(i) + ": " + tsType(g, ps[i]);
    }
    return "(" + args + ") => " + tsType(g, ret);
  }
  if (t == "void") { return "void"; }
  if (t == "bool") { return "boolean"; }
  if (t == "i64" || t == "u64") { return "bigint"; }
  if (t == "string") { return "string"; }
  if (isBulk(t)) { return arrayClass(t); }
  if (isRefArray(g, t)) { return tsType(g, t.slice(0, t.len() - 2)) + "[]"; }
  return "number";
}

string arrayClass(string t) {
  string el = t.slice(0, t.len() - 2);
  if (el == "u8") { return "Uint8Array"; }
  if (el == "i8") { return "Int8Array"; }
  if (el == "i32") { return "Int32Array"; }
  if (el == "u32") { return "Uint32Array"; }
  if (el == "i64") { return "BigInt64Array"; }
  if (el == "u64") { return "BigUint64Array"; }
  if (el == "f32") { return "Float32Array"; }
  if (el == "f64") { return "Float64Array"; }
  return "Uint8Array";
}

/** How many bytes one element takes in the staging buffer. */
i32 widthOf(string t) {
  string el = t.slice(0, t.len() - 2);
  if (el == "u8" || el == "i8") { return 1; }
  if (el == "i32" || el == "u32" || el == "f32") { return 4; }
  if (el == "i64" || el == "u64" || el == "f64") { return 8; }
  return 1;
}

/** A decimal, since this file writes indices and lengths into the text it generates. */
string itoa(i32 n) {
  if (n == 0) { return "0"; }
  bool neg = n < 0;
  i32 v = neg ? -n : n;
  string out = "";
  while (v > 0) {
    i32 d = v % 10;
    out = "0123456789".slice(d, d + 1) + out;
    v = v / 10;
  }
  return neg ? "-" + out : out;
}

/** `: T` where a type is wanted, and nothing at all in JavaScript. */
string ann(G g, string t) { return g.js ? "" : ": " + tsType(g, t); }

/** The same for a type this file spells itself rather than deriving from a wac one. */
string annRaw(G g, string ts) { return g.js ? "" : ": " + ts; }

string cf(G g) { return g.js ? "" : " as CallableFunction"; }
string bs(G g) { return g.js ? "" : " as BufferSource"; }
string ac(G g) { return g.js ? "" : " as const"; }

/** A value crossing *into* the module. */
string toWasm(G g, string t, string expr) {
  string inner = endsWith(t, "?") ? t.slice(0, t.len() - 1) : t;
  string conv = toWasmInner(g, inner, expr);
  // **A `null` crosses as a `null`, whatever the spelling says.** Every reference this compiler emits
  // is the nullable wasm type, so a `T` and a `T?` are one type here and a converter that assumed
  // otherwise would read `.length` off nothing. A number cannot be null and is left alone.
  if (conv == expr || !isRefType(g, inner)) { return conv; }
  // Bound to a name first: the guard names the value twice, and the expression handed in is
  // sometimes a call — evaluating it in both arms collects a ticket twice.
  return "((v) => v === null ? null : " + toWasmInner(g, inner, "v") + ")(" + expr + ")";
}

string toWasmInner(G g, string t, string expr) {
  i32 c = callbackIndex(g, t);
  if (c >= 0) { return "$fnref" + itoa(c) + "(" + expr + ")"; }
  if (t == "string") { return "$strTo(" + expr + ")"; }
  if (isBulk(t)) { return "$arrTo_" + t.slice(0, t.len() - 2) + "(" + expr + ")"; }
  if (isRefArray(g, t)) { return "$arrTo_" + arrSuffix(t) + "(" + expr + ")"; }
  if (typeIndex(g, t) >= 0) { return expr + ".$ref"; }
  return expr;
}

/** A value crossing *out* of it. */
string fromWasm(G g, string t, string expr) {
  if (endsWith(t, "?")) {
    string inner = t.slice(0, t.len() - 1);
    return "((r) => r === null ? null : " + fromWasm(g, inner, "r") + ")(" + expr + ")";
  }
  return fromWasmInner(g, t, expr);
}

string fromWasmInner(G g, string t, string expr) {
  i32 o = outRefIndex(g, t);
  if (o >= 0) {
    // A closure over the reference: JavaScript cannot call a funcref, but it can call the export
    // that does the `call_ref`, and the reference goes in front of the arguments.
    string[] ps = g.oParams[o] == "" ? string[0](fill: "") : splitTop(g.oParams[o], ",");
    string args = "";
    string fwd = "";
    for (i32 i = 0; i < ps.len(); i++) {
      if (i > 0) { args = args + ", "; fwd = fwd + ", "; }
      args = args + "a" + itoa(i) + ann(g, ps[i]);
      fwd = fwd + toWasm(g, ps[i], "a" + itoa(i));
    }
    string call = "($exports.$bind$callref_" + itoa(o) + cf(g) + ")($f"
        + (fwd == "" ? "" : ", " + fwd) + ")";
    return "(($f) => (" + args + ") => " + fromWasm(g, g.oRet[o], call) + ")(" + expr + ")";
  }
  if (t == "string") { return "$strFrom(" + expr + ")"; }
  if (isBulk(t)) { return "$arrFrom_" + t.slice(0, t.len() - 2) + "(" + expr + ")"; }
  if (isRefArray(g, t)) { return "$arrFrom_" + arrSuffix(t) + "(" + expr + ")"; }
  i32 n = typeIndex(g, t);
  if (n >= 0) { return "new " + classNameOf(g.tName[n]) + "(" + expr + ")"; }
  if (t == "bool") { return expr + " !== 0"; }
  return g.js ? expr : expr + " as " + tsType(g, t);
}

// ── Reading the wires ─────────────────────────────────────────────────────────────────────────

/** The lines of a text. */
string[] linesOf(string text) {
  i32 count = 0;
  for (i32 i = 0; i < text.len(); i++) { if (text.slice(i, i + 1) == "\n") { count = count + 1; } }
  string[] out = string[count + 1](fill: "");
  i32 n = 0;
  string cur = "";
  for (i32 i = 0; i < text.len(); i++) {
    if (text.slice(i, i + 1) == "\n") { out[n] = cur; n = n + 1; cur = ""; continue; }
    cur = cur + text.slice(i, i + 1);
  }
  out[n] = cur;
  return out;
}

/** One tab-separated field of a line, or "" past the end. */
string cell(string line, i32 want) {
  i32 n = 0;
  string cur = "";
  for (i32 i = 0; i < line.len(); i++) {
    if (line.slice(i, i + 1) == "\t") {
      if (n == want) { return cur; }
      n = n + 1;
      cur = "";
      continue;
    }
    cur = cur + line.slice(i, i + 1);
  }
  return n == want ? cur : "";
}

/** The `S`/`E`/`M`/`C`/`O`/`A` lines and the export signatures, taken apart once. */
G readWires(string wire, string sigs, bool js) {
  string[] wl = linesOf(wire);
  string[] sl = linesOf(sigs);
  G g = G(js,
          string[wl.len()](fill: ""), string[wl.len()](fill: ""), string[wl.len()](fill: ""),
          string[wl.len()](fill: ""), 0,
          string[wl.len()](fill: ""), 0,
          string[wl.len()](fill: ""), string[wl.len()](fill: ""), string[wl.len()](fill: ""), 0,
          string[wl.len()](fill: ""), string[wl.len()](fill: ""), string[wl.len()](fill: ""), 0,
          string[wl.len()](fill: ""), string[wl.len()](fill: ""), 0,
          string[sl.len()](fill: ""), string[sl.len()](fill: ""), string[sl.len()](fill: ""), 0);
  for (i32 i = 0; i < wl.len(); i++) {
    string tag = cell(wl[i], 0);
    if (tag == "S" || tag == "E") {
      g.tName[g.tCount] = cell(wl[i], 1);
      g.tBind[g.tCount] = cell(wl[i], 2);
      g.tKind[g.tCount] = tag;
      g.tPayload[g.tCount] = cell(wl[i], 3);
      g.tCount = g.tCount + 1;
    } else if (tag == "M") {
      g.mLines[g.mCount] = wl[i];
      g.mCount = g.mCount + 1;
    } else if (tag == "C") {
      g.cRet[g.cCount] = cell(wl[i], 2);
      g.cParams[g.cCount] = cell(wl[i], 3);
      g.cWac[g.cCount] = cell(wl[i], 4);
      g.cCount = g.cCount + 1;
    } else if (tag == "O") {
      g.oRet[g.oCount] = cell(wl[i], 2);
      g.oParams[g.oCount] = cell(wl[i], 3);
      g.oWac[g.oCount] = cell(wl[i], 4);
      g.oCount = g.oCount + 1;
    } else if (tag == "A") {
      g.aOf[g.aCount] = cell(wl[i], 1);
      g.aName[g.aCount] = cell(wl[i], 2);
      g.aCount = g.aCount + 1;
    }
  }
  for (i32 i = 0; i < sl.len(); i++) {
    if (sl[i] == "") { continue; }
    g.sName[g.sCount] = cell(sl[i], 0);
    g.sRet[g.sCount] = cell(sl[i], 1);
    g.sParams[g.sCount] = cell(sl[i], 2);
    g.sCount = g.sCount + 1;
  }
  return g;
}

/** The parameter types of a signature cell, which is empty for none. */
string[] paramsOf(string cellText) {
  return cellText == "" ? string[0](fill: "") : splitTop(cellText, ",");
}

// ── What can be bound ─────────────────────────────────────────────────────────────────────────

/** Whether a callback's own parameters and result are things a host can hand over. */
bool usableSig(string ret, string params) {
  if (startsWith(ret, "fn[")) { return false; }
  string[] ps = paramsOf(params);
  for (i32 i = 0; i < ps.len(); i++) { if (startsWith(ps[i], "fn[")) { return false; } }
  return true;
}

/** Whether one type is something the glue can carry. */
bool okType(G g, string t0) {
  string t = endsWith(t0, "?") ? t0.slice(0, t0.len() - 1) : t0;
  // **`T?` is `T` plus null**, and no boxed `i32?` at the boundary.
  if (endsWith(t0, "?") && isScalar(t)) { return false; }
  if (isScalar(t) || t == "string" || isBulk(t) || typeIndex(g, t) >= 0) { return true; }
  return isRefArray(g, t) && okType(g, t.slice(0, t.len() - 2));
}

/**
 * Whether this signature is one this generator can write glue for.
 *
 * A funcref *parameter* is a host function coming in, which a dispatcher answers; one in return
 * position is a wac function going out, which `$bind$callref_*` answers. A funcref nested inside
 * another signature is neither, and stays declined.
 */
bool supported(G g, i32 s) {
  string ret = g.sRet[s];
  i32 o = outRefIndex(g, ret);
  bool retOk = okType(g, ret) || (o >= 0 && usableSig(g.oRet[o], g.oParams[o]));
  if (!retOk) { return false; }
  string[] ps = paramsOf(g.sParams[s]);
  for (i32 i = 0; i < ps.len(); i++) {
    i32 c = callbackIndex(g, ps[i]);
    bool callable = c >= 0 && usableSig(g.cRet[c], g.cParams[c]);
    if (!okType(g, ps[i]) && !callable) { return false; }
  }
  return true;
}

// ── The types that cross ──────────────────────────────────────────────────────────────────────

/** Append `t` if it is not already there — the crossing set keeps first-seen order. */
i32 addUnique(string[] xs, i32 n, string t) {
  for (i32 i = 0; i < n; i++) { if (xs[i] == t) { return n; } }
  if (n >= xs.len()) { return n; }
  xs[n] = t;
  return n + 1;
}

/**
 * Every type that crosses the boundary, in the order the helpers must be written.
 *
 * The order is the TypeScript generator's and matters twice over: it decides the order of the
 * `$arrTo_*` definitions, and a helper has to be defined before the class that calls it.
 *
 * **An array of arrays needs its element's helpers too.** `u8[][]` is built by calling `$arrTo_u8`
 * per element, and that only exists if `u8[]` is itself in the crossing set — which it is not, when
 * nothing in a signature says `u8[]` on its own.
 */
i32 crossingOf(G g, bool[] usable, string[] out) {
  i32 n = 0;
  for (i32 s = 0; s < g.sCount; s++) {
    if (!usable[s]) { continue; }
    n = addUnique(out, n, g.sRet[s]);
    string[] ps = paramsOf(g.sParams[s]);
    for (i32 i = 0; i < ps.len(); i++) { n = addUnique(out, n, ps[i]); }
  }
  for (i32 t = 0; t < g.tCount; t++) {
    if (g.tKind[t] == "S" && g.tPayload[t] != "") {
      string[] fs = splitTop(g.tPayload[t], ",");
      for (i32 i = 0; i < fs.len(); i++) { n = addUnique(out, n, fieldType(fs[i])); }
    }
    if (g.tKind[t] == "E" && g.tPayload[t] != "") {
      string[] vs = splitTop(g.tPayload[t], ";");
      for (i32 i = 0; i < vs.len(); i++) {
        string rest = variantPayload(vs[i]);
        if (rest == "") { continue; }
        string[] fs = splitTop(rest, "|");
        for (i32 k = 0; k < fs.len(); k++) { n = addUnique(out, n, fieldType(fs[k])); }
      }
    }
    for (i32 m = 0; m < g.mCount; m++) {
      if (cell(g.mLines[m], 1) != g.tBind[t]) { continue; }
      n = addUnique(out, n, orVoid(cell(g.mLines[m], 4)));
      string[] ps = paramsOf(cell(g.mLines[m], 5));
      for (i32 i = 0; i < ps.len(); i++) { n = addUnique(out, n, ps[i]); }
    }
  }
  // **And what the callbacks carry.** A funcref field is one string, so nothing above sees the
  // `u8[][]` inside it; a type that crosses only this way needs its helpers as much as any other.
  for (i32 c = 0; c < g.cCount; c++) {
    n = addUnique(out, n, g.cRet[c]);
    string[] ps = paramsOf(g.cParams[c]);
    for (i32 i = 0; i < ps.len(); i++) { n = addUnique(out, n, ps[i]); }
  }
  for (i32 o = 0; o < g.oCount; o++) {
    n = addUnique(out, n, g.oRet[o]);
    string[] ps = paramsOf(g.oParams[o]);
    for (i32 i = 0; i < ps.len(); i++) { n = addUnique(out, n, ps[i]); }
  }
  i32 fixed = n;
  for (i32 i = 0; i < fixed; i++) {
    string el = out[i];
    while (endsWith(el, "[]") && !isBulk(el)) {
      el = el.slice(0, el.len() - 2);
      n = addUnique(out, n, el);
    }
  }
  return n;
}

/** `name:type` — the type half, which is everything after the first colon. */
string fieldType(string f) {
  i32 at = f.indexOf(":");
  return at < 0 ? "" : f.slice(at + 1, f.len());
}

/** `Variant:field:type|field:type` — everything after the variant's own name. */
string variantPayload(string v) {
  i32 at = v.indexOf(":");
  return at < 0 ? "" : v.slice(at + 1, v.len());
}

string fieldName(string f) {
  i32 at = f.indexOf(":");
  return at < 0 ? f : f.slice(0, at);
}

string orVoid(string t) { return t == "" ? "void" : t; }

// ── The module, as text ───────────────────────────────────────────────────────────────────────

/**
 * Standard base64 with padding — what `btoa` writes, since `atob` is what reads it back.
 *
 * Into a byte array of the exact size rather than a growing string: a module is half a megabyte, and
 * `out = out + ch` per character copies the whole answer each time. The size is known before the
 * first byte is read, which is what makes that avoidable.
 */
string base64(u8[] bytes) {
  u8[] alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".toBytes();
  i32 groups = (bytes.len() + 2) / 3;
  u8[] out = u8[groups * 4]();
  i32 at = 0;
  i32 i = 0;
  while (i < bytes.len()) {
    i32 b0 = bytes[i];
    i32 b1 = i + 1 < bytes.len() ? bytes[i + 1] : 0;
    i32 b2 = i + 2 < bytes.len() ? bytes[i + 2] : 0;
    i32 n = (b0 << 16) | (b1 << 8) | b2;
    out[at] = alphabet[(n >> 18) & 63];
    out[at + 1] = alphabet[(n >> 12) & 63];
    out[at + 2] = i + 1 < bytes.len() ? alphabet[(n >> 6) & 63] : 61;      // 61 is '='
    out[at + 3] = i + 2 < bytes.len() ? alphabet[n & 63] : 61;
    at = at + 4;
    i = i + 3;
  }
  return string.fromBytes(out);
}

// ── The text, built ───────────────────────────────────────────────────────────────────────────

/**
 * A growing byte buffer, because the answer is a megabyte and `+` copies it.
 *
 * The pieces are small — a line at a time — and the whole is not, which is exactly the shape that
 * turns string concatenation quadratic. Doubling keeps it linear, and `string.fromBytes` at the end
 * makes one copy.
 */
struct Out {
  u8[] buf;
  i32 n;
}

Out newOut() { return Out(u8[65536](), 0); }

void put(Out o, string s) {
  u8[] b = s.toBytes();
  if (o.n + b.len() > o.buf.len()) {
    i32 want = o.buf.len();
    while (want < o.n + b.len()) { want = want * 2; }
    u8[] bigger = u8[want]();
    for (i32 i = 0; i < o.n; i++) { bigger[i] = o.buf[i]; }
    o.buf = bigger;
  }
  for (i32 i = 0; i < b.len(); i++) { o.buf[o.n + i] = b[i]; }
  o.n = o.n + b.len();
}

/** One line, which is a piece and the newline that follows it. */
void line(Out o, string s) {
  put(o, s);
  put(o, "\n");
}

string finish(Out o) {
  u8[] exact = u8[o.n]();
  for (i32 i = 0; i < o.n; i++) { exact[i] = o.buf[i]; }
  return string.fromBytes(exact);
}

/**
 * The glue for a module, given the compiler's own description of it.
 *
 * `sigs` is `exportSigsLinked`, `wire` is `bindTypesLinked`, and `lang` is `"ts"` or `"js"` —
 * **JavaScript is this output minus its annotations**, which is why one generator writes both rather
 * than there being two to keep in step.
 */
export string bindgenOf(u8[] wasm, string sigs, string wire, string lang, bool coverage) {
  G g = readWires(wire, sigs, lang == "js");
  bool[] usable = bool[g.sCount](fill: false);
  for (i32 s = 0; s < g.sCount; s++) { usable[s] = supported(g, s); }
  string[] crossing = string[512](fill: "");
  i32 nc = crossingOf(g, usable, crossing);
  bool needsMem = false;
  for (i32 i = 0; i < nc; i++) {
    if (crossing[i] == "string" || isBulk(crossing[i])) { needsMem = true; }
  }

  Out o = newOut();
  // The header names `waccBindgen.ts` in both generators on purpose: it is the *contract* the file
  // was written to, and the two outputs are compared byte for byte, so a file that said which of the
  // two wrote it would make them differ for a reason nobody reading the glue cares about.
  line(o, "// Generated by packages/wacc/tools/waccBindgen.ts — do not edit.");
  line(o, "");
  line(o, "const WASM = \"" + base64(wasm) + "\";");
  // A loop, not `Uint8Array.from(atob(WASM), c => c.charCodeAt(0))`. That form calls a JS function
  // once per byte, and on `packages/box`'s 566 KiB module it costs 40.5 ms against 1.4 ms — 38x
  // what compiling the wasm costs. It is the `wacBind` path, every module a test binds; a built
  // application embeds through `packages/platform/host/children.ts`, which already wrote the loop,
  // so shipped startup was never affected by either spelling.
  //
  // Must stay byte-identical to `packages/wacc/tools/waccBindgen.ts`, which changed in `ab1f97f8`
  // while this port did not — caught as eighteen failures in `packages/wacc/test/bindgenWac.test.ts`,
  // every one of them this line.
  line(o, "const $b = atob(WASM);");
  line(o, "const bytes = new Uint8Array($b.length);");
  line(o, "for (let $i = 0; $i < $b.length; $i++) bytes[$i] = $b.charCodeAt($i);");
  line(o, "const $mod = new WebAssembly.Module(bytes" + bs(g) + ");");
  line(o, "");

  if (g.cCount > 0) {
    line(o, "// A host function reaches wac as a *slot number*: JavaScript cannot make a WasmGC");
    line(o, "// funcref, so the module defines one trampoline per slot and imports a dispatcher");
    line(o, "// that this file supplies. `$fnrefN` registers a function and answers the funcref.");
    for (i32 c = 0; c < g.cCount; c++) {
      if (!usableSig(g.cRet[c], g.cParams[c])) {
        // The import must be satisfied or the module will not instantiate, and this can only ever
        // be reached by wac calling a callback no host could have registered.
        line(o, "const $cbd" + itoa(c) + " = () => {");
        line(o, "  throw new Error(\"" + g.cWac[c] + " cannot be supplied from JavaScript\");");
        line(o, "};");
        line(o, "");
        continue;
      }
      string[] ps = paramsOf(g.cParams[c]);
      string params = "";
      string fwd = "";
      string raw = "";
      for (i32 i = 0; i < ps.len(); i++) {
        if (i > 0) { params = params + ", "; fwd = fwd + ", "; raw = raw + ", "; }
        params = params + "a" + itoa(i) + ann(g, ps[i]);
        fwd = fwd + fromWasm(g, ps[i], "a" + itoa(i));
        raw = raw + "a" + itoa(i) + ": unknown";
      }
      line(o, "const $cbs" + itoa(c) + annRaw(g, "((" + params + ") => " + tsType(g, g.cRet[c])
              + ")[]") + " = [];");
      line(o, "const $cbd" + itoa(c) + " = ($slot" + annRaw(g, "number")
              + (raw == "" ? "" : ", " + raw) + ") =>");
      line(o, "  " + toWasm(g, g.cRet[c], "$cbs" + itoa(c) + "[$slot](" + fwd + ")") + ";");
      line(o, "function $fnref" + itoa(c) + "(f"
              + (g.js ? "" : ": (" + params + ") => " + tsType(g, g.cRet[c])) + ")"
              + annRaw(g, "unknown") + " {");
      line(o, "  let slot = $cbs" + itoa(c) + ".indexOf(f);");
      line(o, "  if (slot < 0) {");
      line(o, "    slot = $cbs" + itoa(c) + ".length;");
      line(o, "    if (slot >= 16) {");
      line(o, "      throw new RangeError(\"at most 16 distinct " + g.cWac[c]
              + " functions can be passed to this module\");");
      line(o, "    }");
      line(o, "    $cbs" + itoa(c) + ".push(f);");
      line(o, "  }");
      line(o, "  return ($exports.$bind$fnref_" + itoa(c) + cf(g) + ")(slot);");
      line(o, "}");
      line(o, "");
    }
    string dispatchers = "";
    for (i32 c = 0; c < g.cCount; c++) {
      if (c > 0) { dispatchers = dispatchers + ", "; }
      dispatchers = dispatchers + "cb" + itoa(c) + ": $cbd" + itoa(c);
    }
    line(o, "const $inst = new WebAssembly.Instance($mod, { wac: { " + dispatchers + " } });");
  } else {
    line(o, "const $inst = new WebAssembly.Instance($mod, {});");
  }
  line(o, "const $exports = $inst.exports"
          + (g.js ? "" : " as Record<string, CallableFunction>") + ";");
  line(o, "");

  if (needsMem) {
    line(o, "const $memory = $inst.exports.$bind$mem" + (g.js ? "" : " as WebAssembly.Memory") + ";");
    line(o, "/** Grow the staging buffer to hold `n` bytes and answer a fresh view of it. */");
    line(o, "function $buffer(n" + annRaw(g, "number") + ")" + annRaw(g, "Uint8Array") + " {");
    line(o, "  ($exports.$bind$mem_ensure" + cf(g) + ")(n);");
    line(o, "  return new Uint8Array($memory.buffer);");
    line(o, "}");
    line(o, "");
    line(o, "function $strTo(s" + annRaw(g, "string") + ")" + annRaw(g, "unknown") + " {");
    line(o, "  const b = new TextEncoder().encode(s);");
    line(o, "  $buffer(b.length).set(b, 0);");
    line(o, "  return ($exports.$bind$str_from_mem" + cf(g) + ")(b.length);");
    line(o, "}");
    line(o, "");
    line(o, "function $strFrom(w" + annRaw(g, "unknown") + ")" + annRaw(g, "string") + " {");
    line(o, "  const n = ($exports.$bind$str_len" + cf(g) + ")(w)" + (g.js ? "" : " as number") + ";");
    line(o, "  $buffer(n);");
    line(o, "  ($exports.$bind$str_to_mem" + cf(g) + ")(w);");
    line(o, "  return new TextDecoder().decode(new Uint8Array($memory.buffer).slice(0, n));");
    line(o, "}");
    line(o, "");
  }

  // The arrays whose elements are references: built and read one element at a time through the
  // `_new`/`_set`/`_get`/`_len` family, because an element is a WasmGC value and not bytes.
  for (i32 i = 0; i < nc; i++) {
    string t = crossing[i];
    if (!isRefArray(g, t)) { continue; }
    string sfx = arrSuffix(t);
    string el = t.slice(0, t.len() - 2);
    string ets = tsType(g, el);
    line(o, "function $arrTo_" + sfx + "(a" + annRaw(g, ets + "[]") + ")" + annRaw(g, "unknown") + " {");
    if (el == "string") {
      line(o, "  if (a.length === 0) return ($exports.$bind$arr_" + sfx + "_new0" + cf(g) + ")();");
      line(o, "  const w = ($exports.$bind$arr_" + sfx + "_new" + cf(g) + ")(a.length, "
              + toWasm(g, el, "a[0]") + ");");
    } else {
      line(o, "  const w = ($exports.$bind$arr_" + sfx + "_new" + cf(g) + ")(a.length);");
    }
    line(o, "  for (let i = 0; i < a.length; i++) {");
    line(o, "    ($exports.$bind$arr_" + sfx + "_set" + cf(g) + ")(w, i, " + toWasm(g, el, "a[i]") + ");");
    line(o, "  }");
    line(o, "  return w;");
    line(o, "}");
    line(o, "");
    line(o, "function $arrFrom_" + sfx + "(w" + annRaw(g, "unknown") + ")" + annRaw(g, ets + "[]") + " {");
    line(o, "  const n = ($exports.$bind$arr_" + sfx + "_len" + cf(g) + ")(w)"
            + (g.js ? "" : " as number") + ";");
    line(o, "  const out" + annRaw(g, ets + "[]") + " = [];");
    line(o, "  for (let i = 0; i < n; i++) {");
    line(o, "    out.push(" + fromWasm(g, el, "($exports.$bind$arr_" + sfx + "_get" + cf(g) + ")(w, i)")
            + ");");
    line(o, "  }");
    line(o, "  return out;");
    line(o, "}");
    line(o, "");
  }

  for (i32 i = 0; i < nc; i++) {
    string t = crossing[i];
    if (!isBulk(t)) { continue; }
    string el = t.slice(0, t.len() - 2);
    string cls = arrayClass(t);
    string w = itoa(widthOf(t));
    line(o, "function $arrTo_" + el + "(a" + annRaw(g, cls) + ")" + annRaw(g, "unknown") + " {");
    line(o, "  const view = $buffer(a.length * " + w + ");");
    line(o, "  new " + cls + "(view.buffer, 0, a.length).set(a);");
    line(o, "  return ($exports.$bind$arr_" + el + "_from_mem" + cf(g) + ")(a.length);");
    line(o, "}");
    line(o, "");
    line(o, "function $arrFrom_" + el + "(w" + annRaw(g, "unknown") + ")" + annRaw(g, cls) + " {");
    line(o, "  const n = ($exports.$bind$arr_" + el + "_len" + cf(g) + ")(w)"
            + (g.js ? "" : " as number") + ";");
    line(o, "  $buffer(n * " + w + ");");
    line(o, "  ($exports.$bind$arr_" + el + "_to_mem" + cf(g) + ")(w);");
    line(o, "  return new " + cls + "($memory.buffer.slice(0, n * " + w + "));");
    line(o, "}");
    line(o, "");
  }

  for (i32 t = 0; t < g.tCount; t++) { classFor(o, g, t); }

  for (i32 s = 0; s < g.sCount; s++) {
    if (!usable[s]) { continue; }
    string[] ps = paramsOf(g.sParams[s]);
    string args = "";
    string conv = "";
    for (i32 i = 0; i < ps.len(); i++) {
      if (i > 0) { args = args + ", "; conv = conv + ", "; }
      args = args + "a" + itoa(i) + ann(g, ps[i]);
      conv = conv + toWasm(g, ps[i], "a" + itoa(i));
    }
    line(o, "export function " + g.sName[s] + "(" + args + ")" + ann(g, orVoid(g.sRet[s])) + " {");
    string call = "($exports." + g.sName[s] + cf(g) + ")(" + conv + ")";
    if (orVoid(g.sRet[s]) == "void") {
      line(o, "  " + call + ";");
    } else {
      line(o, "  return " + fromWasm(g, g.sRet[s], call) + ";");
    }
    line(o, "}");
    line(o, "");
  }

  // **The other names.** One `const` per alias, so a host that asks for `Pending$u8ArrOpt` gets the
  // class that answers to `Pending$u8Arr` — the same class, because here they are the same type.
  for (i32 a = 0; a < g.aCount; a++) {
    string from = classNameOf(g.aName[a]);
    string to = classNameOf(g.aOf[a]);
    if (from == to || typeIndex(g, g.aOf[a]) < 0) { continue; }
    line(o, "/** `" + g.aName[a] + "` is `" + g.aOf[a] + "` here: one wasm type, two spellings. */");
    line(o, "export const " + from + " = " + to + ";");
    line(o, "");
  }

  // **An instrumented module's counters are part of its contract**: without these three wrappers
  // they are exports nobody can call.
  if (coverage) {
    line(o, "");
    line(o, "/** Allocate (or reset) the branch-coverage counters. */");
    line(o, "export function __cov_init(): void {");
    line(o, "  ($exports.__cov_init" + cf(g) + ")();");
    line(o, "}");
    line(o, "");
    line(o, "/** Number of instrumented branch points. */");
    line(o, "export function __cov_len()" + annRaw(g, "number") + " {");
    line(o, "  return ($exports.__cov_len" + cf(g) + ")()" + (g.js ? "" : " as number") + ";");
    line(o, "}");
    line(o, "");
    line(o, "/** Read one branch counter. Traps if __cov_init has not been called. */");
    put(o, "export function __cov_get(i" + annRaw(g, "number") + ")" + annRaw(g, "number") + " {\n");
    put(o, "  return ($exports.__cov_get" + cf(g) + ")(i)" + (g.js ? "" : " as number") + ";\n");
    put(o, "}");
    return finish(o);
  }
  return trimmed(finish(o));
}

/**
 * The generator joins its lines, so there is no newline after the last one.
 *
 * Everything above writes a line at a time, which is one character more than `join("\n")` produces.
 * Dropping it here keeps the difference in one place instead of making every branch remember.
 */
string trimmed(string s) {
  return s.len() > 0 && s.slice(s.len() - 1, s.len()) == "\n" ? s.slice(0, s.len() - 1) : s;
}

/**
 * A struct or an enum as a class holding the reference.
 *
 * Nothing is copied: `$ref` is the WasmGC reference itself, and every accessor calls back into the
 * module. That is what makes a wrapper cheap enough to hand around — a `Point` returned from one call
 * can go straight into the next.
 */
void classFor(Out o, G g, i32 t) {
  string name = g.tName[t];
  string bind = g.tBind[t];
  string cls = classNameOf(name);
  bool isEnum = g.tKind[t] == "E";
  line(o, isEnum
      ? "/** `" + name + "`, held by reference. `tag` says which variant it is. */"
      : "/** `" + name + "`, held by reference. Fields and methods call into the module. */");
  line(o, "export class " + cls + " {");
  line(o, "  constructor(" + (g.js ? "$ref" : "readonly $ref: unknown") + ") {"
          + (g.js ? " this.$ref = $ref; " : "") + "}");
  if (!isEnum) {
    string[] fs = g.tPayload[t] == "" ? string[0](fill: "") : splitTop(g.tPayload[t], ",");
    string args = "";
    string conv = "";
    for (i32 i = 0; i < fs.len(); i++) {
      if (i > 0) { args = args + ", "; conv = conv + ", "; }
      args = args + fieldName(fs[i]) + ann(g, fieldType(fs[i]));
      conv = conv + toWasm(g, fieldType(fs[i]), fieldName(fs[i]));
    }
    // `classNameOf`, not the wac name: an instance's *type* is `Pending<i32>` and its class is
    // `Pending$i32`, which in code position is what has to be written.
    line(o, "  static $of(" + args + ")" + annRaw(g, cls) + " {");
    line(o, "    return new " + cls + "(($exports.$bind$s_" + bind + "_new" + cf(g) + ")(" + conv + "));");
    line(o, "  }");
    for (i32 i = 0; i < fs.len(); i++) {
      string fname = fieldName(fs[i]);
      string ft = fieldType(fs[i]);
      line(o, "  get " + fname + "()" + ann(g, ft) + " {");
      line(o, "    return " + fromWasm(g, ft, "($exports.$bind$s_" + bind + "_get_" + fname + cf(g)
              + ")(this.$ref)") + ";");
      line(o, "  }");
      line(o, "  set " + fname + "(v" + ann(g, ft) + ") {");
      line(o, "    ($exports.$bind$s_" + bind + "_set_" + fname + cf(g) + ")(this.$ref, "
              + toWasm(g, ft, "v") + ");");
      line(o, "  }");
    }
  } else {
    string[] vs = g.tPayload[t] == "" ? string[0](fill: "") : splitTop(g.tPayload[t], ";");
    for (i32 i = 0; i < vs.len(); i++) {
      string vn = variantName(vs[i]);
      string rest = variantPayload(vs[i]);
      string[] fs = rest == "" ? string[0](fill: "") : splitTop(rest, "|");
      string args = "";
      string conv = "";
      for (i32 k = 0; k < fs.len(); k++) {
        if (k > 0) { args = args + ", "; conv = conv + ", "; }
        args = args + fieldName(fs[k]) + ann(g, fieldType(fs[k]));
        conv = conv + toWasm(g, fieldType(fs[k]), fieldName(fs[k]));
      }
      line(o, "  static " + vn + "(" + args + ")" + annRaw(g, cls) + " {");
      line(o, "    return new " + cls + "(($exports.$bind$e_" + bind + "_" + vn + "_new" + cf(g)
              + ")(" + conv + "));");
      line(o, "  }");
    }
    // The union is `"A" | "B"` and the lookup table is `["A", "B"]` — the same names, two
    // separators, and writing the table with the union's separator makes every tag `undefined`.
    string union = "";
    string list = "";
    for (i32 i = 0; i < vs.len(); i++) {
      if (i > 0) { union = union + " | "; list = list + ", "; }
      union = union + "\"" + variantName(vs[i]) + "\"";
      list = list + "\"" + variantName(vs[i]) + "\"";
    }
    line(o, "  get tag()" + annRaw(g, union) + " {");
    line(o, "    const t = ($exports.$bind$e_" + bind + "_tag" + cf(g) + ")(this.$ref)"
            + (g.js ? "" : " as number") + ";");
    line(o, "    return ([" + list + "]" + ac(g) + ")[t];");
    line(o, "  }");
    for (i32 i = 0; i < vs.len(); i++) {
      string vn = variantName(vs[i]);
      string rest = variantPayload(vs[i]);
      if (rest == "") { continue; }
      string[] fs = splitTop(rest, "|");
      for (i32 k = 0; k < fs.len(); k++) {
        string fname = fieldName(fs[k]);
        string ft = fieldType(fs[k]);
        line(o, "  /** The `" + fname + "` of a `" + vn + "` — check `tag` first. */");
        // A getter, as the reference's generator writes it: a caller reads `v.Bool_value`, and a
        // method of that name hands back the function object instead.
        line(o, "  get " + vn + "_" + fname + "()" + ann(g, ft) + " {");
        line(o, "    return " + fromWasm(g, ft, "($exports.$bind$e_" + bind + "_" + vn + "_get_" + fname
                + cf(g) + ")(this.$ref)") + ";");
        line(o, "  }");
      }
    }
  }
  for (i32 m = 0; m < g.mCount; m++) {
    if (cell(g.mLines[m], 1) != bind) { continue; }
    string mn = cell(g.mLines[m], 2);
    bool hasThis = cell(g.mLines[m], 3) == "this";
    string ret = orVoid(cell(g.mLines[m], 4));
    string[] ps = paramsOf(cell(g.mLines[m], 5));
    string args = "";
    string conv = "";
    for (i32 i = 0; i < ps.len(); i++) {
      if (i > 0) { args = args + ", "; conv = conv + ", "; }
      args = args + "a" + itoa(i) + ann(g, ps[i]);
      conv = conv + toWasm(g, ps[i], "a" + itoa(i));
    }
    string helper = hasThis ? "$bind$m_" + bind + "_" + mn : "$bind$sm_" + bind + "_" + mn;
    string inside = hasThis ? (conv == "" ? "this.$ref" : "this.$ref, " + conv) : conv;
    string call = "($exports." + helper + cf(g) + ")(" + inside + ")";
    string sig = hasThis ? mn + "(" + args + ")" : "static " + mn + "(" + args + ")";
    line(o, "  " + sig + ann(g, ret) + " {");
    line(o, ret == "void" ? "    " + call + ";" : "    return " + fromWasm(g, ret, call) + ";");
    line(o, "  }");
  }
  line(o, "}");
  line(o, "");
}

/** `Variant:field:type` — the variant's own name. */
string variantName(string v) {
  i32 at = v.indexOf(":");
  return at < 0 ? v : v.slice(0, at);
}

/**
 * What this generator declined, so a caller learns it rather than discovering it at run time.
 *
 * One `name(params) -> ret` per line. A caller told `makeP(i32) -> P` was declined can change the
 * signature; one handed glue missing a function finds out at the call site.
 */
export string bindgenDeclined(string sigs, string wire) {
  G g = readWires(wire, sigs, false);
  string out = "";
  for (i32 s = 0; s < g.sCount; s++) {
    if (supported(g, s)) { continue; }
    string[] ps = paramsOf(g.sParams[s]);
    string args = "";
    for (i32 i = 0; i < ps.len(); i++) {
      if (i > 0) { args = args + ", "; }
      args = args + ps[i];
    }
    out = out + g.sName[s] + "(" + args + ") -> " + orVoid(g.sRet[s]) + "\n";
  }
  return out;
}
// Rung 3, first slice: the type of a returned literal against the function's declared return type.
//
// The rung is 3,190 reference lines and ~210 distinct messages. This is one of them, chosen because
// it is the smallest diagnostic that still needs everything a type checker needs — a declaration
// walked for its signature, a body walked for a statement nested arbitrarily deep, a type inferred
// from an expression, the two compared, and a position reported that a caller can point at.
//
// ## Two rules, because the language has two
//
// A returned **name** must have the declared type *exactly*: `return p` where `p` is an `i64` is an
// error from an `i32` function, and `f32` from `f64` is too. A returned **literal** is not a value of
// some type that has to match — it is polymorphic over a family, and any of `i32 i64 u32 u64` accepts
// an integer literal.
//
// Modelling only the family is what the first version did, and the parameter grid found it: 58 of 72
// rejections caught, the missing fourteen all within a family. Modelling only exact types would be
// worse, because it would report `return 1` from an `i64` as an error the reference does not.
//
// ## Why a subset is the point
//
// Everything this slice cannot type — a call, a member, arithmetic, a name from another module — is
// silence rather than a guess. It reports a subset of the reference and never a superset, which is
// the only property that lets a partial checker be compared against a complete one at all.
//
// ## Positions
//
// The reference reports the **returned expression**, not the `return` keyword:
//
//     export i32 main() { return "x"; }
//     return: expected i32, found string   @ 1:28
//
// Column 28 is the `"`, column 21 is the `r` of `return`. Every AST node here carries its own line
// and column, so this is `e.line, e.col` and not arithmetic.

import { lex, tokenStride } from "./lex.wac";
import { floatLit, parseInt } from "./lit.wac";
import {
  kPlus, kMinus, kStar, kSlash, kPercent, kAnd, kOr, kCaret,
  kLt, kLe, kGt, kGe, kEq, kNe, kAndAnd, kOrOr, kAssign, kBang,
  kAs, kAsBang, kAsTilde, kAsAt, kShrU, kShl, kShr, kTilde, kShlEq, kShrEq, kShrUEq,
} from "./kinds.wac";
import {
  Arm, Decl, DeclKind, Expr, ExprKind, JsxAttr, Lvalue, LvalueKind, NamedArg, Param, Program, Stmt,
  StmtKind, Ty, TyKind, tyPrim,
} from "./ast.wac";

/** A returned value whose type cannot be the declared one. */
export i32 errReturnTypeMismatch() { return 1; }
/** A non-void function that can reach its closing brace. */
export i32 errMissingReturn() { return 2; }
/**
 * A variable initialised with something that cannot be its declared type.
 *
 * A separate code from the return mismatch because the reference words them differently — *"type
 * mismatch: expected i32, got string"* against *"return: expected i32, found string"* — and rung 3's
 * comparison is by code and position, so two families that a caller could tell apart should not
 * arrive here as one.
 */
export i32 errInitTypeMismatch() { return 3; }
/** Two operands of an arithmetic operator that are not the same type. */
export i32 errOperandMismatch() { return 4; }
/** An argument that cannot be the parameter it is passed to. */
export i32 errArgumentMismatch() { return 5; }
/**
 * An expression that has to be `bool` and is not.
 *
 * Two of the reference's messages, kept as one code because they are one rule in two positions:
 * *"'&&' requires bool operands, got i32"* and *"condition must be bool"*. Both say the same thing —
 * this expression is used where only a boolean can go — and nothing a caller does with the diagnostic
 * would distinguish them.
 */
export i32 errNotBool() { return 6; }
/** `==` or `!=` on a reference type, where the language wants `is`. */
export i32 errNotComparable() { return 7; }
/** A construction argument that cannot be the field it fills. */
export i32 errFieldMismatch() { return 8; }
/** A nullable value where a non-null one is required. */
export i32 errNullableToNonNull() { return 9; }
/**
 * The three ways a write can be refused, kept apart because the reference keeps them apart.
 *
 * *"cannot assign to const variable 'n'"*, *"cannot write to const field 'k'"* and *"cannot write
 * through const reference"* say different things about where the constness lives — on the binding,
 * on the field, or on the path to it — and a caller fixing one would not fix the others.
 */
export i32 errConstVariable() { return 10; }
export i32 errConstField() { return 11; }
export i32 errConstReference() { return 12; }
/** A static method that the struct does not have. */
export i32 errNoStaticMethod() { return 13; }
/** An instance method that the struct does not have. */
export i32 errNoMethod() { return 14; }
/** A non-const method called through a const receiver. */
export i32 errNonConstThroughConst() { return 15; }
/** A cast written with an operator the conversion does not take. */
export i32 errWrongCastOp() { return 16; }
/** Two parameters of one function with the same name. */
export i32 errDuplicateParam() { return 17; }
/** An array element or fill that cannot be the array's element type. */
export i32 errArrayElement() { return 18; }
/** A builtin called with the wrong number of arguments. */
export i32 errBuiltinArity() { return 19; }
/** A builtin argument of the wrong type. */
export i32 errBuiltinArg() { return 20; }
/** A name used where nothing declares it. */
export i32 errUndefinedName() { return 35; }
/** A `void` where a type is needed. */
export i32 errVoidType() { return 36; }
/** A `return` that disagrees with the function's own `void`ness, either way. */
export i32 errReturnValueness() { return 37; }
/** An operator given something it cannot work on. */
export i32 errOperandKind() { return 38; }
/** A field read from something that has no such field, or no fields at all. */
export i32 errNoSuchField() { return 39; }
/** A member reached through a nullable without unwrapping it. */
export i32 errThroughNullable() { return 40; }
/** An index into something that is not an array, or with something that is not an index. */
export i32 errIndex() { return 41; }
/** A ternary whose branches cannot be the same type. */
export i32 errTernaryBranches() { return 42; }
/** `is` or `!` applied to something the question does not make sense for. */
export i32 errReferenceOp() { return 43; }
/** A `switch` on something it cannot switch on. */
export i32 errSwitchSubject() { return 44; }
/** A named construction naming a field the struct does not have, or leaving one out. */
export i32 errNamedField() { return 45; }
/** A float literal too large for the type it is going into. */
export i32 errFloatRange() { return 50; }
/** `E.nope` where `E` is an enum and `nope` is none of its variants. */
export i32 errNoVariant() { return 51; }
/** An import specifier that is a bare word other than `core` — `spec/spec/imports.md`. */
export i32 errUnknownModule() { return 52; }
/** A generic that instantiates itself with a larger argument, so it never terminates. */
export i32 errInfiniteGeneric() { return 53; }
/** An enum method whose name is one of the enum's own variants: `E.A` would mean both. */
export i32 errVariantMethodClash() { return 54; }
/** Two imports of the same name, or an import colliding with a name this file declares. */
export i32 errDuplicateImport() { return 55; }
/**
 * An import of a name the named file does not export — either because it is declared without
 * `export`, or because that file only imports it itself. Importing does not re-export
 * (`§wac-no-reexport-f7kn4wq`), which is the rule that keeps a file's exports its own to state.
 */
export i32 errNoSuchExport() { return 56; }
/**
 * A type name written in a file that never brought it into scope — `§wac-type-name-scope-8vqk3mn`.
 * A variant imports like any other name, so `x is Circle` needs `Circle` imported just as `K k`
 * needs `K`.
 */
export i32 errUndefinedType() { return 57; }

/**
 * Warning codes, numbered from 200 so they cannot be confused with an error's at a glance in a wire
 * dump — the two travel in the same shape and are counted separately. `issues/lang/0126`.
 */
export i32 warnNeverNull() { return 200; }
export i32 warnNeverThat() { return 201; }
export i32 warnAlwaysTraps() { return 202; }
/** A `match` that leaves one of the enum's variants uncovered and has no `else`. */
export i32 errMatchInexhaustive() { return 58; }
/** Two arms of one `match` naming the same variant. */
export i32 errDuplicateCase() { return 59; }
/** An `else` on a `match` whose arms already cover every variant. */
export i32 errElseUnreachable() { return 60; }
/** An arm binding named after the subject it is matching: inside the arm the two would be one name. */
export i32 errBindingCollision() { return 61; }
/** A `match` on a nullable value — there is no variant for the null. */
export i32 errMatchNullable() { return 62; }
/** Two arms of a `match` used as an expression whose values are of unrelated types. */
export i32 errArmTypes() { return 63; }

/** A cast between two types that are already the same. */
export i32 errRedundantCast() { return 46; }
/** Calling something that is not a function, or naming something that does not exist to call. */
export i32 errNotCallable() { return 47; }
/** A method named without calling it. */
export i32 errMethodAsValue() { return 48; }
/** A struct's name used where a value belongs. */
export i32 errStructAsValue() { return 49; }
/** A method that hides a parent's without saying `override`. */
export i32 errOverrideMissing() { return 21; }
/** `override` on a method no parent declares. */
export i32 errOverrideSpurious() { return 22; }
/** `++` or `--` on something that is not an integer. */
export i32 errIncrType() { return 23; }
/** `>>>` on a type where it says nothing, or on a non-integer. */
export i32 errShiftOp() { return 24; }
/** Positional construction with the wrong number of arguments. */
export i32 errCtorArity() { return 25; }
/** A packed type in a position that has no slot for one. */
export i32 errPackedPosition() { return 26; }
/** A write through a string index — strings are immutable. */
export i32 errStringIndexWrite() { return 27; }
/** A default construction of something that has no default value. */
export i32 errNoDefault() { return 28; }
/** A non-null field that refers back to its own struct. */
export i32 errRecursiveField() { return 29; }
/** `as` where the conversion is a downcast and may fail. */
export i32 errDowncast() { return 30; }
/** `break` or `continue` with nothing to leave. */
export i32 errNoLoop() { return 31; }
/** A call with the wrong number of arguments. */
export i32 errCallArity() { return 32; }
/** A nullable packed type, which has no representation. */
export i32 errPackedNullable() { return 33; }
/** A module-level `const` whose value cannot be computed at compile time. */
export i32 errNotCompileTime() { return 34; }
/** Two declarations of one name at file scope. */
export i32 errDuplicateName() { return 64; }
/** Two fields, two methods, or a field and a method of one name in one struct. */
export i32 errDuplicateMember() { return 65; }
/** A character literal holding none or more than one character. */
export i32 errCharLiteral() { return 66; }
/** A `switch` with two `default` clauses. */
export i32 errTwoDefaults() { return 67; }
/**
 * A JSX element whose closing tag names something else — `<div></span>`.
 *
 * wacc-only, as JSX is: `design/lang/0004`. Its own code rather than a borrowed one, because the
 * text a reader sees comes from the code and "that file does not export this name" is about
 * something else entirely.
 */
export i32 errJsxTagMismatch() { return 68; }
/**
 * The same attribute written twice on one element — `<div class="a" class="b"/>`.
 *
 * Refused rather than resolved, which is this language's habit: a switch with two defaults and a
 * struct with two members of one name are both errors, and the tree cannot express precedence
 * either. HTML would take one of them and say nothing, which is the behaviour to *not* inherit.
 */
export i32 errJsxDuplicateAttr() { return 69; }
/**
 * A tag naming a struct that is not a component — one with no `Node render(const this, Node[] kids)`.
 *
 * A tag that names a struct in scope *is* a component (`design/lang/0005`), so this is what says the
 * struct cannot serve as one. It names the signature rather than saying "not a component", because
 * the fix is almost always to write that method or to correct its shape.
 */
export i32 errJsxNotComponent() { return 70; }
/**
 * A generic enum's variant where nothing says which instantiation it is.
 *
 * `Maybe.Just(4)` takes its type arguments from the expected type, and every position has one except
 * a receiver: `Maybe.Just(4).orElse(0)`. The emitter declines that with `unresolved name Maybe`,
 * which names a type that is defined and sends the reader looking for a typo. `issues/lang/0088`.
 */
export i32 errGenericVariantSlot() { return 71; }
/** `match` on a value that is not an enum, which has no variants to have arms for. */
export i32 errMatchNotEnum() { return 72; }
/**
 * A lambda where nothing wanted a funcref — `i32 g = () => 42;`.
 *
 * Its own code because it is the one lambda mistake the ordinary mismatch machinery cannot report:
 * a lambda has no type of its own, `typeOfExpr` answers unknown for one, and unknown is assignable
 * to everything. So the caller's `assignable` agrees and says nothing — which is how all five of the
 * wrong programs in `test/lambda.test.ts` were accepted before `checkLambda` existed.
 */
export i32 errLambdaNoTarget() { return 73; }
/** A lambda whose parameters do not match the funcref it is being used as, in count or in type. */
export i32 errLambdaSignature() { return 74; }

/**
 * How many bytes the first character of `s` takes, read from its lead byte.
 *
 * The same four ranges `str_idx` decodes with, and here for the same reason: "one character" is a
 * question about an encoding, not about a length.
 */
i32 utf8Width(string s) {
  u8[] b = s.toBytes();
  if (b.len() == 0) { return 0; }
  i32 lead = b[0];
  if (lead < 128) { return 1; }
  if (lead < 224) { return 2; }
  if (lead < 240) { return 3; }
  return 4;
}

/**
 * A type is its **canonical name**: `"i32"`, `"P"`, or `""` for one this slice cannot name.
 *
 * It was a small integer per primitive, which was enough while every type was a primitive and became
 * the limit the moment structs mattered. A name costs a string compare where an id cost an integer
 * one, and buys the whole rest of the type system for nothing: two struct types differ exactly when
 * their names do, and "is this a reference type" is "is this name not a primitive".
 *
 * `""` is *unknown*, and unknown is silence. That is different from a type that exists and fits
 * nothing — `u8` cannot be a return type at all — which is a primitive with a name like any other and
 * is refused by `acceptsLiteral` and by never equalling anything a caller can produce.
 */
export string typeNone() { return ""; }

/** Whether a name is one of the language's primitives, as opposed to a struct, enum or import. */
export bool isPrimitiveName(string n) {
  return n == "i32" || n == "i64" || n == "u32" || n == "u64" ||
         n == "f32" || n == "f64" || n == "bool" || n == "string" ||
         n == "u8" || n == "u16" || n == "i8" || n == "i16";
}

/**
 * Whether `==` and `!=` are allowed on this type.
 *
 * They are not, on a reference type: the reference answers `'==' not allowed on reference type P —
 * use 'is' for identity`, and it says so even when both sides are the same `P`, because the question
 * is identity rather than equality. `string` is the exception the language makes — two strings
 * compare by value — which is why this asks about the name rather than about reference-ness.
 */
/**
 * Whether a function with this return type must return a value.
 *
 * `void` is the only type that means *no value*, and under the old id model it came back as "unknown"
 * and so was excluded by accident. Now that a type is its name, `void` is a name like any other and
 * has to be excluded on purpose — which is better, because the exclusion is now a statement about
 * `void` rather than a side effect of not modelling it.
 */
export bool returnsAValue(string n) { return n != "" && n != "void"; }

/**
 * Whether `from` to `to` loses nothing, so plain `as` is the operator.
 *
 * Measured, not derived. There is no tidy formula: `u32 -> u64` is lossless and `i32 -> u64` is not,
 * because the first cannot be negative; `f32 -> f64` is and `i64 -> f64` is not, because 53 bits of
 * mantissa do not hold 64 of integer. A rule invented to cover the first six would have been wrong
 * about the seventh, so this is the set the reference agrees to, and the grid in
 * `test/typecheck.test.ts` re-derives it from the reference on every run rather than trusting it.
 */
bool losslessCast(string from, string to) {
  // A `bool` widens to every numeric type and needs no help doing it — `x as! i32` on a bool is
  // *"lossy cast not needed"*. The other direction is lossy, and takes `as!` or `as~` but not `as@`:
  // there is no raw conversion to a bool, because the bit pattern is not the question.
  if (from == "bool") {
    return to == "i32" || to == "i64" || to == "u32" || to == "u64" || to == "f32" || to == "f64";
  }
  if (from == "i32") { return to == "i64" || to == "f64"; }
  if (from == "u32") { return to == "i64" || to == "u64" || to == "f64"; }
  if (from == "f32") { return to == "f64"; }
  return false;
}

/**
 * Whether `as@` — reinterpret the bits — is available for this conversion.
 *
 * Also measured. It is close to "the target is an integer no wider than the source", and that rule
 * is wrong for `f64 -> i64`, which the reference refuses while allowing `f64 -> i32`. Rather than
 * carry a formula with an exception, this carries the pairs.
 */
bool rawCast(string from, string to) {
  if (from == "i32") { return to == "u32"; }
  if (from == "u32") { return to == "i32"; }
  if (from == "i64") { return to == "i32" || to == "u32" || to == "u64"; }
  if (from == "u64") { return to == "i32" || to == "u32" || to == "i64"; }
  if (from == "f32" || from == "f64") { return to == "i32" || to == "u32"; }
  return false;
}

/** Whether `s` ends with `suffix`. wac has no string method for it. */
bool endsWith(string s, string suffix) {
  u8[] a = s.toBytes();
  u8[] b = suffix.toBytes();
  if (b.len() > a.len()) { return false; }
  for (i32 i = 0; i < b.len(); i++) {
    if (a[a.len() - b.len() + i] != b[i]) { return false; }
  }
  return true;
}

/**
 * The template name in an instantiation — `Box` in `Box<i32>` — or `""` when it is not one.
 *
 * Everything the checker knows about a generic is recorded under the template, because that is the
 * only place its fields are written down. So every lookup that takes an owner has to come back here
 * first, and the type arguments are what it substitutes afterwards.
 */
string genericBase(string t) {
  if (!endsWith(t, ">")) { return ""; }
  u8[] a = t.toBytes();
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 60) {
      u8[] out = u8[i]();
      for (i32 j = 0; j < i; j++) { out[j] = a[j]; }
      return string.fromBytes(out);
    }
  }
  return "";
}

/**
 * The type arguments of an instantiation, split at the commas that are not inside another one.
 *
 * `Pair<Vec<i32>, f64>` has two arguments and four commas' worth of temptation to get this wrong, so
 * the split counts `<` and `>` depth rather than looking for a separator.
 */
string[] genericArgs(string t) {
  string base = genericBase(t);
  if (base == "") { return string[0](); }
  u8[] a = t.toBytes();
  i32 start = base.toBytes().len() + 1;
  i32 end = a.len() - 1;
  i32 n = 1;
  i32 depth = 0;
  for (i32 i = start; i < end; i++) {
    if (a[i] == 60) { depth = depth + 1; }
    else if (a[i] == 62) { depth = depth - 1; }
    else if (a[i] == 44 && depth == 0) { n = n + 1; }
  }
  string[] out = string[n]();
  i32 at = 0;
  i32 from = start;
  depth = 0;
  for (i32 i = start; i <= end; i++) {
    bool cut = i == end;
    if (i < end) {
      if (a[i] == 60) { depth = depth + 1; }
      else if (a[i] == 62) { depth = depth - 1; }
      else if (a[i] == 44 && depth == 0) { cut = true; }
    }
    if (!cut) { continue; }
    i32 lo = from;
    while (lo < i && a[lo] == 32) { lo = lo + 1; }
    u8[] piece = u8[i - lo]();
    for (i32 j = 0; j < piece.len(); j++) { piece[j] = a[lo + j]; }
    out[at] = string.fromBytes(piece);
    at = at + 1;
    from = i + 1;
  }
  return out;
}

/** The template an instantiation is of — `Box` for `Box<i32>` — or the type itself when it is not one. */
string templateOf(string t) {
  string base = genericBase(t);
  return base == "" ? t : base;
}

/**
 * A type written inside a generic, read in the world of one of its instantiations.
 *
 * `T` inside `Box<T>` is `i32` when the owner is `Box<i32>`, and `T[]` is `i32[]` — the suffixes come
 * along, because a parameter can appear under any number of them. A type that mentions no parameter
 * comes back unchanged, which is most of them.
 *
 * Returns unknown when the owner is not an instantiation but the written type still names a
 * parameter: that is a generic's member read without knowing what it was instantiated with, and
 * there is no answer to give.
 */
string substituteType(C c, string owner, string written) {
  string base = genericBase(owner);
  string template = base == "" ? owner : base;
  i32 si = c.structAt(template);
  // **An enum instance is not in the struct table.** `Wrap<i32>` owns a payload written `Box<T>`,
  // and asking the struct table what `Wrap`'s parameters are called answered *nothing* — so the
  // payload kept its `T` and `Wrap.W(Box(5))` read as a field mismatch. The two tables answer the
  // same question about the same kind of name; only one of them was ever asked. `spec/cases/0046`.
  i32 ei = si >= 0 ? -1 : c.enumAt(template);
  string[] params = string[0]();
  if (si >= 0) {
    params = string[c.structParamCount[si]]();
    for (i32 i = 0; i < params.len(); i++) {
      params[i] = c.structParamNames[c.structParamAt[si] + i];
    }
  } else if (ei >= 0) {
    params = string[c.enumParamCount[ei]]();
    for (i32 i = 0; i < params.len(); i++) {
      params[i] = c.enumParamNames[c.enumParamAt[ei] + i];
    }
  }
  if (params.len() == 0) { return written; }

  // Peel `[]` and `?` off, substitute the core, and put them back in the order they came off.
  string core = written;
  string suffix = "";
  for (i32 guard = 0; guard < 8; guard++) {
    if (endsWith(core, "[]")) { core = dropLast(core, 2); suffix = "[]" + suffix; }
    else if (endsWith(core, "?")) { core = dropLast(core, 1); suffix = "?" + suffix; }
    else { break; }
  }

  string[] args = genericArgs(owner);
  // **A bare template substitutes nothing.** Inside `Map<K, V>`'s own body the receiver is `Map`,
  // with no arguments to put anywhere — `K` means `K` there and the written type is already the
  // answer. Without this the recursion below rebuilt `MapEntry<K, V>` out of nothing and reported a
  // field against a type that does not exist.
  if (args.len() == 0) {
    // **Outside the template's own body a bare parameter is unknown, not a type.** Inside `Map<K,
    // V>` the receiver is `Map` and `K` means `K` — that is the case above. At a call site, `Box(5)`
    // is a bare construction whose `T` the arguments decide, and answering `T` reported the literal
    // against a type nobody wrote: *expected T, found i32*. The parameters being active is what
    // separates the two, exactly as it does everywhere else in this file.
    for (i32 i = 0; i < params.len(); i++) {
      if (params[i] == core && !isActiveParam(c, core)) { return typeNone(); }
    }
    return written;
  }
  for (i32 i = 0; i < params.len(); i++) {
    if (params[i] != core) { continue; }
    if (i >= args.len()) { return typeNone(); }
    return args[i] + suffix;
  }
  // **And inside a funcref**, which is a type holding one just as much as `Option<V>` is. A generic
  // whose method takes an `fn[T(i32)]`, or whose field is an `fn[T()]`, kept its `T` here and every
  // question about it was asked against a type nobody wrote. `issues/lang/0141` is where it showed:
  // a lambda handed to `Pending.of` was offered `fn(i32) -> T` as its target and could not match it.
  if (startsWithFn(core)) {
    string fret = funcrefReturn(core);
    if (fret != "") {
      string out = "fn(";
      for (i32 i = 0; i < funcrefParamCount(core); i++) {
        if (i > 0) { out = out + ", "; }
        out = out + substituteType(c, owner, funcrefParamAt(core, i));
      }
      return out + ") -> " + substituteType(c, owner, fret) + suffix;
    }
  }
  // **And inside an instantiation.** `Map<K, V>.get` returns `Option<V>`, whose core is not a
  // parameter — it is a type *holding* one. Answering `Option<V>` for a `Map<string, i32>` made
  // `Option<i32> got = m.get(k);` a mismatch against a type nobody wrote. Substituting the arguments
  // and rebuilding is the same rule one level down, and it recurses because `Map<K, Vec<V>>` exists.
  string inner = genericBase(core);
  if (inner != "") {
    string[] iargs = genericArgs(core);
    string out = inner + "<";
    for (i32 i = 0; i < iargs.len(); i++) {
      if (i > 0) { out = out + ", "; }
      out = out + substituteType(c, owner, iargs[i]);
    }
    return out + ">" + suffix;
  }
  return written;
}

/** `s` without its last `n` bytes. */
string dropLast(string s, i32 n) {
  u8[] a = s.toBytes();
  if (n > a.len()) { return ""; }
  u8[] out = u8[a.len() - n]();
  for (i32 i = 0; i < out.len(); i++) { out[i] = a[i]; }
  return string.fromBytes(out);
}

/**
 * Whether a type is held *by value* — a number or a boolean.
 *
 * The concept `isPrimitiveName` keeps getting used for and is not: `string` is in that list, because
 * the list is about how a type is **passed**, and a string is nonetheless a reference. It can be
 * null, so `s is null` is a fair question; it can be cast to itself, so `s as string` is not
 * redundant; it has methods, so `s.slice(…)` is not a call on something with none.
 *
 * Three rules have now been written with `isPrimitiveName` where they meant this, and each reported
 * working code until it was corrected. Naming the distinction is cheaper than remembering it.
 */
bool isValueType(string n) { return isPrimitiveName(n) && n != "string"; }

/** Whether a type is one of the integers, which is what the bitwise operators and `~` demand. */
bool isIntegerName(string n) {
  return n == "i32" || n == "i64" || n == "u32" || n == "u64";
}

/** Whether a type is nullable, which is one of the ways to have a default value: null. */
bool isNullableName(string n) { return endsWith(n, "?"); }

/** The type inside a `T?`, or `""` when it is not one. */
string withoutNull(string n) {
  if (!endsWith(n, "?")) { return ""; }
  return dropLast(n, 1);
}

/**
 * Whether a type is one of the language's references.
 *
 * A predicate a *deleted* helper used to carry, and deleting it is how its list stopped being kept:
 * the rules that survived asked about structs and arrays and forgot enums, and `a == b` on two of
 * them was accepted for as long as that lasted. So it is back, complete, and it is the one place the
 * question is answered — comparisons and arithmetic both call it, which is what stops the two lists
 * drifting apart again.
 *
 * `anyref` and `i31ref` are here because they are references that resolve to themselves rather than
 * to a declaration, so every `isStruct`-shaped question answers no about them. A 3,600-cell sweep
 * against the reference is what found that; nobody was going to write `anyref < anyref` by hand.
 */
bool isReferenceName(C c, string t) {
  if (t == typeNone() || t == "") { return false; }
  if (isNullableName(t)) { return true; }
  if (t == "string" || t == "anyref" || t == "i31ref") { return true; }
  return isArrayName(t) || c.isStruct(t) || c.isEnum(t) || startsWithFn(t);
}

/**
 * Whether a value of type `got` may be where a `want` is expected.
 *
 * Not equality, because the language has one widening this slice can see: a non-null value goes into
 * a nullable slot, so `P? q = p;` is legal for a `P`. The other direction is not — `P q = p;` for a
 * `P?` is *"cannot assign nullable to non-null"* — but that is a **different family** with its own
 * message, so this answers `true` for it and stays quiet. Saying nothing about a program the
 * reference rejects is a subset checker doing its job; saying the wrong thing about it is not.
 */
export bool assignable(C c, string want, string got) {
  if (want == "" || got == "") { return true; }
  if (want == got) { return true; }
  if (withoutNull(want) == got) { return true; }
  // A nullable source is a hatch **only when its base would fit**. `P?` into a `P` is the
  // nullable-into-non-null family and reports there; `P?` into an `i32` is an ordinary mismatch and
  // was silent for as long as this said "any nullable is assignable to anything". The sweep found it
  // forty times over — one cell per (nullable type, unrelated slot) — which is what a blanket
  // exemption looks like from the outside: not a wrong answer anywhere, just no answer at all.
  // Both nullable: the question is entirely about the bases, and `Circle?` goes into a `Shape?` for
  // the same reason a `Circle` goes into a `Shape`. Unwrapping only the source compared `Shape?`
  // against `Circle` and called a working program wrong — the reference corpus caught it where the
  // sweep did not, because the sweep's accepted half has no nullable-child-into-nullable-parent cell.
  if (isNullableName(want) && isNullableName(got)) {
    return assignable(c, withoutNull(want), withoutNull(got));
  }
  if (isNullableName(got)) { return assignable(c, want, withoutNull(got)); }
  // A child goes into a parent's slot without a cast; the other direction is the downcast that needs
  // `as!`. Upcasting *by assignment* is the same fact as upcasting by cast, one syntax along, and was
  // missed because nothing in the spec corpus assigns a child to a parent.
  if (c.isStruct(want) && c.isStruct(got) && descendsFrom(c, got, want)) { return true; }
  // **A variant is a value of its enum.** `Option<i32> a = Option.Some(5);` — the source has the
  // variant's own type, which is what the reference answers too (*"expected i32, got A"*), and the
  // slot has the enum's. Compared against the *template*, so an instance takes its own variants:
  // `Option<i32>` accepts `Some`, and `Other<i32>` does not.
  // Under any `?` as well: `E? e = E.A(5);` is the nullable slot taking a value, and the two
  // questions — is it the right type, may it be absent — are separate ones.
  string wantCore = withoutNull(want) == "" ? want : withoutNull(want);
  string wantBase = genericBase(wantCore) == "" ? wantCore : genericBase(wantCore);
  if (c.isEnum(wantBase) && c.variantArityIn(wantBase, got) >= 0) { return true; }
  // `anyref` holds any **reference**: a struct, an array, a string, a nullable one of those. Not a
  // primitive — `anyref r = someI32` is a mismatch — so this is not simply "accepts everything".
  //
  // **And an `i31ref`**, which is the one name that was missing: an integer packed *into* a
  // reference is a reference, and that is the entire reason the type exists — it is how an unboxed
  // number and a heap object share one container. `items[0] = 7 as! i31ref;` in `spec/tour.wac` was
  // reported as a mismatch until the repository's own code was put to this checker for the first
  // time. Answered here rather than in `isReferenceType`, which also decides which *casts* are
  // reference casts — and `i31ref as i32` is a conversion, not a downcast.
  if (want == "anyref") { return got == "i31ref" || isReferenceType(c, got); }
  // **And `anyref?`**, which is the same top type with the same rule: `anyref? ctx;` holding a
  // struct is how `packages/sh` carries the context its interrupt callback is handed, and refusing
  // it stopped `packages/ssh/src/sshd.wac` compiling. The line above answers for `anyref` and the
  // `withoutNull(want) == got` line above that answers when the names match exactly — a struct into
  // a nullable top type fell between the two.
  if (withoutNull(want) == "anyref") { return got == "i31ref" || isReferenceType(c, got); }
  return false;
}

/**
 * Whether a type is held by reference, which is what `anyref` accepts and primitives are not.
 *
 * **An enum is one**, and this said it was not — so `anyref r = someEnum` was refused, which is the
 * worse kind of wrong: a gap costs a diagnostic nobody gets, and this cost a program nobody could
 * compile. The fact was not even unknown. `isCastRef` below carries a comment saying "an enum and a
 * funcref are references too", written next to the helper that did not use it.
 *
 * A funcref stays out, and that is not an oversight repeated: the reference refuses
 * `anyref r = someFn` as well, so the two agree and the 324-cell grid is what says so.
 */
bool isReferenceType(C c, string t) {
  string core = withoutNull(t);
  string at = core == "" ? t : core;
  return isArrayName(at) || at == "string" || at == "anyref" || c.isStruct(at) || c.isEnum(at);
}

/**
 * Whether this is specifically a nullable value going into a non-null slot.
 *
 * Its own diagnostic — *"cannot assign nullable to non-null"* — rather than a type mismatch, because
 * the reference words it that way and a caller can tell them apart: one says the types are unrelated,
 * the other says they are the same type and one of them might not be there.
 *
 * `assignable` still answers `true` for it, so the mismatch rules stay quiet and this reports instead
 * of both firing at one position.
 */
export bool nullableIntoNonNull(string want, string got) {
  if (want == "" || got == "") { return false; }
  if (!endsWith(got, "?")) { return false; }
  if (endsWith(want, "?")) { return false; }
  return withoutNull(got) == want;
}

/** Whether `==` is refused on this type because it is a reference. Arrays are, as structs are. */
bool isArrayName(string n) { return endsWith(n, "[]"); }

/**
 * The storage types, which WasmGC allows as array elements and nowhere else.
 *
 * The distinction that matters is **position**, and it took a false alarm on 113 files to see it.
 * `u8 x = 5;` is an error — a packed type cannot be a local — while `bytes[i] = 5;` is the ordinary
 * way every byte buffer in this repository is written, because there the `u8` is an array element and
 * an `i32` truncates into it at the store. A rule about the type alone cannot tell those apart, and
 * the one here was written from the return-type grid, where packed accepts nothing.
 */
bool isPackedName(string n) {
  return n == "u8" || n == "u16" || n == "i8" || n == "i16";
}

// A `comparableByValue(n)` — `n == "" || n == "string" || isPrimitiveName(n)` — was here, exported and
// called by nothing. This file already carries the argument against it: `isValueType` above exists
// because "three rules have now been written with `isPrimitiveName` where they meant this, and each
// reported working code until it was corrected". A fourth predicate in the same family, with no
// caller to say which rule it is for, is the next one of those waiting to happen.

/** The families a literal is polymorphic over. */
export i32 litNone() { return 0; }
export i32 litInteger() { return 1; }
export i32 litFloat() { return 2; }
export i32 litBool() { return 3; }
export i32 litString() { return 4; }
/**
 * `null`, which is also what an *uninitialised* declaration holds.
 *
 * `i32 z;` and `i32 x = null;` parse to the same thing — a `NullLit` init — and the reference gives
 * them the same diagnostic, *"expected i32, got null"*. So the missing initialiser needs no separate
 * rule; it is already this one.
 */
export i32 litNull() { return 5; }

/** The checker's state: what it is reading, and what it has found. */
export struct C {
  u8[] src;
  i32[] toks;
  /**
   * The names declared in the function being checked, and the primitive each was declared with.
   *
   * Two parallel arrays because wac has no map, which is the shape every symbol table in this
   * package will have. Rebuilt per function: a name means nothing outside the one that declared it.
   */
  string[] names;
  string[] types;
  /** Whether each name was declared `const`. */
  bool[] nameConsts;
  /**
   * Whether that constness came only from **aliasing** something const, rather than from the
   * declaration saying so.
   *
   * The two are one flag everywhere else and they answer different questions. `N? cur = this.head;`
   * in a `const this` method may not be written *through* — that is the laundering the alias rule
   * exists to stop — but rebinding the local mutates nothing, and refusing that made every list walk
   * in the spec illegal.
   */
  bool[] nameAliasOnly;
  i32 nameCount;
  /** Enum names. An enum has no default value, which is the only thing recorded about one here. */
  string[] enumNames;
  i32 enumCount;
  /**
   * A generic enum's type parameters, laid out exactly as a struct's are.
   *
   * Nothing recorded them until `Wrap<i32> w = Wrap.W(Box(5))` needed them: substituting a type
   * argument into a payload asks the owner what its parameters are called, and an enum could not
   * answer — so `Box<T>` stayed `Box<T>` and the constructor's argument read as a mismatch.
   */
  string[] enumParamNames;
  i32[] enumParamAt;
  i32[] enumParamCount;
  i32 enumParamTotal;
  /** How many of `names` are module-level and outlive a function. */
  i32 globalCount;
  /**
   * Every function in the file, and the primitives of its parameters.
   *
   * The first table here that outlives one function: locals are cleared per declaration, and this is
   * not — a call names something declared elsewhere in the file, and often further down it. Flat
   * storage because wac has no map and no growable array of structs: `funcParamAt` and
   * `funcParamCount` index into one shared `funcParamPrims`, which is the same shape `lex.wac` uses
   * for tokens and for the same reason.
   */
  /** The structs declared in this file, so a name can be known to be a reference type. */
  string[] structNames;
  /** Each struct's parent, or `""`. Parallel to `structNames`, so inheritance is one hop per lookup. */
  string[] structParents;
  /**
   * The names of each struct's type parameters — `T` for `Box<T>`, `A` and `B` for `Pair<A, B>`.
   *
   * Flat, with `structParamAt` and `structParamCount` indexing into it, which is the same shape the
   * function parameters use and for the same reason: wac has no growable array of arrays. These are
   * what a field type written `T` is substituted *from*, so without them a generic's fields are text.
   */
  string[] structParamNames;
  i32[] structParamAt;
  i32[] structParamCount;
  i32 structParamTotal;
  /**
   * Whether each struct takes type parameters.
   *
   * Recorded rather than inferred from an empty field table, because "generic" and "has no fields"
   * are different facts and only one of them means *say nothing*. A generic's fields and methods are
   * not modelled — `struct Box<T> { T v; }` has a field whose type is the parameter — so every rule
   * that would consult them has to know to stop, and an empty table cannot tell it why it is empty.
   */
  bool[] structGenerics;
  i32 structCount;
  /**
   * Every field of every struct, as three parallel arrays.
   *
   * Flat rather than nested because wac has no map and no growable array of structs, and a field
   * lookup is rare enough that a scan costs nothing at this size. `structNames` could have held an
   * offset and a count, as the function table does — it does not, because a field is looked up by
   * (struct, name) rather than by position, so the offset would buy nothing.
   */
  /**
   * Every method of every struct: who owns it, its name, and the two facts a call site needs.
   *
   * `isStatic` is "declared without `this`", which is what makes `P.mk()` legal and `p.mk()` not.
   * `isConst` is `const this`, which decides whether a const receiver may call it.
   */
  string[] methodOwners;
  string[] methodNames;
  bool[] methodStatics;
  bool[] methodConsts;
  /**
   * What each method returns, as written — `T` inside a generic, substituted at the call site.
   *
   * Absent until now, so a method call typed as *unknown* and every rule downstream of one stopped
   * there: `this.getInner().mutate()` could not be refused because nothing knew what `getInner()`
   * handed back, and `S.make` as a value had no type to mismatch against.
   */
  string[] methodReturns;
  /**
   * Each method's parameter types, flat, with `methodParamAt` and `methodParamCount` indexing in.
   *
   * Only a **static** method needs them: taking one as a value produces a funcref, and a funcref
   * spells its parameters. An instance method cannot be taken as a value at all, so its parameters
   * are recorded and never read — which is cheaper than a second table that leaves them out.
   */
  string[] methodParamTypes;
  i32[] methodParamAt;
  i32[] methodParamCount;
  i32 methodParamTotal;
  i32 methodCount;
  string[] fieldOwners;
  string[] fieldNames;
  string[] fieldTypes;
  /** Whether each field was declared `const`. */
  bool[] fieldConsts;
  i32 fieldCount;
  string[] funcNames;
  /** Each function's return type, so a call has one. */
  string[] funcReturns;
  i32[] funcParamAt;
  i32[] funcParamCount;
  string[] funcParamTypes;
  /**
   * Whether each function takes type parameters, and what they are called.
   *
   * A generic function's signature is written in its own parameters, which mean nothing at a call
   * site until they are bound. Recorded **as written** now rather than blanked, because binding them
   * is exactly what inference does — and the flag is what keeps the ordinary argument check from
   * reading `Box<T>` as a type nobody has.
   */
  bool[] funcGenerics;
  string[] funcTypeParamNames;
  i32[] funcTypeParamAt;
  i32[] funcTypeParamCount;
  i32 funcTypeParamTotal;
  i32 funcCount;
  i32 funcParamTotal;
  /**
   * How many loops and switches enclose the statement being checked.
   *
   * On the state rather than threaded through `checkStmt`, which every rule here would otherwise have
   * to carry to reach the two that use it. Switches count: `break` leaves one, and the reference also
   * accepts `continue` inside one, which is measured rather than inferred from its message.
   */
  i32 loopDepth;
  /**
   * What the expression **about to be walked** is required to be, or unknown.
   *
   * The one piece of information that flows *down* the tree rather than up. Every other rule here
   * reads an expression and asks what it is; a bare `Box(1.0)` cannot be asked that, because its type
   * arguments are inferred from wherever it is going. Carried on the state rather than threaded
   * through `checkExpr`, which forty call sites would otherwise have to pass along.
   *
   * Read and **cleared** at the top of `checkExpr`, so it reaches exactly one expression: the one the
   * context set it for. A sub-expression of that one is in a position of its own, and `Box(1).get()`
   * is the case that proves it — the receiver inherits nothing from the `return` it sits under.
   */
  string expected;
  /** `(code, line, col)` triples, the same shape `dumpErrors` returns for the parser. */
  i32[] errors;
  /**
   * The operands, one per error: `expected bool, found i32`, or `""` where they were not recorded.
   *
   * `spec/spec/errors.md` calls this the `annotation` — the text after the underline — and it is the
   * difference between a diagnostic that names the rule and one that helps. It sits beside the
   * triples rather than inside them because the triples are `i32` and this is not; every site that
   * has the operands in hand passes them, and a site that does not says nothing rather than guessing.
   */
  string[] errorNotes;
  /**
   * How wide each diagnostic is, or `0` where nothing recorded one.
   *
   * **Zero means unknown, not one.** The parse phase has always carried a width — the token it
   * stopped on — and the checker had none, so every check diagnostic underlined a single character
   * whether or not that was the truth. Recording it where a token is in hand makes the two phases
   * comparable, and leaving it `0` elsewhere keeps "we did not measure this" distinguishable from
   * "this really is one character wide", which is what `;` is.
   */
  i32[] errorWidths;
  i32 errorCount;
  /** Whether diagnostics are being discarded — see `report`. */
  bool quiet;
  /**
   * Whether a type name that resolves to nothing is an error yet.
   *
   * Off until every declaration is in, because until then "not declared" only means "not declared
   * *yet*" — a struct whose field names a struct further down the file would be refused on the way
   * past. `checkModule` turns it on once, after the declaration passes.
   */
  bool scopeTypes;
  /**
   * The type parameters of the generic function being checked, which are **unknown types**.
   *
   * `T oops<T>(T a) { i32 x = "hello"; return a; }` is an error `spec/spec/generics.md` names, and
   * the error has nothing to do with `T` — so the body is checked, and every question about `T`
   * answers the way this checker answers every question it cannot resolve: with nothing.
   */
  string[] activeParams;
  i32 activeParamCount;
  /**
   * The generic function whose body is being walked, or `""`.
   *
   * Only self-recursion needs it: `grow<T>` calling `grow` with a `Box<T>` instantiates itself
   * again with a bigger type, which never bottoms out. Calling *another* generic that way is
   * finite, so the name is the whole of what separates the two.
   */
  string activeFunc;
  /**
   * Which enum each variant belongs to, and how many payload fields it has.
   *
   * A variant is *also* declared as a struct under its bare name, because that is how `is Circle`
   * and `case Circle:` write it and how a narrowed value finds its payload. That spelling cannot
   * tell two enums apart: `enum Opened { Ok(i32 fd) }` beside `enum Found { Ok(i32 at) }` is one
   * `Ok` in the struct table holding both payloads, so asking it how many arguments `Ok` takes
   * answers two and belongs to neither. Recorded here per declaration instead — no de-duplication,
   * because the duplication is the fact being recorded.
   */
  string[] variantOwners;
  string[] variantNames;
  i32[] variantArities;
  /** Whether each variant can be written bare — see `markVariantBare`. */
  bool[] variantBare;
  i32 variantCount;

  /**
   * What the file being declared calls a type, against what the file that imported it calls it.
   *
   * `import { Dup as DupB } from "./b.wac"` means `b.wac`'s `Dup` enters this file as `DupB`, and it
   * has to enter under that name throughout — not only as a declaration but everywhere `b.wac`'s own
   * signatures mention it, or `DupB b = fromB()` binds a type whose fields belong to somebody else's
   * `Dup`. Empty except while an imported file is being declared.
   */
  string[] renameFrom;
  string[] renameTo;
  i32 renameCount;

  /**
   * Each method's body, so a call site can ask what its `return`s hand back.
   *
   * `const this` makes what the receiver *reaches* const, and a call through a const receiver has to
   * inherit that — an accessor handing back a field is a way to launder it. But a method whose every
   * `return` constructs a value out of copies reaches nothing, and treating its result as const is
   * what stopped `Counter copy = this.clone(); copy.bump();` from compiling [issue 0060].
   *
   * The body rather than the answer, because the answer needs the field types of whatever is being
   * constructed and the declaration pass runs before the types it would ask about are all known —
   * asking there reported 38 working files against a position in the linked blob.
   */
  Stmt[][] methodBodies;

  /**
   * Types declared for their *members* and not for their *name*.
   *
   * A file may only write the type names it imported, and it may reach further than that: `Cli`'s
   * fields hold `fn[Pending<i32>()]`, so calling one gives a `Pending<i32>` in a file that never
   * named `Pending`. Both facts are true at once, and declaring the reachable type the ordinary way
   * makes only the first one false — `knownTypeName` would then accept `Pending<i32> p`, which the
   * reference refuses with *"undefined type 'Pending'"*.
   *
   * So the declaration happens and this list says it does not carry a name into scope.
   * `issues/lang/0132` is what the missing declaration cost: `.wait()` on a struct nobody had
   * declared answers nothing, and every rule downstream of it goes quiet.
   */
  string[] unnameable;
  i32 unnameableCount;

  /**
   * Warnings: a code, a line and a column each, beside the errors rather than among them.
   *
   * **A parallel table, not a severity column.** Diagnostics are a flat `i32[]` of three slots each
   * with a parallel notes array, touched at twenty-odd sites; adding a fourth slot would change the
   * stride and every one of them. This disturbs nothing, and a warning that is not an error must not
   * reach any count that decides whether a compile succeeded. `issues/lang/0126`.
   */
  i32[] warnings;
  i32 warnCount;
  /**
   * Block scope, as two parallel facts about the name table — `issues/lang/0122`.
   *
   * `nameScope[i]` is the `Stmt[]` body the name was declared in. Every scope in wac has one, and
   * arrays are references, so the body *is* the identity with nothing for two walks to keep in
   * step. `openScopes[0..openScopeCount)` is what is open now. A name is visible when the body
   * that declared it is one of them, filtered inside the lookups rather than at their call sites.
   */
  Stmt[][] nameScope;
  Stmt[][] openScopes;
  i32 openScopeCount;
  /**
   * The scope of a name declared while none was open — one array, compared by identity.
   *
   * It cannot be a fresh `Stmt[]()` per declaration: `is` is identity, so each would match nothing
   * and the name would be invisible everywhere. It cannot be an empty array either, because `{ }`
   * is a real scope with an empty body. A caller that declares names without pushing a scope is
   * saying it does not track scope, and the answer for it has to be *visible*, not *nowhere*.
   */
  Stmt[] noScope;
  /**
   * The return type a `return` inside a lambda answers to, or `""` when not inside one.
   *
   * `checkStmt` takes the enclosing function's return as an AST `Ty`, and a lambda has no return type
   * written — `design/lang/0002` takes it from the `fn[…]` the lambda is checked against, which is a
   * *string*. Every `Ty` variant carries a token, so one cannot be synthesised from a name, and this
   * is the seam that avoids needing to: the `Return` case prefers this when it is set.
   *
   * Saved and restored around the body rather than cleared, because a lambda can sit inside a lambda
   * and the inner one's return type must not become the outer's when it finishes.
   *
   * Saved and restored around the body rather than cleared, because a lambda can sit inside a lambda
   * and the inner one\'s return type must not become the outer\'s when it finishes.
   */
  string lambdaReturn;

  /**
   * Whether `expected` is empty because **nothing could say** what was wanted, as opposed to nothing
   * wanting anything.
   *
   * `typeNone()` is `""`, so those two facts share a spelling — and they need different answers in
   * exactly one place. `i32 g = () => 42;` has a slot and it is not a funcref, which is an error a
   * lambda cannot report any other way, since unknown is assignable to everything. `Pending.of(0,
   * (i32 id) => v, …)` in a file checked **without its imports** has no slot at all, because
   * `Pending` is a name this file does not contain — and refusing there is inventing a diagnostic
   * about a program that is fine.
   *
   * That is not hypothetical: `rung 3` type-checks every `.wac` file in the repository single-file
   * and requires silence, and the first package file to hold a lambda over an imported type
   * (`packages/platform/src/frame.wac`) produced 29 false alarms.
   *
   * Set for one argument at a time by the call arm, read and cleared by `checkExpr` beside
   * `expected` so the two always travel together.
   *
   * `C` is built positionally, and `expected` and `lambdaReturn` are both `string`s, so a value
   * inserted next to them could land in the wrong slot with the types still agreeing and nothing
   * failing. A `bool` has neither problem.
   */
  bool expectedUnknown;



  /**
   * Two capacities, because the tables here hold two different things.
   *
   * `locals` sizes the four that are *per function* — the name table and what goes beside it, which
   * `clearScope` empties between functions, so it only ever holds one body's worth. `decls` sizes
   * everything else: structs, fields, methods, variants, functions, which accumulate across every
   * file the entry imports.
   *
   * They were one number, and it was the entry file's token count. Sizing both by the closure's
   * tokens fixed the overflow (`issues/lang/0098`) and cost 230 MB, because a token is the wrong
   * unit for a table that holds declarations — `issues/lang/0099`.
   */
  C create(u8[] src, i32[] toks, i32 locals, i32 decls) {
    return C(src, toks, string[locals](), string[locals](), bool[locals](),
             bool[locals](), 0,
             string[decls](), 0,
             string[decls](), i32[decls](), i32[decls](), 0,
             0,
