  /**
   * The table index `name` resolves to here, or -1 for a name nothing in scope declared.
   *
   * **Innermost wins, not latest.** The declare walk declares every name in a function before the
   * check walk reads any of them, so a `k` declared later in the function body is already in the
   * table while an inner loop's own `k` is being checked — and both are in scope, so a scan that
   * simply takes the last match gives the inner `k` the outer one's type. That is not theoretical:
   * `packages/crypto/src/fieldp.wac` has an `i32 k` loop counter and an `i64 k` further down the
   * same function, and it reported `i64 and i32` on `k < n`. Depth separates them; among equal
   * depths the later declaration wins, which is what shadowing means.
   */
  i32 findName(const this, string name) {
    i32 top = this.scopeTop();
    i32 best = -1;
    i32 bestDepth = -1;
    for (i32 i = this.nameCount - 1; i >= 0; i--) {
      if (this.names[i] != name) { continue; }
      i32 d = this.depthOf(i);
      if (d > bestDepth) {
        best = i;
        bestDepth = d;
        // Nothing can be nested deeper than the scope we are standing in.
        if (d == top) { return best; }
      }
    }
    return best;
  }

  void declareEnum(this, string name, string[] typeParams) {
    if (this.enumCount >= this.enumNames.len()) { return; }
    this.enumNames[this.enumCount] = name;
    this.enumParamAt[this.enumCount] = this.enumParamTotal;
    this.enumParamCount[this.enumCount] = typeParams.len();
    for (i32 i = 0; i < typeParams.len(); i++) {
      if (this.enumParamTotal >= this.enumParamNames.len()) { break; }
      this.enumParamNames[this.enumParamTotal] = typeParams[i];
      this.enumParamTotal = this.enumParamTotal + 1;
    }
    this.enumCount = this.enumCount + 1;
  }

  /** Which entry holds this enum, or -1. */
  i32 enumAt(const this, string name) {
    for (i32 i = 0; i < this.enumCount; i++) {
      if (this.enumNames[i] == name) { return i; }
    }
    return -1;
  }

  /** Record `Enum.Variant` with its payload count, ambiguity and all. */
  /**
   * Whether this variant has a bare name — false for a generic enum's, whose variants belong to its
   * instances. Kept beside the table rather than derived, because by the time somebody writes `is
   * Some` the enum's type parameters are three lookups away.
   */
  void markVariantBare(this, string name, bool bare) {
    for (i32 i = this.variantCount - 1; i >= 0; i--) {
      if (this.variantNames[i] == name) { this.variantBare[i] = bare; return; }
    }
  }

  void declareVariant(this, string owner, string name, i32 arity) {
    if (this.variantCount >= this.variantNames.len()) { return; }
    this.variantOwners[this.variantCount] = owner;
    this.variantNames[this.variantCount] = name;
    this.variantArities[this.variantCount] = arity;
    this.variantBare[this.variantCount] = true;
    this.variantCount = this.variantCount + 1;
  }

  /**
   * How many payload fields `Enum.Variant` has, or -1 when this enum has no such variant.
   *
   * Asked with **both** names, which is the whole point: the answer for `Found.Ok` is one whatever
   * `Opened.Ok` happens to hold.
   */
  i32 variantArityIn(const this, string owner, string name) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantOwners[i] == owner && this.variantNames[i] == name) {
        return this.variantArities[i];
      }
    }
    return -1;
  }

  /**
   * Is this the name of a variant of some enum that is in scope?
   *
   * Asked by name alone, unlike `variantArityIn`, because the question here is whether the file may
   * *write* the name at all — `x is Circle` needs `Circle` to have come from somewhere, and which
   * enum owns it is the next question rather than this one.
   */
  bool isVariantName(const this, string name) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantNames[i] == name && this.variantBare[i]) { return true; }
    }
    return false;
  }

  /** An enum has no default value, which is the only thing this pass records about one. */
  bool isEnum(const this, string name) {
    for (i32 i = 0; i < this.enumCount; i++) {
      if (this.enumNames[i] == name) { return true; }
    }
    return false;
  }

  void report(this, i32 code, i32 line, i32 col) {
    // **Quiet is for a file being read only for its declarations.** An import is walked to learn
    // what it declares, not to be judged: its diagnostics belong to its own compilation, and
    // reporting them here would put another file's line numbers in this file's answer.
    if (this.quiet) { return; }
    if (this.errorCount * 3 + 3 > this.errors.len()) { return; }
    // **The same complaint twice is one complaint.** A literal is now checked on two paths — the
    // one that types it and the one that only asks whether it fits — and an assignment takes both.
    // The reference reports it once, and a diagnostic list that says it twice is a list that
    // disagrees about how many things are wrong.
    if (this.errorCount > 0 &&
        this.errors[(this.errorCount - 1) * 3] == code &&
        this.errors[(this.errorCount - 1) * 3 + 1] == line &&
        this.errors[(this.errorCount - 1) * 3 + 2] == col) {
      return;
    }
    this.errors[this.errorCount * 3] = code;
    this.errors[this.errorCount * 3 + 1] = line;
    this.errors[this.errorCount * 3 + 2] = col;
    if (this.errorCount < this.errorNotes.len()) { this.errorNotes[this.errorCount] = ""; }
    this.errorCount = this.errorCount + 1;
  }

  /**
   * The same, with the operands the rule was broken by.
   *
   * Kept as a second entry point rather than a fourth parameter on `report`, because most of the
   * hundred-odd call sites have nothing to say and a required argument would have them all inventing
   * one. The note is added after the fact so the de-duplication in `report` still decides whether
   * there is an error here at all.
   */
  void reportWith(this, i32 code, i32 line, i32 col, string note) {
    i32 before = this.errorCount;
    this.report(code, line, col);
    if (this.errorCount == before) { return; }
    if (before < this.errorNotes.len()) { this.errorNotes[before] = note; }
  }

  /** The same, positioned *at a token* — which is what makes a width knowable. */
  void reportTok(this, i32 code, i32 tok, string note) {
    i32 before = this.errorCount;
    this.report(code, this.toks[tok * tokenStride() + 3], this.toks[tok * tokenStride() + 4]);
    if (this.errorCount == before) { return; }
    if (before < this.errorNotes.len()) { this.errorNotes[before] = note; }
    if (before < this.errorWidths.len()) { this.errorWidths[before] = this.toks[tok * tokenStride() + 2]; }
  }
}

/**
 * A token's kind.
 *
 * `Binary.op` is a token *index*, not a kind — `print.wac` renders it with `tok(op)`, which reads the
 * source text at that index. Comparing the index against a `kPlus()` constant compares an index to a
 * kind and is quietly always false, which is what the first version of the operand check did: it
 * compiled, ran, and reported nothing.
 */
i32 tokenKind(C c, i32 t) {
  if (t < 0) { return -1; }
  return c.toks[t * tokenStride()];
}

/** A token's line, for the diagnostics that name a keyword rather than a node. */
i32 tokenLine(C c, i32 t) { return c.toks[t * tokenStride() + 3]; }

/** A token's column, paired with `tokenLine`. */
i32 tokenCol(C c, i32 t) { return c.toks[t * tokenStride() + 4]; }

/** A token's source text. Primitive type names are ordinary identifiers, so this is how they are read. */
string tokenText(C c, i32 t) {
  if (t < 0) { return ""; }
  i32 start = c.toks[t * tokenStride() + 1];
  i32 len = c.toks[t * tokenStride() + 2];
  u8[] out = u8[len]();
  for (i32 i = 0; i < len; i++) { out[i] = c.src[start + i]; }
  return string.fromBytes(out);
}

/**
 * The canonical name of a declared type, or `typeNone` for one this slice cannot name.
 *
 * `Prim` and `Named` are both just their token's text — `i32` and `P` are the same question once a
 * type is a name. An array, a nullable or a funcref is unknown: they have names (`i32[]`, `P?`) that
 * this could spell, and nothing here compares them yet, so spelling them would be inventing a
 * capability the rules do not have.
 */
/**
 * Is this name something the file may write as a type?
 *
 * A struct or an enum it declared or imported, and `isDeclaredName` for everything else that carries
 * a name into scope — an imported alias the single-file slice knows only as unknown, and the two
 * things the spec says look like type names and are not: `f(x)` where `f` is a funcref, and
 * `x is Other` where `Other` is a variable, which is an identity test.
 */
bool knownTypeName(C c, string base) {
  // **Declared is not the same as in scope.** A type reached through an imported signature is
  // declared so that its members can be resolved, and writing its name is still an error — see
  // `C.unnameable`.
  if (c.isUnnameable(base)) { return false; }
  return c.isStruct(base) || c.isEnum(base) || c.isDeclaredName(base) || c.isVariantName(base);
}

export string typeOfTy(C c, Ty t) {
  match (t.kind) {
    case Prim(tok): { return tokenText(c, tok); }
    case Named(tok, typeArgs): {
      // A generic instantiation spells itself. `Box<i32>` and `Box<f64>` are different types and the
      // model here is that a type *is* its canonical name, so the name has to carry the arguments —
      // an earlier version returned unknown for all of them, which made every generic invisible.
      // Invariance then costs nothing: two instantiations differ exactly when their names do.
      // Under the importing file's name for it, when this is an imported file being declared: a
      // signature that says `Dup` in `b.wac` says `DupB` to the file that imported it that way.
      string base = c.renamed(tokenText(c, tok));
      // **A type parameter of the function being checked is an unknown type**, not a name. `T` in
      // `T oops<T>(T a)` stands for whatever a call site binds, so every question about it has an
      // answer this checker cannot compute — and answering with the letter itself made `return a;` a
      // mismatch against a type nobody declared.
      for (i32 i = 0; i < c.activeParamCount; i++) {
        if (c.activeParams[i] == base) { return typeNone(); }
      }
      // Spelled as identifiers and declared by nobody, so resolution would hunt for a declaration
      // and find none. They *are* types; what needed fixing was the hierarchy they sit in, which
      // `isReferenceType` answers.
      if (base == "anyref" || base == "i31ref") { return base; }
      // **The three reports below name the token, not the node's position.** They are the same place
      // — a `Named` type is positioned at its own name — and `reportTok` records the name's *width*
      // as well, which is what puts the caret under `Circle` rather than under its first letter.
      // Forty-seven of the corpus's 264 spanless diagnostics were this one code, the largest single
      // group; `waccx.test.ts` measures the share and holds a floor under it.
      // **A name that resolves to nothing is not a type this file may write.** Writing one requires
      // importing it, variants included (`§wac-type-name-scope-8vqk3mn`) — and the cost of not
      // saying so was a wrong answer rather than a missing message: an unresolved name had no type
      // index, so `x is Circle` fell back to a table keyed by bare name and answered about whichever
      // module's `Circle` was declared first.
      // **A template takes the number of arguments it declares.** `Box<i32, f64>` names no type, and
      // the arity is the one thing that can be checked here without instantiating anything.
      // `spec/cases/0072`.
      if (typeArgs.len() > 0) {
        i32 sat = c.structAt(base);
        if (sat >= 0 && c.structParamCount[sat] != typeArgs.len()) {
          c.reportTok(errUndefinedType(), tok, "");
          return typeNone();
        }
      }
      if (c.scopeTypes && !knownTypeName(c, base)) {
        c.reportTok(errUndefinedType(), tok, "no type " + base + " in scope");
        return typeNone();
      }
      // **A template is not a type.** `Box b = Box(1)` writes the name of a thing that takes an
      // argument and gives none, and the language wants `Box<i32>`. This was refused by accident
      // until now — the construction's field read as *expected T, found i32*, a complaint about the
      // wrong half of the program, and it went silent the moment a bare `Box(5)` stopped being asked
      // to be a `T`. Inside the template's own body the bare name is how the receiver is written,
      // which is what the active parameters say. `spec/cases/0088`.
      if (typeArgs.len() == 0) {
        i32 gsi = c.structAt(base);
        i32 gei = c.enumAt(base);
        bool template = (gsi >= 0 && c.structParamCount[gsi] > 0) ||
                        (gei >= 0 && c.enumParamCount[gei] > 0);
        if (template && c.activeParamCount == 0) {
          c.reportTok(errUndefinedType(), tok, base + " takes type arguments");
          return typeNone();
        }
        return base;
      }
      string out = base + "<";
      for (i32 i = 0; i < typeArgs.len(); i++) {
        string a = typeOfTy(c, typeArgs[i]);
        if (a == typeNone()) { return typeNone(); }
        if (i > 0) { out = out + ", "; }
        out = out + a;
      }
      return out + ">";
    }
    // `i32[]` and `P?` are names too, built from the name inside. An element or inner type this
    // slice cannot spell makes the whole thing unspellable rather than half-named: `Box<i32>[]` is
    // not `[]`.
    case Arr(elem): {
      string inner = typeOfTy(c, elem);
      if (inner == typeNone()) { return typeNone(); }
      return inner + "[]";
    }
    case Nullable(inner): {
      string base = typeOfTy(c, inner);
      if (base == typeNone()) { return typeNone(); }
      return base + "?";
    }
    // A funcref spells itself the way the reference words it — `fn(i32) -> i32` — so two of them are
    // the same type exactly when their parameters and return agree, which is what the language means
    // by assignable here. There is no variance: `fn(bool) -> i32` does not hold a `fn(i32) -> i32`.
    case Funcref(ret, params): {
      string out = "fn(";
      for (i32 i = 0; i < params.len(); i++) {
        string pt = typeOfTy(c, params[i]);
        if (pt == typeNone()) { return typeNone(); }
        if (i > 0) { out = out + ", "; }
        out = out + pt;
      }
      string rt = typeOfTy(c, ret);
      if (rt == typeNone()) { return typeNone(); }
      return out + ") -> " + rt;
    }
  }
}

/**
 * Report a literal that does not fit, with the caller's own code — unless the problem is the range,
 * which has a code of its own.
 *
 * Eight positions ask this question and the reference answers all of them the same way, so the choice
 * is one function here or the same three lines eight times. `mismatch` is what the caller calls a
 * wrong *family*; a float too large for an `f32` is a different complaint about a literal that was
 * otherwise the right kind.
 */
/**
 * A character literal holds exactly one character.
 *
 * Called from two places because a literal reaches the checker two ways: through `checkExpr`, and
 * through the fast path that asks only whether it *fits* a wanted type — `return 'ab'` and
 * `i32 x = 'ab'` take the second and never touched the first.
 */
void checkCharLiteral(C c, Expr e) {
  match (e.kind) {
    case IntLit(tok): {
      string lit = tokenText(c, tok);
      if (lit.len() < 2 || lit[0] != "'") { return; }
      string inner = lit.slice(1, lit.len() - 1);
      if (inner == "") {
        c.report(errCharLiteral(), e.line, e.col);
        return;
      }
      // An escape is one character by construction; anything else is one only if its first
      // character's encoding covers the whole of what is between the quotes.
      if (inner[0] != "\\" && utf8Width(inner) != inner.len()) {
        c.report(errCharLiteral(), e.line, e.col);
      }
    }
    else: { }
  }
}

void reportLiteral(C c, string want, Expr e, i32 mismatch, i32 line, i32 col) {
  checkCharLiteral(c, e);
  if (literalFits(c, want, e)) { return; }
  if (!acceptsLiteral(want, litFamily(c, e))) {
    // The literal's own family is what it was found to be: `1.5` in an `i32` slot is a float where an
    // integer was wanted, and saying so is the whole of the complaint.
    c.reportWith(mismatch, line, col, expectedFound(want, foundType(c, e)));
    return;
  }
  // A range complaint names the **literal**, where a family mismatch names the whole expression:
  // `i32 x = -1.5` is reported at the `-` and `f32 x = -1.0e40` at the `1`. Measured, and the pair is
  // worth stating together, because either one alone reads as an off-by-one against the other.
  Expr inner = innermostLiteral(e);
  c.reportWith(errFloatRange(), inner.line, inner.col, "out of range for " + want);
}

/** The literal under any signs — `1.0e40` in `-1.0e40`, and the expression itself otherwise. */
Expr innermostLiteral(Expr e) {
  match (e.kind) {
    case Unary(op, operand): { return innermostLiteral(operand); }
    else: { return e; }
  }
}

/**
 * A float literal's value, read out of its text.
 *
 * Needed for one rule and no other: an `f32` slot refuses a literal too large to be one, and the
 * boundary is the *value* rather than anything visible in the text — `3.4028235e38` fits and
 * `3.4028236e38` does not, and f32's maximum written out in full with no exponent at all fits. An
 * exponent check would have been wrong on both of those.
 *
 * Accumulated in `f64`, which has room to spare for the comparison. No sign: a leading `-` is a unary
 * operator and never part of the token, which the reference's own column confirms.
 */
/**
 * A float literal's value — read in `lit.wac`, which the emitter reads it in too.
 *
 * This used to have its own reader, and the two disagreed exactly where a reader written twice
 * always does: `f32 x = 1_0e38;` is out of range, and this one stopped at the underscore, saw `1`
 * and let it through. The reference has the same file for the same reason — its issue 0044.
 */
/**
 * Whether an integer literal is inside the bounds of the type it is going into.
 *
 * `negated` is carried down rather than the value being negated on the way up, because the bounds
 * are not symmetric: `-2147483648` is an `i32` and `2147483648` is not, and a check that only looked
 * at the magnitude would refuse the one the language allows.
 */
/**
 * Whether a decimal literal's digits name a number larger than `limit`, compared as text.
 *
 * Longer is larger once the leading zeros and separators are gone, and equal lengths compare
 * character by character. No arithmetic, because the values in question are exactly the ones no
 * integer in this compiler can hold.
 */
bool decimalExceeds(string digits, string limit) {
  u8[] a = digits.toBytes();
  u8[] out = u8[a.len()]();
  i32 n = 0;
  bool seenDigit = false;
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 95) { continue; }
    if (a[i] < 48 || a[i] > 57) { return false; }
    if (a[i] == 48 && !seenDigit) { continue; }
    seenDigit = true;
    out[n] = a[i];
    n = n + 1;
  }
  u8[] lim = limit.toBytes();
  if (n != lim.len()) { return n > lim.len(); }
  for (i32 i = 0; i < n; i++) {
    if (out[i] != lim[i]) { return out[i] > lim[i]; }
  }
  return false;
}

/** Whether the literal was written in hex — `0x…`, which the language reads as bits. */
bool isHexText(string t) {
  return t.len() > 2 && t.slice(0, 1) == "0" && (t.slice(1, 2) == "x" || t.slice(1, 2) == "X");
}

bool integerLiteralFits(C c, string want, Expr e, bool negated) {
  match (e.kind) {
    case IntLit(tok): {
      string text = tokenText(c, tok);
      i64 v = parseInt(text);
      // **A hex literal names bits, not a magnitude.** `0xFFFFFFFF` is how an `i32` of all ones is
      // written and the language takes it; the same value in decimal is out of range. So the bound
      // for one is the type's *width* and for the other its signed range, and a check that used one
      // bound for both reported four of the spec's own programs and eight working files.
      if (isHexText(text)) {
        if (want == "i32" || want == "u32") { return v <= 4294967295; }
        if (want == "i16" || want == "u16") { return v <= 65535; }
        if (want == "i8" || want == "u8") { return v <= 255; }
        return true;
      }
      // **The 64-bit bounds are compared as text.** `parseInt` answers an `i64`, so a literal one past
      // the top wraps and comes back looking small — 2^63 arrives negative and 2^64 arrives as zero.
      // The digits do not wrap. `spec/cases/0061` and `0062`, with `0063` holding the boundary from
      // the other side.
      if (want == "i64") { return !decimalExceeds(text, negated ? "9223372036854775808"
                                                                : "9223372036854775807"); }
      if (want == "u64") { return !negated && !decimalExceeds(text, "18446744073709551615"); }
      // Past the 64-bit answers, because a literal wider than an `i64` wraps in `parseInt` and the
      // comparisons below would read the wrapped value. Those two ask the digits instead, which is
      // why they come first — putting this guard in front of them let 2^63 through.
      if (v < 0) { return true; }
      if (want == "i32") { return negated ? v <= 2147483648 : v <= 2147483647; }
      if (want == "u32") { return !negated && v <= 4294967295; }
      if (want == "i16") { return negated ? v <= 32768 : v <= 32767; }
      if (want == "u16") { return !negated && v <= 65535; }
      if (want == "i8") { return negated ? v <= 128 : v <= 127; }
      if (want == "u8") { return !negated && v <= 255; }
      return true;
    }
    // The sign is a unary operator, and which sign it is decides the bound.
    case Unary(op, operand): {
      return integerLiteralFits(c, want, operand, tokenKind(c, op) == kMinus() ? !negated : negated);
    }
    else: { return true; }
  }
}

f64 floatLiteralValue(C c, i32 tok) {
  return floatLit(tokenText(c, tok));
}

/**
 * Whether a literal fits the slot it is going into — the family question, plus `f32`'s range.
 *
 * One function so the range rule reaches every position at once. It applies in all of them, measured:
 * an initialiser, a return, an argument, an array element, a field, an assignment. Only `f32` is
 * checked — the reference accepts `f64 x = 1.0e400`, which is out of range for an `f64` too, and
 * matching that is the job rather than improving on it.
 */
bool literalFits(C c, string want, Expr e) {
  // `litFamily`, not `litKindOf`: an expression made only of literals is one of them for this
  // question — `f64 s = 1 + 2` is an integer literal sum in a float slot. `issues/lang/0120`.
  i32 lit = litFamily(c, e);
  if (!acceptsLiteral(want, lit)) { return false; }
  string core = withoutNull(want);
  string base = core == "" ? want : core;
  // **An integer literal has to fit the slot it is going into**, which is a different question from
  // the family one above: `4294967296` is an integer and an `i32` has no room for it. Asked of the
  // types whose bounds are exact here — the 64-bit ones would need the literal's own width to answer
  // honestly, and a guess about the top of `u64` is worse than saying nothing.
  if (lit == litInteger()) { return integerLiteralFits(c, base, e, false); }
  if (base != "f32" || lit != litFloat()) { return true; }
  match (e.kind) {
    case FloatLit(tok): {
      // f32's largest finite value plus half an ulp: anything above it rounds to infinity, and
      // anything at or below it rounds to something an `f32` can hold.
      return floatLiteralValue(c, tok) <= 3.4028235677973366e38;
    }
    // The sign is a unary operator and the magnitude is what the range is about, so this asks the
    // same question one node down. The reference agrees: it reports at the literal, not at the `-`.
    case Unary(op, operand): { return literalFits(c, want, operand); }
    else: { return true; }
  }
}

/**
 * The family of an expression made **only of literals** — `1 + 2` is an integer literal sum.
 *
 * `litKindOf` answers about one literal and takes no `C`, so it cannot read an operator's kind; this
 * can, and the operator decides everything. `f64 s = 1 + 2;` was accepted because a `Binary` answered
 * *not a literal* and `typeOfExpr` of two literals is unknown, and unknown is silence — while the
 * spec has an integer literal taking an *integer* type from its context and no implicit conversions
 * (`spec/spec/types.md`). `issues/lang/0120`.
 *
 * A comparison answers a `bool` whatever its operands are, so `bool b = 1 == 1;` must stay a `bool`
 * and not become an integer literal sum. Mixed families answer nothing rather than guessing, which
 * leaves `1.5 * 2` exactly where it was.
 */
i32 litFamily(C c, Expr e) {
  i32 direct = litKindOf(e);
  if (direct != litNone()) { return direct; }
  match (e.kind) {
    case Binary(op, left, right): {
      i32 k = tokenKind(c, op);
      if (k == kEq() || k == kNe() || k == kLt() || k == kLe() || k == kGt() || k == kGe() ||
          k == kAndAnd() || k == kOrOr()) {
        return litNone();
      }
      i32 l = litFamily(c, left);
      if (l != litFamily(c, right)) { return litNone(); }
      return l == litInteger() || l == litFloat() ? l : litNone();
    }
    else: { return litNone(); }
  }
}

/** The family a literal expression belongs to, or `litNone` when the expression is not one. */
export i32 litKindOf(Expr e) {
  match (e.kind) {
    case IntLit(tok): { return litInteger(); }
    case FloatLit(tok): { return litFloat(); }
    case StrLit(tok): { return litString(); }
    case BoolLit(value): { return litBool(); }
    case NullLit: { return litNull(); }
    // `-1.0e40` is a float literal with a sign in front, and every rule that asks this means that.
    // Left out, the whole literal path skipped a negated one — so `f32 x = -1.0e40;` went unchecked
    // while `f32 x = 1.0e40;` did not, which is the sort of hole that only shows up beside its twin.
    case Unary(op, operand): {
      i32 inner = litKindOf(operand);
      return inner == litInteger() || inner == litFloat() ? inner : litNone();
    }
    else: { return litNone(); }
  }
}

/**
 * Whether a declared type accepts a literal of this family.
 *
 * The grid in `test/typecheck.test.ts` regenerates this from the reference on every run, so a
 * disagreement fails loudly rather than sitting here as a stale table.
 */
export bool acceptsLiteral(string want, i32 lit) {
  // A `T?` takes a null, and takes whatever `T` takes: `i32? n = null;` and `i32? n = 5;` are both
  // legal. So the question for a nullable is the question for the type inside it, plus null.
  if (endsWith(want, "?")) {
    if (lit == litNull()) { return true; }
    return acceptsLiteral(withoutNull(want), lit);
  }
  if (lit == litInteger()) {
    return want == "i32" || want == "i64" || want == "u32" || want == "u64";
  }
  if (lit == litFloat()) { return want == "f32" || want == "f64"; }
  if (lit == litBool()) { return want == "bool"; }
  if (lit == litString()) { return want == "string"; }
  // Nothing this slice can name is nullable. A `T?` is, and `typeOfTy` answers `typeNone` for one, so
  // a nullable declaration never reaches here — silence rather than a wrong refusal. A struct is not
  // nullable either: `P q = null;` is `expected P, got null`, which this now says.
  if (lit == litNull()) { return false; }
  return true;
}

/**
 * The type of a non-literal expression, or `typeNone`.
 *
 * Only a name, resolved against the parameters and locals of the function being checked. A call, a
 * member access or arithmetic still needs an expression typer, and silence is the honest answer for
 * all of them.
 */
/**
 * The type an assignment target has, or `typeNone`.
 *
 * The same walk as `typeOfExpr` over a different node family, because an lvalue is its own tree: a
 * name, a field of one, an element of one, or an unwrapped nullable. `LUnwrap` is `x!`, which is the
 * `T` inside a `T?` — the one place a type gets *narrower* going down the tree.
 */
/**
 * Where an lvalue *starts* — `p.x` begins at `p`, not at the dot.
 *
 * The node's own position is the dot, which is right: rung 2 compares this parser's tree against the
 * reference's node for node, positions included, and they agree. What differs is where a *diagnostic*
 * about the whole assignment goes, and the reference puts it at the beginning of the thing assigned
 * to. Walking down to the leftmost node is the difference between agreeing with it and reporting one
 * column later — which a differential oracle counts as a position the reference never mentions.
 */
i32 lvalueStartLine(Lvalue lv) {
  match (lv.kind) {
    case LField(base, nameTok): { return lvalueStartLine(base); }
    case LIndex(base, index): { return lvalueStartLine(base); }
    case LUnwrap(base): { return lvalueStartLine(base); }
    else: { return lv.line; }
  }
}

i32 lvalueStartCol(Lvalue lv) {
  match (lv.kind) {
    case LField(base, nameTok): { return lvalueStartCol(base); }
    case LIndex(base, index): { return lvalueStartCol(base); }
    case LUnwrap(base): { return lvalueStartCol(base); }
    else: { return lv.col; }
  }
}

export string typeOfLvalue(C c, Lvalue lv) {
  match (lv.kind) {
    case LIdent(tok): { return c.typeOfName(tokenText(c, tok)); }
    case LField(base, nameTok): {
      string owner = typeOfLvalue(c, base);
      if (owner == typeNone()) { return typeNone(); }
      return c.fieldType(owner, tokenText(c, nameTok));
    }
    case LIndex(base, index): {
      string arr = typeOfLvalue(c, base);
      if (!isArrayName(arr)) { return typeNone(); }
      return dropLast(arr, 2);
    }

    case LUnwrap(base): {
      string inner = withoutNull(typeOfLvalue(c, base));
      return inner == "" ? typeNone() : inner;
    }
  }
}

export string typeOfExpr(C c, Expr e) {
  match (e.kind) {
    // **A JSX element is core's `Node`**, whatever it contains. `design/lang/0004`.
    case Jsx(tagTok, closeTok, attrs, kids): { return "Node"; }
    case Ident(tok): { return c.typeOfName(tokenText(c, tok)); }
    // `p.x`, typed from the struct's field declarations and its parents'. The receiver is typed by
    // this same function, so `a.b.c` works by recursion for as long as every step is nameable.
    case Member(obj, nameTok): {
      string owner = typeOfExpr(c, obj);
      if (owner == typeNone()) {
        // A **static** method named without being called is a value: a funcref of its own signature.
        // `S.make` is a `fn() -> S`, which is why assigning it to an `i32` is an ordinary mismatch
        // rather than the *"cannot use method as a value"* an instance method gets — a static is a
        // function, and an instance method is not one until it has a receiver.
        return staticMethodType(c, obj, tokenText(c, nameTok));
      }
      string mem = tokenText(c, nameTok);
      // A field first: a field and a method may share a name, and the field is what `p.x` means.
      string ft = c.fieldType(owner, mem);
      if (ft != typeNone() && ft != "") { return ft; }
      // **And an instance method named without being called is a bound reference** —
      // `design/lang/0002` tier one. Answering `typeNone()` here is what made it unassignable and
      // therefore refusable; the value it denotes is the method with its receiver already in it.
      return boundMethodType(c, owner, mem);
    }
    // A cast is its target type, whichever of the four spellings it used. The four differ in what
    // they *permit* — see `checkCast` — and not in what they produce.
    case Cast(op, operand, target): { return typeOfTy(c, target); }
    /**
     * A method call, typed by what the method says it returns.
     *
     * Read in the receiver's world, so `Vec<i32>.at()` declared `T at(…)` is an `i32`. A funcref call
     * has no name to look up and stays unknown, as it always did.
     */
    case Call(callee, args): {
      match (callee.kind) {
        case Member(obj, nameTok): {
          // **A variant construction is a value, and had no type at all.** `E.A(1)` is an `A` — the
          // reference says so in as many words, *"expected i32, got A"* — and it reaches here as a
          // member call on a name that is an enum rather than a value, so `receiverType` answered
          // unknown and every rule downstream went quiet. `match (E.A(1))` was the visible one: the
          // subject had no type, so exhaustiveness, a duplicated arm and a name no variant declares
          // all said nothing about the whole match. `spec/cases/0093`.
          match (obj.kind) {
            case Ident(tok): {
              string en = tokenText(c, tok);
              if (c.isEnum(en) && !c.isDeclaredName(en) &&
                  c.variantArityIn(en, tokenText(c, nameTok)) >= 0) {
                return tokenText(c, nameTok);
              }
            }
            else: { }
          }
          string recvT = receiverType(c, obj);
          if (recvT == typeNone() || recvT == "") { return typeNone(); }
          // **A field holding a funcref answers what its signature says.** `Cli`'s members are
          // `fn[Pending<i32>()] argCount` and friends — fields, not methods — so `cli.readFile(p)`
          // had no type at all, and `.wait(1)` on the result had no receiver to be wrong about. Three
          // files' worth of missed diagnostics were downstream of this one unknown.
          string fref = c.isStruct(recvT) ? c.fieldType(recvT, tokenText(c, nameTok)) : "";
          if (startsWithFn(fref)) {
            string fret = funcrefReturn(fref);
            return fret == "" ? typeNone() : substituteType(c, recvT, fret);
          }
          // **The builtins answer something too**, and nothing here knew what: `return a.len();`
          // from a `string` function was silent because the returned expression had no type to be
          // wrong with, not because the rule was missing. Same closed surface the missing-method
          // rule is written against, one question further on.
          string bret = builtinReturnType(recvT, tokenText(c, nameTok));
          if (bret != "") { return bret; }
          // **A static on a template does not say which instance it builds.** `Box.of(5)` returns
          // `Box<T>` as written, and `T` is bound by the *slot* the call fills rather than by
          // anything here — so answering with the declaration's own text claims `Box<i32> b =
          // Box.of(5)` is a mismatch. The instantiation is what this checker does not model, and the
          // honest answer to a question it cannot answer is no answer.
          if (c.isGeneric(recvT)) { return typeNone(); }
          i32 mi = c.methodAt(recvT, tokenText(c, nameTok));
          if (mi < 0) { return typeNone(); }
          return substituteType(c, recvT, c.methodReturns[mi]);
        }
        else: { return typeNone(); }
      }
    }
    // `x is T` asks a question, so it answers a boolean whatever `x` and `T` are.
    case Is(left, target, other, negated): { return "bool"; }
    /**
     * A binary expression, which had no arm here at all — every one of them typed as unknown, so a
     * comparison used as a value, an arithmetic result returned, and an operand of an operand were
     * all invisible to every rule that asks what an expression is.
     *
     * A comparison and the logical operators are always `bool`. Everything else is the type of its
     * operands, taken from whichever side is not a literal: `x + 1` is an `i32` because `x` is, and
     * the literal takes its type from the other side rather than giving one.
     */
    case Binary(op, left, right): {
      i32 bk = tokenKind(c, op);
      if (bk == kEq() || bk == kNe() || bk == kLt() || bk == kLe() || bk == kGt() || bk == kGe() ||
          bk == kAndAnd() || bk == kOrOr()) {
        return "bool";
      }
      bool lLit = litKindOf(left) != litNone();
      bool rLit = litKindOf(right) != litNone();
      string bl = lLit ? typeNone() : typeOfExpr(c, left);
      string br = rLit ? typeNone() : typeOfExpr(c, right);
      // **Unknown from a literal and unknown from an error are the same value and not the same
      // thing.** `x + 1` takes its type from `x`, because the literal has none of its own; `(s * 2) +
      // t` has an operand that was *reported* and therefore has no type to offer, and answering with
      // the other side made the enclosing `return` complain a second time about a chain the
      // reference had already finished with.
      if (!lLit && bl == typeNone()) { return typeNone(); }
      if (!rLit && br == typeNone()) { return typeNone(); }
      // **Two known operands that disagree make the result unknown**, which is how the reference
      // behaves and why it reports `t.a + t.b + t.c` once rather than twice: the first `+` is an
      // error, so what it produces is not a `string` for the second `+` to complain about. Answering
      // with the left operand's type instead made this checker report every operator in the chain,
      // and every one after the first was a position the reference never mentions.
      if (bl != typeNone() && br != typeNone() && bl != br) { return typeNone(); }
      // **And an operator that has nothing to do to its operand produces nothing.** `t.a * 1000` on
      // a `string` is reported at the `*`; answering "string" for it as well made the enclosing
      // `return` complain a second time, at a position the reference never mentions because it had
      // already said what was wrong.
      if (bk != kPlus() && (bl == "string" || br == "string")) { return typeNone(); }
      if (bl != typeNone()) { return bl; }
      return br;
    }
    case Unwrap(operand): {
      string inner = withoutNull(typeOfExpr(c, operand));
      return inner == "" ? typeNone() : inner;
    }
    case Index(arr, index): {
      string a = typeOfExpr(c, arr);
      if (!isArrayName(a)) { return typeNone(); }
      string elem = dropLast(a, 2);
      // Reading a packed element **widens**: `bytes[i]` from a `u8[]` is an i32-shaped value, which
      // is why `return this.data[i];` from an `i32` function is the ordinary way this repository
      // reads a byte. Calling it a `u8` reported 115 files. The exact widened type is not measured,
      // so this says nothing — the same answer, and the same reason, as a packed assignment target.
      if (isPackedName(elem)) { return typeNone(); }
      return elem;
    }
    // `!x` is a boolean; `-x` and `~x` are whatever `x` is.
    case Unary(op, operand): {
      if (tokenKind(c, op) == kBang()) { return "bool"; }
      return typeOfExpr(c, operand);
    }
    // Both branches or nothing. A conditional whose arms disagree has a type the reference works out
    // by unification, which this slice cannot do — and guessing one branch would be worse than
    // silence, because the guess is right half the time and wrong in a way nothing here would catch.
    case Ternary(cond, then, els): {
      string t = typeOfExpr(c, then);
      return t == typeOfExpr(c, els) ? t : typeNone();
    }
    // **A `match` used as an expression**, by exactly the rule one arm up: every arm agrees and that
    // is the type, or they do not and this says nothing rather than guessing. There was no arm here
    // at all, so `string got = match (o) { … };` over arms that all answer `i32` went unreported —
    // the mutation sweep's second-to-last miss, in `packages/std/test/wac/option_test.wac`.
    //
    // A *statement* arm has no value and a match containing one is not an expression, so an arm
    // without one ends the question. Unknown is contagious for the same reason it is in `Ternary`:
    // one arm this checker cannot type says nothing about whether the others agree with it.
    case MatchExpr(subject, arms): {
      if (arms.len() == 0) { return typeNone(); }
      string mt = "";
      for (i32 i = 0; i < arms.len(); i++) {
        if (arms[i].value is null) { return typeNone(); }
        // **A literal arm adapts and says nothing.** `spec/spec/enums.md`: the arms unify exactly as
        // a ternary's branches do, and *"an integer or float literal arm takes the type expected of
        // the whole expression"*. So `f64 x = match (o) { case A: 1, case B: 2.5 }` is legal and the
        // `1` is an `f64`, which is why a literal cannot be asked what it is here — reading one as
        // `i32` refused a program the spec runs.
        if (litFamily(c, arms[i].value!) != litNone()) { continue; }
        string at = typeOfExpr(c, arms[i].value!);
        if (at == typeNone() || at == "") { return typeNone(); }
        if (mt == "") { mt = at; } else if (at != mt) { return typeNone(); }
      }
      // Every arm was a literal, so the whole match takes its type from wherever it is going — which
      // is the slot's business and not this function's.
      return mt == "" ? typeNone() : mt;
    }
    // A construction is either a struct being made or a function being called — the parser cannot
    // tell, so neither can this, and the name decides. A struct name gives the struct; a function
    // name gives what it returns; anything else is unknown.
    case Construct(ctype, args, named): {
      string name = "";
      match (ctype.kind) {
        case Named(tok, typeArgs): {
          if (typeArgs.len() > 0) { return typeOfTy(c, ctype); }
          name = tokenText(c, tok);
        }
        else: { }
      }
      if (name == "") { return typeNone(); }
      // `Box(1.0)` with no type arguments written is legal — the arguments are *inferred*, from the
      // declared type of whatever the construction flows into, and inside the generic's own methods
      // the bare name means the instantiation being compiled. Neither is knowable from the syntax at
      // hand, so this says unknown rather than guessing `Box`, which would be a type nothing has.
      if (c.isStruct(name)) { return c.isGeneric(name) ? typeNone() : name; }
      i32 at = c.funcAt(name);
      if (at < 0) {
        // **A name holding a funcref is callable, and says what it answers.** `fn[Read()] read` is a
        // parameter, not a declared function, so `read()` fell out of here with no type — and the
        // arm above says a funcref call "has no name to look up and stays unknown", which is true of
        // `(f())()` and not of this. There is a name, and `typeOfName` has it.
        //
        // What it cost was not the call: `match (read())` had no subject type, so the *bindings* had
        // none either, and `bytes.len(1)` inside the arm was unreported in `packages/stream`. A
        // subject this checker cannot type takes every rule inside the match down with it.
        string held = c.typeOfName(name);
        if (startsWithFn(held)) {
          string hret = funcrefReturn(held);
          return hret == "" ? typeNone() : hret;
        }
        return typeNone();
      }
      if (c.funcGenerics[at]) { return genericCallReturn(c, at, args); }
      return c.funcReturns[at];
    }
    else: { return typeNone(); }
  }
}

/**
 * Whether a statement list always leaves the function — the reference's *"not all code paths return
 * a value"*.
 *
 * Control flow rather than types, and the second kind of thing rung 3 does. The rule is the ordinary
 * definite-return analysis with one subtlety that the spec's own cases are mostly about:
 *
 * **`while (true)` leaves the function unless something can break out of it.** An infinite loop with
 * no exit never reaches the statement after it, so a function ending in one needs no return; give it
 * a reachable `break` and the loop can finish, so the closing brace becomes reachable again and a
 * return is required. Four of the seven spec cases are exactly this, and they place the `break`
 * inside a block, inside an `else if`, and inside a `match` arm — so "does this loop contain a
 * break" has to walk as deep as the statements go.
 *
 * A `break` inside a **nested** loop or a `switch` belongs to that construct, not to this loop, and
 * does not make it finite. That is why `breaksOut` stops descending at a loop or a switch and
 * `alwaysLeaves` does not.
 */
bool alwaysLeaves(Stmt[] body) {
  // **Any** statement, not the last one. An earlier `return` settles it just as well: everything
  // after it is unreachable, so the function still always leaves. Reading only the last statement
  // said otherwise for `{ return 1; i32 dead = 2; }`, which the reference accepts — a false alarm,
  // and the kind that only a corpus of *accepted* programs can find.
  for (i32 i = 0; i < body.len(); i++) {
    if (leaves(body[i])) { return true; }
  }
  return false;
}

/** Whether one statement always leaves the function. */
bool leaves(Stmt s) {
  match (s.kind) {
    case Return(value): { return true; }
    case Trap: { return true; }
    case Block(body): { return alwaysLeaves(body); }
    // Both arms, and there must be an arm to take: an `if` with no `else` falls through when the
    // condition is false.
    case If(cond, then, els): {
      return els.len() > 0 && alwaysLeaves(then) && alwaysLeaves(els);
    }
    case While(cond, body): { return isTrueLiteral(cond) && !breaksOut(body); }
    case DoWhile(body, cond): { return isTrueLiteral(cond) && !breaksOut(body); }
    // A `for` with no condition is the other spelling of `while (true)`.
    case For(init, cond, update, body): { return (cond is null) && !breaksOut(body); }
    // A `match` is exhaustive by construction — the language requires every variant — so it leaves
    // when every arm does. Modelling it was not optional: six functions in this very file are a
    // single `match` whose arms all return, and treating that as falling through reported all six.
    case Match(subject, arms): {
      if (arms.len() == 0) { return false; }
      for (i32 i = 0; i < arms.len(); i++) {
        if (!alwaysLeaves(arms[i].body)) { return false; }
      }
      return true;
    }
    // A `switch` needs a `default` as well: without one, a subject matching no case falls straight
    // through. A `break` in a case leaves the switch and not the function, so `alwaysLeaves` on the
    // case body is exactly the right question.
    case Switch(subject, cases): {
      bool hasDefault = false;
      for (i32 i = 0; i < cases.len(); i++) {
        if (cases[i].value is null) { hasDefault = true; }
        if (!alwaysLeaves(cases[i].body)) { return false; }
      }
      return hasDefault;
    }
    else: { return false; }
  }
}

/** `true`, written literally — the only condition this slice will call infinite. */
bool isTrueLiteral(Expr e) {
  match (e.kind) {
    case BoolLit(value): { return value; }
    else: { return false; }
  }
}

/**
 * Whether a `break` in this list belongs to the loop enclosing it.
 *
 * Does not descend into a nested loop or a `switch`: a `break` there is that construct's, and the
 * outer loop is still infinite. Does descend into blocks, `if`/`else` and `match` arms, because a
 * break in any of those is the loop's — which is what three of the spec's cases check.
 */
bool breaksOut(Stmt[] body) {
  for (i32 i = 0; i < body.len(); i++) {
    if (breaksOutOf(body[i])) { return true; }
  }
  return false;
}

bool breaksOutOf(Stmt s) {
  match (s.kind) {
    case Break: { return true; }
    case Block(body): { return breaksOut(body); }
    case If(cond, then, els): { return breaksOut(then) || breaksOut(els); }
    case Match(subject, arms): {
      for (i32 i = 0; i < arms.len(); i++) {
        if (breaksOut(arms[i].body)) { return true; }
      }
      return false;
    }
    else: { return false; }
  }
}

/**
 * The operands of `+ - * / %`, which must be the same type.
 *
 * Three sets, and which set an operator is in was read off the reference rather than assumed:
 *
 *   - **`+ - * / %` and `& | ^`** answer `type mismatch in 'op': A and B` whenever the operands
 *     differ. One rule, no exceptions among primitives.
 *   - **`< <= > >= == !=`** answer the same. A mixed comparison against a `string` answers a
 *     *different* message depending on which side it is on — `i32 < string` is `'<' not allowed on
 *     reference type` while `string < i32` is `type mismatch in '<'` — but both sit at the operator,
 *     which is the position this reports, so the distinction costs nothing here. An earlier version
 *     excluded strings from comparisons on the strength of seeing the first message and not the
 *     second, and lost recall for no reason. `string == string` is allowed and stays silent because
 *     the two agree, not because of a rule about strings.
 *   - **`&& ||`** never answer a mismatch at all. `1 && 2` is `'&&' requires bool operands`, which is
 *     about each operand on its own rather than about the pair, so it is not this check.
 *
 * Shifts are in none of them: they deliberately accept mixed widths — `i64 << i32` is legal, and the
 * friction log records a compiler bug from assuming otherwise.
 *
 * A literal operand is skipped rather than typed. `x + 1` is legal for any numeric `x` because the
 * literal takes the other side's type, so demanding they agree would report exactly the code
 * everybody writes.
 */
/**
 * An expression's type, **with a literal's own family filled in**.
 *
 * A literal is polymorphic over its family and takes the type of the slot it fills, which is why
 * `typeOfExpr` answers unknown for one. A comparison is not a slot: `1 == "hello"` has nothing to
 * take a type from, and the whole complaint is that the two sides cannot be the same type.
 */
/**
 * How many digits an integer literal is written with, ignoring `_`, a sign and a base prefix.
 *
 * Used only to answer "is this certainly an `i32`", so it counts rather than parses: this checker
 * has no integer parser and does not need one to know that twenty digits is not an `i32`.
 */
i32 literalDigits(C c, Expr e) {
  match (e.kind) {
    case IntLit(tok): {
      string t = tokenText(c, tok);
      i32 n = 0;
      for (i32 i = 0; i < t.len(); i++) {
        string ch = t[i];
        if (ch == "_" || ch == "-" || ch == "+") { continue; }
        if (ch == "x" || ch == "X" || ch == "b" || ch == "B" || ch == "o" || ch == "O") { return 0; }
        n = n + 1;
      }
      return n;
    }
    case Unary(op, operand): { return literalDigits(c, operand); }
    else: { return 0; }
  }
}

string naturalTypeOf(C c, Expr e) {
  // **Two literals joined are still a literal's family.** `("46316…" + "…").toBytes(1)` is a string
  // receiver however many pieces it was written in, and `typeOfExpr` answers unknown for it because
  // each side answers unknown on its own. Only where the two agree: `1 + x` is still the slot's
  // business, and this must not decide it.
  match (e.kind) {
    case Binary(op, left, right): {
      // **A chain, not only a pair.** `"a" + "b" + "c"` has a *binary* on its left, so asking whether
      // each side is a literal stopped at the second `+` — and the string this repository actually
      // writes, a 78-digit constant split across two lines and then `.toBytes()`, is exactly that
      // shape. Recursing answers `string` for the whole chain; two sides that disagree still answer
      // nothing, and a side that is not a literal at all still leaves the question to the slot.
      // **A comparison answers `bool`, whatever it compared.** Recursing without this said `i32`
      // for `status == 204`, and the `!` in front of it — four files write one — became a unary
      // operator on a number. `typeOfExpr` has always known this; the recursion had to be told.
      i32 bk2 = tokenKind(c, op);
      if (bk2 == kEq() || bk2 == kNe() || bk2 == kLt() || bk2 == kLe() || bk2 == kGt() ||
          bk2 == kGe() || bk2 == kAndAnd() || bk2 == kOrOr()) {
        return "bool";
      }
      string ln = naturalTypeOf(c, left);
      string rn = naturalTypeOf(c, right);
      if (ln == typeNone() || rn == typeNone()) { return typeOfExpr(c, e); }
      return ln == rn ? ln : typeNone();
    }
    else: { }
  }
  i32 lk = litKindOf(e);
  if (lk == litInteger()) {
    // **Only when it certainly fits.** An integer literal is polymorphic over `i32 i64 u32 u64`, and
    // calling it an `i32` is a useful answer for a rule with nothing else to go on — but
    // `18446744073709551615` is not an `i32` in any reading, and saying so produced a complaint
    // about a type the program never had, where the reference reports the literal being out of range
    // and stops. Ten digits is the boundary and nine is the one that is certain; a based literal
    // counts as unknown, which is the safe direction.
    return literalDigits(c, e) > 0 && literalDigits(c, e) < 10 ? "i32" : typeNone();
  }
  if (lk == litFloat()) { return "f64"; }
  if (lk == litBool()) { return "bool"; }
  if (lk == litString()) { return "string"; }
  return typeOfExpr(c, e);
}
/**
 * A JSX element's own rules: an attribute's value is a `string`, and a child is a `Node`.
 *
 * Both are ordinary assignability questions, which is why the errors read like every other type
 * error rather than like a syntax special case — and why the *positions* are the value's, not the
 * element's. `design/lang/0004`.
 */
/**
 * A component's own rules: it is a struct with a `render`, and its attributes are its fields.
 *
 * The field rules are named construction's — every field written, written once, and no name the
 * struct does not have — because the desugaring *is* a named construction, and two sets of rules for
 * one construct would differ the first time either moved. `errNamedField` is the same code
 * `Card { … }` reports, so the message a reader gets does not depend on which spelling they used.
 */
void checkJsxComponent(C c, string comp, i32 tagTok, JsxAttr[] attrs) {
  // `Node render(const this, Node[] kids)` is what makes a struct usable as a tag. Checked by shape
  // rather than by existence: a `render` taking nothing is a likelier mistake than no `render` at all.
  i32 mi = c.methodAt(comp, "render");
  bool ok = mi >= 0 && !c.methodStatics[mi] && c.methodReturns[mi] == "Node"
    && c.methodParamCount[mi] == 1 && c.methodParamTypes[c.methodParamAt[mi]] == "Node[]";
  if (!ok) {
    c.reportTok(errJsxNotComponent(), tagTok,
                comp + " is not a component: it has no `Node render(const this, Node[] kids)`");
    return;
  }
  for (i32 i = 0; i < attrs.len(); i++) {
    if (!c.hasField(comp, tokenText(c, attrs[i].nameTok))) {
      c.reportTok(errNamedField(), attrs[i].nameTok,
                  comp + " has no " + tokenText(c, attrs[i].nameTok));
    }
  }
  // Every field, because a named construction builds the whole struct. An optional attribute is a
  // thing named construction does not have either, and fixing it there fixes it here — so the
  // message names the field that is missing rather than counting, which is the half a reader needs.
  string at = templateOf(comp);
  for (i32 hop = 0; hop <= c.structCount; hop++) {
    if (at == "") { break; }
    for (i32 fi = 0; fi < c.fieldCount; fi++) {
      if (c.fieldOwners[fi] != at) { continue; }
      // A nullable attribute is optional, by the rule named construction follows — which is the same
      // rule, because this *is* a named construction. `design/lang/0007`.
      if (withoutNull(c.fieldTypes[fi]) != "") { continue; }
      bool set = false;
      for (i32 i = 0; i < attrs.len(); i++) {
        if (tokenText(c, attrs[i].nameTok) == c.fieldNames[fi]) { set = true; }
      }
      if (!set) {
        c.reportTok(errNamedField(), tagTok, comp + " needs " + c.fieldNames[fi]);
      }
    }
    at = c.parentOf(at);
  }
}

void checkJsx(C c, i32 tagTok, i32 closeTok, JsxAttr[] attrs, Expr[] kids) {
  // **A closing tag names the element it closes.** `<div></span>` is well formed as *shape* — the
  // parser read an element with a name at each end — and wrong as a program, which is why it is
  // said here, with the name that was written and the one that was expected.
  if (closeTok >= 0 && tagTok >= 0 && tokenText(c, closeTok) != tokenText(c, tagTok)) {
    c.reportTok(errJsxTagMismatch(), closeTok,
                "</" + tokenText(c, closeTok) + "> closes <" + tokenText(c, tagTok) + ">");
  }
  // A fragment has no name, so nothing here is about its tag: only its children are checked, by the
  // loop below that every element shares. `design/lang/0006`.
  // **A tag that names a struct in scope is a component**, and then its attributes are that struct's
  // fields rather than strings: `<Card count={3}/>` is `Card { count: 3 }.render(…)`, so `count` is
  // checked against the field's declared type. `design/lang/0005`.
  string comp = tagTok < 0 ? "" : tokenText(c, tagTok);
  bool isComponent = c.isStruct(comp) && !c.isGeneric(comp);
  if (isComponent) {
    checkJsxComponent(c, comp, tagTok, attrs);
  }
  for (i32 i = 0; i < attrs.len(); i++) {
    for (i32 j = 0; j < i; j++) {
      if (tokenText(c, attrs[j].nameTok) == tokenText(c, attrs[i].nameTok)) {
        c.reportTok(errJsxDuplicateAttr(), attrs[i].nameTok,
                    tokenText(c, attrs[i].nameTok) + " is already set on this element");
      }
    }
    checkExpr(c, attrs[i].value);
    // A component's attribute answers to its field's type; an element's is a string. Both are the
    // ordinary assignability question, asked against a different want.
    if (isComponent) {
      string want = c.fieldType(comp, tokenText(c, attrs[i].nameTok));
      if (want == typeNone() || want == "") { continue; }
      if (litKindOf(attrs[i].value) != litNone()) {
        reportLiteral(c, want, attrs[i].value, errFieldMismatch(),
                      attrs[i].value.line, attrs[i].value.col);
        continue;
      }
      string got = typeOfExpr(c, attrs[i].value);
      if (got != typeNone() && !assignable(c, want, got)) {
        c.reportWith(errFieldMismatch(), attrs[i].value.line, attrs[i].value.col,
                     tokenText(c, attrs[i].nameTok) + " is " + want + ", and this is " + got);
      }
      continue;
    }
    // **A literal is asked whether it fits, not what it is.** `{7}` has no type until something
    // wants one — asking `typeOfExpr` gives nothing and the mismatch goes unreported, which is how
    // `<div id={7}/>` was accepted. Every other position in this file reaches for `reportLiteral`
    // first for exactly this reason.
    if (litKindOf(attrs[i].value) != litNone()) {
      reportLiteral(c, "string", attrs[i].value, errFieldMismatch(),
                    attrs[i].value.line, attrs[i].value.col);
      continue;
    }
    string got = typeOfExpr(c, attrs[i].value);
    if (got != typeNone() && !assignable(c, "string", got)) {
      c.reportWith(errFieldMismatch(), attrs[i].value.line, attrs[i].value.col,
                   "an attribute is a string, and " + tokenText(c, attrs[i].nameTok) +
                   " is " + got);
    }
  }
  for (i32 i = 0; i < kids.len(); i++) {
    checkExpr(c, kids[i]);
    if (litKindOf(kids[i]) != litNone()) {
      reportLiteral(c, "Node", kids[i], errFieldMismatch(), kids[i].line, kids[i].col);
      continue;
    }
    string got = typeOfExpr(c, kids[i]);
    if (got != typeNone() && !assignable(c, "Node", got)) {
      c.reportWith(errFieldMismatch(), kids[i].line, kids[i].col,
                   "a child is a Node, and this is " + got);
    }
  }
}

void checkExpr(C c, Expr e) {
  string want = c.expected;
  bool wantUnknown = c.expectedUnknown;
  c.expected = typeNone();
  c.expectedUnknown = false;
  // A **character literal** arrives as an integer literal wearing quotes, and how many characters
  // are inside is a question only its text can answer: `''` holds none and `'ab'` holds two. Both
  // are reported at the literal, which is where the reference reports them.
  checkCharLiteral(c, e);

  match (e.kind) {
    // **Reported here rather than from `typeOfExpr`**, because that function is asked the same
    // question about the same node more than once and a diagnostic from it would arrive as many
    // times as it was asked. `checkExpr` walks each expression once, which is what makes it the
    // place a refusal belongs. The seam for implementing this is `c.expected` — already the
    // target-type channel a literal is checked through — plus a scope holding the parameters.
    case Lambda(params, body): {
      checkLambda(c, want, wantUnknown, e, params, body);
    }
    case Binary(op, left, right): {
      checkExpr(c, left);
      checkExpr(c, right);
      i32 k = tokenKind(c, op);
      // `>>>` is an unsigned shift, so on a type that is already unsigned it says nothing that `>>`
      // does not — the language calls that redundant rather than harmless. On a float it has no
      // meaning at all. Both name the operator, so both are one code here.
      if (k == kShrU()) {
        string st = typeOfExpr(c, left);
        if (st == "u32" || st == "u64" || st == "f32" || st == "f64") {
          c.reportTok(errShiftOp(), op, "");
        }
      }
      bool arith = k == kPlus() || k == kMinus() || k == kStar() || k == kSlash() ||
                   k == kPercent() || k == kAnd() || k == kOr() || k == kCaret();
      // Arithmetic and bitwise operators want a number. Two booleans *agree*, so the same-type rule
      // below has nothing to say about `a + b` — this is the question of what the operands are, which
      // is the same distinction `&&` draws, one operator family further along.
      string alt = typeOfExpr(c, left);
      string art = typeOfExpr(c, right);
      // **`==` on a reference asks the wrong question, and asks it once.**
      //
      // Two references are equal when they are the same object, which the language spells `is`, so
      // the reference compiler answers *"'==' not allowed on reference type P — use 'is' for
      // identity"* — one sentence, whether the two sides are the same reference type or one is a
      // reference and the other is not. `< <= > >=` are the same rule and get the same answer: the
      // reference refuses `p < q` on a reference with that wording too, so splitting them would be
      // two rules that have to be kept saying the same thing.
      //
      // This is the only place that answers it, and it returns. Three rules used to overlap here:
      // a mismatch rule, a reference-versus-something-else rule, and a struct-or-array rule further
      // down, so `a == b` on two structs came back twice and `1 == "s"` came back twice — nine
      // diagnostics over six lines where the reference gives six. `report` already refuses the same
      // code twice at one position for the reason that applies to two different codes just as well:
      // a list that says it twice disagrees about how many things are wrong.
      //
      // **A nullable name is always a reference** — primitives have no nullable form — so `N?` and
      // `i32[]?` need no lookup, and asking `isStruct` about them answered no, which is how they
      // escaped the old rule and reached the emitter with nowhere to go.
      //
      // `string` is the exception, and it is on `string` **exactly**: `==` on two strings compares
      // bytes, which the emitter has a helper for, while `string?` would have to answer for null
      // first and so goes to `is` like anything else.
      // **Each side's type, from whichever of the two questions can answer it.** `at == ""` compares
      // a string against a string *literal*, and a literal has no type until something gives it one,
      // so `typeOfExpr` says unknown and the two-strings exemption below would not apply — the
      // checker refuses forty lines of its own source. `naturalTypeOf` fills a literal in and says
      // unknown for plenty that `typeOfExpr` knows, `c.activeParams[i]` among them, which is the
      // same failure from the other side. Neither alone is enough; the first that answers is.
      string nl = alt != typeNone() ? alt : naturalTypeOf(c, left);
      string nr = art != typeNone() ? art : naturalTypeOf(c, right);
      bool anyCmp = k == kEq() || k == kNe() || k == kLt() || k == kLe() || k == kGt() || k == kGe();
      if (anyCmp) {
        // A side that is *known* to be a reference other than a plain string. `string` is not in
        // here because two of them compare by value; it comes back below, where the two disagree.
        //
        // **An enum belongs in this list and was in none of the rules this replaced**, so `a == b`
        // on two of them was accepted outright: the struct-or-array rule asked `isStruct`, and the
        // mixed rule needed the sides to differ, which two `E`s do not. A funcref is deliberately
        // absent — the reference compares two of those without complaint.
        // A reference, minus the two the reference compiler compares anyway: a plain `string`, whose
        // `==` compares bytes, and a **funcref**, which it compares without complaint. Both
        // exceptions are read off the reference rather than argued for — the funcref one is not
        // obvious, and the sweep is what turned it up, as six false alarms on the first attempt.
        bool lRef = nl != "string" && !startsWithFn(nl) && isReferenceName(c, nl);
        bool rRef = nr != "string" && !startsWithFn(nr) && isReferenceName(c, nr);
        // **A string against a known something-else** — `1 == "hello"`, by far the commonest of
        // these in the corpus. Both sides have to be known: an expression this checker cannot type
        // compared against a string literal is not an error, and treating unknown as not-a-string
        // made it one in forty places in this file alone.
        bool strMix = nl != typeNone() && nr != typeNone() &&
                      (nl == "string") != (nr == "string");
        if (lRef || rRef || strMix) {
          c.report(errNotComparable(), e.line, e.col);
          return;
        }
      }
      // **Arithmetic on a reference**, which is the same question one operator family along. This
      // asked about `bool` and funcrefs only, so `S + S`, `E * E`, `i32[] - i32[]` and
      // `anyref % anyref` were all accepted — forty-five cells of the sweep, and every one of them a
      // program the reference refuses. `+` on two strings is the exception and concatenates; every
      // other combination involving a string is caught by the rule below, which predates this.
      bool lArith = alt != "string" && isReferenceName(c, alt);
      bool rArith = art != "string" && isReferenceName(c, art);
      if (arith && (alt == "bool" || art == "bool" || lArith || rArith)) {
        c.reportTok(errOperandMismatch(), op, "");
      }
      // **A `string` is a number for exactly one operator.** `+` concatenates and the comparisons
      // order it, and the rest of the arithmetic family has nothing to do to one — *"'*' requires
      // numeric type, got string"*, at the operator. Read off the reference rather than assumed:
      // `==`, `<` and `+` are all accepted on two strings, so the rule is about the operator and not
      // about the type being a reference.
      if (arith && k != kPlus() && (alt == "string" || art == "string")) {
        c.reportTok(errOperandKind(), op, "");
      }
      // **Two literals of different families**, which is the one case where neither side can take
      // its type from the other: `1 + "é"` has nothing to infer from and is a mismatch whatever the
      // slot wants. Measured across the ten pairs — an integer with a float, a string with a bool
      // and the rest — and the answer is the same every time, reported at the operator. Same family
      // is silent, including `true + false`, which is the numeric rule's business and not this one's.
      bool bothLit = litKindOf(left) != litNone() && litKindOf(right) != litNone();
      if (bothLit && litKindOf(left) != litKindOf(right) &&
          litKindOf(left) != litNull() && litKindOf(right) != litNull() &&
          (arith || k == kEq() || k == kNe() || k == kLt() || k == kLe() || k == kGt() ||
           k == kGe())) {
        c.reportTok(errOperandMismatch(), op, "");
      }
      // The bitwise operators want *integers*, which is a narrower demand than "numeric": `a & b` on
      // two `f64`s is refused although the two agree, so the same-type rule below never sees it. A
      // shift asks it of both sides separately — the value being shifted and the amount to shift by.
      bool bitwise = k == kAnd() || k == kOr() || k == kCaret();
      bool shift = k == kShl() || k == kShr() || k == kShrU();
      if (bitwise || shift) {
        string lt2 = typeOfExpr(c, left);
        string rt2 = typeOfExpr(c, right);
        bool badL = lt2 != typeNone() && !isIntegerName(lt2);
        bool badR = rt2 != typeNone() && !isIntegerName(rt2);
        if (badL || badR) { c.reportTok(errOperandKind(), op, ""); }
      }
      bool sameType = k == kPlus() || k == kMinus() || k == kStar() || k == kSlash() ||
                      k == kPercent() || k == kAnd() || k == kOr() || k == kCaret();
      bool comparison = k == kLt() || k == kLe() || k == kGt() || k == kGe() ||
                        k == kEq() || k == kNe();
      // `&&` and `||` are the other rule: each operand must be a boolean on its own, which is a
      // different question from whether the two agree. Reported at the operator, where the reference
      // reports it, and a literal counts — `p && 1` is an error while `p && true` is not.
      if (k == kAndAnd() || k == kOrOr()) {
        if (notBool(c, left) || notBool(c, right)) {
          c.report(errNotBool(), e.line, e.col);
        }
        return;
      }
      if (!sameType && !comparison) { return; }
      string nl2 = naturalTypeOf(c, left);
      string nr2 = naturalTypeOf(c, right);
      // A literal operand takes the other side's type, so `x + 1` is legal for any numeric `x` and
      // demanding they agree would report the code everybody writes.
      if (litKindOf(left) != litNone() || litKindOf(right) != litNone()) {
        // **A literal only adapts inside its own family.** That is the whole content of the skip
        // above, and it was written as *every* literal adapts — so `x + s` was refused for a named
        // `string s` and `x + "s"` was accepted, which is the same program twice. A string literal
        // is a string whatever slot it lands in and has nothing to take from the other side.
        // Asked through `naturalTypeOf`, which is what fills a literal's own family in; two
        // literals are the rule further up, and a comparison is the reference-type rule's.
        bool oneString = (nl2 == "string") != (nr2 == "string");
        if (sameType && !bothLit && oneString && nl2 != typeNone() && nr2 != typeNone()) {
          c.report(errOperandMismatch(), e.line, e.col);
        }
        return;
      }
      string a = typeOfExpr(c, left);
      string b = typeOfExpr(c, right);
      if (a == typeNone() || b == typeNone() || a == b) { return; }
      c.reportWith(errOperandMismatch(), e.line, e.col, a + " and " + b);
    }
    // A name that nothing declares. The most-missed family in the reference's own tests, and the last
    // rule here to need a *complete* picture of scope rather than a fact about one construct: every
    // binder the language has must be known, because anything missed is a false alarm on working
    // code rather than a gap. Locals, parameters, `this` and match bindings come from the name table;
    // functions, structs, enums, imports and the primitive type names are looked up where they live.
    case Jsx(tagTok, closeTok, attrs, kids): { checkJsx(c, tagTok, closeTok, attrs, kids); }
    case Ident(tok): {
      string idn = tokenText(c, tok);
      if (!nameExists(c, idn)) {
        c.reportWith(errUndefinedName(), e.line, e.col, "no " + idn + " in scope");
        return;
      }
      // A struct's name is not a value. It reaches expression position legitimately as the receiver
      // of a static call, and that arrives through the `Call` and `Member` arms rather than here —
      // so an `Ident` that names a struct and nothing else is one used where a value belongs.
      if (!c.isDeclaredName(idn) && c.isStruct(idn) && c.funcAt(idn) < 0) {
        c.report(errStructAsValue(), e.line, e.col);
      }
    }
    // `x is null` and `a is b` ask about a *reference*, so a primitive is not something they can be
    // asked about. Both land on the `is`, which is this node's own position.
    case Is(left, target, other, negated): {
      checkExpr(c, left);
      // **A type test needs no payload** — `[§enum-is-qualified-8jkq4wp]`: `s is Shape.Circle(1.0)`
      // is an error rather than silently false. The right of `is` parses as an expression when it is
      // qualified, so a variant *construction* arrives here looking like an ordinary identity test
      // against a freshly built value, which can never be identical to anything. Asked of the shape
      // rather than of the type, because the construction is what is wrong. `spec/cases/0076`.
      if (!(other is null) && isVariantConstruction(c, other!)) {
        c.report(errOperandKind(), e.line, e.col);
      }
      if (!(other is null)) { checkExpr(c, other!); }
      // **The target is a type, and this is the only place that reads it as one.** Every other rule
      // here asks about the left operand, so `mkA() is Circle` never resolved `Circle` at all — and a
      // variant needs importing like any other name (`§wac-type-name-scope-8vqk3mn`). The identity
      // form `x is Other`, where `Other` is a variable, arrives as `other` rather than `target` and
      // is untouched by this.
      if (!(target is null)) {
        string want = typeOfTy(c, target!);
        // **`A is B` where the two share no ancestor is always false** — the second of
        // `issues/lang/0126`'s three. Legal, and the reader believes it defends something.
        //
        // Both types known, both references, neither generic: a generic instantiation's chain is
        // what this checker does not model, and "cannot know" must not become "never true".
        string have = typeOfExpr(c, left);
        if (want != typeNone() && want != "" && have != typeNone() && have != "" &&
            isReferenceType(c, want) && isReferenceType(c, have) &&
            !c.isGeneric(want) && !c.isGeneric(have) && !shareAncestor(c, have, want)) {
          c.warn(warnNeverThat(), e.line, e.col);
        }
      }
      // Phrased as "is it a **primitive**" rather than "is it not a reference". The two are not the
      // same question: an enum, a funcref and a generic instantiation are all references, and asking
      // the negative form reported 27 files that were doing nothing wrong. The positive form only
      // ever fires on a type this checker can name, which is the direction to be wrong in.
      string lt3 = typeOfExpr(c, left);
      // **`x is null` on something that is never null** — the first of `issues/lang/0126`'s three.
      // Legal, and answers false: `[§wac-nonnull-isnull-k8fn3wp]`, which is why it is a warning and
      // not an error — `Slot<T>.empty` must instantiate for nullable and non-nullable `T` alike.
      //
      // The reference's own note is the argument for saying it at all: `packages/platform` changed
      // `env` from `string?` to `Pending<string?>`, every `cli.env(n) is not null` became a
      // tautology, and five survived a migration the type checker otherwise caught completely.
      //
      // Only where the type is *known* and a reference: a primitive cannot be null and is refused
      // above rather than warned about, an unknown type is the answer this checker gives whenever it
      // cannot compute one, and a type parameter is unknown by construction — warning on any of
      // those is a false alarm on correct code, which is the direction that costs trust.
      if ((target is null) && (other is null) && lt3 != typeNone() && lt3 != "" &&
          withoutNull(lt3) == "" && isReferenceType(c, lt3) && !c.isGeneric(lt3)) {
        c.warn(warnNeverNull(), e.line, e.col);
      }
      // **A funcref is a reference and still not testable**, which is why it is named rather than
      // reached by the negative form the comment above rejects: the reference answers *"'is' type
      // test requires a reference type, got fn(i32) -> i32"*, because there is no hierarchy of
      // function types and nothing to test at runtime. The positive form stays for everything else.
      // …and only when there *is* a target, because `f is null` on a nullable funcref is the
      // ordinary way to ask whether one was supplied, which the reference accepts. The restriction
      // is about testing a funcref's *type*, not about mentioning one.
      if (isValueType(lt3) || (!(target is null) && startsWithFn(lt3))) {
        c.report(errReferenceOp(), e.line, e.col);
      }
    }
    // `p!` on something that was never nullable: there is nothing to unwrap.
    case Unwrap(operand): {
      checkExpr(c, operand);
      // The same caution: unwrapping is refused only when the operand is a type this checker knows
      // is not nullable — rather than whenever it cannot see a `?`. What it knows is wider than the
      // struct-or-primitive this used to list: an enum, an array, a funcref and `anyref` are all
      // types with no `?`, and `someEnum!` compiled. The `withoutNull` guard above is what makes
      // asking `isReferenceName` safe here, since it has already established there is no `?`.
      string ut2 = typeOfExpr(c, operand);
      if (withoutNull(ut2) == "" &&
          (isPrimitiveName(ut2) || ut2 == "bool" || isReferenceName(c, ut2))) {
        c.report(errReferenceOp(), e.line, e.col);
      }
    }
    case Unary(op, operand): {
      checkExpr(c, operand);
      // `!` wants a boolean; `-` wants a number; `~` wants an integer. Three different demands on the
      // one node, all reported at the operator, and all of them silent on an unknown operand.
      i32 uk = tokenKind(c, op);
      // **A literal's own family, not the slot's.** `-"s"` is the whole of the mistake and there is
      // nothing else for the literal to take a type from — the same argument that made a comparison
      // fill it in. Asking `typeOfExpr` answered unknown and stayed silent on every one of them.
      string ut = naturalTypeOf(c, operand);
      if (ut != typeNone()) {
        if (uk == kBang() && ut != "bool") {
          c.reportTok(errOperandKind(), op, "");
        // **Negating a reference**, which listed `bool`, `string` and structs — so `-someEnum`,
        // `-someArray`, `-someFn` and `-someAnyref` all compiled. The list is the same one that
        // forgot enums twice elsewhere today, which is why the question is now asked of one
        // predicate instead of being spelled out per rule.
        // **And an unsigned integer has no negation.** `-a` on a `u32` or a `u64` compiled; the
        // reference answers *"unary '-' is not defined on u32"*, at the operator, which is where
        // this reports. `u8` and `u16` are packed rather than unsigned-arithmetic types and the
        // reference complains about them three times over — this catches one of the three, which
        // rung 3 permits, because a subset at the right position is the contract.
        } else if (uk == kMinus() &&
                   (ut == "bool" || ut == "u32" || ut == "u64" || isReferenceName(c, ut))) {
          c.reportTok(errOperandKind(), op, "");
        } else if (uk == kTilde() && !isIntegerName(ut)) {
          c.reportTok(errOperandKind(), op, "");
        }
      }
    }
    // The expression form of `++`. `IncrStmt` had it as a statement, and `return x++` is neither —
    // the same shape reached through a different node, which is the third time that has happened.
    case Incr(target, op, prefix): { checkIncr(c, target, e.line, e.col); }
    // A `match` used for its value. Its arms hold expressions rather than statements, so nothing that
    // walked the statement form reached them — found by the grid, not by a rule looking wrong.
    case MatchExpr(subject, arms): {
      checkExpr(c, subject);
      // An expression arm carries a value and no body — one `Arm` type serves both forms, as the
      // reference has it — so the value is the whole of what there is to walk here.
      //
      // The bindings are declared *here* rather than in `declareStmt`, because that walks statements
      // and this is an expression: a `match` used for its value can sit inside an initialiser or a
      // return, where the declaration pass never goes. Three files said so — `case Some(v): v * 3`
      // reported `v` as undefined. Declaring them at the point of use is enough because an arm's
      // value is walked immediately afterwards, and leaving them in scope for the rest of the
      // function is over-permissive in the silent direction, which is the one to err in.
      checkArmVariants(c, subject, arms);
      for (i32 i = 0; i < arms.len(); i++) {
        for (i32 b = 0; b < arms[i].bindingToks.len(); b++) {
          c.declare(tokenText(c, arms[i].bindingToks[b]), armBindingType(c, subject, arms[i], b));
        }
        checkBindingCollision(c, subject, arms[i]);
        // **An arm of an expression match narrows too.** Only the statement form did, so
        // `match (s) { case Circle: s.radius, ... }` looked for `radius` on the un-narrowed subject
        // and reported a field that was there all along — the spec's own program for this clause.
        // The same const rule applies for the same reason: the arm is describing one value.
        string saved = armNarrowing(c, subject, arms[i]);
        string subj = subjectName(c, subject);
        bool wasConst = subj == "" ? false : c.isConstName(subj);
        bool wasAlias = subj == "" ? false : c.isAliasOnlyName(subj);
        if (subj != "" && arms[i].variantTok >= 0) { c.setConstFlags(subj, true, false); }
        if (!(arms[i].value is null)) { checkExpr(c, arms[i].value!); }
        if (subj != "") { c.setConstFlags(subj, wasConst, wasAlias); }
        restoreNarrowing(c, subject, saved);
      }
      checkArmValueTypes(c, arms);
    }
    // `i32[](1, 2)`, `i8[](1.5)`, `E[2](fill: 5)` — every element and the fill must fit the element
    // type, which is the same question as an initialiser with the type coming from the `[]`.
    case ArrNew(elem, size, fill, elements): {
      if (!(size is null)) {
        checkExpr(c, size!);
        // A length is a count, so it is an `i32` — at the size expression, which is the only thing
        // there is to name.
        Expr sz = size!;
        i32 slit = litKindOf(sz);
        if (slit != litNone()) {
          if (!acceptsLiteral("i32", slit)) { c.report(errIndex(), sz.line, sz.col); }
        } else {
          // The same rule as an index and the same slip: `isIntegerName` accepted `i64`, `u32` and
          // `u64`, while the literal branch above demanded an `i32`.
          string st2 = typeOfExpr(c, sz);
          if (st2 != typeNone() && st2 != "i32") { c.report(errIndex(), sz.line, sz.col); }
        }
      }
      string elemWant = typeOfTy(c, elem);
      // An element's slot is the element type, which is what lets a bare generic infer inside one.
      for (i32 i = 0; i < elements.len(); i++) {
        c.expected = elemWant;
        checkExpr(c, elements[i]);
      }
      if (!(fill is null)) {
        c.expected = elemWant;
        checkExpr(c, fill!);
      }
      string want = elemWant;
      if (want == typeNone()) { return; }
      // `E[2]()` with nothing to fill it asks every element for a default, and an enum has none.
      //
      // **`E[]()` asks for nothing**, which is a different program: the listed form with no elements
      // is an empty array, and an array with no elements never builds one. `return Expr[]();` is a
      // line in this compiler's own parser, and it was reported the moment the checker could see
      // what `Expr` is — the rule needed a size before it needed a default.
      if (!(size is null) && elements.len() == 0 && (fill is null) && !hasDefault(c, want, 0)) {
        c.report(errNoDefault(), e.line, e.col);
      }
      // A packed element is an `i32` at this position, the way `bytes[i] = 5` is: the width is the
      // array's business, not the element expression's.
      if (isPackedName(want)) { want = "i32"; }
      for (i32 i = 0; i < elements.len(); i++) { checkElement(c, want, elements[i]); }
      if (!(fill is null)) { checkElement(c, want, fill!); }
    }
    // A cast's operand. `(p + q) as i64` reported nothing, because typing a cast as its target — the
    // right answer — meant never looking inside it.
    case Cast(op, operand, target): { checkExpr(c, operand); checkCast(c, e, op, operand, target); }
    case Ternary(cond, then, els): {
      // **Both branches sit in the ternary's own slot.** `Box<i32> b = c ? Box(1) : Box(2);` needs
      // it: a bare `Box(…)` takes its type arguments from where it is going, and `c.expected` is
      // cleared by the first expression that reads it — so the second branch got nothing and the
      // whole thing was reported as a template used as a value.
      // `want`, not `c.expected`: the slot was read and cleared at the top of this function, which is
      // the whole mechanism — an expression gets the context it was given and cannot leak it sideways.
      string slot = want;
      checkExpr(c, cond);
      c.expected = slot;
      checkExpr(c, then);
      c.expected = slot;
      checkExpr(c, els);
      // The condition is the `if` rule in expression position, and lands on the condition itself.
      if (notBool(c, cond)) {
    c.reportWith(errNotBool(), cond.line, cond.col,
                 expectedFound("bool", foundType(c, cond)));
  }
      // The branches have to agree, because the whole expression is one type. A literal branch takes
      // the other's type, as everywhere, so only two known and different types are a complaint — and
      // it names the node rather than either branch, neither being more wrong than the other.
      if (litKindOf(then) == litNone() && litKindOf(els) == litNone()) {
        string tt = typeOfExpr(c, then);
        string et = typeOfExpr(c, els);
        // **Reference branches take their closest common ancestor**, which `spec/spec/control.md`
        // states and this rule did not know: `flag ? c : r` on a `Circle` and a `Rect` is a `Shape`,
        // and neither branch is assignable to the other. Asking assignability in both directions
        // answers "no" for every pair of siblings, and refused four programs the spec runs.
        if (tt != typeNone() && et != typeNone() && !assignable(c, tt, et) &&
            !assignable(c, et, tt) && !shareAncestor(c, tt, et)) {
          c.report(errTernaryBranches(), e.line, e.col);
        }
      } else if (litKindOf(then) != litNone() && litKindOf(els) != litNone()) {
        // Two literals of different families — `c ? 1 : true` — have nothing to take a type from.
        // **Except a `null`**, which takes the other branch's type: `c ? 1 : null` in an `i32?` slot
        // is the shape the spec writes for a nullable primitive.
        if (litKindOf(then) != litKindOf(els) &&
            litKindOf(then) != litNull() && litKindOf(els) != litNull()) {
          c.report(errTernaryBranches(), e.line, e.col);
        }
      }
    }
    case Index(arr, index): {
      checkExpr(c, arr);
      checkExpr(c, index);
      checkIndex(c, e, arr, index);
    }
    case Member(obj, nameTok): {
      checkReceiver(c, obj);
      checkMember(c, e, obj, tokenText(c, nameTok));
    }
    // `g(a)` is a **Construct**, not a Call. The parser cannot tell a call from a struct
    // construction — `Point(1, 2)` and `g(a)` are the same syntax — so it builds `Construct` with a
    // `Named` type for both and the resolver decides which later. A `case Call` never matches a
    // plain named call, which is why the first version of this reported nothing at all.
    case Construct(ctype, args, named): {
      // Each argument is walked with the slot it is going into, which is what lets a generic
      // construction nested in one — `g(Box(1.0))` — infer from the parameter.
      match (ctype.kind) {
        case Named(ctok, ctargs): {
          string cname = tokenText(c, ctok);
          for (i32 i = 0; i < args.len(); i++) {
            c.expected = argumentSlot(c, cname, ctargs.len() > 0 ? typeOfTy(c, ctype) : cname, i);
            // `argumentSlot` answers `typeNone()` for four different reasons, and one of them is that
            // `cname` is neither a struct nor a function *this file* contains — an imported type,
            // under a single-file check. Empty therefore means "could not tell" here as it does in
            // the call arm; see `C.expectedUnknown`.
            c.expectedUnknown = c.expected == typeNone();
            checkExpr(c, args[i]);
            c.expectedUnknown = false;
          }
        }
        else: {
          // A constructed type that is not a plain name: nothing named a slot at all.
          for (i32 i = 0; i < args.len(); i++) {
            c.expectedUnknown = true;
            checkExpr(c, args[i]);
            c.expectedUnknown = false;
          }
        }
      }
      match (ctype.kind) {
        case Named(tok, typeArgs): {
          string name = tokenText(c, tok);
          if (c.isStruct(name)) {
            // A **bare generic** takes its type arguments from wherever it is going. With a target
            // whose template is this one, the construction *is* that type and its arguments are
            // checked against the substituted fields; with no target at all there is nothing to infer
            // from, and the reference calls the bare name undefined — which it is, since a template
            // is not a type. `Box(1.0)` assigned to a `Box<f64>` is ordinary and `Box(1).get()` is
            // not, and the only difference between them is the slot.
            string spelled = typeArgs.len() > 0 ? typeOfTy(c, ctype) : name;
            if (typeArgs.len() == 0 && c.isGeneric(name)) {
              // The target's **nullability is not part of the question**: a `MapEntry<K, V>?` slot
              // takes a `MapEntry<K, V>`, and the construction produces the non-null one. Comparing
              // the spelled target directly missed that and reported a working line in `packages/std`.
              string wantCore = withoutNull(want);
              string wantBase = wantCore == "" ? want : wantCore;
              if (templateOf(wantBase) == name) {
                spelled = wantBase;
              } else {
                c.report(errNotCallable(), e.line, e.col);
                return;
              }
            }
            checkConstruct(c, spelled, args, named, e);
            // Two questions a construction asks that the field types do not. With arguments, the
            // count has to match — parents included, since a child is constructed with the whole
            // chain's fields. With none, it is a *default* construction, and the struct has to have
            // a default at all.
            if (!c.isGeneric(name)) {
              if (args.len() > 0 && named.len() == 0 && args.len() != fieldArity(c, name)) {
                c.report(errCtorArity(), e.line, e.col);
              } else if (args.len() == 0 && named.len() == 0 && !hasDefault(c, name, 0)) {
                c.report(errNoDefault(), e.line, e.col);
              }
            }
          }
          else { checkCallee(c, name, args, named, e); }
        }
        else: { }
      }
    }
    // A real `Call` is a method or a funcref. A method call is `Call(Member(receiver, name), args)`
    // and is checked; a funcref call has no name to look up and is not.
    case Call(callee, args): {
      // **A variant construction's arguments have slots, and they are the payload's.** `Wrap.W(Box(5))`
      // puts a `Box<T>` in the first one, which is what a bare `Box(5)` needs to know which instance
      // it is — without it the construction was checked against no slot at all and refused as "not
      // callable". `spec/cases/0046`.
      string payloadOwner = variantCalleeOwner(c, callee);
      // **In the instance's world, not the template's.** The slot `W` declares is written `Box<T>`,
      // and handing that to a bare `Box(5)` asks it to be a `Box<T>` — a type nobody wrote. Which
      // instance it is comes from the slot the construction itself lands in: `Wrap<i32> w = …` is
      // the only place `i32` is said. `spec/cases/0046`.
      // `want`, not `c.expected`: the slot is read and cleared at the top of this function, exactly
      // as the array and construction arms above already note.
      string outerSlot = want;
      string outerBase = genericBase(outerSlot);
      bool ownerKnown = payloadOwner != "" && outerBase != "" && c.enumAt(outerBase) >= 0 &&
                        c.variantArityIn(outerBase, payloadOwner) >= 0;
      // **A method's parameter types, so an argument knows what it is filling.** Without this a
      // lambda passed to a method had no target and was refused outright — `issues/lang/0141`, which
      // is most of this repository's APIs: `Pending.of` is a static taking three funcrefs, and every
      // capability answers through it.
      //
      // A generic receiver is left alone: its parameter types are written in the template's letters,
      // and `typeOfExpr` already declines to answer for one rather than claiming `T`.
      string methodOwner = "";
      // **A generic static takes its `T` from the slot the call lands in.** `Pending.of` is declared
      // `Pending<T> of(…)` inside `struct Pending<T>`, so it returns the owner instantiated — which
      // means the wanted type *is* the instantiation, and no unification is needed to read `T` off
      // it. `issues/lang/0141`; the enum-payload arm below binds from `want` the same way and for the
      // same reason.
      string methodInst = "";
      match (callee.kind) {
        case Member(mobj, mnameTok): {
          string mrecv = typeOfExpr(c, mobj);
          if (mrecv == typeNone()) { mrecv = staticOwnerName(c, mobj); }
          if (mrecv != "" && mrecv != typeNone()) {
            if (!c.isGeneric(mrecv)) {
              methodOwner = mrecv;
              // **A receiver that names an instantiation carries its own `T`.** `methodAt` collapses
              // `Vec<fn[i32(i32)]>` to the template it was declared in, so a parameter written `T`
              // arrives spelled `T` — and an argument checked against `T` is checked against a type
              // nobody wrote. `issues/lang/0141` bound `T` for a *static* from the slot the call lands
              // in; an instance method needs no slot, because the receiver already says which
              // instantiation this is.
              //
              // `Vec<fn[i32(i32)]> hs; hs.push((i32 n) => n);` is what found it: a lambda has no type
              // of its own, so *expected T, found a lambda* is the whole diagnostic, and a container
              // of continuations could not be filled.
              if (templateOf(mrecv) != mrecv) { methodInst = mrecv; }
            }
            else if (genericBase(want) == mrecv) {
              // The call's result is an instantiation of the very generic being called on, so its
              // arguments can be read in that world. Anything else is left alone: a generic whose
              // parameters this checker cannot bind is one it declines to guess about.
              methodOwner = mrecv;
              methodInst = want;
            }
          }
        }
        else: { }
      }
      i32 methodIx = methodOwner == "" ? -1 : c.methodAt(methodOwner, tokenText(c, calleeName(c, callee)));
      for (i32 i = 0; i < args.len(); i++) {
        // **Whether this argument has a slot at all**, which is a different question from what the
        // slot is. Neither branch fires when the receiver is a type this file does not contain — an
        // import, in a single-file check — and an empty `c.expected` then means "could not tell"
        // rather than "nothing wanted". Only `checkLambda` needs the difference; see
        // `C.expectedUnknown`.
        bool slotted = false;
        if (payloadOwner != "") {
          string slot = c.fieldTypeAtIndex(payloadOwner, i);
          c.expected = ownerKnown ? substituteType(c, outerSlot, slot) : slot;
          slotted = true;
        } else if (methodIx >= 0 && i < c.methodParamCount[methodIx]) {
          string mslot = c.methodParamTypes[c.methodParamAt[methodIx] + i];
          c.expected = methodInst == "" ? mslot : substituteType(c, methodInst, mslot);
          slotted = true;
        }
        c.expectedUnknown = !slotted;
        checkExpr(c, args[i]);
        c.expectedUnknown = false;
      }
      match (callee.kind) {
        case Member(obj, nameTok): {
          // The **object**, not the whole callee. Walking the callee as an expression would read
          // `p.inc()` as a field access to `inc` and call it a missing field, which is the method it
          // is about to check. The nullable rule still applies and is asked for separately, because
          // *"cannot call method on nullable"* is its own diagnostic.
          checkReceiver(c, obj);
          checkThroughNullable(c, e, obj);
          checkMethodCall(c, e, callee, obj, tokenText(c, nameTok), args);
        }
        else: {
          checkExpr(c, callee);
          // **`7()` is not a call.** A funcref is, a name that is a function is, and everything else
          // this checker can put a type to is *"type 'i32' is not callable"* — at the callee, which
          // is where the reference reports it. Silent on a type it cannot name, as everywhere.
          //
          // `null()` is the one that has no type to put: a null is not a value of anything, and
          // `naturalTypeOf` says so by answering nothing. It is still not callable, and
          // `packages/bls/src/fp12.wac` is where a mutation wrote one.
          if (litKindOf(callee) == litNull()) {
            c.report(errNotCallable(), callee.line, callee.col);
            return;
          }
          string ct = naturalTypeOf(c, callee);
          if (ct != typeNone() && ct != "" && !startsWithFn(ct)) {
            c.report(errNotCallable(), callee.line, callee.col);
          }
        }
      }
    }
    else: { }
  }
}

/**
 * `x++` and `--x`, which are a write and an arithmetic operation at once.
 *
 * Two rules, and they land in different places: the write is refused at the **operand**, which is
 * where every other const complaint goes, and a type that cannot be incremented is refused at the
 * **node's own position**. Those are the same column for `++x` and differ for `x++`, and the node's
 * position differs again between the two forms — a statement `x++;` starts at the `x`, while the
 * expression `return x++` is positioned at the operator. Passing the position in rather than deriving
 * it from the operator token is what lets one function serve both.
 *
 * Unsigned types are fine despite the wording of the reference's message — `u32` and `u64` increment
 * — which is measured rather than read off the text. Everything that is not an integer at all is
 * refused, floats included; that half used to be spelled as the two float names, so a struct or a
 * string incremented quietly.
 */
void checkIncr(C c, Lvalue target, i32 line, i32 col) {
  checkWrite(c, target);
  checkLvalueExprs(c, target);
  string t = typeOfLvalue(c, target);
  // **Everything that is not an integer**, which this listed as the two floats. A `bool`, a string,
  // a struct, an enum, an array, a funcref and an `anyref` were all incrementable — seven of the
  // thirteen types a grid tries. Unsigned integers *are* fine despite the wording of the reference's
  // message, which is the part that has to be measured rather than read.
  // A `u8[]` element is an integer that happens to be stored narrow — `b[0]++` is ordinary — so the
  // packed names count here even though they cannot be written as a type anywhere useful.
  if (t != typeNone() && t != "" && !isIntegerName(t) && !isPackedName(t)) {
    c.report(errIncrType(), line, col);
  }
}

/**
 * A nullable packed type, which the language has nowhere to put.
 *
 * `u8?` is not a narrower `i32?`: unwrapping one has to yield a value, and no slot is one byte wide,
 * so there is no representation for the unwrapped case at all. Refused wherever the type is written,
 * and the array form `u8?[]` is the same fact one level down — an array of them would need the
 * element to exist.
 */
/**
 * A packed type written where it has no slot to live in.
 *
 * `checkParams` has said for a long time that a packed type "exists as an array element and nowhere
 * else", and enforced it for parameters. A local, a return type and a cast target are the other
 * three positions, and each was silent — a rule claimed in four places and implemented in one, which
 * a grid over the types by the positions is what found.
 *
 * An **array element** is the only position that is legal — not a struct field, which is refused
 * too, and which I had assumed was allowed until the grid said otherwise. So this asks about the
 * type as written rather than about anything inside it: `u8[]` is an array and fine anywhere, and
 * only a bare `u8` is wrong.
 */
void checkPackedHere(C c, string t, i32 line, i32 col) {
  if (isPackedName(t)) { c.report(errPackedPosition(), line, col); }
}

void checkPackedNullable(C c, string t, Ty at) {
  // **Every `[]`, not the outermost one.** `u8?[][]` is an array of arrays of a nullable packed
  // type, and stripping one suffix left `u8?[]`, which is not itself packed. `spec/cases/0070`.
  string inner = t;
  for (i32 guard = 0; guard < 8; guard++) {
    if (!isArrayName(inner)) { break; }
    inner = dropLast(inner, 2);
  }
  string unwrapped = withoutNull(inner);
  if (unwrapped != "" && isPackedName(unwrapped)) {
    Ty base = baseTy(at);
    c.reportWith(errPackedNullable(), base.line, base.col, t + " has no room for the absent case");
  }
}

/**
 * The innermost type under any `[]` and `?` suffixes.
 *
 * Each suffix carries its own token position — the parser records where the `[` is, not where the
 * type it decorates begins — so a complaint about `u8?[]` reported at the `Ty` itself lands on the
 * bracket, three columns past where the reference puts it. Rung 2 learned this about parse errors;
 * this is the same fact reaching a different consumer.
 */
Ty baseTy(Ty t) {
  match (t.kind) {
    case Arr(elem): { return baseTy(elem); }
    case Nullable(inner): { return baseTy(inner); }
    else: { return t; }
  }
}

/**
 * The expressions buried inside an lvalue — the `i` in `a[i]`, and so on down the path.
 *
 * A write's target is walked for what it *is* (const, a string index) and, until the grid asked, not
 * at all for what is in it: `a[(p + q)]++` had a fault in a position nothing visited. Writing this
 * separately from `checkWrite` keeps the two questions apart, since one reports about the path and
 * the other about the expressions hanging off it.
 */
void checkLvalueExprs(C c, Lvalue lv) {
  match (lv.kind) {
    case LIndex(base, index): { checkLvalueExprs(c, base); checkExpr(c, index); }
    case LField(base, nameTok): { checkLvalueExprs(c, base); }
    case LUnwrap(base): { checkLvalueExprs(c, base); }
    else: { }
  }
}

/**
 * Whether anything in the file binds this name.
 *
 * Every binder wac has, in one place, because the undefined-name rule is only as good as this list:
 * a name it does not know about is a false diagnostic on working code rather than a missed case.
 * Locals, parameters, `this`, match bindings and imports live in the name table; functions, structs
 * and enums have tables of their own; and the primitive type names are bound by the language rather
 * than by anything in the file — `string.fromBytes(b)` puts one in expression position.
 */
bool nameExists(C c, string n) {
  if (c.isDeclaredName(n)) { return true; }
  if (c.funcAt(n) >= 0 || c.isStruct(n) || c.isEnum(n)) { return true; }
  return isPrimitiveName(n) || n == "string" || n == "bool" || n == "anyref";
}

/** Whether an expression is known not to be a boolean. Unknown is `false`: silence, as everywhere. */
/**
 * `expected <want>, found <got>` — the annotation `spec/spec/errors.md` asks for, phrased as the
 * reference phrases it.
 *
 * Empty when either side is a type this checker cannot name, because "expected i32, found unknown"
 * is worse than no annotation at all: it reads as a fact about the program when it is a fact about
 * the compiler.
 */
string expectedFound(string want, string got) {
  if (want == typeNone() || want == "" || got == typeNone() || got == "") { return ""; }
  return "expected " + want + ", found " + got;
}

/** What an expression is, for a diagnostic — a literal answers with the type it naturally has. */
string foundType(C c, Expr e) {
  i32 k = litFamily(c, e);
  if (k == litInteger()) { return "i32"; }
  if (k == litFloat()) { return "f64"; }
  if (k == litBool()) { return "bool"; }
  if (k == litString()) { return "string"; }
  return typeOfExpr(c, e);
}

bool notBool(C c, Expr e) {
  i32 lit = litKindOf(e);
  if (lit != litNone()) { return lit != litBool(); }
  string t = typeOfExpr(c, e);
  return t != typeNone() && t != "bool";
}

/**
 * What is being called, before anything about the arguments.
 *
 * Four answers, and only the first is a function: a **declared function**, a **local holding a
 * funcref**, a **local holding something else** — which is not callable at all — and a name that is
 * nothing, which is the undefined-name rule reaching call position. All three complaints land on the
 * call, which is the only thing there is to name.
 *
 * A call through a funcref is checked for arity and no further: the parameter *types* are in the
 * funcref's spelling and could be compared, but that needs the spelling taken apart again and the
 * corpus does not distinguish it.
 */
void checkCallee(C c, string name, Expr[] args, NamedArg[] named, Expr call) {
  if (c.funcAt(name) >= 0) {
    // `f { x: 1 }` — the named-argument syntax belongs to struct construction and nothing else.
    if (named.len() > 0) { c.report(errNotCallable(), call.line, call.col); return; }
    checkCall(c, name, args, call);
    return;
  }
  if (c.isDeclaredName(name)) {
    string t = c.typeOfName(name);
    if (t == typeNone() || t == "") { return; }
    if (named.len() > 0) { c.report(errNotCallable(), call.line, call.col); return; }
    i32 arity = funcrefArity(t);
    if (arity < 0) {
      // **A local that is not a funcref does not take the call position.**
      // `[§wac-param-shadows-func-5nkq2wp]`: a bare name in call position resolves to a local or
      // parameter *of funcref type* before any function. So `i32 cert = cert(cli);` calls the
      // imported `cert`, and reporting the local's type here applied the rule with its condition
      // dropped. It only ever fired when the shadowed function was *imported*, because a same-file
      // one is found by `funcAt` above. `issues/lang/0143`.
      //
      // Still reported when the name is bound only once: `i32 x = 1; x()` with no `x` anywhere is
      // not callable and the reference says so too, so silence there would be a new disagreement in
      // the other direction rather than a fix.
      if (c.shadowsOuterName(name)) { return; }
      c.report(errNotCallable(), call.line, call.col);
      return;
    }
    // A **type parameter's** funcref says how many arguments it takes and nothing about what they
    // are, and inside a generic function even that is a substitution this checker does not perform.
    if (arity != args.len()) { c.report(errCallArity(), call.line, call.col); return; }
    checkFuncrefArgs(c, t, args);
    return;
  }
  if (c.isEnum(name) || isPrimitiveName(name) || name == "string" || name == "bool") { return; }
  c.report(errNotCallable(), call.line, call.col);
}

/**
 * How many parameters a funcref type takes, or -1 when the type is not one.
 *
 * Counted from the spelling — `fn(i32, f64) -> void` — because the spelling *is* the type here. An
 * empty parameter list is zero rather than one, which is the whole of the special case.
 */
i32 funcrefArity(string t) {
  if (!startsWithFn(t)) { return -1; }
  u8[] a = t.toBytes();
  i32 depth = 0;
  i32 n = 1;
  bool empty = true;
  for (i32 i = 3; i < a.len(); i++) {
    if (a[i] == 41 && depth == 0) { break; }
    if (a[i] == 40 || a[i] == 60) { depth = depth + 1; }
    else if (a[i] == 41 || a[i] == 62) { depth = depth - 1; }
    else if (a[i] == 44 && depth == 0) { n = n + 1; }
    if (a[i] != 32) { empty = false; }
  }
  return empty ? 0 : n;
}

/**
 * The `i`th parameter of a funcref type, from its spelling, or `""`.
 *
 * Split the way `funcrefArity` counts: on a comma at depth zero, so `fn(fn(i32, i32) -> i32, u8[])`
 * is two parameters rather than three. The spelling *is* the type here, which is why this can be
 * read off it at all.
 */
string funcrefParam(string t, i32 index) {
  if (!startsWithFn(t)) { return ""; }
  u8[] a = t.toBytes();
  i32 depth = 0;
  i32 n = 0;
  i32 from = 3;
  for (i32 i = 3; i < a.len(); i++) {
    if (a[i] == 41 && depth == 0) {
      if (n == index) { return trimmed(t, from, i); }
      return "";
    }
    if (a[i] == 40 || a[i] == 60) { depth = depth + 1; }
    else if (a[i] == 41 || a[i] == 62) { depth = depth - 1; }
    else if (a[i] == 44 && depth == 0) {
      if (n == index) { return trimmed(t, from, i); }
      n = n + 1;
      from = i + 1;
    }
  }
  return "";
}

/** `t[from..to)` without surrounding spaces. */
string trimmed(string t, i32 from, i32 to) {
  u8[] a = t.toBytes();
  i32 b = from;
  i32 e = to;
  while (b < e && a[b] == 32) { b = b + 1; }
  while (e > b && a[e - 1] == 32) { e = e - 1; }
  u8[] out = u8[e - b]();
  for (i32 i = 0; i < out.len(); i++) { out[i] = a[b + i]; }
  return string.fromBytes(out);
}

/**
 * A call through a funcref, argument by argument.
 *
 * **Only against a parameter this checker can name.** An unbound `T` inside a generic, or a
 * `Pending<T>`, is a spelling it cannot compare without performing a substitution it does not
 * perform — and a wrong complaint about correct code is worse than a missed one, so those are
 * skipped. What is left is the concrete case, which is the one that matters: every capability the
 * platform hands a program is a funcref field, so `cli.sendTo(handle, bytes, peer, port)` against
 * `fn(i32, string, i32, u8[])` went to nobody until the module refused to instantiate.
 */
void checkFuncrefArgs(C c, string held, Expr[] args) {
  for (i32 i = 0; i < args.len(); i++) {
    string want = funcrefParam(held, i);
    if (want == "" || want == typeNone()) { continue; }
    if (!nameableType(c, want)) { continue; }
    i32 lit = litKindOf(args[i]);
    if (lit != litNone()) {
      reportLiteral(c, want, args[i], errArgumentMismatch(), args[i].line, args[i].col);
      continue;
    }
    string got = typeOfExpr(c, args[i]);
    if (got == typeNone() || got == "") { continue; }
    if (nullableIntoNonNull(want, got)) {
      c.report(errNullableToNonNull(), args[i].line, args[i].col);
    } else if (!assignable(c, want, got)) {
      c.report(errArgumentMismatch(), args[i].line, args[i].col);
    }
  }
}

/** Whether this checker can compare against a type by name, rather than only carry it around. */
bool nameableType(C c, string t) {
  if (isArrayName(t)) { return true; }
  return isPrimitiveName(t) || t == "string" || t == "bool" || c.isStruct(t) || c.isEnum(t);
}

/**
 * What a funcref answers — the `T` of `fn(i32) -> T` — or `""` when the type is not one.
 *
 * The arrow is the separator, and the one that matters is the one after the **parameter list's own
 * closing parenthesis** — found by depth, not by position. `fn(fn(i32) -> i32) -> bool` takes a
 * funcref and answers a bool, so splitting on the *first* arrow would have said `i32`.
 *
 * Taking the *last* one is wrong in the mirror case, which is what this used to do: a funcref that
 * answers a funcref, `fn(fn(i32) -> i32) -> fn(i32) -> i32`, has its final arrow inside its own
 * return type, and splitting there answered `i32` for something that hands back a function. Nothing
 * noticed while the only caller was a struct field, because no field in this repository holds one —
 * the generated sweep found it within a minute of a second caller existing.
 */
string funcrefReturn(string t) {
  if (!startsWithFn(t)) { return ""; }
  u8[] a = t.toBytes();
  // `fn(` opens the parameter list at index 2; the matching close is where the signature's own
  // arrow follows.
  i32 depth = 0;
  i32 close = -1;
  for (i32 i = 2; i < a.len(); i++) {
    if (a[i] == 40) { depth = depth + 1; }
    if (a[i] == 41) {
      depth = depth - 1;
      if (depth == 0) { close = i; break; }
    }
  }
  if (close < 0) { return ""; }
  i32 at = -1;
  if (close + 3 < a.len() && a[close + 1] == 32 && a[close + 2] == 45 && a[close + 3] == 62) {
    at = close + 4;
  }
  if (at < 0) { return ""; }
  string out = "";
  for (i32 i = at; i < a.len(); i++) {
    if (a[i] == 32 && out == "") { continue; }
    out = out + t[i];
  }
  return out;
}

/**
 * A lambda against the `fn[…]` the context wants — `design/lang/0002` tier two.
 *
 * **The target is the whole of its type.** A lambda writes its parameters and nothing else, so its
 * signature is only complete once something says what it is being used as. wac always does: there is
 * no `var`, so a lambda is written into an assignment, an argument or a `return`, and `c.expected`
 * carries that type down — the same channel a literal is checked through, for the same reason.
 *
 * The parameters are compared as one string rather than one at a time. A funcref has no variance
 * (`typeOfTy` says so where it builds the name), so two signatures agree exactly when they spell the
 * same, and one comparison reports arity and parameter types together in the words the rest of this
 * checker uses: *expected fn(i32) -> i32, found fn() -> i32*.
 */
void checkLambda(C c, string want, bool wantUnknown, Expr e, Param[] params, Stmt[] body) {
  // Nothing wanted a funcref here. A lambda has no type of its own to fall back on, so this is the
  // one shape that cannot be reported as a mismatch by the caller: `typeOfExpr` answers unknown for
  // a lambda, and unknown is assignable to everything, which is exactly how `i32 g = () => 42;` was
  // accepted before this function existed.
  if (!startsWithFn(want)) {
    // **Nothing could say what was wanted is not the same as nothing wanted one.** See
    // `C.expectedUnknown`: an argument to a call whose callee this file cannot see has no slot to be
    // wrong about, and reporting there invents a diagnostic about a program that compiles.
    if (wantUnknown) { return; }
    c.reportWith(errLambdaNoTarget(), e.line, e.col,
                 want == typeNone() ? "" : expectedFound(want, "a lambda"));
    return;
  }

  string ret = funcrefReturn(want);
  string got = "fn(";
  for (i32 i = 0; i < params.len(); i++) {
    string pt = typeOfTy(c, params[i].type);
    if (i > 0) { got = got + ", "; }
    got = got + pt;
  }
  got = got + ") -> " + ret;
  if (got != want) {
    c.reportWith(errLambdaSignature(), e.line, e.col, expectedFound(want, got));
    return;
  }

  // The body, with the parameters visible and `return` answering to the target's return type.
  //
  // Saved and restored rather than cleared: a lambda inside a lambda would otherwise leave the outer
  // one's returns checked against nothing when the inner one finished.
  string outer = c.lambdaReturn;
  c.lambdaReturn = ret;
  c.pushScope(body);
  for (i32 i = 0; i < params.len(); i++) {
    c.declareConst(tokenText(c, params[i].nameTok), typeOfTy(c, params[i].type), params[i].isConst);
  }
  // **The locals, before the walk** — the same two passes a function body gets, and for the same
  // reason: a statement may name something declared further down. The enclosing function's
  // `declareAll` cannot do it, because a lambda is an *expression* and `declareStmt` walks
  // statements, so a lambda's body is the one place locals were never collected. Without this,
  // `() => { i32 x = 2; return x; }` reported *undefined name* at `x`.
  declareAll(c, body);
  for (i32 i = 0; i < body.len(); i++) { checkStmt(c, body[i], tyPrim(-1, e.line, e.col)); }
  c.popScope();
  c.lambdaReturn = outer;
}

/** A call's method name token, or -1 when the callee is not a member access. */
i32 calleeName(C c, Expr callee) {
  match (callee.kind) {
    case Member(obj, nameTok): { return nameTok; }
    else: { return -1; }
  }
}

/**
 * The type a *static* call is on — `Box.make(…)` — where the receiver is a type rather than a value.
 *
 * `typeOfExpr` answers nothing for the `Box` in `Box.make`, because it is a name that is not a
 * variable. A static is called on the type, so the name itself is the owner.
 */
string staticOwnerName(C c, Expr obj) {
  match (obj.kind) {
    case Ident(tok): {
      string n = c.renamed(tokenText(c, tok));
      return c.isStruct(n) || c.isEnum(n) ? n : "";
    }
    else: { return ""; }
  }
}

/**
 * How many parameters a funcref spelling has, and the `i`th of them.
 *
 * The spelling is `fn(A, B) -> R`, so the parameters are what sits between the first `(` and its
 * matching `)`, split on commas at depth zero — a parameter may itself be an `fn(…)` or a `Map<K, V>`,
 * and neither may be split through.
 */
i32 funcrefParamCount(string t) {
  string inside = funcrefParamText(t);
  if (inside == "") { return 0; }
  i32 n = 1;
  i32 depth = 0;
  u8[] a = inside.toBytes();
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 40 || a[i] == 60) { depth = depth + 1; }
    else if (a[i] == 41 || a[i] == 62) { depth = depth - 1; }
    else if (a[i] == 44 && depth == 0) { n = n + 1; }
  }
  return n;
}

string funcrefParamAt(string t, i32 at) {
  string inside = funcrefParamText(t);
  i32 n = 0;
  i32 depth = 0;
  i32 start = 0;
  u8[] a = inside.toBytes();
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 40 || a[i] == 60) { depth = depth + 1; }
    else if (a[i] == 41 || a[i] == 62) { depth = depth - 1; }
    else if (a[i] == 44 && depth == 0) {
      if (n == at) { return trimSpace(inside.slice(start, i)); }
      n = n + 1;
      start = i + 1;
    }
  }
  return n == at ? trimSpace(inside.slice(start, a.len())) : "";
}

/** What is between `fn(` and its matching `)`. */
string funcrefParamText(string t) {
  if (!startsWithFn(t)) { return ""; }
  u8[] a = t.toBytes();
  i32 depth = 0;
  for (i32 i = 2; i < a.len(); i++) {
    if (a[i] == 40) { depth = depth + 1; }
    if (a[i] == 41) {
      depth = depth - 1;
      if (depth == 0) { return i == 3 ? "" : t.slice(3, i); }
    }
  }
  return "";
}

/** `s` without leading or trailing spaces. */
string trimSpace(string s) {
  u8[] a = s.toBytes();
  i32 from = 0;
  i32 to = a.len();
  while (from < to && a[from] == 32) { from = from + 1; }
  while (to > from && a[to - 1] == 32) { to = to - 1; }
  return s.slice(from, to);
}

/** Whether a type name is a funcref, which this spells `fn(` and nothing else does. */
bool startsWithFn(string t) {
  u8[] a = t.toBytes();
  if (a.len() < 4) { return false; }
  return a[0] == 102 && a[1] == 110 && a[2] == 40;
}

/**
 * The arguments of a call against the parameters of what it calls.
 *
 * Only a plain named function declared in this file. A name that is not one — a struct being
 * constructed, an imported function, a generic — simply is not in the table, and `funcAt` answering
 * -1 is the silence that keeps this a subset.
 *
 * An arity mismatch is left alone too. The reference answers it with its own message — *"expected 2
 * argument(s), got 1"* — and pairing arguments with parameters positionally when the counts differ
 * would report the wrong ones anyway.
 */
/**
 * Whether a call to a generic function says what its type parameters are.
 *
 * Three ways it can fail and they are one rule: a parameter no argument's type mentions
 * (`T zero<T>()`), an argument whose type is not evident (`id(null)` — a null is not a value of
 * anything), and an argument whose shape cannot match the parameter's (`unbox(p)` where `p` is a `P`
 * and the parameter is `Box<T>`). All three end with a `T` nobody has bound, which is the thing to
 * report, and `bindTypeParams` already answers it — it binds what it can and says nothing about
 * what it cannot, so an unbound name after every argument means the call did not determine it.
 *
 * What this does **not** do is check each argument against its substituted parameter type. That
 * needs the substitution, and being wrong in the silent direction is the rule here.
 */
/**
 * A type **as written**, with the type parameters left standing: `Box<T>`, `T[]`, `T?`.
 *
 * `typeOfTy` answers `unknown` for all of these on purpose — `T` stands for whatever a call site
 * binds, so no question about it has an answer. But a *local* declared `Box<T> b` still needs a
 * spelling for one rule: a generic that instantiates itself with a type built out of its own
 * parameter never bottoms out, and unknown cannot tell `grow(b)` from `grow(a)`.
 */
string writtenTy(C c, Ty t) {
  match (t.kind) {
    case Prim(tok): { return tokenText(c, tok); }
    case Named(tok, typeArgs): {
      string base = c.renamed(tokenText(c, tok));
      if (typeArgs.len() == 0) { return base; }
      string out = base + "<";
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (i > 0) { out = out + ", "; }
        out = out + writtenTy(c, typeArgs[i]);
      }
      return out + ">";
    }
    case Arr(elem): { return writtenTy(c, elem) + "[]"; }
    case Nullable(inner): { return writtenTy(c, inner) + "?"; }
    else: { return ""; }
  }
}

/** Whether a written type is exactly one of the type parameters in scope. */
bool isActiveParam(C c, string t) {
  for (i32 i = 0; i < c.activeParamCount; i++) {
    if (c.activeParams[i] == t) { return true; }
  }
  return false;
}

/**
 * Whether a written type *mentions* a type parameter in scope — `Box<T>`, `T[]`, `T?`.
 *
 * A whole-name match: `Tree` does not mention `T`, which a substring search would say it does.
 */
bool mentionsActiveParam(C c, string t) {
  u8[] b = t.toBytes();
  for (i32 i = 0; i < c.activeParamCount; i++) {
    u8[] p = c.activeParams[i].toBytes();
    if (p.len() == 0) { continue; }
    for (i32 at = 0; at + p.len() <= b.len(); at++) {
      bool hit = true;
      for (i32 k = 0; k < p.len(); k++) {
        if (b[at + k] != p[k]) { hit = false; }
      }
      if (!hit) { continue; }
      bool beforeOk = at == 0 || !isNameByte(b[at - 1]);
      i32 after = at + p.len();
      bool afterOk = after >= b.len() || !isNameByte(b[after]);
      if (beforeOk && afterOk) { return true; }
    }
  }
  return false;
}

/** A byte a name may be spelled with, so a whole-name match knows where one ends. */
bool isNameByte(i32 b) {
  return (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || b == 95;
}

/** Whether an expression is a call made *through a funcref value* rather than to a named function. */
bool funcrefCall(C c, Expr e) {
  match (e.kind) {
    // `g(1)` where `g` is a local reaches here as a **`Construct`**, not a `Call`: `name(args)` is
    // ambiguous until something says whether `name` is a type, and the parser leaves that to the
    // checker. Both spellings are the same question here.
    case Construct(ctype, args, named): {
      match (ctype.kind) {
        case Named(tok, typeArgs): { return startsWithFn(c.typeOfName(tokenText(c, tok))); }
        else: { return false; }
      }
    }
    case Call(callee, args): {
      match (callee.kind) {
        case Ident(tok): { return startsWithFn(c.typeOfName(tokenText(c, tok))); }
        else: { return false; }
      }
    }
    else: { return false; }
  }
}

void checkGenericInference(C c, i32 at, string name, Expr[] args, Expr call) {
  i32 n = c.funcTypeParamCount[at];
  if (n == 0) { return; }
  string[] names = string[n]();
  string[] bound = string[n]();
  for (i32 i = 0; i < n; i++) {
    names[i] = c.funcTypeParamNames[c.funcTypeParamAt[at] + i];
    bound[i] = "";
  }
  for (i32 i = 0; i < args.len(); i++) {
    // **A literal does say what `T` is, here.** `pick(3, 9, true)` infers `i32` from the literals and
    // the language means it — `spec/tour.wac` says so and `genericCallReturn` passes `typeNone` for
    // one because *its* question is what the call returns, where a literal must not pin the answer.
    // Two questions, one argument, and the fourth time this session that "a literal has no type of
    // its own" has been the wrong half of the rule to reach for.
    // **A call through a funcref says nothing about `T`.** `id(g(1))` for `fn[i32(i32)] g` is a
    // compile error the spec spells out — *"a call through a funcref, whose return type is not read
    // here"* — and this checker could name the type, which is not the same as the language reading
    // it. Bound by nothing, so `T` reaches the unbound report below exactly as `null` does.
    // `spec/cases/0085`.
    if (funcrefCall(c, args[i])) { continue; }
    string got = foundType(c, args[i]);
    bindTypeParams(c, c.funcParamTypes[c.funcParamAt[at] + i], got, names, bound);
  }
  // **A funcref parameter is not judged.** `mapOption<T, U>(Option<T> o, fn[U(T)] f)` binds `U`
  // through the *shape* of a function type, and `bindTypeParams` decomposes arrays, nullables and
  // generic instances but not `fn(…) -> …`. Reporting an unbound `U` here refused
  // `packages/std/test/wac/option_test.wac`, which is correct code. Silence until the binder can
  // read a funcref, which is the direction to be wrong in.
  for (i32 i = 0; i < args.len(); i++) {
    if (startsWithFn(c.funcParamTypes[c.funcParamAt[at] + i])) { return; }
  }
  // **A generic that instantiates itself with a bigger type never bottoms out.** `i32 grow<T>(T a)
  // { Box<T> b = Box(a); return grow(b); }` asks for `grow<Box<T>>`, then `grow<Box<Box<T>>>`, and
  // no depth limit makes that finite. The binding is what says so: an ordinary recursion binds `T`
  // to `T` — a recursive sort calling itself on the same `T[]` is the commonest shape in the
  // language — and this one binds it to a type that *contains* `T`. `spec/cases/0086`.
  if (c.activeParamCount > 0 && name == c.activeFunc) {
    for (i32 t = 0; t < n; t++) {
      if (bound[t] == "" || isActiveParam(c, bound[t])) { continue; }
      if (!mentionsActiveParam(c, bound[t])) { continue; }
      c.reportWith(errCallArity(), call.line, call.col,
                   "instantiating " + name + " again with " + bound[t]);
      return;
    }
  }
  // **Inside a generic function nothing is evident.** `T twice<T>(T a) { return id(id(a)); }` calls
  // `id` with a value whose type *is* the enclosing `T`, which this checker holds as an unknown type
  // on purpose — so every argument looks inevident and every call looks uninferrable. The enclosing
  // parameters being active is exactly the condition, and it is the same silence the rest of this
  // file keeps about a type it cannot name.
  if (c.activeParamCount > 0) { return; }
  // **An argument this checker cannot name is its own limit, not the program's.** `id(true ? x : 0)`,
  // `id(s[1])` and `which(i32[2]())` are all inferrable and all answer `typeNone` here, and reporting
  // them refused three of the spec's own programs. A `null` is the one argument that is genuinely
  // evident *and* nameless — it is not a value of anything, which is why the spec refuses `id(null)`
  // and why that case survives this guard.
  for (i32 i = 0; i < args.len(); i++) {
    if (litKindOf(args[i]) == litNull()) { continue; }
    if (funcrefCall(c, args[i])) { continue; }
    if (foundType(c, args[i]) == typeNone()) { return; }
  }
  for (i32 t = 0; t < n; t++) {
    if (bound[t] != "") { continue; }
    c.reportWith(errCallArity(), call.line, call.col,
                 "nothing in the call says what " + names[t] + " is");
    return;
  }
}

void checkCall(C c, string name, Expr[] args, Expr call) {
  i32 at = c.funcAt(name);
  if (at < 0) { return; }
  // The count first, and it stops there: a call with the wrong number of arguments is one complaint
  // about the call, not one per argument that happened to line up with the wrong parameter.
  if (c.funcParamCount[at] != args.len()) {
    c.report(errCallArity(), call.line, call.col);
    return;
  }
  // Arity applies to a generic function; the *types* do not, until the parameters are bound. Binding
  // them is what this asks about — not whether each argument fits, which needs the substitution this
  // checker does not perform, but whether the call determines `T` at all.
  if (c.funcGenerics[at]) {
    checkGenericInference(c, at, name, args, call);
    return;
  }
  for (i32 i = 0; i < args.len(); i++) {
    string want = c.funcParamTypes[c.funcParamAt[at] + i];
    if (want == typeNone()) { continue; }
    i32 lit = litKindOf(args[i]);
    if (lit != litNone()) {
      reportLiteral(c, want, args[i], errArgumentMismatch(), args[i].line, args[i].col);
      continue;
    }
    string got = typeOfExpr(c, args[i]);
    if (nullableIntoNonNull(want, got)) {
      c.report(errNullableToNonNull(), args[i].line, args[i].col);
    } else if (!assignable(c, want, got)) {
      c.report(errArgumentMismatch(), args[i].line, args[i].col);
    }
  }
}

/**
 * A struct construction's arguments against the fields they fill.
 *
 * Positional only, and the arity has to match. Both restrictions are the reference's rather than
 * convenience: a wrong count is *"positional construction of 'P' expects 2 arguments"*, its own
 * family; and `P(x: 1)` is not named-argument syntax at all — the reference answers *"expects 2
 * arguments"* **and** *"undefined variable 'x'"*, so whatever that spelling means, it is not this.
 */
void checkConstruct(C c, string name, Expr[] args, NamedArg[] named, Expr at) {
  if (named.len() > 0) {
    // `Point { x: 1, z: 3 }` names its fields, so the two questions are whether every name is one the
    // struct has and whether every field the struct has was named. Both land on the construction.
    string tmpl = templateOf(name);
    if (!c.isStruct(tmpl) || c.isGeneric(tmpl)) { return; }
    for (i32 i = 0; i < named.len(); i++) {
      if (!c.hasField(tmpl, tokenText(c, named[i].nameTok))) {
        c.report(errNamedField(), at.line, at.col);
        return;
      }
    }
    // **A field may be left out when its type is nullable, and not otherwise.** The strict rule was
    // right about the danger — a construction that quietly defaults a field it forgot is a wrong
    // value with no diagnostic — and wrong about which fields have that danger: `string? note` says
    // *absent is one of the values*, and `null` is what absent means. A non-nullable field has no
    // such value, so leaving it out is still refused. `design/lang/0007`.
    for (i32 fi = 0; fi < c.fieldCount; fi++) {
      if (c.fieldOwners[fi] != tmpl) { continue; }
      if (withoutNull(c.fieldTypes[fi]) != "") { continue; }
      bool set = false;
      for (i32 i = 0; i < named.len(); i++) {
        if (tokenText(c, named[i].nameTok) == c.fieldNames[fi]) { set = true; }
      }
      if (!set) { c.report(errNamedField(), at.line, at.col); return; }
    }
    return;
  }
  if (c.constructArity(name) != args.len()) { return; }
  for (i32 i = 0; i < args.len(); i++) {
    // Read in the instantiation's world: `Box<i32>(1)` wants an `i32` where the field says `T`, and
    // a bare `Box(1)` has nothing to substitute from, so `T` comes back unknown and says nothing.
    string want = substituteType(c, name, c.constructFieldAt(name, i));
    if (want == typeNone()) { continue; }
    i32 lit = litKindOf(args[i]);
    if (lit != litNone()) {
      reportLiteral(c, want, args[i], errFieldMismatch(), args[i].line, args[i].col);
      continue;
    }
    if (!assignable(c, want, typeOfExpr(c, args[i]))) {
      c.report(errFieldMismatch(), args[i].line, args[i].col);
    }
  }
}

/**
 * Whether writing through this lvalue is refused, and why.
 *
 * Three answers because the reference gives three, and they are about different things: the binding
 * is const, the field is const, or the path to it goes through a const reference. A caller fixing one
 * would not fix the others.
 *
 * Reported at the **target**, which is where the reference puts all three.
 */
void checkWrite(C c, Lvalue lv) {
  match (lv.kind) {
    case LIdent(tok): {
      // A write to a name nothing declares. Reached here rather than by the expression rule, because
      // an assignment's target is an `Lvalue` and not an `Expr` — the same rule, one node kind along,
      // which is the fourth time that distinction has hidden a case.
      if (!nameExists(c, tokenText(c, tok))) {
        c.report(errUndefinedName(), lv.line, lv.col);
        return;
      }
      // Only when the declaration said `const`. A local that merely aliases something const may be
      // rebound — assigning to the name mutates nothing, and the alias rule is about writing through.
      if (c.isConstName(tokenText(c, tok)) && !c.isAliasOnlyName(tokenText(c, tok))) {
        c.reportWith(errConstVariable(), lv.line, lv.col, tokenText(c, tok) + " is const");
      }
    }
    case LField(base, nameTok): {
      Lvalue root = rootOf(lv);
      if (undefinedRoot(c, root)) { c.report(errUndefinedName(), root.line, root.col); return; }
      // The same two questions the expression form asks, in the position an `LField` node occupies —
      // the dot — rather than at the root, where the const complaints go. Writing to a field is not
      // a different question from reading one about whether the field is there.
      string ownerT = typeOfLvalue(c, base);
      if (ownerT != typeNone() && ownerT != "") {
        if (withoutNull(ownerT) != "") {
          c.report(errThroughNullable(), lv.line, lv.col);
          return;
        }
        string ownerTmpl = templateOf(ownerT);
        if (c.isStruct(ownerTmpl) && !c.isGeneric(ownerTmpl)) {
          if (!c.hasField(ownerT, tokenText(c, nameTok)) &&
              c.methodAt(ownerT, tokenText(c, nameTok)) < 0) {
            c.report(errNoSuchField(), lv.line, lv.col);
            return;
          }
        } else if (isPrimitiveName(ownerT) || ownerT == "bool") {
          c.report(errNoSuchField(), lv.line, lv.col);
          return;
        }
      }
      string owner = typeOfLvalue(c, base);
      if (owner != typeNone() && c.isConstField(owner, tokenText(c, nameTok))) {
        c.report(errConstField(), root.line, root.col);
        return;
      }
      // Otherwise the path itself may be const: a `const P p` refuses every write through it, field
      // by field, whatever those fields say about themselves.
      if (constPath(c, base)) {
        c.reportWith(errConstReference(), root.line, root.col, constNote(c, root));
      }
    }
    case LIndex(base, index): {
      string baseT = typeOfLvalue(c, base);
      if (baseT != typeNone() && baseT != "" && !isArrayName(baseT) && baseT != "string") {
        c.report(errIndex(), lv.line, lv.col);
        return;
      }
      // Both index complaints land on the `LIndex` node — the bracket — where as an expression the
      // "not an array" one names the operand and the "bad index" one names the index. An lvalue is
      // one node with one position and the reference uses it for both.
      i32 wlit = litKindOf(index);
      if (wlit != litNone()) {
        if (!acceptsLiteral("i32", wlit)) { c.report(errIndex(), lv.line, lv.col); }
      } else {
        string wit = typeOfExpr(c, index);
        if (wit != typeNone() && !isIntegerName(wit)) { c.report(errIndex(), lv.line, lv.col); }
      }
      Lvalue idxRoot = rootOf(lv);
      if (undefinedRoot(c, idxRoot)) {
        c.report(errUndefinedName(), idxRoot.line, idxRoot.col);
        return;
      }
      // A string is not an array with a store: indexing one reads a byte and there is nowhere to put
      // one back. Reported at the index itself rather than at the root, which is where every other
      // complaint in this function goes — the immutability is the string's, not the path's.
      if (typeOfLvalue(c, base) == "string") {
        c.report(errStringIndexWrite(), lv.line, lv.col);
        return;
      }
      Lvalue r = rootOf(lv);
      if (constPath(c, base)) {
        c.reportWith(errConstReference(), r.line, r.col, constNote(c, r));
      }
    }
    case LUnwrap(base): { checkWrite(c, base); }
  }
}

/** Whether the root of a write path is a name nothing declares. */
bool undefinedRoot(C c, Lvalue root) {
  match (root.kind) {
    case LIdent(tok): { return !nameExists(c, tokenText(c, tok)); }
    else: { return false; }
  }
}

/**
 * The leftmost lvalue in a path — `p` in `p.a.b[0]`.
 *
 * Every const complaint is reported here, which is where the reference puts them: for `p.k = 1` it
 * names column 56, the `p`, and not 57, the field node. Reporting at the node that *is* const would
 * have been the obvious choice and is off by one against every compound target.
 */
/** `` `xs` is const `` when the root of the path is a plain name, and nothing when it is not. */
string constNote(C c, Lvalue root) {
  match (root.kind) {
    case LIdent(tok): { return tokenText(c, tok) + " is const"; }
    else: { return ""; }
  }
}

Lvalue rootOf(Lvalue lv) {
  match (lv.kind) {
    case LIdent(tok): { return lv; }
    case LField(base, nameTok): { return rootOf(base); }
    case LIndex(base, index): { return rootOf(base); }
    case LUnwrap(base): { return rootOf(base); }
  }
}

/**
 * Whether an lvalue names a const reference — a binding declared `const`, or a path through one.
 *
 * Distinct from `checkWrite`'s first case: assigning *to* `p` is a const-variable error, while
 * assigning to `p.x` through a const `p` is a const-reference one. Same constness, different
 * complaint, because one rebinds the name and the other reaches past it.
 */
/**
 * Whether an expression is a **const binding by name** — `c`, and not `c.field` or `this.items[i]`.
 *
 * The narrow question on purpose. A path *rooted* at something const is read all over this
 * repository — `out[i] = this.items[i]!` in `parse.wac` copies out of a `const this` and is
 * ordinary — and only the binding itself carries the constness the language tracks.
 */
bool constName(C c, Expr e) {
  match (e.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      return c.isConstName(n) || c.isAliasOnlyName(n);
    }
    else: { return false; }
  }
}

/** Whether a write target is reached *through* something — a field or an element, not a name. */
bool indirectLvalue(Lvalue lv) {
  match (lv.kind) {
    case LField(base, nameTok): { return true; }
    case LIndex(base, index): { return true; }
    case LUnwrap(base): { return indirectLvalue(base); }
    else: { return false; }
  }
}

bool constPath(C c, Lvalue lv) {
  match (lv.kind) {
    case LIdent(tok): { return c.isConstName(tokenText(c, tok)); }
    case LField(base, nameTok): { return constPath(c, base); }
    case LIndex(base, index): { return constPath(c, base); }
    case LUnwrap(base): { return constPath(c, base); }
  }
}

/** One array element or fill against the element type. */
void checkElement(C c, string want, Expr e) {
  i32 lit = litKindOf(e);
  if (lit != litNone()) {
    reportLiteral(c, want, e, errArrayElement(), e.line, e.col);
    return;
  }
  string got = typeOfExpr(c, e);
  if (!assignable(c, want, got)) { c.report(errArrayElement(), e.line, e.col); }
}

/**
 * Whether an expression calls a function, which is what a module-level `const` may not do.
 *
 * A constant's value is computed before the program runs, so arithmetic on literals is fine and
 * `P(1)` is fine — a construction is a shape rather than a computation — while `n()` and `i32[n()]()`
 * are not. Phrased as "does this contain a call" rather than "is this constant" on purpose: the
 * second is the larger claim and the first is the one the corpus actually distinguishes, so this
 * says nothing about anything else.
 */
/**
 * Whether an initialiser reads a module-level constant that does not have a value yet.
 *
 * "Yet" is the file's own order: the ones before this declaration are settled and the rest are not,
 * which makes a self-reference and a cycle the same question asked at different distances. A name
 * that is not a module constant at all — a function, a struct, an enum — is somebody else's rule.
 */
bool readsUnsettledConst(C c, Program prog, Expr e, string[] settled, i32 settledCount) {
  match (e.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      if (!isModuleConst(c, prog, n)) { return false; }
      for (i32 i = 0; i < settledCount; i++) {
        if (settled[i] == n) { return false; }
      }
      return true;
    }
    case Binary(op, left, right): {
      return readsUnsettledConst(c, prog, left, settled, settledCount)
          || readsUnsettledConst(c, prog, right, settled, settledCount);
    }
    case Unary(op, operand): { return readsUnsettledConst(c, prog, operand, settled, settledCount); }
    case Construct(ctype, args, named): {
      for (i32 i = 0; i < args.len(); i++) {
        if (readsUnsettledConst(c, prog, args[i], settled, settledCount)) { return true; }
      }
      for (i32 i = 0; i < named.len(); i++) {
        if (readsUnsettledConst(c, prog, named[i].value, settled, settledCount)) { return true; }
      }
      return false;
    }
    case Call(callee, args): {
      for (i32 i = 0; i < args.len(); i++) {
        if (readsUnsettledConst(c, prog, args[i], settled, settledCount)) { return true; }
      }
      return false;
    }
    case ArrNew(elem, size, fill, elements): {
      for (i32 i = 0; i < elements.len(); i++) {
        if (readsUnsettledConst(c, prog, elements[i], settled, settledCount)) { return true; }
      }
      return false;
    }
    else: { return false; }
  }
}

/** Whether a name is one of this file's module-level constants. */
bool isModuleConst(C c, Program prog, string name) {
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case ConstDecl(nameTok, type, init, exported): {
        if (tokenText(c, nameTok) == name) { return true; }
      }
      else: { }
    }
  }
  return false;
}

bool callsAFunction(C c, Expr e) {
  match (e.kind) {
    case Construct(ctype, args, named): {
      match (ctype.kind) {
        case Named(tok, typeArgs): {
          if (c.funcAt(tokenText(c, tok)) >= 0) { return true; }
        }
        else: { }
      }
      for (i32 i = 0; i < args.len(); i++) {
        if (callsAFunction(c, args[i])) { return true; }
      }
      return false;
    }
    case Call(callee, args): {
      // **A variant construction is a value, not a call.** `const E X = E.A(7);` is a constant the
      // spec writes down — `variables.md` lists a struct, an enum variant, and anything built out of
      // them — and it parses as `Call(Member(E, A), …)` like everything else with parentheses. What
      // makes it a constant is that `struct.new` is a constant instruction; what made this rule
      // refuse it is that the shape looks like a call from the outside.
      match (callee.kind) {
        case Member(obj, nameTok): {
          match (obj.kind) {
            case Ident(tok): {
              string en = tokenText(c, tok);
              if (c.isEnum(en) && c.variantArityIn(en, tokenText(c, nameTok)) >= 0) {
                for (i32 i = 0; i < args.len(); i++) {
                  if (callsAFunction(c, args[i])) { return true; }
                }
                return false;
              }
            }
            else: { }
          }
        }
        else: { }
      }
      return true;
    }
    case Binary(op, left, right): { return callsAFunction(c, left) || callsAFunction(c, right); }
    case Unary(op, operand): { return callsAFunction(c, operand); }
    case ArrNew(elem, size, fill, elements): {
      if (!(size is null)) {
        if (callsAFunction(c, size!)) { return true; }
      }
      if (!(fill is null)) {
        if (callsAFunction(c, fill!)) { return true; }
      }
      for (i32 i = 0; i < elements.len(); i++) {
        if (callsAFunction(c, elements[i])) { return true; }
      }
      return false;
    }
    else: { return false; }
  }
}

/**
 * Whether an expression names something const, following field access.
 *
 * `this.inner.mutate()` inside a `const this` method is refused, and the constness has to travel
 * through the field access to see it — a receiver that is a plain name was all the first version
 * looked at, so every deep receiver came back non-const. Three spec cases are this shape.
 *
 * What it deliberately does not do is follow an *assignment*: `Counter c = this; c.mutate();` is also
 * refused by the reference, and knowing that needs to track where `c` came from, which is flow
 * analysis rather than a walk. That case stays uncaught, and uncaught is the safe direction.
 */
/** Is this type one a write can reach shared state through — a struct, an enum or an array? */
bool mutableRefName(C c, string t) {
  string at = endsWith(t, "?") ? t.slice(0, t.len() - 1) : t;
  return isArrayName(at) || c.isStruct(at) || c.isEnum(at);
}

/**
 * Can a value this expression produces be reached from anywhere the caller already holds?
 *
 * A construction is a new object, which is not enough on its own: `Box(this.i)` is a fresh `Box`
 * whose field is the receiver's, and writing through it writes through the const reference. So a
 * field that could hold a reference has to be built from something fresh in turn, while a field that
 * cannot — an `i32`, a `string` — is a copy and may be built from anything. That is what makes
 * `Counter(this.n)` fresh and `Box(this.i)` not [issue 0060].
 *
 * Everything else is not fresh, a nested call and a named construction included: a syntactic
 * question with a conservative default, not an escape analysis.
 */
bool freshValue(C c, Expr e) {
  match (e.kind) {
    case ArrNew(elem, size, fill, elements): {
      if (!mutableRefName(c, typeOfTy(c, elem))) { return true; }   // one copy per element
      for (i32 i = 0; i < elements.len(); i++) {
        if (!freshValue(c, elements[i])) { return false; }
      }
      if (fill is not null) { return freshValue(c, fill!); }
      return true;
    }
    case Construct(ctype, args, named): {
      if (named.len() > 0) { return false; }
      string t = typeOfTy(c, ctype);
      i32 n = c.constructArity(t);
      for (i32 i = 0; i < n && i < args.len(); i++) {
        if (!mutableRefName(c, c.constructFieldAt(t, i))) { continue; }   // a copy, whatever built it
        if (!freshValue(c, args[i])) { return false; }
      }
      return true;
    }
    else: { return false; }
  }
}

/**
 * Does every `return` in this body hand back something freshly built?
 *
 * A body with no `return` answers yes, which costs nothing: the question is only ever asked about a
 * call whose value is used, and a method that returns a value has a `return`.
 */
bool returnsOnlyFresh(C c, Stmt[] body) {
  for (i32 i = 0; i < body.len(); i++) {
    match (body[i].kind) {
      case Return(value): {
        if (value is not null) {
          if (!freshValue(c, value!)) { return false; }
        }
      }
      case If(cond, then, els): {
        if (!returnsOnlyFresh(c, then)) { return false; }
        if (!returnsOnlyFresh(c, els)) { return false; }
      }
      case While(wcond, wbody): { if (!returnsOnlyFresh(c, wbody)) { return false; } }
      case For(init, fcond, update, fbody): { if (!returnsOnlyFresh(c, fbody)) { return false; } }
      case DoWhile(dbody, dcond): { if (!returnsOnlyFresh(c, dbody)) { return false; } }
      case Block(bbody): { if (!returnsOnlyFresh(c, bbody)) { return false; } }
      case Switch(subject, cases): {
        for (i32 k = 0; k < cases.len(); k++) {
          if (!returnsOnlyFresh(c, cases[k].body)) { return false; }
        }
      }
      case Match(msubject, arms): {
        for (i32 k = 0; k < arms.len(); k++) {
          if (!returnsOnlyFresh(c, arms[k].body)) { return false; }
        }
      }
      else: { }
    }
  }
  return true;
}

bool constExpr(C c, Expr e) {
  match (e.kind) {
    case Ident(tok): { return c.isConstName(tokenText(c, tok)); }
    case Member(obj, nameTok): { return constExpr(c, obj); }
    case Index(arr, index): { return constExpr(c, arr); }
    case Unwrap(operand): { return constExpr(c, operand); }
    // What a method hands back through a const receiver is itself const. `this.getInner().mutate()`
    // inside a `const this` method is refused, and the accessor is the whole point of the case: it
    // looks like a way to launder the constness and is not one. The receiver decides, not the return
    // type — a method called on something const returns something const.
    case Call(callee, args): {
      match (callee.kind) {
        case Member(obj, nameTok): {
          if (!constExpr(c, obj)) { return false; }
          // …unless the method can only be handing back something it built out of copies, which
          // reaches nothing the receiver holds [issue 0060].
          i32 mi = c.methodAt(typeOfExpr(c, obj), tokenText(c, nameTok));
          if (mi < 0) { return true; }
          return !returnsOnlyFresh(c, c.methodBodyAt(mi));
        }
        else: { return false; }
      }
    }
    else: { return false; }
  }
}

/**
 * Whether a type can be produced out of nothing — `P p = P();` and `P[2]()` both ask this.
 *
 * Primitives have a zero, arrays and strings have an empty one, a nullable has null. A struct has a
 * default when every field does, so this recurses; an **enum has none at all**, even one whose every
 * variant is payload-free, because there is no variant the language would pick for you.
 *
 * `depth` is the cycle guard, and returning `false` at the bottom of it is not a fallback: a struct
 * that reaches itself through non-null fields genuinely has no default, since building one would
 * require building one first. That is the same fact the recursive-field rule reports, seen from the
 * construction rather than from the declaration.
 *
 * Unknown is `true` — silence, as everywhere else here. A type this pass cannot see is not a type it
 * gets to complain about.
 */
bool hasDefault(C c, string t, i32 depth) {
  if (t == typeNone() || t == "") { return true; }
  if (depth > 16) { return false; }
  if (isNullableName(t) || isArrayName(t)) { return true; }
  // A funcref has no zero: there is no function to point at until something points it somewhere.
  if (startsWithFn(t)) { return false; }
  if (c.isEnum(t)) { return false; }
  if (!c.isStruct(t) || c.isGeneric(t)) { return true; }
  for (i32 i = 0; i < c.fieldCount; i++) {
    if (c.fieldOwners[i] != t) { continue; }
    if (!hasDefault(c, c.fieldTypes[i], depth + 1)) { return false; }
  }
  string parent = c.parentOf(t);
  if (parent != "") { return hasDefault(c, parent, depth + 1); }
  return true;
}

/** Whether `from`'s non-null fields can reach `target`, which is what makes a reference recursive. */
bool reachesStruct(C c, string from, string target, i32 depth) {
  if (depth > 16 || !c.isStruct(from) || c.isGeneric(from)) { return false; }
  if (from == target) { return true; }
  for (i32 i = 0; i < c.fieldCount; i++) {
    if (c.fieldOwners[i] != from) { continue; }
    string ft = c.fieldTypes[i];
    if (isNullableName(ft) || isArrayName(ft)) { continue; }
    if (reachesStruct(c, ft, target, depth + 1)) { return true; }
  }
  return false;
}

/** How many fields a positional construction of this struct takes, parents included. */
/**
 * What `case List(xs)` binds `xs` to: the variant's `b`th payload field.
 *
 * Declared as unknown until now, which is safe and silent — and silence is what `xs.len(1)` got,
 * along with every other question about a payload. A variant is a struct here and its payload is
 * that struct's fields in order, so the answer is already in the table; nothing was asking for it.
 *
 * Unknown when the variant is not one this checker holds, which is the usual direction: a generic
 * enum's payload is written in its parameters, and a name that means nothing here means nothing.
 */
string armBindingType(C c, Expr subject, Arm arm, i32 b) {
  if (arm.variantTok < 0) { return typeNone(); }
  string variant = tokenText(c, arm.variantTok);
  // **A generic enum's variant is not a struct, and it is still a variant.** This used to require
  // `c.isStruct(variant)` and returned at the door for every generic enum: `declareModule` registers
  // a variant as a bare struct only when its enum takes no type parameters, because `Some` belongs to
  // `Option<i32>` and to every other instance and so names no type on its own (`spec/cases/0037`).
  // Its *fields* are declared either way, which is what this function actually reads — so the guard
  // was excluding the case it was capable of answering, and `isVariantName` is no use either because
  // that asks the same bare-name question.
  //
  // Nothing replaces it: the owners loop below already answers "is this a variant, and exactly one
  // enum's" and returns when it is not. The guard was an early-out that happened to be wrong.
  // **A binding belongs to the enum being matched, and this asked the file instead.**
  // `match (unzip(f))` on an imported `Unzipped { Ok(u8[] bytes) }`, in a file that also declares
  // `Object { Ok(i32 kind, …) }`, bound `raw` to the *local* `Ok`'s first payload and reported every
  // use of it — a false alarm about a name whose declaration is in another file. The owner guard
  // below could not see it: exactly one enum declares `Ok` as far as this slice knows, and it is the
  // wrong one. So the subject decides, and when the subject's type is unknown — which is what an
  // imported function's return is here — nothing about the binding is knowable.
  // `issues/lang/0096`, `spec/cases/0093`.
  string subjT = typeOfExpr(c, subject);
  if (subjT == typeNone() || subjT == "") { return typeNone(); }
  string subjCore = withoutNull(subjT);
  if (subjCore == "") { subjCore = subjT; }
  string subjOwner = enumOfSubject(c, subjCore, isVariantConstruction(c, subject));
  if (subjOwner == "" || !c.isEnum(subjOwner)) { return typeNone(); }
  // **The enum is what may be generic, not the variant.** `Opt<T> { Some(T v) }` registers `Some` as
  // an ordinary struct whose field is written `T`, so binding `v` to it says a working `case Some(v):
  // v` returns a `T` where an `i32` was declared. Six programs said so at once.
  //
  // And **only when one enum declares this variant**: the table is keyed by bare name, so `Ok` from
  // two enums is one struct holding both payloads, and a binding typed from it belongs to neither.
  i32 owners = 0;
  string owner = "";
  for (i32 i = 0; i < c.variantCount; i++) {
    if (c.variantNames[i] != variant) { continue; }
    owners = owners + 1;
    owner = c.variantOwners[i];
  }
  if (owners != 1) { return typeNone(); }
  // And the one that declares it has to be the one being matched. Two enums cannot both declare `Ok`
  // in one file — `spec/cases/0073` — so this fires when the other declarer is imported, where the
  // payload fields under that bare name are the *local* enum's and belong to neither.
  if (owner != subjOwner) { return typeNone(); }
  i32 n = 0;
  for (i32 i = 0; i < c.fieldCount; i++) {
    if (c.fieldOwners[i] != variant) { continue; }
    if (n == b) {
      // **A generic enum's payload is written as its parameter, and the subject says what that is.**
      // `Opt<T> { Some(T v) }` records the field as `T`, which names nothing on its own — so the
      // instantiation has to supply it. `substituteType` already reads the *enum* table for exactly
      // this (`spec/cases/0046`); it had simply never been reached from here.
      //
      // An unsubstituted `T` still fails `nameable`, so an enum with no instantiation to consult is
      // exactly as silent as it was.
      string ft = substituteType(c, subjCore, c.fieldTypes[i]);
      return nameable(c, ft) ? ft : typeNone();
    }
    n = n + 1;
  }
  return typeNone();
}

/**
 * Whether this checker can name the type at all — as opposed to holding a string that looks like one.
 *
 * `Opt<T> { Some(T v) }` records a field whose type is written `T`, and `T` is a *parameter*: an
 * enum's generic-ness cannot be asked of `isGeneric`, which reads the struct table and has no row for
 * an enum. Asking what the type is instead of who declared it answers both — a parameter is a name
 * nothing declares, and binding to it made a working `case Some(v): v` return the wrong type in six
 * programs.
 */
bool nameable(C c, string t) {
  string core = t;
  for (i32 guard = 0; guard < 8; guard++) {
    if (endsWith(core, "[]")) { core = dropLast(core, 2); }
    else if (endsWith(core, "?")) { core = dropLast(core, 1); }
    else { break; }
  }
  string base = genericBase(core);
  string at = base == "" ? core : base;
  return isPrimitiveName(at) || at == "string" || at == "bool" || startsWithFn(at) ||
         c.isStruct(at) || c.isEnum(at);
}

i32 fieldArity(C c, string t) {
  i32 n = 0;
  string at = t;
  for (i32 guard = 0; guard < 16; guard++) {
    if (at == "") { return n; }
    for (i32 i = 0; i < c.fieldCount; i++) {
      if (c.fieldOwners[i] == at) { n = n + 1; }
    }
    at = c.parentOf(at);
  }
  return n;
}

/**
 * Whether a type is held by reference, for the purposes of a cast.
 *
 * Wider than `isReferenceType`, which `anyref` asks: an enum and a funcref are references too, and a
 * nullable one is still one. Kept separate because the two questions have different answers for
 * `anyref` itself and there is no benefit to pretending otherwise.
 */
bool isCastRef(C c, string t) {
  string core = withoutNull(t);
  string at = core == "" ? t : core;
  if (at == "" || at == typeNone()) { return false; }
  return isArrayName(at) || at == "string" || at == "anyref" || startsWithFn(at) ||
         c.isEnum(at) || c.isStruct(at);
}

/**
 * Whether two types meet anywhere in the hierarchy — the ternary's rule.
 *
 * `spec/spec/control.md`: the type of a ternary over references is their *closest common ancestor*,
 * "found by walking each branch's chain of parent structs and taking the nearest struct that appears
 * in both chains". Only branches with **no** common ancestor are an error. Nullability is not part of
 * the question: `S?` and `Sub` meet at `S` whether or not either can be absent.
 */
bool shareAncestor(C c, string a, string b) {
  string ac = withoutNull(a) == "" ? a : withoutNull(a);
  string bc = withoutNull(b) == "" ? b : withoutNull(b);
  // **Two variants of one enum are siblings**, in exactly the sense two structs with one parent are:
  // `y ? E.A(3) : E.B(4)` is an `E`, and each branch has its own variant's type. The parent chain
  // cannot say so — a variant is registered as a struct with no parent — so the enum that owns them
  // answers instead. `spec/cases/0093`'s neighbourhood.
  string ao = variantOwnerOf(c, ac);
  if (ao != "" && ao == variantOwnerOf(c, bc)) { return true; }
  if (ao != "" && (ao == bc || genericBase(bc) == ao)) { return true; }
  string bo = variantOwnerOf(c, bc);
  if (bo != "" && (bo == ac || genericBase(ac) == bo)) { return true; }
  string walk = ac;
  for (i32 guard = 0; guard < 16; guard++) {
    if (walk == "") { return false; }
    if (bc == walk || descendsFrom(c, bc, walk)) { return true; }
    walk = c.parentOf(walk);
  }
  return false;
}

/** The enum that declares this variant, or `""` — ambiguous when two enums do, so nobody's. */
string variantOwnerOf(C c, string name) {
  i32 owners = 0;
  string only = "";
  for (i32 i = 0; i < c.variantCount; i++) {
    if (c.variantNames[i] != name) { continue; }
    owners = owners + 1;
    only = c.variantOwners[i];
  }
  return owners == 1 ? only : "";
}

/** Whether `sub` inherits from `super`, which is what makes a cast between them a downcast. */
bool descendsFrom(C c, string sub, string sup) {
  string at = c.parentOf(sub);
  for (i32 guard = 0; guard < 16; guard++) {
    if (at == "") { return false; }
    if (at == sup) { return true; }
    at = c.parentOf(at);
  }
  return false;
}

/**
 * The builtin statics on the primitive types, and the one instance method with an arity worth checking.
 *
 * `f64.toBits`, `string.fromCodepoint` and their siblings are not declared anywhere. They are the
 * language's own surface, so no signature in the file describes them and the receiver is a type name
 * that is not a struct — which is exactly why they were invisible to every rule up to here, and why
 * they were the largest uncaught cluster once the struct rules were done. Eight spec cases.
 *
 * The surface, measured rather than guessed: each float pairs with the unsigned integer of its own
 * width, `toBits` takes the float and gives the bits and `fromBits` is the reverse; `string.fromBytes`
 * takes `u8[]`, `string.fromCodepoint` takes `i32`. Any other name on those three types has no static
 * method at all, rather than a wrong signature. Arity is reported at the call and an argument's type
 * at the argument, so the two are different positions and are kept as different codes.
 *
 * An argument is compared *exactly*, not by assignability — `f32.toBits(someF64)` is refused even
 * though an `f32` widens to an `f64`, because reinterpretation is about a width and not a value. A
 * literal is the one exception, and takes the parameter's type the way an initialiser does.
 *
 * Returns whether the receiver was a builtin, which is what stops the struct rules from also looking.
 */
bool checkBuiltinCall(C c, Expr call, string recv, string name, Expr[] args) {
  string want = "";
  if (recv == "f64" || recv == "f32") {
    if (name != "toBits" && name != "fromBits") {
      c.reportWith(errNoStaticMethod(), call.line, call.col, "no " + recv + "." + name);
      return true;
    }
    if (name == "toBits") { want = recv; }
    else if (recv == "f64") { want = "u64"; }
    else { want = "u32"; }
  } else if (recv == "string") {
    if (name == "fromBytes") { want = "u8[]"; }
    else if (name == "fromCodepoint") { want = "i32"; }
    else {
      c.reportWith(errNoStaticMethod(), call.line, call.col, "no " + recv + "." + name);
      return true;
    }
  } else {
    return false;
  }
  if (args.len() != 1) {
    c.report(errBuiltinArity(), call.line, call.col);
    return true;
  }
  i32 lit = litKindOf(args[0]);
  if (lit != litNone()) {
    reportLiteral(c, want, args[0], errBuiltinArg(), args[0].line, args[0].col);
    return true;
  }
  string got = typeOfExpr(c, args[0]);
  if (got != typeNone() && got != want) { c.report(errBuiltinArg(), args[0].line, args[0].col); }
  return true;
}

/** The funcref type of `S.make`, or unknown when the receiver is not a struct with that static. */
/**
 * `c.inc` — an **instance** method already bound to that object, as a value.
 *
 * The receiver-less signature: `i32 inc(this)` bound to a `Counter` is an `fn[i32()]`, which is the
 * whole point of the feature — a bound reference is interchangeable with every `fn[…]` a program
 * already passes around, so `Shell.askInterrupt`'s funcref-plus-context pair can collapse into one.
 *
 * `design/lang/0002`, tier one. The emitter has carried this since the pair representation landed: a
 * `fn[…]` value is `{funcref, env}`, and the bound wrapper casts the env to the receiver rather than
 * dropping it. What was missing was the language admitting the value.
 *
 * Generics stay out, as they do for a static: the instantiation is what this checker does not model,
 * and answering the template's own text would claim a type no instance has.
 */
string boundMethodType(C c, string recv, string name) {
  if (recv == "" || c.isGeneric(recv) || !c.isStruct(recv)) { return typeNone(); }
  i32 at = c.methodAt(recv, name);
  if (at < 0 || c.methodStatics[at]) { return typeNone(); }
  string out = "fn(";
  for (i32 i = 0; i < c.methodParamCount[at]; i++) {
    if (i > 0) { out = out + ", "; }
    out = out + c.methodParamTypes[c.methodParamAt[at] + i];
  }
  return out + ") -> " + c.methodReturns[at];
}

string staticMethodType(C c, Expr obj, string name) {
  string owner = "";
  match (obj.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      if (c.typeOfName(n) == typeNone() && c.isStruct(n)) { owner = n; }
    }
    else: { }
  }
  if (owner == "" || c.isGeneric(owner)) { return typeNone(); }
  i32 at = c.ownMethodAt(owner, name);
  if (at < 0 || !c.methodStatics[at]) { return typeNone(); }
  string out = "fn(";
  for (i32 i = 0; i < c.methodParamCount[at]; i++) {
    if (i > 0) { out = out + ", "; }
    out = out + c.methodParamTypes[c.methodParamAt[at] + i];
  }
  return out + ") -> " + c.methodReturns[at];
}

/**
 * The type a receiver denotes: the value's type, or the struct itself when the receiver names one.
 *
 * `p.m()` and `P.m()` are the same syntax and differ only in that, which the method-call rule already
 * knew and `typeOfExpr` did not.
 */
string receiverType(C c, Expr obj) {
  match (obj.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      string t = c.typeOfName(n);
      if (t != typeNone()) { return t; }
      if (c.isStruct(n)) { return n; }
      return typeNone();
    }
    // **A literal receiver has the type of its own family**, which is the third place this checker
    // has needed that: `"abc".len()` is a `string`'s builtin however the string was written, and
    // asking `typeOfExpr` about a literal answers unknown by design.
    else: { return naturalTypeOf(c, obj); }
  }
}

/**
 * Bind a generic function's type parameters by matching its written parameter against an actual type.
 *
 * `Box<T>` against `Box<f64>` binds `T` to `f64`; `T` against anything binds it to that; `T[]` against
 * `f64[]` looks one level down. Anything that does not line up binds nothing, which leaves the
 * parameter unbound and the return type unknown — silence, as everywhere.
 *
 * String against string, because in this checker a type *is* its canonical name and the written form
 * and the actual form are both one.
 */
void bindTypeParams(C c, string written, string actual, string[] names, string[] bound) {
  if (written == "" || actual == "" || written == typeNone() || actual == typeNone()) { return; }
  for (i32 i = 0; i < names.len(); i++) {
    if (names[i] == written) {
      if (bound[i] == "") { bound[i] = actual; }
      return;
    }
  }
  if (endsWith(written, "[]") && endsWith(actual, "[]")) {
    bindTypeParams(c, dropLast(written, 2), dropLast(actual, 2), names, bound);
    return;
  }
  if (endsWith(written, "?") && endsWith(actual, "?")) {
    bindTypeParams(c, dropLast(written, 1), dropLast(actual, 1), names, bound);
    return;
  }
  string wb = genericBase(written);
  if (wb == "" || wb != genericBase(actual)) { return; }
  string[] wargs = genericArgs(written);
  string[] aargs = genericArgs(actual);
  if (wargs.len() != aargs.len()) { return; }
  for (i32 i = 0; i < wargs.len(); i++) { bindTypeParams(c, wargs[i], aargs[i], names, bound); }
}

/** A written type with the bound parameters put in, or unknown when any of them is still open. */
string applyBindings(string written, string[] names, string[] bound) {
  string core = written;
  string suffix = "";
  for (i32 guard = 0; guard < 8; guard++) {
    if (endsWith(core, "[]")) { core = dropLast(core, 2); suffix = "[]" + suffix; }
    else if (endsWith(core, "?")) { core = dropLast(core, 1); suffix = "?" + suffix; }
    else { break; }
  }
  for (i32 i = 0; i < names.len(); i++) {
    if (names[i] != core) { continue; }
    if (bound[i] == "") { return typeNone(); }
    return bound[i] + suffix;
  }
  // **And inside an instantiation.** `Box<T> wrap<T>(T v)` returns a `Box<T>`, whose core is not a
  // parameter but a type *holding* one — so answering with the written text made `Box<i32> b =
  // wrap(x);` a mismatch against a type nobody wrote. `T` alone already worked, which is exactly why
  // it went unnoticed: the identity function is the case everybody tests.
  string base = genericBase(core);
  if (base != "") {
    string[] args = genericArgs(core);
    string out = base + "<";
    for (i32 i = 0; i < args.len(); i++) {
      string one = applyBindings(args[i], names, bound);
      if (one == typeNone()) { return typeNone(); }
      if (i > 0) { out = out + ", "; }
      out = out + one;
    }
    return out + ">" + suffix;
  }
  return written;
}

/**
 * The return type of a call to a generic function, with its type parameters inferred from the
 * arguments — or unknown when the arguments do not settle them.
 */
string genericCallReturn(C c, i32 at, Expr[] args) {
  i32 n = c.funcTypeParamCount[at];
  string[] names = string[n]();
  string[] bound = string[n]();
  for (i32 i = 0; i < n; i++) {
    names[i] = c.funcTypeParamNames[c.funcTypeParamAt[at] + i];
    bound[i] = "";
  }
  i32 count = c.funcParamCount[at];
  if (args.len() != count) { return typeNone(); }
  for (i32 i = 0; i < count; i++) {
    string got = litKindOf(args[i]) != litNone() ? typeNone() : typeOfExpr(c, args[i]);
    bindTypeParams(c, c.funcParamTypes[c.funcParamAt[at] + i], got, names, bound);
  }
  return applyBindings(c.funcReturns[at], names, bound);
}

/**
 * What the `i`th argument of a call or construction is required to be, or unknown.
 *
 * A struct's `i`th field or a function's `i`th parameter — the two shapes share the syntax, so this
 * asks which one the name is, exactly as the checking rules do one level up.
 */
string argumentSlot(C c, string name, string spelled, i32 i) {
  if (c.isStruct(name)) {
    if (c.isGeneric(name) && spelled == name) { return typeNone(); }
    return substituteType(c, spelled, c.constructFieldAt(spelled, i));
  }
  i32 at = c.funcAt(name);
  if (at < 0 || c.funcGenerics[at] || i >= c.funcParamCount[at]) { return typeNone(); }
  return c.funcParamTypes[c.funcParamAt[at] + i];
}

/**
 * The object of a member access or a method call, which is not quite an ordinary expression.
 *
 * `P.mk()` and `f64.toBits(x)` put a **type name** in receiver position, and a type name is not a
 * value — the struct-as-value rule would report every static call in the repo, which is exactly what
 * it did. A receiver that is a bare name denoting a type is therefore not walked as an expression at
 * all; anything else is.
 */
void checkReceiver(C c, Expr obj) {
  match (obj.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      // A local of that name shadows the type and is an ordinary value again.
      if (!c.isDeclaredName(n) && (c.isStruct(n) || c.isEnum(n) || isPrimitiveName(n) ||
          n == "string" || n == "bool")) {
        return;
      }
    }
    else: { }
  }
  checkExpr(c, obj);
}

/**
 * Reaching through a nullable without unwrapping it.
 *
 * `p.x` on a `P?` is refused even though `P` has an `x`: the value might not be there, and the
 * language wants that said with `!` rather than assumed. Its own diagnostic rather than a missing
 * field, because the field is not missing.
 */
void checkThroughNullable(C c, Expr at, Expr obj) {
  string t = typeOfExpr(c, obj);
  if (t == typeNone()) { return; }
  string inner = withoutNull(t);
  if (inner != "" && c.isStruct(inner)) { c.report(errThroughNullable(), at.line, at.col); }
}

/**
 * A field that the owner does not have — or that it could not have, being a primitive.
 *
 * Silent unless the owner is *known*: an unknown type has no fields to be missing. A name that is a
 * method rather than a field is not missing either, which is why the method table is consulted before
 * complaining — `c.get` without parentheses is the reference's own separate diagnostic.
 */
void checkMember(C c, Expr at, Expr obj, string name) {
  // **`E.nope` is a variant that is not there.** The object is a *type name* rather than a value, so
  // every rule below — which asks what the object's type is — had nothing to work with and stayed
  // silent. The variant table answers it directly, and answers it per enum: `Ok` belonging to some
  // other enum says nothing about this one, which is why the question is asked with both names.
  match (obj.kind) {
    case Ident(tok): {
      string en = tokenText(c, tok);
      if (c.isEnum(en) && c.typeOfName(en) == typeNone() && c.variantArityIn(en, name) < 0) {
        c.report(errNoVariant(), at.line, at.col);
        return;
      }
    }
    else: { }
  }
  // **A literal has fields as much as any other value of its type**, which is to say none: `7.n` is
  // *"type 'i32' has no field 'n'"*. Asking `typeOfExpr` answered unknown, as it does for every
  // literal by design, and this rule then had nothing to be about — the fifth place that has come
  // up, and the reason `naturalTypeOf` exists.
  string t = naturalTypeOf(c, obj);
  if (t == typeNone() || t == "") { return; }
  if (withoutNull(t) != "") { checkThroughNullable(c, at, obj); return; }
  // **A string and an array have members, and a short list of them.** This returned for both, so
  // `s.nope` on a string was silent where the reference says *"type 'string' has no field 'nope'"*.
  // The lists are `isArrayBuiltin` and `isStringBuiltin`, which `checkMethodCall` has used all along
  // — I wrote a third copy before finding them, which is the mistake this file has been full of
  // today in the other direction. They are also right: asking the reference about two dozen
  // plausible names (`push`, `at`, `trim`, `startsWith`…) turns up exactly these.
  //
  // A name that *is* on the list falls through to the method-as-value rule, because `s.len` without
  // the call is a different complaint from `s.nope`.
  if (isArrayName(t) || t == "string") {
    bool known = t == "string" ? isStringBuiltin(name) : isArrayBuiltin(name);
    if (!known) { c.report(errNoSuchField(), at.line, at.col); }
    return;
  }
  if (c.isStruct(t)) {
    if (c.isGeneric(t)) { return; }
    if (c.hasField(t, name)) { return; }
    // A method reached as a *value*. This function is only asked about members that are not the
    // callee of a call — the `Call` arm walks the object instead — so a method name arriving here is
    // one that was named without being called, which the language does not allow.
    // **An instance method named without being called is a value now** — `design/lang/0002` tier one,
    // decided 2026-08-15. It denotes the method bound to this receiver, an `fn[…]` of the
    // receiver-less signature, interchangeable with every other `fn[…]` a program passes around.
    //
    // A *static* reached through a value is still not one: `c.make` where `make` takes no `this` is
    // a function that has nothing to do with `c`, and naming it through an instance says something
    // the language does not mean. `S.make` is how a static is referenced and `staticMethodType`
    // types it.
    i32 mi = c.methodAt(t, name);
    if (mi >= 0) {
      if (c.methodStatics[mi]) { c.report(errMethodAsValue(), at.line, at.col); }
      return;
    }
    c.report(errNoSuchField(), at.line, at.col);
    return;
  }
  // An enum's value is one of its variants and the checker does not know which, so a payload field is
  // not reachable through the enum type — only through a variant, which `is` narrowing produces.
  // **Only when no variant has it.** A `case B:` arm makes `B`'s payload reachable through the
  // subject's own name — `case B: return e.x;` is accepted by the reference — and this checker does
  // not model that narrowing. Reporting every field on an enum therefore refused correct programs,
  // which is the one direction a subset checker may not be wrong in. A name no variant declares is
  // still wrong whichever arm you are in, and that is what is left.
  // A payload is reachable through the enum's own name **inside an arm that narrowed it**, which is
  // where `case B: return e.x;` gets its meaning — and the arm walk below retypes the subject for
  // exactly that reason. Outside one the enum has no such field, which the reference says too.
  if (c.isEnum(t)) { c.report(errNoSuchField(), at.line, at.col); return; }
  // A primitive has no fields at all. Its *statics* are reached through a type name rather than a
  // value, so this cannot be one of those — `f64.toBits` has an `Ident` for an object, not a value.
  //
  // **Nor does a funcref or an `anyref`**, and those fell off the end of this function: every branch
  // above is about a type that has *some* members, and the last one asked about primitives, so the
  // two references with none at all were the ones nothing was about.
  if (isPrimitiveName(t) || t == "bool" || startsWithFn(t) || t == "anyref" || t == "i31ref") {
    c.report(errNoSuchField(), at.line, at.col);
  }
}

/** An index expression: is the thing an array, and is the index one. */
void checkIndex(C c, Expr at, Expr arr, Expr index) {
  string t = typeOfExpr(c, arr);
  if (t != typeNone() && t != "" && !isArrayName(t) && t != "string") {
    // At the **operand**: it is the thing that is not an array. As an lvalue the same complaint lands
    // on the bracket instead, because that is where an `LIndex` node sits — two node kinds, two
    // positions, which is the second time this exact split has come up.
    c.report(errIndex(), arr.line, arr.col);
    return;
  }
  i32 lit = litKindOf(index);
  if (lit != litNone()) {
    if (!acceptsLiteral("i32", lit)) { c.report(errIndex(), index.line, index.col); }
    return;
  }
  // **`i32`, not "some integer".** This asked `isIntegerName`, which is true of `i64`, `u32` and
  // `u64` too, so `xs[someI64]` compiled — while the literal path three lines up already spelled
  // `acceptsLiteral("i32", …)`. The two halves of one rule disagreed about what the rule was, and
  // the typed half was the lenient one, which is the direction that compiles and then means
  // something else. wasm's array instructions take an `i32`; the wider question was never this one.
  string it = typeOfExpr(c, index);
  if (it != typeNone() && it != "i32") { c.report(errIndex(), index.line, index.col); }
}

/**
 * A method call: does the struct have it, and may this receiver call it?
 *
 * Static and instance calls are the same syntax — `P.mk()` and `p.mk()` differ only in whether the
 * receiver names a struct or a value — so the receiver decides which question is asked. A local
 * shadowing a struct name is a value, which is why the scope is consulted first.
 *
 * Reported at the call, which is the receiver's own position and where the reference puts all three.
 */
/** Whether an expression is a bare identifier, which is the only receiver whose position is settled. */
bool isPlainName(Expr e) {
  match (e.kind) {
    case Ident(tok): { return true; }
    else: { return false; }
  }
}

/**
 * Whether a name is one of the builtins the language gives every array, or every string.
 *
 * **Read off `compiler/wacTypeCheck.ts` rather than guessed at**, which is the whole reason this rule
 * can exist: an earlier version of this checker declined to report a missing method on either,
 * saying the surface was larger than `len` and had not been measured. It is four names and three
 * names, and both lists are closed — so the measurement was one grep, and the comment outlived it.
 */
string builtinReturnType(string recv, string name) {
  if (isArrayName(recv) && name == "len") { return "i32"; }
  if (recv == "string") {
    if (name == "len") { return "i32"; }
    if (name == "indexOf") { return "i32"; }
    if (name == "slice") { return "string"; }
    if (name == "toBytes") { return "u8[]"; }
  }
  // **An integer's five answer in the receiver's own width**, which is what the instruction does:
  // `i64.clz` is `[i64] -> [i64]`, not `[i64] -> [i32]`. Stating it here rather than assuming `i32`
  // is what keeps `i64 n = x.leadingZeros()` from being a mismatch on one side or the other.
  if (isIntegerType(recv) && isIntBuiltin(name)) { return recv; }
  // `fill` and `copyFrom` are deliberately absent: they answer nothing, and an expression with no
  // type is what `typeNone` already means everywhere else here.
  return "";
}

/**
 * An offset or a length handed to a bulk builtin — a count, so an integer.
 *
 * A literal is asked whether the family fits, exactly as an index is; anything else is asked what it
 * is, and nothing is said about a type this checker cannot name.
 */
void checkCountArg(C c, Expr e) {
  i32 lit = litKindOf(e);
  if (lit != litNone()) {
    if (!acceptsLiteral("i32", lit)) {
      c.reportWith(errBuiltinArg(), e.line, e.col, expectedFound("i32", foundType(c, e)));
    }
    return;
  }
  string t = typeOfExpr(c, e);
  if (t != typeNone() && t != "" && !isIntegerName(t)) {
    c.reportWith(errBuiltinArg(), e.line, e.col, expectedFound("i32", t));
  }
}

bool isArrayBuiltin(string name) {
  return name == "len" || name == "copyFrom" || name == "fill";
}

bool isStringBuiltin(string name) {
  return name == "len" || name == "slice" || name == "toBytes" || name == "indexOf";
}

/**
 * The five bit methods every integer has, which are five wasm instructions with no other spelling.
 *
 * `clz`, `ctz`, `popcnt`, `rotl` and `rotr` are MVP — every engine that can run a wac module has had
 * them since 2017 — and the language could not reach them, so `packages/zstd` writes a 32-iteration
 * loop for `highBit` in its FSE hot path and five crypto primitives each define their own `rotl`.
 * `issues/lang/0069`, whose shape this is: a **method**, so the width comes from the receiver with no
 * overloading, and so that the existing free functions named `rotl` keep working.
 */
bool isIntBuiltin(string name) {
  return name == "leadingZeros" || name == "trailingZeros" || name == "onesCount"
      || name == "rotateLeft" || name == "rotateRight";
}

/** How many arguments each takes: a rotation takes its count, the other three take nothing. */
i32 intBuiltinArity(string name) {
  return name == "rotateLeft" || name == "rotateRight" ? 1 : 0;
}

/** Whether a receiver is an integer, which is the one thing these five need of it. */
bool isIntegerType(string t) {
  return t == "i32" || t == "u32" || t == "i64" || t == "u64";
}

/**
 * The variant a call is constructing — `Wrap.W(…)` answers `W` — or `""` for anything else.
 *
 * Named by the variant rather than the enum because that is what the field table is keyed by: a
 * variant is a struct whose fields are its payload, which is how `case W(b)` finds `b` a type.
 */
string variantCalleeOwner(C c, Expr callee) {
  match (callee.kind) {
    case Member(obj, nameTok): {
      match (obj.kind) {
        case Ident(tok): {
          string en = tokenText(c, tok);
          string vn = tokenText(c, nameTok);
          if (c.isEnum(en) && c.variantArityIn(en, vn) >= 0) { return vn; }
          return "";
        }
        else: { return ""; }
      }
    }
    else: { return ""; }
  }
}

void checkMethodCall(C c, Expr call, Expr callee, Expr obj, string name, Expr[] args) {
  string recv = "";
  bool isStatic = false;
  match (obj.kind) {
    case Ident(tok): {
      string n = tokenText(c, tok);
      string ty = c.typeOfName(n);
      if (ty != typeNone()) {
        recv = ty;
      } else if (c.isStruct(n)) {
        recv = n;
        isStatic = true;
      } else if (c.isEnum(n)) {
        recv = n;
        isStatic = true;
      } else if (checkBuiltinCall(c, call, n, name, args)) {
        // A primitive type name as the receiver — a builtin static. A local of that name would have
        // been found above, which is what keeps a variable called `string` a variable.
        return;
      }
    }
    else: {
      // **The same answer `receiverType` gives**, which this had grown its own version of: a string
      // literal was special-cased here and a *concatenation* of two was not, so
      // `("aaa, " + "bbb").toBytes(1)` had no receiver and no complaint. A literal takes its type
      // from context everywhere except here, where the receiver is the context — and that rule lives
      // in one function now rather than in two that disagree.
      recv = naturalTypeOf(c, obj);
      // **A generic enum's variant, used as a receiver.** `Maybe.Just(4).orElse(0)` has nowhere to
      // take its instantiation from: inference works from the expected type, and a receiver is the
      // one position with none. The checker used to say nothing at all and the *emitter* declined it
      // with `unresolved name Maybe` — a diagnostic from the wrong phase, naming a type that is
      // perfectly well defined. `issues/lang/0088`.
      // Not `recv == typeNone()`: a variant *with* a payload answers the template's own name here,
      // which is a type no instance has. What both spellings share is that the answer is not an
      // instantiation, and an instantiation is what a method call needs.
      if (genericBase(recv) == "" && genericVariantConstruction(c, obj)) {
        c.reportWith(errGenericVariantSlot(), obj.line, obj.col,
                     "a generic enum's variant takes its type arguments from the expected type, " +
                     "and a receiver has none — assign it to a declared local first");
      }
    }
  }
  // **The two closed surfaces.** An array has three methods and a string four, and a name that is
  // not one of them is a missing method however the receiver was written — which is what makes this
  // reportable at last: the rule needed the list, and the list is in the compiler this is measured
  // against. A *nullable* receiver is somebody else's diagnostic ("unwrap with '!'") and is not
  // named here, which is why the test is against the array's own spelling rather than against
  // "contains a bracket".
  if (isArrayName(recv) && !isArrayBuiltin(name)) {
    c.report(errNoMethod(), callee.line, callee.col);
    return;
  }
  if (recv == "string" && !isStringBuiltin(name)) {
    c.report(errNoMethod(), callee.line, callee.col);
    return;
  }
  // **A variant construction is a call with an arity.** `E.C(1, 0)` reaches here spelled like a
  // static — the enum names the variant — and the count is the variant's own, asked for with both
  // names so that two enums sharing a variant name answer separately. Asking the struct table
  // instead said "two" for an `Ok` that two enums declare, and reported a correct program.
  // **`!isGeneric(recv)` used to be here and was dead**: `isGeneric` walked the struct table only,
  // so it answered *no* for every enum and this arm ran for all of them. Widening `isGeneric` to know
  // about enums made it live, and live it turns the check off for exactly the enums that had it —
  // `Maybe.Just(1, 2)` became accepted. The clause is gone rather than repaired, because what it was
  // there to exclude, a generic *struct*, `isEnum` already excludes. `issues/lang/0088`.
  if (isStatic && c.isEnum(recv)) {
    i32 wantArgs = c.variantArityIn(recv, name);
    if (wantArgs >= 0 && args.len() != wantArgs) {
      c.report(errCallArity(), call.line, call.col);
    }
    return;
  }
  // `"hi".toBytes()` is a method on a string value, not a static, and takes no arguments.
  if (recv == "string" && name == "toBytes") {
    if (args.len() != 0) { c.report(errBuiltinArity(), call.line, call.col); }
    return;
  }
  // **The integer bit methods.** Signedness is irrelevant to all five and the opcode is chosen by
  // width alone, so `i32`/`u32` and `i64`/`u64` get the same five; the result and a rotation's count
  // are the receiver's own type, which is what makes `x.rotateLeft(1)` need no inference.
  if (isIntegerType(recv) && isIntBuiltin(name)) {
    i32 wantArgs = intBuiltinArity(name);
    if (args.len() != wantArgs) {
      c.report(errBuiltinArity(), call.line, call.col);
      return;
    }
    for (i32 i = 0; i < args.len(); i++) {
      if (litKindOf(args[i]) != litNone()) {
        reportLiteral(c, recv, args[i], errBuiltinArg(), args[i].line, args[i].col);
        continue;
      }
      string got = typeOfExpr(c, args[i]);
      if (got != typeNone() && !assignable(c, recv, got)) {
        c.reportWith(errBuiltinArg(), args[i].line, args[i].col, expectedFound(recv, got));
      }
    }
    return;
  }
  // An integer has those five and nothing else, which is worth saying by name rather than letting
  // the struct rules look for a method on an `i32`.
  if (isIntegerType(recv) && !isIntBuiltin(name)) {
    c.reportWith(errNoMethod(), callee.line, callee.col, "no " + recv + "." + name);
    return;
  }
  // `len()` is the one method an array and a string share, and it takes nothing.
  if ((isArrayName(recv) || recv == "string") && name == "len") {
    if (args.len() != 0) { c.report(errBuiltinArity(), call.line, call.col); }
    return;
  }
  // **The bulk pair.** `copyFrom(src, srcStart, dstStart, count)` moves elements between two arrays,
  // so the source is an array holding the same kind; `fill(value, start, count)` writes one value
  // across a range. Both were listed as builtins and neither was checked, which is six of the spec's
  // own programs — `spec/cases/0030` through `0035`.
  if (isArrayName(recv) && name == "copyFrom") {
    if (args.len() != 4) {
      c.report(errBuiltinArity(), call.line, call.col);
      return;
    }
    // **A literal has no type of its own**, so `typeOfExpr` answers nothing for `copyFrom(5, …)` and
    // the guard below would let it past. `foundType` gives a literal the type it naturally has,
    // which is the whole of what makes `5` not an array.
    string srcT = foundType(c, args[0]);
    if (srcT != typeNone() && srcT != "" && srcT != recv) {
      c.reportWith(errBuiltinArg(), args[0].line, args[0].col, expectedFound(recv, srcT));
    }
    for (i32 i = 1; i < args.len(); i++) { checkCountArg(c, args[i]); }
    return;
  }
  if (isArrayName(recv) && name == "fill") {
    if (args.len() != 3) {
      c.report(errBuiltinArity(), call.line, call.col);
      return;
    }
    // **A packed element widens to `i32` on the way out and takes one on the way in.** `u8[]` filled
    // from an `i32` is how `packages/zstd/src/block.wac` writes a run, and asking for a `u8` exactly
    // refused a working file — `spec/cases/0036`.
    string el = dropLast(recv, 2);
    if (isPackedName(el)) { el = "i32"; }
    if (litKindOf(args[0]) != litNone()) {
      reportLiteral(c, el, args[0], errBuiltinArg(), args[0].line, args[0].col);
    } else {
      string vt = typeOfExpr(c, args[0]);
      if (vt != typeNone() && vt != "" && !assignable(c, el, vt)) {
        c.reportWith(errBuiltinArg(), args[0].line, args[0].col, expectedFound(el, vt));
      }
    }
    for (i32 i = 1; i < args.len(); i++) { checkCountArg(c, args[i]); }
    return;
  }
  // A method on something that has none. A primitive has no methods at all, and an array has only
  // the builtins — so a name that is not one of those is missing rather than unknown. Reported at the
  // **receiver**, which is where the reference puts this one: `x.toString()` names the `x`, unlike a
  // struct's missing method, which names the call.
  // **Numbers and booleans only.** An array's builtin surface is larger than `len` — `push`, `fill`,
  // `copy` and more — and a string's has `slice` in it, and this has measured neither, so calling an
  // unknown method on one missing reported 70 files and then 10. What is left is the half of the rule
  // that can be stated without the measurement: a number has no methods at all, which is a fact
  // rather than a list. `string` is in `isPrimitiveName` and has to be excluded by name, which is the
  // whole trap — the predicate is about how a type is *passed*, not about what it can do.
  if (isValueType(recv)) {
    // **At the callee**, which is the node the reference reports at — `errAt(ctx, …, callee.line,
    // callee.col)` — and rung 2 says this parser's node positions are the reference's. Reporting at
    // the *receiver* agreed with it for `n.len()` and missed by three columns for `xs[0].len()`,
    // which is what "the same node" fixes and what guessing at the dot would not have.
    c.report(errNoMethod(), callee.line, callee.col);
    return;
  }
  bool recvConst = !isStatic && constExpr(c, obj);
  // **An instantiation answers to its template here.** `cli.readFile(path)` is a
  // `Pending<FileResult>`, and the struct table holds `Pending` — so the gate below saw a name that
  // is not a struct and returned, which is why `.wait(1)` went unreported in three files. Everything
  // this function decides — is there such a method, how many arguments does it take, is the receiver
  // const — is the template's business and not the type arguments'. What *is* theirs is the return
  // type, and that is `typeOfExpr`'s question, asked elsewhere and still asked of the instance.
  string recvBase = genericBase(recv);
  if (recvBase != "" && !c.isStruct(recv) && c.isStruct(recvBase)) { recv = recvBase; }
  // **A narrowed variant keeps its enum's methods.** `if (e is A) { e.val() }` retypes `e` to the
  // variant, and `val` belongs to the enum — the variant is a struct holding the payload and nothing
  // else. Looking the method up on the owner is what makes narrowing free rather than costly.
  if (c.isStruct(recv) && c.methodAt(recv, name) < 0) {
    for (i32 i = 0; i < c.variantCount; i++) {
      if (c.variantNames[i] != recv) { continue; }
      if (c.methodAt(c.variantOwners[i], name) >= 0) { recv = c.variantOwners[i]; }
    }
  }
  // **The receivers that fell out of every arm above.** This bailed for anything that is not a
  // struct, so an enum, a funcref and an `anyref` were the three kinds nothing was about — and the
  // reference answers *"struct 'E' has no method 'nope'"* for all of them. An enum's own methods are
  // recorded like a struct's, so the lookup is the same one; a funcref and an `anyref` have none at
  // all and need no lookup. Generics stay exempt for the reason spelled out below: an empty answer
  // there means "not modelled" rather than "not there".
  if (c.isEnum(recv) && !c.isGeneric(recv) && c.methodAt(recv, name) < 0 &&
      c.variantArityIn(recv, name) < 0) {
    c.reportWith(errNoMethod(), callee.line, callee.col, "no " + recv + "." + name);
    return;
  }
  if (startsWithFn(recv) || recv == "anyref" || recv == "i31ref") {
    c.reportWith(errNoMethod(), callee.line, callee.col, "no " + recv + "." + name);
    return;
  }
  if (recv == typeNone() || recv == "" || !c.isStruct(recv)) { return; }
  // A generic's methods are not recorded, so an empty answer here means "not modelled" rather than
  // "not there". Three files and a spec case said so: `this.hash(k)` inside `Map<K, V>` is an
  // ordinary call that this would otherwise call missing.
  //
  // **The count is recorded, though, and does not depend on the type arguments.** `Pending<T>.wait`
  // takes none whatever `T` is, so `.wait(1)` is wrong for every instantiation at once — which is
  // seven of the nine diagnostics this checker still missed on the repository's own code, all of
  // them a `Pending<…>` from the platform. Types stay unmodelled; arity does not need them.
  if (c.isGeneric(recv)) {
    i32 gm = c.methodAt(genericBase(recv) == "" ? recv : genericBase(recv), name);
    if (gm >= 0 && args.len() != c.methodParamCount[gm]) {
      c.report(errCallArity(), call.line, call.col);
    }
    return;
  }

  // A field can hold a funcref, and `sh.externalNames()` calls the field rather than a method of
  // that name. `packages/sh` has four of them. A name that is a field is not a missing method.
  //
  // **It still has an arity**, which is written in the field's own type: `fn(i32) -> bool` takes one
  // however it is reached. Returning here without asking made a call through a field the one call
  // shape this checker never counted — and `Cli`'s whole surface is fields.
  if (c.hasField(recv, name)) {
    string held = c.fieldType(recv, name);
    i32 heldArity = funcrefArity(held);
    if (heldArity >= 0 && args.len() != heldArity) {
      c.report(errCallArity(), call.line, call.col);
      return;
    }
    // And the argument *types*, which used to stop at the count. The reference reports both;
    // `issues/lang/0123` is what the gap cost.
    if (heldArity >= 0 && !c.isGeneric(recv)) { checkFuncrefArgs(c, held, args); }
    return;
  }

  // Statics are looked up on the struct itself; instance methods inherit.
  i32 at = isStatic ? c.ownMethodAt(recv, name) : c.methodAt(recv, name);
  if (at < 0) {
    // **Where the reference puts this, which turned out to be a rule and not a guess.**
    //
    // It reports at the start of the receiver for `n.len()` and at the *dot* for `xs[0].len()`, and
    // this used to say that nothing here could tell which — so a receiver that was not a plain name
    // went unreported rather than reported in a place the reference never mentions. The sentence
    // naming the two cases *is* the discriminator, and measuring it settles which applies:
    //
    // | receiver | the reference's column |
    // | --- | --- |
    // | `j.nope()` | the start of `j` |
    // | `sh.j.nope()`, `arr[0].nope()`, `j.self().nope()`, `sh.m.j.nope()` | the dot before `nope` |
    //
    // A plain name keeps `call`'s own position, which is that start and already agreed. Everything
    // else reports at the dot, which is the token before the method's name — there is nothing
    // between them, so `nameTok - 1` is it.
    //
    // The oracle for the position is `corpusMutate`, which asserts that where the reference answers
    // with one diagnostic every position we report is that one, over 223 broken real files. A dot
    // computed wrongly fails there rather than passing quietly.
    if (!isPlainName(obj)) {
      i32 dotTok = -1;
      match (callee.kind) {
        case Member(mobj, mnameTok): { dotTok = mnameTok - 1; }
        else: { }
      }
      if (dotTok < 0) { return; }
      c.reportTok(isStatic ? errNoStaticMethod() : errNoMethod(), dotTok, "");
      return;
    }
    c.report(isStatic ? errNoStaticMethod() : errNoMethod(), call.line, call.col);
    return;
  }
  // A static call must name a static method, and an instance call must not. The reference words the
  // first as "has no static method", which is why a mismatch here is the same diagnostic as a
  // missing one rather than a fourth.
  // **`(C.inc)(c)` is the inline form of a method reference**, which `spec/tour.wac` documents two
  // lines above the code that needed it: an instance method named through its type is a value whose
  // first parameter is the receiver, and calling it there and then is the same call. It reads as a
  // static call and is not one, so the mismatch below has to let this shape through rather than
  // report the method missing.
  // The arity is still checked, and **counts the receiver**: `P.get()` passes none where the
  // unbound method takes one, which the reference reports as "expected 1 argument(s), got 0" rather
  // than as a missing static. That is the same arithmetic the emitter does when it puts the object
  // in front of the arguments.
  if (isStatic && !c.methodStatics[at]) {
    if (args.len() != c.methodParamCount[at] + 1) {
      c.report(errCallArity(), call.line, call.col);
    }
    return;
  }
  if (isStatic != c.methodStatics[at]) {
    c.report(isStatic ? errNoStaticMethod() : errNoMethod(), call.line, call.col);
    return;
  }
  if (!isStatic && recvConst && !c.methodConsts[at]) {
    c.report(errNonConstThroughConst(), call.line, call.col);
    return;
  }
  // **A method call has a count too**, and this checker had never asked: a plain function's arity is
  // checked, a variant construction's is, and `b.trim(1)` on a method taking none went through. The
  // receiver is not among the recorded parameters — it is `this` and belongs to the call rather than
  // the list — so the comparison is direct for both an instance call and a static one.
  //
  // Real code is where this showed up. Seventeen of twenty missed diagnostics in a mutation of the
  // repository's own packages were this shape, and none of the four thousand generated programs had
  // ever called a method with the wrong number of arguments.
  if (args.len() != c.methodParamCount[at]) {
    c.report(errCallArity(), call.line, call.col);
  }
}

/**
 * Whether this cast used the operator the conversion takes.
 *
 * Four spellings, and the language treats them as a claim about what is happening rather than as
 * synonyms: `as` says nothing is lost, `as!` says the value is checked, `as~` says it is truncated,
 * `as@` says the bits are reinterpreted. Using the wrong one is *"lossy cast not needed"* or its
 * siblings — the reference's own family — and the point is that a reader can trust the spelling.
 *
 * Only conversions between two primitives this slice can name. A cast to or from a struct, an array
 * or a generic is a reference cast, which has its own rules and its own diagnostics.
 *
 * The **position differs by which complaint it is**, which no amount of reasoning would have
 * suggested and which took three corrections to get right:
 *
 *   - *"lossy cast not needed"* — a heavier operator on a conversion that loses nothing — names the
 *     **operand**. For `x as~ i64` it is the `x`, not the `as~` two columns later.
 *   - *"'i32' -> 'u32' is lossy — use 'as!', 'as~', or 'as@'"* names the **operator**, because it is
 *     advice about which operator to write.
 *   - *"no raw conversion for 'f64' -> 'f32'"* names the **operator** too.
 *
 * The one that names the operand is the one saying the cast should not be there at all; the two that
 * name the operator are saying this operator is the wrong one. That reads as a principle in
 * hindsight and was three separate contradictions from the spec corpus in practice.
 */
/**
 * What a cast's operand *is*, including when it is a literal.
 *
 * **A literal has a default type, and a cast's slot cannot give it one**: the slot here is the cast's
 * own target, so asking a literal what it is answered "nothing" and every cast on one went unchecked
 * — `1 as~ i32`, `1 as! i32` and `1.5 as~ f64` are each a lossy spelling where `as` would work, which
 * the reference refuses and this accepted (`issues/lang/0119`). A literal falls back to its own
 * notation: `f64` for a float, `i32` for an integer with a reading there and `i64` for one without,
 * which is what keeps `1000000000000 as@ i32` the legal truncation it is.
 *
 * One function because `checkCast` asked this in three places, and two of them had already been given
 * the answer the third was about to need.
 */
string castOperandType(C c, Expr operand) {
  i32 lit = litKindOf(operand);
  if (lit == litFloat()) { return "f64"; }
  if (lit == litInteger()) {
    return integerLiteralFits(c, "i32", operand, false) ? "i32" : "i64";
  }
  if (lit != litNone()) { return typeNone(); }
  return typeOfExpr(c, operand);
}

void checkCast(C c, Expr e, i32 op, Expr operand, Ty target) {
  string to = typeOfTy(c, target);
  // A cast down a struct hierarchy is the one cast that can *fail* rather than lose precision, so it
  // takes `as!` — the checked spelling — and plain `as` is refused. Upcasting is silent: a `Circle`
  // is a `Shape` with nothing to check. Reported at the operator, like every other wrong-spelling
  // complaint in this family.
  // A cast between two references, which is a different family from a numeric conversion: only `as`
  // and `as!` mean anything, and which of the two is right is decided by the direction. Upcasting is
  // always safe and takes `as`; downcasting can fail and takes `as!`; `as~` and `as@` are refused
  // outright, because truncating and reinterpreting are questions about a bit pattern and a reference
  // does not have one to talk about. All at the operator, like every other wrong-spelling complaint.
  string castFrom = castOperandType(c, operand);
  if (castFrom == typeNone() || castFrom == "" || to == typeNone() || to == "") { return; }
  // **A packed type is not castable, in either direction.** The rule below excluded packed types
  // from the crossing check, which reads as a carve-out for something legal — and the reference
  // refuses every one of them: `n as u8`, `a[0] as i32` where `a` is a `u8[]`, `s.v as i32` for a
  // packed field, and the same with `as~`. A packed value is read and widened where it sits; there
  // is no conversion to spell because there is no slot to put the result of one in.
  //
  // Reported at the operator, which is where the reference puts it and where every other
  // wrong-spelling complaint in this family goes.
  if (isPackedName(castFrom) || isPackedName(to)) {
    c.reportTok(errWrongCastOp(), op, "from " + castFrom + " to " + to);
    return;
  }
  bool fromRef = isCastRef(c, castFrom);
  bool toRef = isCastRef(c, to);
  i32 ck = tokenKind(c, op);
  // Crossing between the two worlds is never a conversion. `i32 as string` and `P as i32` are both
  // *"no valid cast"*, whichever spelling is used — a number and a reference have nothing in common
  // to convert. The one exception is `i31ref`, handled below, which exists precisely to cross.
  if (fromRef != toRef && castFrom != "i31ref" && to != "i31ref" &&
      (fromRef || isValueType(castFrom)) && (toRef || isValueType(to)) &&
      !isPackedName(castFrom) && !isPackedName(to)) {
    c.reportTok(errWrongCastOp(), op, "from " + castFrom + " to " + to);
    return;
  }
  // Two references. Only `as` and `as!` mean anything, and which is right depends on the direction:
  // upcasting — including a type to itself — is always safe and takes `as`, and everything else is
  // treated as a downcast that may fail and takes `as!`. `string as P` is a downcast by this rule
  // rather than an error of its own, which is measured: the reference words it *"downcast to 'P' may
  // fail"* even though a string will never be a `P`.
  if (fromRef && toRef && castFrom != "i31ref" && to != "i31ref") {
    // A funcref is a reference that converts to nothing but itself — there is no hierarchy of
    // function types here and nothing to check at runtime, so every spelling is refused.
    if (startsWithFn(castFrom) != startsWithFn(to) ||
        (startsWithFn(castFrom) && castFrom != to)) {
      c.reportTok(errWrongCastOp(), op, "from " + castFrom + " to " + to);
      return;
    }
    if (ck == kAsTilde() || ck == kAsAt()) {
      c.reportTok(errWrongCastOp(), op, "from " + castFrom + " to " + to);
      return;
    }
    // Two things have to widen for a cast to be the safe direction: the **type**, and the
    // **nullability**. `P as P?` adds the possibility of being absent and cannot fail; `P? as P`
    // takes it away and can; `Sub as Base?` does both at once. Measured across the nullable row,
    // where `P? as Base?` is a downcast despite both sides being nullable, because `P` is not a
    // `Base` — the two conditions are independent and both are required.
    string fromCore = withoutNull(castFrom);
    string fromBase = fromCore == "" ? castFrom : fromCore;
    string toCore = withoutNull(to);
    string toBase = toCore == "" ? to : toCore;
    bool widensType = fromBase == toBase || descendsFrom(c, fromBase, toBase);
    bool widensNull = isNullableName(to) || !isNullableName(castFrom);
    bool up = widensType && widensNull;
    if (up && ck == kAsBang()) {
      c.reportTok(errWrongCastOp(), op, "from " + castFrom + " to " + to);
    }
    if (!up && ck == kAs()) { c.reportTok(errDowncast(), op, ""); }
    // **`x as! T` between types that share no ancestor always traps** — the third of
    // `issues/lang/0126`'s three. A downcast is a claim checked at run time, and one that cannot
    // hold is a trap the reader has written on purpose-looking code.
    //
    // Only for `as!`, which is the spelling that traps; `as` between unrelated references is already
    // the error above, and saying both would be two complaints about one line.
    if (ck == kAsBang() && !c.isGeneric(fromBase) && !c.isGeneric(toBase) &&
        !shareAncestor(c, fromBase, toBase)) {
      c.warn(warnAlwaysTraps(), e.line, e.col);
    }
    return;
  }
  // `i31ref` is a reference that pairs with `i32`, and with nothing else: coming back out is
  // lossless, going in is lossy, and any other source has no conversion at all whichever spelling is
  // used. Handled here rather than in the numeric tables because it is not a primitive.
  if (to == "i31ref") {
    string i31from = castOperandType(c, operand);
    if (i31from == typeNone() || i31from == "i31ref") { return; }
    // **Out of `anyref` is the other way in**, and it is the shape `spec/tour.wac` uses: an
    // `anyref[]` holds unboxed numbers beside heap objects, and getting one back out is a downcast
    // that can fail — so `as!` carries it and the other three spellings do not. This block knew
    // only the `i32` pairing and called the tour's own line a cast with no conversion.
    if (i31from == "anyref") {
      if (tokenKind(c, op) != kAsBang()) {
        c.reportTok(errDowncast(), op, "");
      }
      return;
    }
    // **"these types" has to name them.** Six of this code's eleven report sites passed no operand,
    // so the message promised information it did not give — the worst kind of diagnostic, because a
    // reader stops looking for what it did not say. The five that already named them show the
    // format, and the two types are in scope at every one of the six.
    if (i31from != "i32") {
      c.reportTok(errWrongCastOp(), op, "from " + i31from + " to " + to);
      return;
    }
    // `i32 -> i31ref` is the lossy direction: `as!` and `as~` carry it, `as` and `as@` do not.
    i32 ik = tokenKind(c, op);
    if (ik == kAs() || ik == kAsAt()) {
      c.reportTok(errWrongCastOp(), op, "from " + i31from + " to " + to);
    }
    return;
  }
  // Only conversions between two **value** types from here on. A `string` reaches this point through
  // `isPrimitiveName` and must not: casting one to itself is ordinary, where casting an `i32` to an
  // `i32` is redundant.
  if (to == typeNone() || !isValueType(to) || isPackedName(to)) { return; }
  string from = castOperandType(c, operand);
  // Out of an `i31ref` and into an integer, which is the lossless direction — so `as` is the only
  // spelling that carries it, and every other one is a complaint at the operator.
  if (from == "i31ref") {
    if (to == "i32" && tokenKind(c, op) != kAs()) {
      c.reportTok(errWrongCastOp(), op, "from " + from + " to " + to);
    }
    return;
  }
  if (from == typeNone() || !isValueType(from) || isPackedName(from)) { return; }
  i32 k = tokenKind(c, op);
  // A cast to the type it already is does nothing, and the language says so rather than allowing it
  // as a no-op. Only measured for plain `as`; the checked and truncating spellings say nothing here.
  // A cast to the type it already is does nothing, whichever of the four was written — the checked
  // and truncating spellings are as redundant as the plain one, which the first version of this
  // assumed the opposite of.
  if (from == to) {
    c.reportTok(errRedundantCast(), op, "");
    return;
  }

  bool lossless = losslessCast(from, to);

  // Losslessness is decided first, whichever operator was written. `x as@ i64` from an `i32` is
  // *"lossy cast not needed"* and not *"no raw conversion"* — the reference complains that the
  // conversion needs no help before it complains about which help was offered. Ordering this the
  // other way round put the right diagnostic at the wrong position, and only the corpus said so.
  if (k == kAs()) {
    // At the operator: *"'i32' -> 'u32' is lossy — use 'as!', 'as~', or 'as@'"* is advice about
    // which operator to write, so it points at the one that is there.
    if (!lossless) { c.reportWith(errWrongCastOp(), e.line, e.col, "from " + from + " to " + to); }
    return;
  }
  if (lossless) {
    c.reportWith(errWrongCastOp(), operand.line, operand.col, "from " + from + " to " + to);
    return;
  }
  // Not lossless, so `as!` and `as~` are both fine. `as@` additionally needs a raw form to exist,
  // and *that* complaint is about the operator, so it is reported there.
  if (k == kAsAt() && !rawCast(from, to)) {
    c.reportWith(errWrongCastOp(), e.line, e.col, "from " + from + " to " + to);
  }
}

/**
 * Two parameters of one function or method sharing a name.
 *
 * Reported at the second, which is the one that could be renamed. Nothing else here looks at a
 * declaration for its own sake — every other rule is about a use — so this is the first check that
 * reads a signature rather than following a walk.
 */
void checkParams(C c, Param[] params) {
  for (i32 i = 0; i < params.len(); i++) {
    // A packed type has no slot of its own — it exists as an array element and nowhere else — so it
    // cannot be a parameter. Reported at the type, which is the same position a duplicate name uses.
    string pt = typeOfTy(c, params[i].type);
    if (isPackedName(pt)) {
      c.report(errPackedPosition(), params[i].type.line, params[i].type.col);
    }
    // `void` is what a function returns, not a value anything can hold, so it is not a type a
    // parameter or a field can have.
    if (pt == "void") { c.report(errVoidType(), params[i].type.line, params[i].type.col); }
    checkPackedNullable(c, pt, params[i].type);
    string a = tokenText(c, params[i].nameTok);
    for (i32 j = 0; j < i; j++) {
      if (tokenText(c, params[j].nameTok) == a) {
        c.report(errDuplicateParam(), params[i].type.line, params[i].type.col);
        break;
      }
    }
  }
}

/** Every name a statement declares, however deeply nested. */
void declareStmt(C c, Stmt s) {
  match (s.kind) {
    case Var(type, nameTok, init, isConst): {
      // A local that **aliases** something const is const too. `Counter c = this; c.mutate();` inside
      // a `const this` method looks like a way to launder the constness and is not one — the local
      // and the receiver are the same object.
      //
      // Only for a type you can write **through**: a struct or an array. `i32 v = this.n;` is a copy
      // and writing to it is nobody's business but the local's, and a `string` is a reference but an
      // immutable one — assigning a new string to the local mutates nothing, which is why
      // `string s = SOME_CONST; s = s + "x";` is ordinary and reported seven times before this said
      // "reference" where it meant "writable".
      string vt = typeOfTy(c, type);
      string vcore = withoutNull(vt);
      string vbase = vcore == "" ? vt : vcore;
      bool writable = isArrayName(vbase) || c.isStruct(vbase);
      bool aliasesConst = writable && constExpr(c, init);
      // **A local built out of a live type parameter keeps its written spelling.** `Box<T> b` is
      // unknown to every other rule here, and has to be — but the name then carries no trace of `T`
      // at all, which is what a self-instantiating generic is recognised by. Only when the written
      // type *mentions* a parameter in scope: everything else already has a real answer.
      if (vt == typeNone() && c.activeParamCount > 0) {
        string wt = writtenTy(c, type);
        if (wt != "" && !isActiveParam(c, wt) && mentionsActiveParam(c, wt)) { vt = wt; }
      }
      c.declareConst(tokenText(c, nameTok), vt, isConst || aliasesConst);
      // Recorded as the aliasing kind, so a write *through* it is still refused while rebinding the
      // name is not. `while (cur is not null) { cur = cur!.next; }` walks a list in a `const this`
      // method, which is what ten of the spec's own linked-list programs do.
      if (!isConst && aliasesConst) { c.markAliasOnly(tokenText(c, nameTok)); }
      // **A `match` used as an initialiser binds names too**, and this walked only statements — so
      // `i32 got = match (o) { case Some(v): v * 3, … };` left `v` undeclared, every arm typed as
      // unknown, and the whole initialiser unknown with them. The statement form two arms down has
      // always done this; the expression form was simply never walked.
      declareMatchBindings(c, init);
    }
    case Block(body): { declareScoped(c, body); }
    case If(cond, then, els): { declareScoped(c, then); declareScoped(c, els); }
    case While(cond, body): { declareScoped(c, body); }
    case DoWhile(body, cond): { declareScoped(c, body); }
    case For(init, cond, update, body): {
      // **The body is the initialiser's scope too.** `for (i32 i = ...) { } i32 r = i;` is an error
      // because `i` belongs to the loop, and pushing the body before declaring the initialiser says
      // so without a second stack to keep in step with this one. `issues/lang/0122`.
      c.pushScope(body);
      if (!(init is null)) { declareStmt(c, init!); }
      declareAll(c, body);
      c.popScope();
    }
    case Switch(subject, cases): {
      for (i32 i = 0; i < cases.len(); i++) { declareScoped(c, cases[i].body); }
    }
    case Match(subject, arms): {
      for (i32 i = 0; i < arms.len(); i++) {
        // The arm's bindings are names too, and they scope to the arm. This slice does not track
        // that, so they are declared as *unknown* — which both silences them and, because a second
        // declaration poisons, silences any local elsewhere in the function with the same name.
        //
        // Not modelling them was a false alarm rather than a gap. `typeOfTy` in this very file has an
        // `Arr` arm declaring a local `string inner` and a `Nullable` arm binding a `Ty` called
        // `inner`; without this, the local's type leaked across and `typeOfTy(c, inner)` was reported
        // as an argument mismatch against its own parameter.
        c.pushScope(arms[i].body);
        for (i32 b = 0; b < arms[i].bindingToks.len(); b++) {
          c.declare(tokenText(c, arms[i].bindingToks[b]), armBindingType(c, subject, arms[i], b));
        }
        declareAll(c, arms[i].body);
        c.popScope();
      }
    }
    else: { }
  }
}

/** Every name declared in a list of statements. */
/**
 * Declare the bindings of a `match` written as an expression.
 *
 * `declareAll` walks statements, and an arm's bindings are declared where the statement form is
 * walked. An initialiser is an *expression*, so a match in one was never reached and its bindings
 * never existed — which made every arm mentioning one unknown, and the match unknown with them.
 *
 * Only the initialiser itself, not every expression inside it: a match nested deeper is a shape this
 * repository does not contain, and walking all of `ExprKind` to find one would be a lot of code for
 * a case nothing writes. The bindings are declared with `armBindingType`, the same answer the
 * statement form uses.
 */
void declareMatchBindings(C c, Expr e) {
  match (e.kind) {
    case MatchExpr(subject, arms): {
      for (i32 i = 0; i < arms.len(); i++) {
        for (i32 b = 0; b < arms[i].bindingToks.len(); b++) {
          c.declare(tokenText(c, arms[i].bindingToks[b]), armBindingType(c, subject, arms[i], b));
        }
      }
    }
    else: { }
  }
}

/** `declareAll` in a scope of its own, which is what a block, a case or a loop body is. */
void declareScoped(C c, Stmt[] body) {
  c.pushScope(body);
  declareAll(c, body);
  c.popScope();
}

void declareAll(C c, Stmt[] body) {
  for (i32 i = 0; i < body.len(); i++) { declareStmt(c, body[i]); }
}

/**
 * How many names a condition narrows, and to what — written into `outNames` / `outTypes`.
 *
 * Purely syntactic, which is what the reference does and is measured rather than assumed: `x is T`
 * narrows, `a && b` narrows with either side, and **`||` and `!` do not**. `(s is Circle) || true`
 * leaves `s` a `Shape`, because the other arm may be the one that held; `!(s is Circle)` guarding an
 * early return does not narrow what follows either, which is the reference declining to reason about
 * control flow it could have.
 *
 * The narrowing lasts for the **then** branch and no further. Nothing here survives the `if`.
 */
i32 narrowingsOf(C c, Expr cond, string[] outNames, string[] outTypes, i32 n) {
  match (cond.kind) {
    case Is(left, target, other, negated): {
      if (negated || (target is null) || n >= outNames.len()) { return n; }
      match (left.kind) {
        case Ident(tok): {
          string t = typeOfTy(c, target!);
          if (t == typeNone()) { return n; }
          // **`p is P` on a `P?` asks whether it is *there*, not what it is.** Recording it as a
          // retyping to `P` makes the checker believe the name is no longer nullable, and the very
          // next thing such code does is `p!.v` — which it then refuses, because there is nothing
          // left to unwrap. The knowledge changes; the type does not. A target that is a genuinely
          // different type still narrows, which is the case this exists for.
          string cur = c.typeOfName(tokenText(c, tok));
          if (withoutNull(cur) == t) { return n; }
          outNames[n] = tokenText(c, tok);
          outTypes[n] = t;
          return n + 1;
        }
        else: { return n; }
      }
    }
    case Binary(op, l, r): {
      if (tokenKind(c, op) != kAndAnd()) { return n; }
      return narrowingsOf(c, r, outNames, outTypes, narrowingsOf(c, l, outNames, outTypes, n));
    }
    else: { return n; }
  }
}

/** Whether an expression builds an enum variant: `Shape.Circle(1.0)`, or a bare `Circle(1.0)`. */
/**
 * A variant construction whose enum is generic, which is the one that needs a slot to be known.
 *
 * **Asked without the arity**, unlike `isVariantConstruction`: a generic enum's variants are recorded
 * under the *template's* name and `variantArityIn` is keyed by owner, so asking it here answered -1
 * and the whole predicate came back false for exactly the case it exists to catch. What identifies
 * this shape is that the name is an enum, that enum is generic, and a member of it is being called.
 */
bool genericVariantConstruction(C c, Expr e) {
  match (e.kind) {
    // `Maybe.Just(4)` — a variant with a payload, which is a call.
    case Call(callee, args): { return genericEnumMember(c, callee); }
    // `Maybe.Absent` — one without, which is not.
    case Member(obj, nameTok): { return genericEnumMember(c, e); }
    else: { return false; }
  }
}

/** Whether this is `E.Name` where `E` is a generic enum in scope. */
bool genericEnumMember(C c, Expr e) {
  match (e.kind) {
    case Member(obj, nameTok): {
      match (obj.kind) {
        case Ident(tok): {
          string en = tokenText(c, tok);
          return c.isGenericEnum(en);
        }
        else: { return false; }
      }
    }
    else: { return false; }
  }
}

bool isVariantConstruction(C c, Expr e) {
  match (e.kind) {
    case Call(callee, args): {
      match (callee.kind) {
        case Member(obj, nameTok): {
          match (obj.kind) {
            case Ident(tok): {
              string en = tokenText(c, tok);
              return c.isEnum(en) && c.variantArityIn(en, tokenText(c, nameTok)) >= 0;
            }
            else: { return false; }
          }
        }
        case Ident(tok): { return c.isVariantName(tokenText(c, tok)); }
        else: { return false; }
      }
    }
    else: { return false; }
  }
}

/**
 * A condition, which must be a boolean.
 *
 * Reported at the condition itself rather than at the `if`, which is where the reference puts it —
 * *"condition must be bool"* names the expression that is wrong, not the statement containing it.
 * The condition is also walked as an ordinary expression, so a mismatch inside it is still found.
 */
void checkCond(C c, Expr cond) {
  if (notBool(c, cond)) {
    c.reportWith(errNotBool(), cond.line, cond.col,
                 expectedFound("bool", foundType(c, cond)));
  }
  checkExpr(c, cond);
}

/** Every `return` in a list of statements. */
/** `checkAll` in a scope of its own, matching `declareScoped` in the declare walk. */
void checkScoped(C c, Stmt[] body, Ty want) {
  c.pushScope(body);
  checkAll(c, body, want);
  c.popScope();
}

void checkAll(C c, Stmt[] body, Ty want) {
  for (i32 i = 0; i < body.len(); i++) { checkStmt(c, body[i], want); }
}

/** Every `return` in a statement, however deeply nested, checked against `want`. */
void checkStmt(C c, Stmt s, Ty want) {
  match (s.kind) {
    /**
     * An assignment, which is the initialiser question with the declared type coming from the target
     * rather than from a `Ty` node.
     *
     * Only plain `=`. A compound assignment (`n += 1`) is the operator's rule rather than this one —
     * the reference accepts `n += 1` for an `i32` exactly as it accepts `n + 1` — and folding the two
     * would report the literal cases that rule deliberately skips.
     */
    // `n++` writes as much as `n = n + 1` does.
    case IncrStmt(target, op): { checkIncr(c, target, s.line, s.col); }
    // A bare expression — `p.set(1);` — was walked nowhere. Every expression rule reached only
    // expressions that were part of something else: a return, an initialiser, a condition. A
    // statement that is just a call is the commonest shape in the language and had no rule applied
    // to it at all, which is how the const-receiver check looked broken when it was merely unreached.
    case ExprStmt(expr): { checkExpr(c, expr); }
    case Assign(target, op, rhs): {
      c.expected = typeOfLvalue(c, target);
      checkExpr(c, rhs);
      // **A const reference stored somewhere that outlives the binding.** `h.i = c` and `xs[0] = c`
      // put a `const S` where nothing downstream can tell it apart from a mutable one — the write
      // `h.i.v = 2` is then accepted, which is the laundering `[§wac-const-deep-j6b1nyg]` refuses.
      // A *local* is the exception and not an oversight: `S t = c;` propagates the constness onto
      // the new name instead (`markAliasOnly`), because a name is something this checker can track
      // and a field of some struct on the heap is not. `spec/cases/0079`, `0080`.
      if (tokenKind(c, op) == kAssign() && indirectLvalue(target) && constName(c, rhs)) {
        string rt = typeOfExpr(c, rhs);
        string rcore = withoutNull(rt);
        string rbase = rcore == "" ? rt : rcore;
        if (isArrayName(rbase) || c.isStruct(rbase)) {
          c.report(errConstReference(), rhs.line, rhs.col);
        }
      }
      // Every assignment writes, compound or not — `n += 1` on a const is refused exactly as `n = 1`
      // is, so this comes before the plain-`=` gate below.
      checkWrite(c, target);
      if (tokenKind(c, op) != kAssign()) {
        // A compound assignment is the operator's rule and the assignment's at once: `x += 1.5` on an
        // `i32` is refused for the same reason `x + 1.5` would be, but reported at the **target**
        // rather than at the operator. Literals count here, unlike in a binary expression, because
        // there is no other side for the literal to take its type from — the target settles it.
        string ct = typeOfLvalue(c, target);
        if (ct == typeNone() || ct == "" || isPackedName(ct)) { return; }
        // **A shift's right-hand side is a count, not the other half of a pair.**
        // `spec/spec/operators.md`: a compound operator has *"same type rules as the underlying
        // operator"*, and spells the consequence out — `i64 <<= i32` is allowed wherever `i64 <<
        // i32` is. The same-type rule below is right for `+=` and wrong here, and it refused three
        // programs the spec runs.
        i32 shiftKind = tokenKind(c, op);
        if (shiftKind == kShlEq() || shiftKind == kShrEq() || shiftKind == kShrUEq()) {
          string samt = typeOfExpr(c, rhs);
          if (!isIntegerName(ct) || (samt != typeNone() && !isIntegerName(samt))) {
            c.report(errOperandKind(), lvalueStartLine(target), lvalueStartCol(target));
          }
          return;
        }
        // `+=` and its siblings are arithmetic, so the target has to be something arithmetic can be
        // done to: a number, or a `string`, which concatenates. An array, a struct, an enum and a
        // funcref all *agree with themselves*, so the type comparison below has nothing to say about
        // `a += b` on two of them — the same shape as `a & b` on two floats, one operator family on.
        i32 tline = lvalueStartLine(target);
        i32 tcol = lvalueStartCol(target);
        if (!isValueType(ct) && ct != "string") {
          c.report(errOperandMismatch(), tline, tcol);
          return;
        }
        i32 clit = litKindOf(rhs);
        if (clit != litNone()) {
          reportLiteral(c, ct, rhs, errOperandMismatch(), tline, tcol);
          return;
        }
        string cgot = typeOfExpr(c, rhs);
        if (cgot != typeNone() && cgot != ct) {
          c.report(errOperandMismatch(), tline, tcol);
        }
        return;
      }
      string wantTo = typeOfLvalue(c, target);
      if (wantTo == typeNone()) { return; }
      // **A packed target takes an `i32`** — which is measured now rather than assumed. A packed
      // target is an array element by construction, nothing else can have that type, and an integer
      // truncates into one at the store; what this used to add was that what the reference accepts
      // *beyond* that was not measured, so it said nothing at all and `bytes[i] = "s"` was accepted.
      //
      // Measured: the reference takes an integer literal and an `i32` there, and refuses `i64`,
      // `f64`, `bool` and `string`, naming `i32` in each. So the rule is the `i32` rule, which is
      // the same widening `typeOfExpr`'s `Index` arm already does on the reading side — `bytes[i]`
      // from a `u8[]` is an i32-shaped value. Four element types were unchecked, `u8` `i8` `u16`
      // `i16`; `u32`, `i64`, `f64` and `bool` were not, because those are variable types that answer
      // for themselves.
      if (isPackedName(wantTo)) { wantTo = "i32"; }
      i32 litTo = litFamily(c, rhs);
      if (litTo != litNone()) {
        reportLiteral(c, wantTo, rhs, errInitTypeMismatch(), rhs.line, rhs.col);
        return;
      }
      string gotTo = typeOfExpr(c, rhs);
      if (nullableIntoNonNull(wantTo, gotTo)) {
        c.report(errNullableToNonNull(), rhs.line, rhs.col);
      } else if (!assignable(c, wantTo, gotTo)) {
        c.reportWith(errInitTypeMismatch(), rhs.line, rhs.col, expectedFound(wantTo, gotTo));
      }
    }
    // The same question one position over: a declared type, and something that has to fit it.
    case Var(type, nameTok, init, isConst): {
      string wantVar = typeOfTy(c, type);
      checkPackedNullable(c, wantVar, type);
      checkPackedHere(c, wantVar, type.line, type.col);
      if (wantVar == typeNone()) { return; }
      i32 litVar = litFamily(c, init);
      if (litVar != litNone()) {
        reportLiteral(c, wantVar, init, errInitTypeMismatch(), init.line, init.col);
        return;
      }
      string gotVar = typeOfExpr(c, init);
      if (nullableIntoNonNull(wantVar, gotVar)) {
        c.report(errNullableToNonNull(), init.line, init.col);
      } else if (!assignable(c, wantVar, gotVar)) {
        c.reportWith(errInitTypeMismatch(), init.line, init.col, expectedFound(wantVar, gotVar));
      }
      c.expected = wantVar;
      checkExpr(c, init);
    }
    case Return(value): {
      // Before the types: whether there should be a value here at all. Both directions are errors and
      // both name the `return` itself rather than what follows it — there is nothing to name in the
      // second case, which is presumably why the reference settled on the statement for both.
      //
      // **Inside a lambda the answer comes from `c.lambdaReturn`**, because a lambda writes no return
      // type and `want` is still the enclosing function's. `design/lang/0002` settles what `return`
      // means here: it returns from the lambda, which is the only available reading once the lambda
      // can outlive the frame it was written in.
      string declared = c.lambdaReturn != "" ? c.lambdaReturn : typeOfTy(c, want);
      if (declared == "void" && !(value is null)) {
        c.report(errReturnValueness(), s.line, s.col);
        return;
      }
      if ((value is null) && returnsAValue(declared)) {
        c.report(errReturnValueness(), s.line, s.col);
        return;
      }
      if (value is null) { return; }
      string expected = declared;
      if (!returnsAValue(expected)) { return; }
      Expr e = value!;
      i32 lit = litKindOf(e);
      if (lit != litNone()) {
        // A literal: polymorphic over a family, so the question is whether the declared type is in it.
        reportLiteral(c, expected, e, errReturnTypeMismatch(), e.line, e.col);
        return;
      }
      // A name: a value of exactly one type, so the question is whether it is the declared one.
      string got = typeOfExpr(c, e);
      if (nullableIntoNonNull(expected, got)) {
        c.report(errNullableToNonNull(), e.line, e.col);
      } else if (!assignable(c, expected, got)) {
        c.reportWith(errReturnTypeMismatch(), e.line, e.col, expectedFound(expected, got));
      }
      c.expected = expected;
      checkExpr(c, e);
    }
    // Every arm carrying statements recurses. `els` is an empty array rather than a null for "no
    // else", and `Switch`/`Match` hold their bodies one level deeper, inside cases and arms.
    case Block(body): { checkScoped(c, body, want); }
    case If(cond, then, els): {
      checkCond(c, cond);
      // `if (s is Circle) { s.radius }` — the guard is what makes the payload reachable, so the then
      // branch is walked with `s` retyped and the old type put back afterwards. Saved and restored
      // rather than scoped, because this checker's names are one flat table per function.
      string[] nNames = string[8]();
      string[] nTypes = string[8]();
      i32 nCount = narrowingsOf(c, cond, nNames, nTypes, 0);
      string[] saved = string[nCount]();
      bool[] savedConst = bool[nCount]();
      bool[] savedAlias = bool[nCount]();
      for (i32 i = 0; i < nCount; i++) {
        saved[i] = c.typeOfName(nNames[i]);
        // **A narrowed name is const for the branch**, exactly as a match arm's subject is: writing
        // to it would leave the narrowing describing a value that has gone. `spec/cases/0071`.
        savedConst[i] = c.isConstName(nNames[i]);
        savedAlias[i] = c.isAliasOnlyName(nNames[i]);
        c.setType(nNames[i], nTypes[i]);
        c.setConstFlags(nNames[i], true, false);
      }
      // The narrowings are set and restored *outside* the arm's scope: they retype names that
      // belong to an enclosing one, and a name is only reachable while its own scope is open.
      checkScoped(c, then, want);
      for (i32 i = 0; i < nCount; i++) {
        c.setType(nNames[i], saved[i]);
        c.setConstFlags(nNames[i], savedConst[i], savedAlias[i]);
      }
      checkScoped(c, els, want);
    }
    // `break` and `continue` need something to leave. Switches count for both — `break` obviously,
    // and `continue` because the reference accepts it there, which is measured rather than read off
    // its message. Reported at the statement, which is the whole of it.
    // **A trap's message is what the host is told, so it is text.** Accepting a message at all meant
    // accepting any expression as one until this: `spec/cases/0043` is the message, `0045` is that it
    // has to be a string.
    case Trap(value): {
      if (!(value is null)) {
        Expr msg = value!;
        c.expected = "string";
        checkExpr(c, msg);
        if (litKindOf(msg) != litNone()) {
          if (litKindOf(msg) != litString()) {
            c.reportWith(errOperandKind(), msg.line, msg.col,
                         expectedFound("string", foundType(c, msg)));
          }
        } else {
          string mt = typeOfExpr(c, msg);
          if (mt != typeNone() && mt != "" && mt != "string") {
            c.reportWith(errOperandKind(), msg.line, msg.col, expectedFound("string", mt));
          }
        }
      }
    }
    case Break: {
      if (c.loopDepth == 0) { c.report(errNoLoop(), s.line, s.col); }
    }
    case Continue: {
      if (c.loopDepth == 0) { c.report(errNoLoop(), s.line, s.col); }
    }
    case While(cond, body): {
      checkCond(c, cond);
      c.loopDepth = c.loopDepth + 1;
      checkScoped(c, body, want);
      c.loopDepth = c.loopDepth - 1;
    }
    case DoWhile(body, cond): {
      checkCond(c, cond);
      c.loopDepth = c.loopDepth + 1;
      checkScoped(c, body, want);
      c.loopDepth = c.loopDepth - 1;
    }
    case For(init, cond, update, body): {
      // The init and update are statements, and were declared but never checked — a `for` whose
      // initialiser is wrong said nothing. The reachability grid found it: `For` passed on its body
      // and failed on its init, which is exactly the shape of a walk that descends one field and not
      // its siblings.
      // Initialiser, condition and update are all inside the body's scope: `i` is declared there
      // and read by all three. Matches the declare walk. `issues/lang/0122`.
      c.pushScope(body);
      if (!(init is null)) { checkStmt(c, init!, want); }
      if (!(cond is null)) { checkCond(c, cond!); }
      if (!(update is null)) { checkStmt(c, update!, want); }
      c.loopDepth = c.loopDepth + 1;
      checkAll(c, body, want);
      c.loopDepth = c.loopDepth - 1;
      c.popScope();
    }
    case Switch(subject, cases): {
      checkExpr(c, subject);
      // A `switch` jumps on an integer, and a signed or unsigned 32-bit one at that. Reported at the
      // subject, which is the expression that cannot be switched on.
      string subT = typeOfExpr(c, subject);
      if (subT != typeNone() && subT != "" && subT != "i32" && subT != "u32") {
        c.report(errSwitchSubject(), subject.line, subject.col);
      }
      // **One `default` at most**, reported at the second one's own keyword — the first is the
      // arm that works and the second is the mistake.
      bool sawDefault = false;
      for (i32 i = 0; i < cases.len(); i++) {
        if (!(cases[i].value is null)) { continue; }
        if (sawDefault) { c.report(errTwoDefaults(), cases[i].line, cases[i].col); }
        sawDefault = true;
      }
      // A case value is compared against the subject with `==`, so it is an `i32` like the subject.
      // At the `case` keyword rather than at the value, which is why a `Case` now carries a position:
      // the complaint is about the arm rather than about the expression in it.
      for (i32 i = 0; i < cases.len(); i++) {
        if (cases[i].value is null) { continue; }
        Expr cv = cases[i].value!;
        i32 cvl = litKindOf(cv);
        if (cvl != litNone()) {
          if (!acceptsLiteral("i32", cvl)) {
            c.report(errSwitchSubject(), cases[i].line, cases[i].col);
          }
        } else {
          string cvt = typeOfExpr(c, cv);
          if (cvt != typeNone() && !isIntegerName(cvt)) {
            c.report(errSwitchSubject(), cases[i].line, cases[i].col);
          }
        }
      }
      c.loopDepth = c.loopDepth + 1;
      for (i32 i = 0; i < cases.len(); i++) { checkScoped(c, cases[i].body, want); }
      c.loopDepth = c.loopDepth - 1;
    }
    case Match(subject, arms): {
      checkArmVariants(c, subject, arms);
      c.loopDepth = c.loopDepth + 1;
      for (i32 i = 0; i < arms.len(); i++) {
        // **An arm narrows the subject**, exactly as `if (s is Circle)` does — `case Circle:` is the
        // same question asked by the other syntax, and `s.radius` inside it means the payload. The
        // subject has to be a plain name for this: narrowing `f().x` would mean claiming the second
        // call returns what the first did.
        string saved = armNarrowing(c, subject, arms[i]);
        checkBindingCollision(c, subject, arms[i]);
        // The subject is const for the length of a narrowed arm: assigning to it would leave the
        // narrowing describing a value that is no longer there.
        string subj = subjectName(c, subject);
        bool wasConst = subj == "" ? false : c.isConstName(subj);
        bool wasAlias = subj == "" ? false : c.isAliasOnlyName(subj);
        if (subj != "" && arms[i].variantTok >= 0) { c.setConstFlags(subj, true, false); }
        // Scoped: the arm's bindings were declared against this same body array.
        checkScoped(c, arms[i].body, want);
        if (subj != "") { c.setConstFlags(subj, wasConst, wasAlias); }
        restoreNarrowing(c, subject, saved);
      }
      c.loopDepth = c.loopDepth - 1;
    }
  }
}

/**
 * Retype a match subject to the arm's variant for the arm's body, answering what to put back.
 *
 * The saved type is returned through the checker's own table rather than by value, because a name
 * that was not narrowed must be left exactly as it was — and "not narrowed" happens for every arm
 * whose subject is an expression rather than a name, and for `else`.
 */
/**
 * The arms of an expression match all produce the one value, so their types have to agree.
 *
 * Compared only between arms this checker can name, and never against a literal: `case A: 0.0,
 * case B: 1` is an integer literal in a float's slot, which is the literal rule's business and not a
 * disagreement between arms. Two concrete types that cannot stand in for one another in either
 * direction are the case worth reporting, and the second one is where the mistake reads.
 */
void checkArmValueTypes(C c, Arm[] arms) {
  string first = "";
  for (i32 i = 0; i < arms.len(); i++) {
    if (arms[i].value is null) { continue; }
    Expr v = arms[i].value!;
    string vt = armShape(c, v);
    if (vt == "") { continue; }
    if (first == "") { first = vt; continue; }
    if (vt == first) { continue; }
    // Any mix of numbers is somebody else's rule — the literal's slot decides whether `0` belongs in
    // an `f64`, and two arms both producing numbers are not the disagreement this is looking for.
    if (numericShape(vt) && numericShape(first)) { continue; }
    if (assignable(c, first, vt) || assignable(c, vt, first)) { continue; }
    // **Both sides have to be a type this checker can vouch for.** `case Some(v): v * 3` in
    // `packages/std` has a payload whose type comes from the enum's instantiation, and what came back
    // was a name rather than a type — against `-1` that read as a disagreement and refused a working
    // file. Silence on anything else is the same rule the rest of this checker keeps.
    if (!concreteShape(vt) || !concreteShape(first)) { continue; }
    c.report(errArmTypes(), v.line, v.col);
  }
}

/**
 * What an arm's value is, as a type name — a literal answers with the type it naturally has.
 *
 * Skipping literals outright was the first version, on the grounds that a literal takes its type
 * from its slot. It does, but only among types that could hold it: `case Point: 0.0, else: "x"` is
 * the spec's own example of arms that disagree, and both of its arms are literals, so skipping them
 * skipped the case the rule exists for.
 */
string armShape(C c, Expr v) {
  i32 k = litKindOf(v);
  if (k == litInteger()) { return "i32"; }
  if (k == litFloat()) { return "f64"; }
  if (k == litBool()) { return "bool"; }
  if (k == litString()) { return "string"; }
  if (k == litNull()) { return ""; }
  string t = typeOfExpr(c, v);
  return t == typeNone() ? "" : t;
}

/** Integers and floats alike, which is the set this rule declines to police. */
bool numericShape(string t) {
  return isIntegerName(t) || t == "f32" || t == "f64";
}

/** A primitive this checker is sure of. Anything else — a struct, a generic payload — stays silent. */
bool concreteShape(string t) {
  return numericShape(t) || t == "bool" || t == "string";
}

/** The subject's name, when the subject is a plain name — `""` for anything else. */
string subjectName(C c, Expr subject) {
  match (subject.kind) {
    case Ident(tok): { return tokenText(c, tok); }
    else: { return ""; }
  }
}

/**
 * A binding may not reuse the subject's name.
 *
 * `case Circle(s):` where the subject is also `s` would put two meanings on one name for the length
 * of the arm — the payload and the value it came out of — and the language refuses rather than
 * choosing one.
 */
void checkBindingCollision(C c, Expr subject, Arm arm) {
  string nm = subjectName(c, subject);
  if (nm == "") { return; }
  for (i32 b = 0; b < arm.bindingToks.len(); b++) {
    if (tokenText(c, arm.bindingToks[b]) != nm) { continue; }
    c.reportTok(errBindingCollision(), arm.bindingToks[b], "");
  }
}

string armNarrowing(C c, Expr subject, Arm arm) {
  if (arm.variantTok < 0) { return ""; }
  match (subject.kind) {
    case Ident(tok): {
      string nm = tokenText(c, tok);
      string was = c.typeOfName(nm);
      if (was == typeNone()) { return ""; }
      string variant = tokenText(c, arm.variantTok);
      if (!c.isStruct(variant)) { return ""; }
      c.setType(nm, variant);
      return was;
    }
    else: { return ""; }
  }
}

void restoreNarrowing(C c, Expr subject, string was) {
  if (was == "") { return; }
  match (subject.kind) {
    case Ident(tok): { c.setType(tokenText(c, tok), was); }
    else: { }
  }
}

/** Check one program, and return `(code, line, col)` triples in source order. */
/**
 * Two declarations of one name, at file scope and inside a struct.
 *
 * The **positions are the reference's**, and they are not where a reader would guess: a duplicate
 * *declaration* is reported at the declaration's own start — the `i32` of `i32 foo()`, not the
 * `foo` — and a duplicate *member* at its type's start for the same reason. This slice reports a
 * subset of the reference and never a superset, so a position that is merely reasonable is a
 * contradiction; these were read off the reference one case at a time.
 */
/**
 * The two declaration rules the spec states and this checker did not.
 *
 * **`E.A` cannot mean two things.** A variant is reached as `E.A` and so is a static, so an enum
 * whose method is named after one of its own variants has a name with two meanings —
 * `spec/spec/enums.md` makes a variant a name in its own right, and this is that rule inside the
 * enum rather than across the file.
 *
 * **A generic that instantiates itself with a *larger* argument never terminates.**
 * `struct Rec<T> { Rec<Box<T>>? next; }` is the spec's own example: `Rec<i32>` needs `Rec<Box<i32>>`
 * needs `Rec<Box<Box<i32>>>`. The test is *growth*, not self-reference: `Node<T> { Node<T>? next; }`
 * is an ordinary linked list, and `Pair<A, B> { Pair<B, A>? swap; }` cycles between two
 * instantiations and terminates. What cannot terminate is an argument that *contains* a parameter
 * without being it. The spec caps nesting at 24 rather than reasoning about shape; this rejects the
 * shape, which is narrower, and a program it accepts is one the cap would have caught anyway.
 */
/**
 * The two collision rules `spec/spec/naming.md` states about imports.
 *
 * *"Two imports with the same name is a compile error"* (`§wac-dup-import-vqn4100`), and *"an import
 * colliding with a local name is a compile error"* (`§wac-dup-import-local-4fadlvg`). Both are
 * decidable from the importing file alone — its import list and its own declarations — which is why
 * they are here rather than waiting on anything that reads the other files.
 *
 * Reported at the second mention, which is the one that could have been written differently: the
 * spec's own remedy is `import { foo as bar }`, and it is the later import that takes the rename.
 */
void checkImportCollisions(C c, Program prog) {
  string[] seen = string[256]();
  i32 n = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Import(pathTok, prefixTok, items): {
        for (i32 i = 0; i < items.len(); i++) {
          string alias = tokenText(c, items[i].aliasTok);
          bool clash = false;
          for (i32 k = 0; k < n; k++) {
            if (seen[k] == alias) { clash = true; }
          }
          if (!clash) {
            for (i32 e = 0; e < prog.decls.len(); e++) {
              if (declaredNameOf(c, prog.decls[e]) == alias) { clash = true; }
            }
          }
          if (clash) {
            c.reportTok(errDuplicateImport(), items[i].aliasTok, "");
          } else if (n < seen.len()) {
            seen[n] = alias;
            n = n + 1;
          }
        }
      }
      else: { }
    }
  }
}

/** The name a declaration introduces, or `""` — an import introduces one too, and is not one. */
string declaredNameOf(C c, Decl d) {
  match (d.kind) {
    case Func(nameTok, returnType, params, body, exported, typeParams): {
      return tokenText(c, nameTok);
    }
    case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
      return tokenText(c, nameTok);
    }
    case EnumDecl(nameTok, variants, exported, methods, typeParams): { return tokenText(c, nameTok); }
    case ConstDecl(nameTok, type, init, exported): { return tokenText(c, nameTok); }
    else: { return ""; }
  }
}

void checkDeclarationRules(C c, Program prog) {
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        for (i32 m = 0; m < methods.len(); m++) {
          string mn = tokenText(c, methods[m].nameTok);
          for (i32 v = 0; v < variants.len(); v++) {
            if (tokenText(c, variants[v].nameTok) != mn) { continue; }
            c.reportTok(errVariantMethodClash(), methods[m].nameTok, "");
          }
        }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() == 0) { continue; }
        // Not named `self`: a wac local by that name has no wapy rendering — `issues/lang/0077` —
        // and this file round-trips through wapy on every suite run, which is where that showed up.
        string owner = tokenText(c, nameTok);
        for (i32 f = 0; f < fields.len(); f++) {
          if (!growsItself(c, fields[f].type, owner, typeParams)) { continue; }
          c.report(errInfiniteGeneric(), fields[f].type.line, fields[f].type.col);
        }
      }
      else: { }
    }
  }
}

/** Whether this written type is the struct itself with an argument that *contains* a parameter. */
bool growsItself(C c, Ty t, string owner, i32[] typeParams) {
  match (t.kind) {
    case Arr(elem): { return growsItself(c, elem, owner, typeParams); }
    case Nullable(inner): { return growsItself(c, inner, owner, typeParams); }
    case Named(tok, typeArgs): {
      if (tokenText(c, tok) == owner) {
        for (i32 i = 0; i < typeArgs.len(); i++) {
          if (argumentGrows(c, typeArgs[i], typeParams)) { return true; }
        }
      }
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (growsItself(c, typeArgs[i], owner, typeParams)) { return true; }
      }
      return false;
    }
    else: { return false; }
  }
}

/** Whether an argument mentions a type parameter without being one: `Box<T>` does, `T` does not. */
bool argumentGrows(C c, Ty t, i32[] typeParams) {
  match (t.kind) {
    case Named(tok, typeArgs): {
      string nm = tokenText(c, tok);
      for (i32 i = 0; i < typeParams.len(); i++) {
        if (tokenText(c, typeParams[i]) == nm) { return false; }
      }
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (mentionsParam(c, typeArgs[i], typeParams)) { return true; }
      }
      return false;
    }
    case Arr(elem): { return mentionsParam(c, elem, typeParams); }
    case Nullable(inner): { return argumentGrows(c, inner, typeParams); }
    else: { return false; }
  }
}

/** Whether a written type mentions one of these parameters anywhere inside it. */
bool mentionsParam(C c, Ty t, i32[] typeParams) {
  match (t.kind) {
    case Named(tok, typeArgs): {
      string nm = tokenText(c, tok);
      for (i32 i = 0; i < typeParams.len(); i++) {
        if (tokenText(c, typeParams[i]) == nm) { return true; }
      }
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (mentionsParam(c, typeArgs[i], typeParams)) { return true; }
      }
      return false;
    }
    case Arr(elem): { return mentionsParam(c, elem, typeParams); }
    case Nullable(inner): { return mentionsParam(c, inner, typeParams); }
    else: { return false; }
  }
}

/**
 * A line number for a diagnostic's note.
 *
 * Local rather than imported: `numText` lives in the emitter, and the checker does not depend on it —
 * a diagnostic wanting to say "line 12" is not a reason to make the front end depend on the back one.
 */
string lineText(i32 v) {
  if (v <= 0) { return "?"; }
  string out = "";
  i32 x = v;
  while (x > 0) {
    i32 d = x % 10;
    out = "0123456789".slice(d, d + 1) + out;
    x = x / 10;
  }
  return out;
}

void checkDuplicates(C c, Program prog) {
  string[] names = string[512]();
  i32[] nameLines = i32[512]();
  i32 n = 0;
  // A variant is reachable as a bare name — `Circle(1.0)` with no `Shape.` in front of it — so two
  // enums declaring one leave the file with a name that means two things. Kept across the whole walk
  // rather than per enum, which is the only way the collision is visible at all. `spec/cases/0073`.
  string[] variantNames = string[256]();
  // Where each was declared, so a collision can name **both** places. A message that says only
  // "declared twice" at the second one leaves a reader searching for the first, which in a file with
  // an enum of twenty variants is the whole of the work. `issues/lang/0114`.
  i32[] variantLines = i32[256]();
  i32 vn = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    string name = "";
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        name = tokenText(c, nameTok);
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        name = tokenText(c, nameTok);
        // A struct's members share one namespace: two fields, two methods, or one of each.
        string[] members = string[256]();
        i32 m = 0;
        for (i32 f = 0; f < fields.len(); f++) {
          string fname = tokenText(c, fields[f].nameTok);
          bool dup = false;
          for (i32 k = 0; k < m; k++) {
            if (members[k] == fname) { dup = true; }
          }
          if (dup) {
            c.reportWith(errDuplicateMember(), fields[f].type.line, fields[f].type.col,
                         fname + " appears twice");
          }
          if (m < members.len()) {
            members[m] = fname;
            m = m + 1;
          }
        }
        for (i32 t = 0; t < methods.len(); t++) {
          string mn = tokenText(c, methods[t].nameTok);
          bool dup2 = false;
          for (i32 k = 0; k < m; k++) {
            if (members[k] == mn) { dup2 = true; }
          }
          if (dup2) {
            c.report(errDuplicateMember(), methods[t].returnType.line, methods[t].returnType.col);
          }
          if (m < members.len()) {
            members[m] = mn;
            m = m + 1;
          }
        }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        name = tokenText(c, nameTok);
        for (i32 v = 0; v < variants.len(); v++) {
          string vname = tokenText(c, variants[v].nameTok);
          i32 dupv = -1;
          for (i32 k = 0; k < vn; k++) {
            if (variantNames[k] == vname) { dupv = variantLines[k]; }
          }
          // **And against the names already at file scope.** A variant is reachable bare — `Thing(7)`
          // with no `E.` in front — so it shares a namespace with every struct, enum, function and
          // constant in the file, and the two lists were never compared with each other. A `struct
          // Thing` beside a variant `Thing` was reported as *wrong number of arguments to the
          // constructor* at the call site in one order, and **not at all** in the other, while the
          // reference said *duplicate name* for both. `issues/lang/0114`.
          for (i32 k = 0; k < n; k++) {
            if (names[k] == vname) { dupv = nameLines[k]; }
          }
          if (dupv >= 0) {
            c.reportTok(errDuplicateName(), variants[v].nameTok,
                        vname + " is declared twice — the first is on line " + lineText(dupv));
          }
          if (vn < variantNames.len()) {
            variantNames[vn] = vname;
            variantLines[vn] = variants[v].nameTok < 0 ? 0 : tokenLine(c, variants[v].nameTok);
            vn = vn + 1;
          }
        }
        // A variant's payload fields are named like a struct's, and collide like them.
        for (i32 v = 0; v < variants.len(); v++) {
          string[] payload = string[64]();
          i32 pn = 0;
          for (i32 f = 0; f < variants[v].fields.len(); f++) {
            string pname = tokenText(c, variants[v].fields[f].nameTok);
            bool dup3 = false;
            for (i32 k = 0; k < pn; k++) {
              if (payload[k] == pname) { dup3 = true; }
            }
            if (dup3) {
              c.reportWith(errDuplicateMember(), variants[v].fields[f].type.line,
                         variants[v].fields[f].type.col, pname + " appears twice");
            }
            if (pn < payload.len()) {
              payload[pn] = pname;
              pn = pn + 1;
            }
          }
        }
      }
      case ConstDecl(nameTok, type, init, exported): { name = tokenText(c, nameTok); }
      else: { }
    }
    if (name == "") { continue; }
    i32 seen = -1;
    for (i32 k = 0; k < n; k++) {
      if (names[k] == name) { seen = nameLines[k]; }
    }
    // The other direction of the same collision: a declaration whose name a variant already took.
    for (i32 k = 0; k < vn; k++) {
      if (variantNames[k] == name) { seen = variantLines[k]; }
    }
    if (seen >= 0) {
      c.reportWith(errDuplicateName(), prog.decls[d].line, prog.decls[d].col,
                   name + " is declared twice — the first is on line " + lineText(seen));
    }
    if (n < names.len()) {
      names[n] = name;
      nameLines[n] = prog.decls[d].line;
      n = n + 1;
    }
  }
}

export i32[] checkProgram(u8[] src, i32[] toks, i32 tokenCount, Program prog) {
  C c = C.create(src, toks, tokenCount, tokenCount);
  checkModule(c, prog);
  return errorsOf(c);
}

/** The `(code, line, col)` triples a finished check answers with. */
export i32[] errorsOf(C c) {
  i32[] out = i32[c.errorCount * 3]();
  for (i32 i = 0; i < c.errorCount * 3; i++) { out[i] = c.errors[i]; }
  return out;
}

/** The warnings, in the same `(code, line, col)` shape and from their own table. */
export i32[] warningsOf(C c) {
  i32[] out = i32[c.warnCount * 3]();
  for (i32 i = 0; i < c.warnCount * 3; i++) { out[i] = c.warnings[i]; }
  return out;
}

/** The operands of each diagnostic, in the same order — `""` where the site had none to give. */
export string[] notesOf(C c) {
  string[] out = string[c.errorCount]();
  for (i32 i = 0; i < c.errorCount; i++) {
    out[i] = i < c.errorNotes.len() ? c.errorNotes[i] : "";
  }
  return out;
}

/** How wide each diagnostic is, in the same order — `0` where nothing measured one. */
export i32[] widthsOf(C c) {
  i32[] out = i32[c.errorCount]();
  for (i32 i = 0; i < c.errorCount; i++) {
    out[i] = i < c.errorWidths.len() ? c.errorWidths[i] : 0;
  }
  return out;
}

/**
 * Everything this checker does to one module, against whatever is already declared in `c`.
 *
 * Split out so a file's **imports** can be run through it first with `c.quiet` set: their
 * declarations land in the same tables, their diagnostics are thrown away, and the file that matters
 * is then checked with every name it can see. A single file is that with an empty `c` and nothing
 * quiet, which is what `checkProgram` is.
 */
/**
 * Everything a module *declares*, into `c` — and, when `only` is non-empty, **only the names in it**.
 *
 * Split from the checking passes so a file's imports can contribute their declarations without being
 * checked. The filter is what makes that safe: every table in this checker is keyed by a bare name
 * and the first declaration of one wins, so letting an import contribute every name it happens to
 * hold put another file's `Rng` in front of this file's — forty working files reported as errors.
 * `import { X } from "…"` says exactly which names cross, and this honours it.
 *
 * A type that crosses brings its members with it: the filter is asked about the struct, and its
 * fields and methods follow, because a name reaches them through the type rather than on its own.
 */
export void declareModule(C c, Program prog, string[] only) {
  // Module-level `const` declarations, which are in scope in every body and outlive `clearScope`.
  // A write to one is *"cannot assign to constant 'S'"*, which is the const-variable rule reaching a
  // scope it did not have — and reaching it through fields too: `S.v = 9` on a `const P S` is refused
  // the way a `const P p` parameter is.
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case ConstDecl(nameTok, type, init, exported): {
        if (!wantedName(only, tokenText(c, nameTok))) { continue; }
        c.declareConst(c.renamed(tokenText(c, nameTok)), typeOfTy(c, type), true);
      }
      else: { }
    }
  }
  c.globalCount = c.nameCount;

  // Signatures first, over the whole file: a call names something declared elsewhere, and often
  // further down. The same argument as collecting locals before walking a body, one scope up.
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (!wantedName(only, tokenText(c, nameTok))) { continue; }
        string[] etps = string[typeParams.len()]();
        for (i32 i = 0; i < typeParams.len(); i++) { etps[i] = tokenText(c, typeParams[i]); }
        c.declareEnum(c.renamed(tokenText(c, nameTok)), etps);
        // Each variant is a type of its own, with its payload as fields. `s is Circle` narrows `s`
        // to `Circle`, and `s.radius` then has to find a `radius` somewhere — so the variant has to
        // be as much a struct as anything else here. Registered under its bare name, which is how
        // `is` writes it; the qualified `Shape.Circle` is a construction and goes elsewhere.
        for (i32 vi = 0; vi < variants.len(); vi++) {
          string vname = tokenText(c, variants[vi].nameTok);
          // **A generic enum's variants have no bare name.** `Some` belongs to `Option<i32>` and to
          // every other instance, so it names no type on its own — `a is Some` is a name nobody
          // declared rather than a narrowing (`spec/cases/0037`). A non-generic enum's variant *is*
          // a bare name, which is how `s is Circle` narrows.
          //
          // The variant still goes in the table, because `Option.None` is how one is written and
          // that has to keep working — skipping the registration entirely refused four working files
          // and `spec/tour.wac` itself. What it loses is the bare *type*: `spec/cases/0042`.
          bool bare = typeParams.len() == 0;
          if (bare) { c.declareStruct(vname, "", string[0]()); }
          c.declareVariant(tokenText(c, nameTok), vname, variants[vi].fields.len());
          c.markVariantBare(vname, bare);
          for (i32 fi = 0; fi < variants[vi].fields.len(); fi++) {
            c.declareFieldConst(vname, tokenText(c, variants[vi].fields[fi].nameTok),
                                typeOfTy(c, variants[vi].fields[fi].type), false);
          }
        }
        // **An enum's methods, which were never declared at all.** `enum E { … i32 val(const this) }`
        // put `val` nowhere, so `e.val()` was unreported only because an enum is not a struct and the
        // method check returns on anything else — silence by accident rather than by rule. Declared
        // under the enum's own name, which is where a receiver typed `E` looks, and where a variant
        // narrowed out of it looks too.
        string ename = tokenText(c, nameTok);
        for (i32 mi = 0; mi < methods.len(); mi++) {
          string[] emps = string[methods[mi].params.len()]();
          for (i32 pi = 0; pi < methods[mi].params.len(); pi++) {
            emps[pi] = typeOfTy(c, methods[mi].params[pi].type);
          }
          // **A generic enum's method types are unknown until an instance supplies them.**
          // `Opt<T>.orElse` answers a `T`, and there is no substitution for an enum here — the
          // parameter table belongs to structs. Recording the letter made `o.orElse(0)` return a
          // type nobody declared, in eighteen programs. The arity is still worth having, which is
          // why the method is declared at all.
          bool gen = typeParams.len() > 0;
          c.declareMethod(ename, tokenText(c, methods[mi].nameTok),
                          !methods[mi].hasThis, methods[mi].thisConst,
                          gen ? typeNone() : typeOfTy(c, methods[mi].returnType), emps,
                          methods[mi].body);
        }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        // Filtered on the name the declaring file wrote, declared under the name the importing
        // file gave it: `only` carries what was asked for, the rename carries what to call it.
        string name = tokenText(c, nameTok);
        if (!wantedName(only, name)) { continue; }
        name = c.renamed(name);
        string[] tps = string[typeParams.len()]();
        for (i32 i = 0; i < typeParams.len(); i++) { tps[i] = tokenText(c, typeParams[i]); }
        c.declareStruct(name, parentTok < 0 ? "" : tokenText(c, parentTok), tps);
        // A generic struct's fields are not recorded. `struct Box<T> { T v; }` has a field whose
        // type is the *parameter* `T`, which is a name like any other to `typeOfTy` and therefore
        // looks like a struct called `T` — enough to make `Box(1)` a field mismatch against a type
        // that does not exist. The spec corpus caught it:
        // `[§wac-generic-expected-position-3qmz8vk]`. With no fields recorded the arity is zero,
        // never matches, and construction of a generic says nothing — which is the honest answer
        // until instantiation is modelled.
        // Generics included, and their field types recorded **as written** — `T`, `T[]`. A name like
        // `T` is meaningless on its own, and becomes a type only once an instantiation says what its
        // arguments are, which is what `substituteType` does at every lookup. Recording nothing, as
        // the first version did, made every generic's members invisible rather than unknown.
        for (i32 i = 0; i < fields.len(); i++) {
          // `const struct Config { … }` makes every field const without any of them saying so,
          // which is the whole point of the spelling: one word instead of one per field.
          c.declareFieldConst(name, tokenText(c, fields[i].nameTok),
                              typeOfTy(c, fields[i].type), isConst || fields[i].isConst);
        }
        for (i32 i = 0; i < methods.len(); i++) {
          string[] mps = string[methods[i].params.len()]();
          for (i32 pi = 0; pi < methods[i].params.len(); pi++) {
            mps[pi] = typeOfTy(c, methods[i].params[pi].type);
          }
          c.declareMethod(name, tokenText(c, methods[i].nameTok),
                          !methods[i].hasThis, methods[i].thisConst,
                          typeOfTy(c, methods[i].returnType), mps,
                          methods[i].body);
        }
      }
      else: { }
    }
  }
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        // A generic function's signature is written in terms of its own type parameters, which mean
        // nothing at a call site: `Box<T>` accepts every `Box<…>`, and `T` accepts everything. Its
        // arity is still worth having — that does not depend on the types — so the parameters are
        // recorded as unknown rather than the function being left out.
        // Recorded **as written**, generics included: `Box<T>` and `T` are what a call site binds
        // against. An earlier version blanked them, which was right when nothing could bind them and
        // is now the thing standing between a generic call and its return type.
        if (!wantedName(only, tokenText(c, nameTok))) { continue; }
        string[] prims = string[params.len()]();
        for (i32 i = 0; i < params.len(); i++) { prims[i] = typeOfTy(c, params[i].type); }
        string[] ftps = string[typeParams.len()]();
        for (i32 i = 0; i < typeParams.len(); i++) { ftps[i] = tokenText(c, typeParams[i]); }
        c.declareFunc(c.renamed(tokenText(c, nameTok)), typeOfTy(c, returnType), prims,
                      params.len(), ftps);
      }
      else: { }
    }
  }
}

/**
 * Every arm names a variant the subject's enum actually has.
 *
 * Reported at the **`case`**, which is the token before the name — the reference's position, and one
 * this checker can reach because the tokens are a flat array and the arm knows its own index.
 *
 * Asked of the enum the subject *is*: a variant belonging to some other enum is not this one's, and
 * an instantiation asks its template, since `Opt<i32>` and `Opt` have the same variants by
 * construction.
 */
/**
 * The enum a subject is a value of — `E` for an `E`, and `E` for an `E.A(1)`.
 *
 * A variant construction has the *variant's* own type, because a variant is registered as a struct
 * of its own: that is how `case A:` narrows and how a payload is found. So `match (E.A(1))` asked
 * `isEnum` about `A` and was told no, and every rule keyed on that question — exhaustiveness, a
 * duplicated arm, a name no variant declares — said nothing at all about the whole match.
 * Ambiguity answers `""`: two enums declaring one variant name cannot happen in a file
 * (`spec/cases/0073`), but one of them may be imported, and then the payload under that name
 * belongs to neither. `spec/cases/0093`.
 */
string enumOfSubject(C c, string t, bool built) {
  string base = genericBase(t);
  string owner = base == "" ? t : base;
  if (c.isEnum(owner)) { return owner; }
  // **Only for a subject this file built itself.** `match (E.A(1))`'s type is the variant `A`, and
  // mapping it to `E` is the whole point of this function. But a *type name* that happens to match a
  // local variant is a different thing: `packages/git/src/repo.wac` declares `RepoAt.Opened` and
  // matches a value whose type is `pack.wac`'s `enum Opened`, which it never imported — so the name
  // resolved to `RepoAt`, and every arm of the real enum came back as "no variant of that name".
  // A name is only read as a variant when the expression in hand is a construction of one.
  if (!built) { return ""; }
  i32 owners = 0;
  string only = "";
  for (i32 i = 0; i < c.variantCount; i++) {
    if (c.variantNames[i] != owner) { continue; }
    owners = owners + 1;
    only = c.variantOwners[i];
  }
  return owners == 1 ? only : "";
}

void checkArmVariants(C c, Expr subject, Arm[] arms) {
  string t = typeOfExpr(c, subject);
  if (t == typeNone() || t == "") { return; }
  // **A nullable subject has no arm for the null.** Asked before the enum question, because
  // `Shape?` is not an enum name and the check below would bail out on it and say nothing.
  if (withoutNull(t) != "") {
    c.report(errMatchNullable(), subject.line, subject.col);
    return;
  }
  string owner = enumOfSubject(c, t, isVariantConstruction(c, subject));
  // **A subject that is not an enum at all**, which this returned for silently — so `match (someI32)`
  // compiled, along with every other non-enum subject: twelve of the thirteen types a grid tries.
  // The reference answers *"match requires an enum value, got i32"*.
  //
  // The silence was right for a subject this checker cannot *type* — an unknown answers nothing, and
  // that is still the branch above. What was wrong is treating "typed, and not an enum" as the same
  // case. A generic is exempt for the usual reason: its instantiation is not modelled here, so an
  // empty answer means unmodelled rather than absent.
  //
  // **Phrased as "is it one of these" rather than "is it not an enum"**, which is the same choice the
  // `is` rule explains a few hundred lines up, for the same reason and after the same mistake. The
  // negative form fires on any name this file cannot resolve — `JsonValue` imported from a file the
  // caller did not supply is not an enum *here* — and it turned fifteen of the repository's own
  // files red, `packages/json` and `packages/url` among them. The positive form only ever fires on a
  // type this checker can name, which is the direction to be wrong in.
  //
  // `c.isStruct` is true of a **variant**, which is a struct holding the payload — and
  // `packages/git/src/repo.wac` matches on another file's `Opened` while declaring a variant of its
  // own by that name, so the subject resolved to a struct and this reported a correct program. The
  // file is the one the paragraph below is already about, which is a fair warning that its shape is
  // the one to test any rule here against.
  bool notEnum = (isValueType(t) || t == "string" || isArrayName(t) || startsWithFn(t) ||
                  t == "anyref" || t == "i31ref" || c.isStruct(t)) &&
                 variantOwnerOf(c, t) == "";
  if (owner == "" && notEnum && !c.isGeneric(t) && !isVariantConstruction(c, subject)) {
    c.report(errMatchNotEnum(), subject.line, subject.col);
    return;
  }
  if (owner == "" || !c.isEnum(owner)) { return; }
  // **And the file has to be able to see what that enum holds.** `packages/git/src/repo.wac` matches
  // on `pack.wac`'s `enum Opened` while declaring a variant of its own called `Opened`, and imports
  // the *function* rather than the enum — so the name resolves to an enum whose variants are not in
  // this file's table at all. Every rule below counts them: an arm was "no variant of that name"
  // and the match "does not cover every variant", both about an enum nobody here can enumerate.
  // Nothing is knowable, which is the same answer an unknown subject gets. `spec/cases/0095`.
  i32 known = 0;
  for (i32 k = 0; k < c.variantCount; k++) {
    if (c.variantOwners[k] == owner) { known = known + 1; }
  }
  if (known == 0) { return; }
  // **Reported only for a name that is nobody's variant.** Belonging to *this* enum is the question
  // the reference answers, and answering it needs to know which file the subject's type came from —
  // the provenance this checker does not keep, and the reason `case Match:` in `packages/ssh` was
  // refused while being perfectly correct. A name no enum anywhere declares is wrong under every
  // reading, and that is the half worth reporting.
  for (i32 i = 0; i < arms.len(); i++) {
    if (arms[i].variantTok <= 0) { continue; }
    string vn = tokenText(c, arms[i].variantTok);
    bool anywhere = false;
    for (i32 k = 0; k < c.variantCount; k++) {
      if (c.variantNames[k] == vn) { anywhere = true; }
    }
    if (anywhere) { continue; }
    c.reportTok(errNoVariant(), arms[i].variantTok - 1, "");
  }

  // **The same variant twice.** One arm of the two can never run, and which one is not the point:
  // the second mention is the mistake, so that is where it is reported.
  string[] seen = string[arms.len()]();
  i32 seenCount = 0;
  for (i32 i = 0; i < arms.len(); i++) {
    if (arms[i].variantTok <= 0) { continue; }
    string vn = tokenText(c, arms[i].variantTok);
    bool dup = false;
    for (i32 k = 0; k < seenCount; k++) { if (seen[k] == vn) { dup = true; } }
    if (dup) {
      c.reportTok(errDuplicateCase(), arms[i].variantTok - 1, "");
    } else {
      seen[seenCount] = vn;
      seenCount = seenCount + 1;
    }
  }

  // **Every variant, or an `else`.** Counted against the variants this enum owns rather than against
  // every variant in the file, which is the question that needed provenance — and the comment above
  // said that provenance was missing. It is not any more: `variantOwners` records which enum each
  // variant belongs to, and an imported enum now enters under the importing file's name for it, so
  // two modules' same-named variants no longer answer for each other.
  i32 total = 0;
  i32 covered = 0;
  for (i32 k = 0; k < c.variantCount; k++) {
    if (c.variantOwners[k] != owner) { continue; }
    total = total + 1;
    for (i32 i = 0; i < seenCount; i++) {
      if (seen[i] == c.variantNames[k]) { covered = covered + 1; }
    }
  }
  // An enum whose variants this checker cannot see at all says nothing, by the same rule that keeps
  // it quiet about every other name it cannot resolve.
  if (total == 0) { return; }

  bool hasElse = false;
  for (i32 i = 0; i < arms.len(); i++) { if (arms[i].variantTok < 0) { hasElse = true; } }

  if (!hasElse && covered < total) {
    c.report(errMatchInexhaustive(), subject.line, subject.col);
  }
  // And the other way round: once every variant is named, an `else` is a branch nothing reaches.
  if (hasElse && covered == total) {
    c.report(errElseUnreachable(), subject.line, subject.col);
  }
}

/** Whether an unfiltered pass, or a filtered one that wants this name. */
bool wantedName(string[] only, string name) {
  if (only.len() == 0) { return true; }
  for (i32 i = 0; i < only.len(); i++) {
    if (only[i] == name) { return true; }
  }
  return false;
}

/**
 * Re-reads the type names written in declarations, now that every declaration is in.
 *
 * `declareModule` resolves a struct's field types while it is still declaring structs, so it cannot
 * be the pass that judges them — `struct Holder { Inner i; }` would be refused whenever `Inner` came
 * later in the file. Bodies need no such pass: they are walked after all of this, and every type they
 * mention goes through `typeOfTy` on the way.
 *
 * A declaration's own type parameters are in scope while its annotations are read, or `Box<T>`'s
 * `T value;` becomes a name nobody declared.
 */
void checkDeclaredTypeNames(C c, Program prog) {
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        setActiveParams(c, typeParams);
        // `struct R : Shape` with no `Shape` anywhere: a parent is a written type name like any
        // other, and every other position that takes one is already checked. Reported at the parent
        // itself, which is the only part of the declaration that is wrong. `spec/cases/0074`.
        if (parentTok >= 0 && !c.isStruct(tokenText(c, parentTok))) {
          c.reportTok(errUndefinedType(), parentTok, "");
        }
        for (i32 i = 0; i < fields.len(); i++) {
          // A packed type has no room for the absent case, in a field exactly as in a parameter or
          // a local — the rule was written for the two positions somebody happened to hit first.
          checkPackedNullable(c, typeOfTy(c, fields[i].type), fields[i].type);
        }
        for (i32 m = 0; m < methods.len(); m++) {
          typeOfTy(c, methods[m].returnType);
          for (i32 i = 0; i < methods[m].params.len(); i++) {
            typeOfTy(c, methods[m].params[i].type);
          }
        }
        c.activeParamCount = 0;
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        setActiveParams(c, typeParams);
        for (i32 v = 0; v < variants.len(); v++) {
          for (i32 i = 0; i < variants[v].fields.len(); i++) {
            checkPackedNullable(c, typeOfTy(c, variants[v].fields[i].type),
                                variants[v].fields[i].type);
          }
        }
        for (i32 m = 0; m < methods.len(); m++) {
          typeOfTy(c, methods[m].returnType);
          for (i32 i = 0; i < methods[m].params.len(); i++) {
            typeOfTy(c, methods[m].params[i].type);
          }
        }
        c.activeParamCount = 0;
      }
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        setActiveParams(c, typeParams);
        // A return type is the fourth position a type can be written in, and the packed rule is the
        // same in all of them — `spec/cases/0060`.
        checkPackedNullable(c, typeOfTy(c, returnType), returnType);
        // **At the declaration, not at the type.** The reference puts this one at column 1 — the
        // start of the whole declaration rather than the return type's own position, which is where
        // every other packed complaint sits. Read off it rather than made consistent, because a
        // diagnostic in a different place from the reference's is a rung-3 failure whichever of the
        // two reads better.
        checkPackedHere(c, typeOfTy(c, returnType), returnType.line, 1);
        for (i32 i = 0; i < params.len(); i++) { typeOfTy(c, params[i].type); }
        c.activeParamCount = 0;
      }
      case ConstDecl(nameTok, type, init, exported): { typeOfTy(c, type); }
      else: { }
    }
  }
}

/** The type parameters of the declaration being read, which are unknown types rather than names. */
void setActiveParams(C c, i32[] typeParams) {
  c.activeParamCount = 0;
  for (i32 i = 0; i < typeParams.len(); i++) {
    if (c.activeParamCount >= c.activeParams.len()) { continue; }
    c.activeParams[c.activeParamCount] = tokenText(c, typeParams[i]);
    c.activeParamCount = c.activeParamCount + 1;
  }
}

export void checkModule(C c, Program prog) {
  checkDuplicates(c, prog);
  checkDeclarationRules(c, prog);
  checkImportCollisions(c, prog);
  // Imported names, which this single-file slice cannot resolve but must not call undefined. What is
  // imported is in scope for the whole file, so these sit with the module-level constants.
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Import(pathTok, prefixTok, items): {
        // **`core` is the one specifier that is not a file**, so it is the one bare word allowed.
        // `spec/spec/imports.md`: a quoted `"core"` is an error, because a quoted specifier says *a
        // file lives at this path* and there is no path here to be right about — and *"so is any
        // other bare word, which reports `unknown module 'x'`"*.
        //
        // The parser records the word without checking it, and says so in a comment that gives the
        // reason as "matching the reference means a new error code". The spec asks for the check on
        // its own terms, so here it is.
        if (prefixTok >= 0 && tokenText(c, prefixTok) != "core") {
          c.reportTok(errUnknownModule(), prefixTok, "");
        }
        // Compared without its quotes rather than against a spelling with escaped ones: an escaped
        // quote inside a literal is a shape `wapy`'s rendering of this file cannot read back, and
        // this source round-trips through it on every suite run.
        string quoted = pathTok < 0 ? "" : tokenText(c, pathTok);
        if (quoted.len() >= 2 && quoted.slice(1, quoted.len() - 1) == "core") {
          c.reportTok(errUnknownModule(), pathTok, "");
        }
        // **What `core` exports, and the bar for adding to it.** `spec/spec/imports.md` sets it:
        // a type earns a place here only if a value of it has to cross a *repository* boundary
        // through a funcref signature, because wac has nominal types and no closures. `Read` passes
        // it; `Node` and `Attr` pass it more strongly, since the compiler emits their constructors
        // for JSX and no author picks the name to be able to fix a mismatch — `design/lang/0004`.
        //
        // A name it does not export is `no such export`, the same complaint a `./file.wac` import
        // gets, and it is checkable here because `core` ships inside the compiler rather than
        // living on disk. `spec/cases/0087`.
        if (prefixTok >= 0 && tokenText(c, prefixTok) == "core") {
          for (i32 i = 0; i < items.len(); i++) {
            string named = tokenText(c, items[i].nameTok);
            if (named == "Read" || named == "Node" || named == "Attr") { continue; }
            c.reportTok(errNoSuchExport(), items[i].nameTok, "");
          }
        }
        for (i32 i = 0; i < items.len(); i++) {
          // **Only when nothing better is known.** Declaring an imported name as unknown is what
          // makes a single-file check silent about it rather than calling it undefined — but when
          // the file's imports have actually been read, the name already has a struct, an enum or a
          // signature behind it, and a second declaration *poisons* it back to unknown. `Decoded d =
          // decode(raw);` came out a mismatch that way, with both names imported and both known.
          string alias = tokenText(c, items[i].aliasTok);
          if (c.isDeclaredName(alias) || c.isStruct(alias) || c.isEnum(alias)) { continue; }
          c.declare(alias, typeNone());
        }
        if (prefixTok >= 0 && !c.isDeclaredName(tokenText(c, prefixTok))) {
          c.declare(tokenText(c, prefixTok), typeNone());
        }
      }
      else: { }
    }
  }

  declareModule(c, prog, string[0]());

  // **Every declaration is in, so a name that resolves to nothing now resolves to nothing.** From
  // here a type name this file never brought into scope is an error rather than something unknown,
  // and the declarations written above are re-read under that rule: a struct's field type is
  // resolved during the pass that declares it, when half the file is still unseen.
  c.scopeTypes = true;
  checkDeclaredTypeNames(c, prog);

  // Methods, which until now were not walked at all: every rule here stopped at the edge of a
  // struct, so a method's returns, initialisers and operands went entirely unchecked. `this` is an
  // ordinary `Ident` whose text is `this`, so typing it is one entry in the scope — the struct's own
  // name — and every rule then reaches `this.x` through the field table that already existed.
  // A module-level constant's initialiser, *after* the signatures — the rule is "does this call a
  // function", so it needs to know which names are functions, and a constant may be initialised by
  // one declared further down the file. The first version of this ran before the signature pass and
  // silently found nothing, which looked exactly like the rule not working.
  // **A constant is computed in the order the file writes them**, so its initialiser may only read
  // one that already has a value. Reading itself is the same rule seen close up — `const i32 A = A +
  // 1` has nothing to read yet, and `A = B; B = A` has no order in which either could go first.
  // `spec/cases/0056` and `0057`.
  string[] settled = string[256]();
  i32 settledCount = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case ConstDecl(nameTok, type, init, exported): {
        // **The initialiser is an expression, and nothing was walking it.** Every rule in this file
        // about literals, elements, defaults and names applied to a local's initialiser and to none
        // of these — `const E[] T = E[3]()` was silent where the same line inside a function was
        // refused, and so was `i32[2](fill: "x")`. `spec/cases/0067` and `0068`.
        string constType = typeOfTy(c, type);
        // A constant is a value, and `void` is the absence of one. `spec/cases/0069`.
        if (constType == "void") { c.report(errVoidType(), type.line, type.col); }
        checkPackedNullable(c, constType, type);
        // A literal initialiser is asked whether it fits, exactly as a local's is — `const i32 A =
        // 1.5` is a float in an integer's slot. `spec/cases/0075`.
        if (litKindOf(init) != litNone() && constType != typeNone()) {
          reportLiteral(c, constType, init, errInitTypeMismatch(), init.line, init.col);
        }
        c.expected = constType;
        checkExpr(c, init);
        if (callsAFunction(c, init)) { c.report(errNotCompileTime(), init.line, init.col); }
        if (readsUnsettledConst(c, prog, init, settled, settledCount)) {
          c.report(errNotCompileTime(), init.line, init.col);
        }
        if (settledCount < settled.len()) {
          settled[settledCount] = tokenText(c, nameTok);
          settledCount = settledCount + 1;
        }
      }
      else: { }
    }
  }

  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        string owner = tokenText(c, nameTok);
        // `Box<T>`'s own parameters are in scope for its fields and for every method it declares —
        // `T v;` and `T get(const this)` are the template's, not names the file left undeclared.
        setActiveParams(c, typeParams);
        // A non-null field that reaches its own struct: `struct Node { Node next; }` cannot be built
        // at all, because building one needs one first. Reported at the field's type, which is the
        // only place it *can* be reported — a struct like this is refused on sight, with no
        // construction anywhere in the file to hang the complaint on.
        for (i32 fi = 0; fi < fields.len(); fi++) {
          string ft = typeOfTy(c, fields[fi].type);
          // The same two rules a parameter has, in the other declaration position that takes a type.
          if (isPackedName(ft)) {
            c.report(errPackedPosition(), fields[fi].type.line, fields[fi].type.col);
          }
          if (ft == "void") { c.report(errVoidType(), fields[fi].type.line, fields[fi].type.col); }
          if (isNullableName(ft) || isArrayName(ft) || !c.isStruct(ft)) { continue; }
          if (reachesStruct(c, ft, owner, 0)) {
            c.report(errRecursiveField(), fields[fi].type.line, fields[fi].type.col);
          }
        }
        string parent = c.parentOf(owner);
        for (i32 mi = 0; mi < methods.len(); mi++) {
          // `override` is a claim about a parent, and the language checks it both ways: a method that
          // hides one without saying so, and a method that says so with nothing to hide. The first is
          // reported at the return type — where a method's declaration starts, as with a missing
          // return — and the second at the keyword itself, which is the part that is wrong.
          bool hides = parent != "" && c.methodAt(parent, tokenText(c, methods[mi].nameTok)) >= 0;
          if (methods[mi].isOverride && !hides) {
            c.reportTok(errOverrideSpurious(), methods[mi].overrideTok, "");
          } else if (!methods[mi].isOverride && hides) {
            c.report(errOverrideMissing(), methods[mi].returnType.line, methods[mi].returnType.col);
          }
          c.clearScope();
          // **The function's own body is the outermost scope**, pushed before `this` and the
          // parameters so that they belong to it. `issues/lang/0122`.
          c.pushScope(methods[mi].body);
          // A method without `this` is static, and `this` means nothing in it.
          // A `const this` method may not write through the receiver, which is the same rule as a
          // `const P p` parameter and reuses it exactly.
          if (methods[mi].hasThis) {
            c.declareConst("this", owner, methods[mi].thisConst);
          }
          checkParams(c, methods[mi].params);
          for (i32 i = 0; i < methods[mi].params.len(); i++) {
            c.declareConst(tokenText(c, methods[mi].params[i].nameTok),
                           typeOfTy(c, methods[mi].params[i].type),
                           methods[mi].params[i].isConst);
          }
          declareAll(c, methods[mi].body);
          checkAll(c, methods[mi].body, methods[mi].returnType);
          c.popScope();
          // At the **return type**, where the reference puts it. A `Method` carries no position of
          // its own — unlike a `Decl`, which is why the top-level version reports at the declaration
          // — and the return type is the first thing a method has that does.
          if (returnsAValue(typeOfTy(c, methods[mi].returnType)) &&
              !alwaysLeaves(methods[mi].body)) {
            c.report(errMissingReturn(), methods[mi].returnType.line, methods[mi].returnType.col);
          }
        }
        c.activeParamCount = 0;
      }
      else: { }
    }
  }
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        // **A generic function's body is checked**, with its type parameters left unknown.
        //
        // It was skipped entirely once, because answering questions about `T` produced wrong answers.
        // But `spec/spec` says `T oops<T>(T a) { i32 x = "hello"; return a; }` is an error, and it is
        // — the mistake in it has nothing to do with `T`. Leaving the parameters unknown is what
        // separates the two: everything involving one is silent by the same rule that keeps this
        // checker quiet about anything it cannot name, and everything concrete is checked as usual.
        // Declarations first, in a pass of their own over the whole body, so a `return` that reads a
        // name declared later still resolves it. A checker that declared as it walked would treat a
        // forward reference as unknown for no reason — the reference has the whole function in hand
        // and so does this.
        c.activeParamCount = 0;
        for (i32 i = 0; i < typeParams.len(); i++) {
          if (c.activeParamCount >= c.activeParams.len()) { continue; }
          c.activeParams[c.activeParamCount] = tokenText(c, typeParams[i]);
          c.activeParamCount = c.activeParamCount + 1;
        }
        c.activeFunc = tokenText(c, nameTok);
        c.clearScope();
        c.pushScope(body);
        checkParams(c, params);
        for (i32 i = 0; i < params.len(); i++) {
          c.declareConst(tokenText(c, params[i].nameTok), typeOfTy(c, params[i].type),
                         params[i].isConst);
        }
        declareAll(c, body);
        checkAll(c, body, returnType);
        c.popScope();
        // Reported at the declaration rather than at the closing brace, which is where the reference
        // puts it: the fault is the function's, not any one statement's.
        //
        // The type parameters stay in scope for this last question: it reads the return type again,
        // and `T max<T>(T a, T b)` clearing them first made `T` a name nobody had declared.
        if (returnsAValue(typeOfTy(c, returnType)) && !alwaysLeaves(body)) {
          c.report(errMissingReturn(), prog.decls[d].line, prog.decls[d].col);
        }
        c.activeParamCount = 0;
      }
      else: { }
    }
  }
}
// What each error code says, in English.
//
// This is the first thing in the package to *consume* a code rather than count one, and writing it
// found two things immediately. The codes were not unique — four of them named two different errors
// each, which no position-comparing oracle could ever have noticed. And `report` carries a code and a
// position and nothing else, so none of these messages can say `expected i32, found f64`: the
// operands are not there to say it with. `spec/spec/errors.md` wants `annotation` and `hint` fields
// too, and those need a diagnostic that carries its operands, which is the next thing to build.
//
// So what follows is the rule that was broken, phrased as the reference phrases it where the spec
// quotes the wording, and plainly where it does not. It is deliberately the *rule* and never a guess
// at the values involved — a message that invents `expected i32` when it does not know is worse than
// one that omits it.

/**
 * The lex-phase codes — `err*` in `lex.wac`, and a third space again: 1–7, which is why the phase
 * column has to say which space a number came from.
 */
export string lexMessage(i32 code) {
  if (code == 1) { return "unexpected character"; }
  if (code == 2) { return "unterminated string"; }
  if (code == 3) { return "unknown escape"; }
  if (code == 4) { return "unterminated block comment"; }
  if (code == 5) { return "unterminated character literal"; }
  if (code == 6) { return "empty character literal"; }
  if (code == 7) { return "character literal holds more than one character"; }
  return "the lexer refused this";
}

/** The parse-phase codes, which are a separate space from the checker's — `perr*` in `parse.wac`. */
export string parseMessage(i32 code) {
  if (code == 20) { return "unexpected token"; }
  if (code == 21) { return "expected a type"; }
  if (code == 22) { return "expected an expression"; }
  if (code == 23) { return "this cannot be assigned to"; }
  if (code == 24) { return "this cannot appear at the top level of a file"; }
  if (code == 25) { return "expected a field name"; }
  if (code == 26) { return "expected a method name"; }
  if (code == 27) { return "expected a brace after the struct name"; }
  if (code == 28) { return "a function type cannot be used as an array element type"; }
  return "the parser refused this";
}

/** The check-phase codes — `err*` in `check.wac`. */
/**
 * What a warning says. Separate from `checkMessage` because the two are separate channels: a code
 * that is not an error must not be reachable by asking the error table for it.
 */
export string warnMessage(i32 code) {
  if (code == 200) { return "this is never null, so the test is always false"; }
  if (code == 201) { return "these types share no ancestor, so the test is always false"; }
  if (code == 202) { return "these types share no ancestor, so this cast always traps"; }
  return "";
}

export string checkMessage(i32 code) {
  if (code == 1) { return "return type does not match the function's"; }
  if (code == 2) { return "not every path returns a value"; }
  if (code == 3) { return "initialiser does not match the declared type"; }
  if (code == 4) { return "operands have mismatched types"; }
  if (code == 5) { return "argument does not match the parameter's type"; }
  if (code == 6) { return "condition must be bool"; }
  if (code == 7) { return "these types cannot be compared"; }
  if (code == 8) { return "field does not match the declared type"; }
  if (code == 9) { return "a nullable value cannot be assigned to a non-null type"; }
  if (code == 10) { return "cannot assign to const variable"; }
  if (code == 11) { return "cannot assign to a field of a const value"; }
  if (code == 12) { return "cannot write through const reference"; }
  if (code == 13) { return "no such static method"; }
  if (code == 14) { return "no such method"; }
  if (code == 15) { return "a non-const reference cannot be taken from a const one"; }
  if (code == 16) { return "wrong cast operator for these types"; }
  if (code == 17) { return "duplicate parameter name"; }
  if (code == 18) { return "array element does not match the element type"; }
  if (code == 19) { return "wrong number of arguments to a builtin"; }
  if (code == 20) { return "argument of the wrong type to a builtin"; }
  if (code == 21) { return "this method overrides one and does not say `override`"; }
  if (code == 22) { return "this method says `override` and overrides nothing"; }
  if (code == 23) { return "increment needs an integer"; }
  if (code == 24) { return "shift needs integer operands"; }
  if (code == 25) { return "wrong number of arguments to the constructor"; }
  if (code == 26) { return "a packed type cannot be used in this position"; }
  if (code == 27) { return "a string's characters cannot be written to"; }
  if (code == 28) { return "this type has no default value"; }
  if (code == 29) { return "a struct cannot hold a non-null field of its own type"; }
  if (code == 30) { return "this cast goes down the hierarchy and must be checked"; }
  if (code == 31) { return "there is no loop here to break out of or continue"; }
  if (code == 32) { return "wrong number of arguments"; }
  if (code == 33) { return "a packed type cannot be nullable"; }
  if (code == 34) { return "a module-level const must be computable at compile time"; }
  if (code == 35) { return "undefined name"; }
  if (code == 36) { return "void cannot be used as a type here"; }
  if (code == 37) { return "a return with a value in a void function, or without one where a value is wanted"; }
  if (code == 38) { return "this operator does not take an operand of that kind"; }
  if (code == 39) { return "no such field"; }
  if (code == 40) { return "a nullable value must be unwrapped before it is used"; }
  if (code == 41) { return "an index must be an integer"; }
  if (code == 42) { return "the two branches of a ternary have unrelated types"; }
  if (code == 43) { return "this operator needs a reference"; }
  if (code == 44) { return "a switch subject must be an integer or a string"; }
  // Both halves, because the code carries both: a name the struct does not have, and a field left
  // out. The headline said only the first, so a construction missing `y` was reported as though `y`
  // were misspelled — and a component, which is a named construction with a tag for a name, said it
  // about an attribute the reader had not written at all.
  if (code == 45) { return "a named construction names each field of the struct exactly once"; }
  if (code == 46) { return "this cast is between one type and itself"; }
  if (code == 47) { return "this is not something that can be called"; }
  if (code == 48) { return "a method is not a value; call it or take it as a funcref"; }
  if (code == 49) { return "a struct name is not a value"; }
  if (code == 50) { return "float literal out of range for its type"; }
  if (code == 51) { return "no variant of that name"; }
  if (code == 52) { return "unknown module"; }
  if (code == 53) { return "a generic that instantiates itself for ever"; }
  if (code == 54) { return "an enum method cannot be named after one of its variants"; }
  if (code == 55) { return "this name is already imported or declared in this file"; }
  if (code == 56) { return "that file does not export this name"; }
  if (code == 57) { return "undefined type"; }
  if (code == 58) { return "match does not cover every variant"; }
  if (code == 59) { return "duplicate case for the same variant"; }
  if (code == 60) { return "else arm is unreachable — all variants are covered"; }
  if (code == 61) { return "binding collides with the matched subject"; }
  if (code == 62) { return "match requires a non-null value"; }
  if (code == 63) { return "match arms have incompatible types"; }
  if (code == 64) { return "duplicate name at file scope"; }
  if (code == 65) { return "duplicate member in this struct"; }
  if (code == 66) { return "a character literal must hold exactly one character"; }
  if (code == 67) { return "a switch cannot have two defaults"; }
  if (code == 68) { return "this closing tag names a different element"; }
  if (code == 69) { return "this attribute is written twice"; }
  if (code == 70) { return "this tag names a struct that cannot render"; }
  if (code == 71) { return "which instantiation of this generic enum is not known here"; }
  if (code == 72) { return "match requires an enum value"; }
  if (code == 73) { return "nothing here wants a function, so this lambda has no type"; }
  if (code == 74) { return "this lambda's parameters do not match the function type wanted"; }
  return "this program was refused";
}

/**
 * The `= help:` line, where a rule has advice worth giving.
 *
 * Different in kind from the annotation: the annotation is data from the site — the values this
 * particular program used — and this is advice about the *rule*, which is the same every time it is
 * broken. So it lives here and needs nothing from the hundred-odd call sites, which is why it costs
 * a table rather than a sweep.
 *
 * Empty for most codes on purpose. A hint that restates the message is noise, and the reader has
 * already read the message.
 */
export string hintFor(i32 code) {
  if (code == 1) { return "use a cast if the conversion is meant: `as!` is checked, `as~` takes the nearest value"; }
  if (code == 2) { return "add a return at the end, or make every branch return"; }
  if (code == 3) { return "use `as!` for a checked conversion or `as~` for the nearest value"; }
  if (code == 6) { return "use a comparison, such as `x != 0`"; }
  if (code == 9) { return "unwrap it with `!` once you have checked it is not null"; }
  if (code == 10) { return "drop the `const`, or bind a separate local for the value that changes"; }
  if (code == 12) { return "take the parameter without `const` if it is meant to be written through"; }
  if (code == 16) { return "`as` converts without loss, `as!` checks at runtime, `as~` takes the nearest value"; }
  if (code == 30) { return "use `as!` — a cast down the hierarchy has to be checked"; }
  if (code == 33) { return "store the packed value in a wider type, or drop the `?`"; }
  if (code == 40) { return "unwrap it with `!`, or test it with `is null` first"; }
  if (code == 46) { return "the cast can be removed"; }
  if (code == 50) { return "use `f64` if the value does not fit an `f32`"; }
  if (code == 55) { return "rename one of them with `as`"; }
  if (code == 56) { return "import it from the file that declares it — importing does not re-export"; }
  if (code == 57) { return "import the type, or check the spelling"; }
  if (code == 58) { return "add the missing arms, or an `else`"; }
  if (code == 60) { return "remove the `else` — every variant is already covered"; }
  if (code == 62) { return "unwrap the subject with `!`, or test it with `is null` first"; }
  // Added where the help is real. A hint that only restates the message is worse than none: it
  // costs a line of everybody's terminal and teaches nothing, and the percentage it moves is a
  // measurement of itself.
  if (code == 4) { return "cast one side, or change what the other was declared as"; }
  if (code == 13) { return "a static is called on the type — check the spelling, or call it on a value"; }
  if (code == 15) { return "take a copy, or declare the destination `const` too"; }
  if (code == 19) { return "check the builtin's parameters — they are fixed"; }
  if (code == 20) { return "check the builtin's parameters — they are fixed"; }
  if (code == 24) { return "shift a whole number by a whole number"; }
  if (code == 32) { return "check the declaration for how many it takes"; }
  if (code == 34) { return "build it from literals, or move it into a function"; }
  if (code == 38) { return "check what the operand is — the operator wants another kind"; }
  if (code == 64) { return "rename one of them"; }
  if (code == 65) { return "rename one of them"; }
  // A second round, chosen the same way: each of these says something the message does not, and the
  // ones that would only have restated it were left alone. Counted over the spec's refused corpus
  // rather than guessed at — `waccx.test.ts` reports the percentage and holds a floor under it.
  if (code == 22) { return "check the parent declares it, with the same parameters"; }
  if (code == 26) { return "a packed type is an array's element type — a variable or parameter is `i32`"; }
  if (code == 28) { return "give one: `T[n](fill: v)` — a reference has no zero to start from"; }
  if (code == 29) { return "make the field nullable with `?` — a value of it has to end somewhere"; }
  if (code == 31) { return "a `break` inside a `switch` leaves the switch, and there is no loop here"; }
  if (code == 47) { return "only a function, a funcref or a method is callable"; }
  return "";
}

/**
 * Help for a *parse* diagnostic, where there is any.
 *
 * Only two of these have anything to say. "unexpected token" is the parser's way of saying it has
 * no idea, and a hint under it would be filler — which is why the numbers this moves are smaller
 * than the count of parse diagnostics suggests they could be.
 */
export string parseHintFor(i32 code) {
  if (code == 21) { return "a type is a name like `i32`, `string`, or one this file declares"; }
  if (code == 25) { return "a field is `type name;` — the name comes after the type"; }
  return "";
}
// Rung 4, first slice: a wasm module that runs.
//
// The ladder's oracle for this rung is deliberately *not* byte identity with the reference — see the
// README — but a canonical module form beside the one already sitting in this repository for nothing:
// **compile a program and run it**. That oracle needs something to run, and nothing here emitted a
// byte until now, so this is the walking skeleton: the binary scaffolding every later section needs,
// and just enough of the language to make a module that answers a question.
//
// What it covers: an exported function taking `i32` parameters and returning an `i32`, whose body is
// a single `return` of a literal, a parameter, or arithmetic over those. That is a fraction of the
// language and the point is not the fraction — it is that the shape is end to end, so the next rule
// added is measured by running it rather than by reading it.

import { lex, Lexed, tokenStride } from "./lex.wac";
import { floatLit, parseInt } from "./lit.wac";
import { P, parseProgram } from "./parse.wac";
import {
  Arm, JsxAttr, JsxSpan, jsxTrim, Decl, DeclKind, Expr, ExprKind, Lvalue, LvalueKind, Method, NamedArg,
  Param, Program, Stmt, StmtKind, Ty, TyKind,
} from "./ast.wac";
import {
  kPlus, kMinus, kStar, kSlash, kPercent, kAnd, kOr, kCaret, kShl, kShr, kShrU,
  kEq, kNe, kLt, kLe, kGt, kGe, kAndAnd, kOrOr, kBang, kTilde, kAssign, kInc,
  kPlusEq, kMinusEq, kStarEq, kSlashEq, kPercentEq, kAndEq, kOrEq, kCaretEq,
  kShlEq, kShrEq, kShrUEq, kString, kAsAt, kAsBang, kAsTilde,
} from "./kinds.wac";

/**
 * A growable byte buffer.
 *
 * wac has no growable array, so this is the same doubling `Buf` every package here ends up writing —
 * kept local rather than imported because `packages/wacc` has no dependencies and the whole value of
 * a self-hosting compiler is that it needs none.
 */
export struct B {
  u8[] data;
  i32 len;

  B create() { return B(u8[64](), 0); }

  void byte(this, i32 v) {
    if (this.len >= this.data.len()) {
      u8[] bigger = u8[this.data.len() * 2]();
      for (i32 i = 0; i < this.len; i++) { bigger[i] = this.data[i]; }
      this.data = bigger;
    }
    this.data[this.len] = v;
    this.len = this.len + 1;
  }

  /** Every byte of another buffer, which is how a section is spliced in once its length is known. */
  void bytes(this, B other) {
    for (i32 i = 0; i < other.len; i++) { this.byte(other.data[i]); }
  }

  /**
   * LEB128, unsigned. Seven bits at a time, low group first, the top bit saying "more follows".
   *
   * The encoding is not canonical — `0` may be written as one byte or five — which is exactly why
   * rung 4 does not compare bytes: two implementations may both be right and differ. This writes the
   * short form, being the one everything else writes.
   */
  void u32leb(this, i32 v) {
    i32 rest = v;
    for (i32 guard = 0; guard < 5; guard++) {
      i32 low = rest & 127;
      rest = (rest as@ u32 >> 7) as@ i32;
      if (rest == 0) {
        this.byte(low);
        return;
      }
      this.byte(low | 128);
    }
  }

  /** The same for an `i64`, which a wide constant needs and which cannot go through the 32-bit one. */
  void i64leb(this, i64 v) {
    i64 rest = v;
    for (i32 guard = 0; guard < 10; guard++) {
      i32 low = (rest & 127) as~ i32;
      rest = rest >> 7;
      bool signBit = (low & 64) != 0;
      if ((rest == 0 && !signBit) || (rest == -1 && signBit)) {
        this.byte(low);
        return;
      }
      this.byte(low | 128);
    }
  }

  /** LEB128, signed: the same, but the sign bit of the last group has to be the value's own. */
  void i32leb(this, i32 v) {
    i32 rest = v;
    for (i32 guard = 0; guard < 5; guard++) {
      i32 low = rest & 127;
      rest = rest >> 7;
      bool signBit = (low & 64) != 0;
      if ((rest == 0 && !signBit) || (rest == -1 && signBit)) {
        this.byte(low);
        return;
      }
      this.byte(low | 128);
    }
  }

  /** An `f32` constant: four raw little-endian bytes, not a LEB — floats are not varints. */
  void f32bits(this, f32 v) {
    u32 bits = f32.toBits(v);
    u32 sh = 0;
    while (sh < 32) {
      this.byte((bits >> sh & 255) as~ i32);
      sh = sh + 8;
    }
  }

  /**
   * An `f64` constant: eight raw little-endian bytes.
   *
   * The shift amount is a `u64` too. Shifting a `u64` by an `i32` came out as `ff ff ff ff` in the
   * low half — every constant wrong by exactly one part in 2^20, which reads as a rounding error and
   * is not one. Keeping both sides the same width is the fix and the lesson.
   */
  void f64bits(this, f64 v) {
    u64 bits = f64.toBits(v);
    u64 sh = 0;
    while (sh < 64) {
      this.byte((bits >> sh & 255) as~ i32);
      sh = sh + 8;
    }
  }

  /** A name, length-prefixed, which is how wasm writes every string in the binary. */
  void name(this, string s) {
    u8[] b = s.toBytes();
    this.u32leb(b.len());
    for (i32 i = 0; i < b.len(); i++) { this.byte(b[i]); }
  }
}

/**
 * A wac type's wasm value type.
 *
 * Four of them, and the mapping is many-to-one: `u32` and `bool` are `i32` in wasm, `u64` is `i64`.
 * That is exactly why the opcodes cannot be chosen from the value type — `i32.div_s` and `i32.div_u`
 * are both operations on an `i32`, and which one is right is a fact about the *wac* type that the
 * wasm type has already thrown away.
 */
i32 valType(string t) {
  // **`anyref` is the top of the reference hierarchy and `i31ref` a 31-bit integer inside a
  // reference** — no allocation, which is how an unboxed number and a heap object share a container.
  // Both are one byte, like the numeric types and unlike every other reference here, because neither
  // names a type in the type section.
  if (t == "anyref") { return 110; }
  if (t == "i31ref") { return 108; }
  if (t == "i64" || t == "u64") { return 126; }
  if (t == "f32") { return 125; }
  if (t == "f64") { return 124; }
  return 127;
}

/** Whether a wac type is an array, which is a *reference* and so two bytes rather than one. */
bool isArrayType(string t) {
  u8[] a = t.toBytes();
  if (a.len() < 3) { return false; }
  return a[a.len() - 2] == 91 && a[a.len() - 1] == 93;
}

/** A wac type's element, for an array. */
string elemOf(string t) {
  u8[] a = t.toBytes();
  u8[] out = u8[a.len() - 2]();
  for (i32 i = 0; i < out.len(); i++) { out[i] = a[i]; }
  return string.fromBytes(out);
}

/**
 * A value type, written rather than returned.
 *
 * An array is `0x64 <typeidx>` — a non-null reference to a declared type — so a value type is not one
 * byte and cannot be. Every place that wrote `types.byte(valType(t))` had to become a call here,
 * which is the shape a GC type forces on an emitter that started with scalars.
 */
/**
 * How a wac type is **represented**, which is not the same as what it is.
 *
 * A `string` is stored as an `i8[]` — the reference's type section says so and a literal is
 * `array.new_fixed` over the bytes — but it is *not* an `i8[]` to the language: `s[i]` on a string
 * gives a one-character string where `b[i]` on a `u8[]` gives an `i32`. Normalising the two into one
 * type erased that and emitted `array.get_s` for a string index, which returns the wrong kind of
 * thing entirely. The representation is shared; the type is not.
 */
string repType(string t) { return t == "string" ? "i8[]" : t; }

void writeValType(B out, Env env, string t) {
  // **The heap type after `0x63` is signed.** A reference type is `0x63` followed by an *s33* — the
  // encoding that lets a negative value mean `func`, `extern`, `eq` and the rest, and a non-negative
  // one mean a type index. Written as an unsigned LEB it is identical for the first sixty-four
  // indices and wrong for every one after, because 64 sets the sign bit of a one-byte LEB: index 65
  // came back as heap type **-63**. Nothing here had sixty-four types until linking, so this was
  // right for as long as a module was one file.
  if (t == "string") {
    out.byte(99);
    out.i32leb(env.arrayType("i8[]"));
    return;
  }
  // **Nullable** references, `0x63`, not the non-null `0x64`. A non-null reference has no default
  // value, so an array of them cannot be created with `array.new_default` — *"array type 1 has
  // non-defaultable element"* — and wac arrays are created that way constantly. The reference's own
  // locals are nullable too, which is the measurement that settled it.
  if (isArrayType(t)) {
    out.byte(99);
    out.i32leb(env.arrayType(t));
    return;
  }
  if (env.isStructName(t)) {
    out.byte(99);
    out.i32leb(env.structType(t));
    return;
  }
  // **A `fn[…]` value is a pair, not a bare funcref** — `design/lang/0002`. `{funcref, env}`, so a
  // bound reference can carry its receiver and still be the same type as every other `fn[]`.
  if (isFuncrefType(t)) {
    out.byte(99);
    out.i32leb(env.pairType(t));
    return;
  }
  out.byte(valType(t));
}

/**
 * The result type of a static on a *primitive* — `f64.toBits(x)` and its three siblings — or `""`.
 *
 * These are not methods on a value and not calls to anything declared: the receiver is a type name,
 * and each is one reinterpret instruction. They are the only reason 37 corpus files stop where they
 * do, which is what makes four instructions worth a table.
 */
string primStaticType(string owner, string name) {
  if (owner == "f32" && name == "toBits") { return "u32"; }
  if (owner == "f64" && name == "toBits") { return "u64"; }
  if (owner == "f32" && name == "fromBits") { return "f32"; }
  if (owner == "f64" && name == "fromBits") { return "f64"; }
  return "";
}

/** What such a static takes, so a literal argument arrives at the right width. */
string primStaticArg(string owner, string name) {
  if (owner == "f32" && name == "toBits") { return "f32"; }
  if (owner == "f64" && name == "toBits") { return "f64"; }
  if (owner == "f32" && name == "fromBits") { return "u32"; }
  if (owner == "f64" && name == "fromBits") { return "u64"; }
  return "";
}

/** The type name a bare identifier spells, when it is a primitive rather than a value. */
string primTypeName(Env env, u8[] src, Lexed lexed, Expr obj) {
  match (obj.kind) {
    case Ident(tok): {
      string n = tokenTextOf(src, lexed, tok);
      if (env.localAt(n) >= 0) { return ""; }
      if (n == "f32" || n == "f64" || n == "i32" || n == "i64" || n == "u32" || n == "u64") {
        return n;
      }
      return "";
    }
    else: { return ""; }
  }
}

/** The key a name token means — its own file's declaration, or whichever file has one. */
string nameKeyOf(Env env, u8[] src, Lexed lexed, i32 tok) {
  return env.keyAt(tokenTextOf(src, lexed, tok), tokenLine(lexed, tok));
}

/** A non-negative number as text, for building a key no source can spell — and for a diagnostic. */
export string numText(i32 n) {
  if (n == 0) { return "0"; }
  string out = "";
  i32 v = n;
  for (i32 guard = 0; guard < 12; guard++) {
    if (v == 0) { return out; }
    i32 d = v % 10;
    out = string.fromCodepoint(48 + d) + out;
    v = v / 10;
  }
  return out;
}

/** The line a token is on, which is what says which linked file it came from. */
i32 tokenLine(Lexed lexed, i32 t) {
  if (t < 0) { return 1; }
  return lexed.tokens[t * tokenStride() + 3];
}

/** The column a token starts at, which a coverage point needs to name a `case` arm. */
i32 tokenCol(Lexed lexed, i32 t) {
  if (t < 0) { return 1; }
  return lexed.tokens[t * tokenStride() + 4];
}

/** The storage type inside an array type, where a packed element is narrower than a value type. */
i32 storageType(string elem) {
  if (elem == "i8" || elem == "u8") { return 120; }
  if (elem == "i16" || elem == "u16") { return 119; }
  return valType(elem);
}

/** Whether a wac type is one of the unsigned integers, which decides `_s` from `_u`. */
/**
 * Register a type that a declaration *names*, whichever kind it is.
 *
 * The array pre-pass has been found one declaration short four times, and each time the rule was the
 * same — *every place a type can be named* — so signatures join it here rather than in a fifth list
 * of the same places.
 */
void registerNamed(Env env, string t) {
  if (isArrayType(t)) { env.arrayType(t); }
  if (isFuncrefType(t)) { env.sigType(t); }
}

/**
 * The signature a function is **emitted** with, which is not quite the one it is declared with: a
 * method's receiver is its first wasm parameter, and `void` is no result rather than one.
 *
 * Every function's wasm type is now this signature's entry in the shared table, rather than one type
 * per function. That is what makes `ref.func f` storable in a `fn[...]` local: wasm compares two
 * type *indices* in one rec group by position, not by shape, so a function whose type is a private
 * copy of the right shape is not the right type.
 */
string emittedSig(Env env, u8[] src, Lexed lexed, Ty returnType, Param[] params, string receiver) {
  return emittedSigOf(env, src, lexed, typeOfTyName(env, src, lexed, returnType), params, receiver);
}

/**
 * The same, for a function whose return type is a **name** rather than a written `Ty`.
 *
 * A lambda writes no return type — `design/lang/0002` takes it from the `fn[…]` the lambda is used
 * as — and every `Ty` carries a token, so one cannot be synthesised from a type name. The checker
 * needed the same seam and grew `c.lambdaReturn` for it.
 */
string emittedSigOf(Env env, u8[] src, Lexed lexed, string ret, Param[] params, string receiver) {
  string out = "fn[" + ret + "(";
  if (receiver != "") { out = out + receiver; }
  for (i32 i = 0; i < params.len(); i++) {
    if (i > 0 || receiver != "") { out = out + ","; }
    out = out + typeOfTyName(env, src, lexed, params[i].type);
  }
  return out + ")]";
}

/** The signature a registered function has, spelled the way a `fn[...]` type is. */
/** The type a literal is when nothing else says — the default of its family, or `""`. */
string naturalLiteralType(Expr e) {
  match (e.kind) {
    case IntLit(tok): { return "i32"; }
    case FloatLit(tok): { return "f64"; }
    case Jsx(tagTok, closeTok, attrs, kids): { return "Node"; }
    case JsxText(startOff, endOff): { return "Node"; }
    case StrLit(tok): { return "string"; }
    case BoolLit(value): { return "bool"; }
    // A `null` says nothing about what it is a null *of*, so a type parameter it is the only
    // evidence for cannot be inferred at all.
    else: { return ""; }
  }
}

/**
 * Bind a generic function's type parameters by **matching its declared types against the actual ones**.
 *
 * `mapOption<T, U>(Option<T> o, fn[U(T)] f)` called with an `Option<i32>` and an `fn[string(i32)]`
 * binds `T` from the first argument and `U` from the *return type of the second* — which is the half
 * of it a method could not have expressed, and the reason this is a function in the first place.
 *
 * The match is structural and one-sided: the declaration is the pattern, the argument's type is the
 * subject, and a parameter that appears twice has to be given the same answer both times.
 */
bool bindTypeParams(Env env, u8[] src, Lexed lexed, Ty t, string actual, i32[] tps, string[] out) {
  match (t.kind) {
    case Prim(tok): { return true; }
    case Arr(elem): {
      if (!isArrayType(actual)) { return false; }
      return bindTypeParams(env, src, lexed, elem, elemOf(actual), tps, out);
    }
    case Nullable(inner): { return bindTypeParams(env, src, lexed, inner, actual, tps, out); }
    case Funcref(ret, params): {
      if (!isFuncrefType(actual)) { return false; }
      if (sigParamCount(actual) != params.len()) { return false; }
      if (!bindTypeParams(env, src, lexed, ret, sigReturn(actual), tps, out)) { return false; }
      for (i32 i = 0; i < params.len(); i++) {
        if (!bindTypeParams(env, src, lexed, params[i], sigParamAt(actual, i), tps, out)) {
          return false;
        }
      }
      return true;
    }
    case Named(tok, typeArgs): {
      string nm = tokenTextOf(src, lexed, tok);
      for (i32 i = 0; i < tps.len(); i++) {
        if (tokenTextOf(src, lexed, tps[i]) != nm) { continue; }
        if (actual == "") { return false; }
        // Seen before: the two uses have to agree, or this is not the instance being called.
        if (out[i] != "" && out[i] != actual) { return false; }
        out[i] = actual;
        return true;
      }
      if (typeArgs.len() == 0) { return true; }
      if (!isInstance(actual) || templateOf(actual) != nm) { return false; }
      for (i32 i = 0; i < typeArgs.len(); i++) {
        if (!bindTypeParams(env, src, lexed, typeArgs[i], typeArgAt(actual, i), tps, out)) {
          return false;
        }
      }
      return true;
    }
  }
}

/**
 * The instance a call to a generic function names — `mapOption<i32,string>` — or `""`.
 *
 * Spelled the same way a generic type's instance is, because it is the same thing: a name plus its
 * arguments, registered on sight and compiled once. The difference is only where the arguments come
 * from, and this is the function that answers that.
 */
string genericCallInstance(Env env, u8[] src, Lexed lexed, i32 tok, Expr[] args) {
  if (env.prog is null) { return ""; }
  string raw = tokenTextOf(src, lexed, tok);
  Program pg = env.prog!;
  for (i32 d = 0; d < pg.decls.len(); d++) {
    match (pg.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() == 0) { continue; }
        if (tokenTextOf(src, lexed, nameTok) != raw) { continue; }
        if (params.len() != args.len()) { return ""; }
        string[] bound = string[typeParams.len()]();
        for (i32 i = 0; i < args.len(); i++) {
          string at = typeOfE(src, lexed, env, args[i]);
          // **A literal has no type of its own and here there is no slot to take one from**: the
          // parameter is `T`, so what `T` is *is* the question the literal has to answer. Its natural
          // type is the answer — `ident(7)` is `ident<i32>` — which is the one place in this emitter
          // a literal's type comes from the literal.
          if (at == "") { at = naturalLiteralType(args[i]); }
          if (!bindTypeParams(env, src, lexed, params[i].type, at, typeParams, bound)) { return ""; }
        }
        string inst = raw + "<";
        for (i32 i = 0; i < bound.len(); i++) {
          // A parameter no argument mentions cannot be inferred, and guessing would compile a
          // different function from the one that was called.
          if (bound[i] == "") { return ""; }
          if (i > 0) { inst = inst + ","; }
          inst = inst + bound[i];
        }
        inst = inst + ">";
        // **Noted on sight, registered in order.** Which instances exist is discovered here, by
        // whichever walk reaches the call first; *registering* one — giving it an entry in the
        // function table — happens in `collectInstances`, which walks the instances in the order
        // they were discovered. The two have to be the same order, because the function table's
        // order is the module's numbering and the emission passes iterate the instance list. Doing
        // the registration here instead put a generic function's entry ahead of the methods of an
        // instance discovered before it, and every call after that point reached the wrong index.
        env.instantiate(inst, raw);
        return inst;
      }
      else: { }
    }
  }
  return "";
}

/**
 * The function slot `Owner.name` names when it is used as a *value*, or -1.
 *
 * Only a name that resolves to a **type** can be one: `c.inc` is a method already bound to an
 * object, which is exactly what has no representation here, and asking for it is the error the tour
 * points at rather than a thing to emit.
 */
i32 methodRefAt(u8[] src, Lexed lexed, Env env, Expr obj, i32 nameTok) {
  string own = staticOwner(src, lexed, env, obj);
  if (own == "") { return -1; }
  return env.funcAt(own + "." + tokenTextOf(src, lexed, nameTok));
}

string signatureOf(Env env, i32 at) {
  string out = "fn[" + env.funcReturns[at] + "(";
  // **The receiver is a parameter of the function that was emitted**, so a reference to a method has
  // it first and a call through that reference passes the object where `this` was.
  string recv = env.funcRecv[at];
  if (recv != "") { out = out + recv; }
  for (i32 i = 0; i < env.funcParamCount[at]; i++) {
    if (i > 0 || recv != "") { out = out + ","; }
    out = out + env.paramTypeAt(at, i);
  }
  return out + ")]";
}

/**
 * The same signature **without** the receiver — what a bound reference `c.inc` denotes.
 *
 * `design/lang/0002` tier one. `signatureOf` puts the receiver first because that is where a method's
 * `this` is emitted; a bound reference has it in the pair's env instead, so the value's type is the
 * declared parameters and nothing else. The two differ in arity, which is why a bound reference could
 * not be a bare `ref.func` and the pair representation had to land first.
 */
string boundSignatureOf(Env env, i32 at) {
  string out = "fn[" + env.funcReturns[at] + "(";
  for (i32 i = 0; i < env.funcParamCount[at]; i++) {
    if (i > 0) { out = out + ","; }
    out = out + env.paramTypeAt(at, i);
  }
  return out + ")]";
}

/**
 * `c.inc` — the function a bound reference names, or -1.
 *
 * A *value* receiver, unlike `methodRefAt`'s type-name receiver: the owner is the object's type. A
 * static reached this way is deliberately not one — `c.make` names a function that has nothing to do
 * with `c`, and the checker refuses it.
 */
i32 boundRefAt(u8[] src, Lexed lexed, Env env, string owner, i32 nameTok) {
  if (owner == "" || !env.isStructName(owner)) { return -1; }
  string name = tokenTextOf(src, lexed, nameTok);
  // **Up the chain, because a method is inherited and the checker knows it.** `c.twice` on a `Kid`
  // whose `Base` declares `twice` is an ordinary bound reference; looking only at the object's own
  // type left the checker accepting what the emitter could not type, which is a *blocked module* —
  // loud rather than wrong, and still a hole. The bound wrapper needs no help: it casts the env to
  // the declaring type, and a `Kid` is one.
  string at2 = env.canonType(owner);
  for (i32 guard = 0; guard < 32 && at2 != ""; guard++) {
    i32 at = env.funcAt(at2 + "." + name);
    if (at >= 0) { return env.funcRecv[at] == "" ? -1 : at; }
    at2 = env.parentOf(at2);
  }
  return -1;
}

/** The `i`th type argument in `Vec<i32>` or `Map<string,Vec<i32>>` — by depth, since they nest. */
string typeArgAt(string inst, i32 want) {
  i32 depth = 0;
  i32 from = -1;
  i32 n = 0;
  for (i32 i = 0; i < inst.len(); i++) {
    string c = inst[i];
    if (c == "<") {
      depth = depth + 1;
      if (depth == 1) { from = i + 1; }
      continue;
    }
    // This one already opened the angle bracket above, so it counts only the square ones.
    if (c == "[") { depth = depth + 1; }
    if (c == "]") { depth = depth - 1; }
    if (c == ">") {
      depth = depth - 1;
      if (depth == 0) { return n == want ? inst.slice(from, i) : ""; }
    }
    if (c == "," && depth == 1) {
      if (n == want) { return inst.slice(from, i); }
      n = n + 1;
      from = i + 1;
    }
  }
  return "";
}

/** Whether a name is an instantiation rather than a plain type. */
bool isInstance(string t) {
  return t.indexOf("<") > 0;
}

/** The template an instantiation is of: `Vec` from `Vec<i32>`. */
string templateOf(string inst) {
  i32 at = inst.indexOf("<");
  return at < 0 ? "" : inst.slice(0, at);
}

/**
 * The owner a static call means when it is written on a **template**: `Vec.create()`.
 *
 * The instantiation is not in the call — it is in the slot the answer goes into, which is the
 * language's own spelling: `Vec<i32> w = Vec.create();`. So this takes the wanted type, and
 * `typeOfE`, which has no slot to consult, cannot answer this shape at all.
 */
string templateStatic(Env env, u8[] src, Lexed lexed, Expr obj, string want) {
  if (!isInstance(want)) { return ""; }
  match (obj.kind) {
    case Ident(tok): {
      return tokenTextOf(src, lexed, tok) == templateOf(want) ? want : "";
    }
    else: { return ""; }
  }
}

/**
 * Bring a template's parameters into scope as its arguments, and say how many were pushed.
 *
 * The caller pops exactly that many, which is the whole protocol: a template's members are
 * registered and emitted with this in force, and nothing else about them changes.
 */
i32 pushSubstitution(Env env, u8[] src, Lexed lexed, i32[] typeParams, string inst, string of) {
  for (i32 i = 0; i < typeParams.len(); i++) {
    if (env.subCount >= env.subFrom.len()) { return i; }
    env.subFrom[env.subCount] = tokenTextOf(src, lexed, typeParams[i]);
    env.subTo[env.subCount] = typeArgAt(inst, i);
    env.subCount = env.subCount + 1;
  }
  env.curInst = inst;
  env.curGeneric = of;
  return typeParams.len();
}

void popSubstitution(Env env, i32 n) {
  env.subCount = env.subCount - n;
  env.curInst = "";
  env.curGeneric = "";
}

/**
 * Whether a type as *written* admits null — which its name cannot say.
 *
 * `T?` and `T` are one wasm type here, deliberately: every reference this emitter writes is
 * nullable, so the difference is the checker's to keep. It matters in exactly one place, and this
 * is why the flag exists rather than a spelling: the **default** of a `P?` is null, and the default
 * of a `P` is a defaulted `P`.
 */
bool isNullableTy(Ty t) {
  match (t.kind) {
    case Nullable(inner): { return true; }
    else: { return false; }
  }
}

/** Whether a type is a function reference, which is decided by its spelling. */
bool isFuncrefType(string t) {
  // **An array of funcrefs is an array.** `fn[void(i32)][]` starts with `fn[` as well, so a test that
  // asked only that answered yes to both this and `isArrayType`, and which one a caller consulted
  // first decided what the type was. `writeValType` asks about arrays first and was right by luck;
  // the callback-signature table asks this one and was not — it recorded the *array* as a callback
  // signature, so the module declared `$bind$fnref_j` as `fn[fn[void(i32)][](i32)]` and built a pair
  // struct in its body. wasm rejects that as a return-type mismatch, which made every module that
  // stores continuations in an array invalid — a handler table being exactly that.
  return t.len() > 3 && t.slice(0, 3) == "fn[" && !isArrayType(t);
}

/**
 * The return type inside `fn[R(A,B)]`, and the `i`th parameter — by scanning rather than splitting.
 *
 * A signature nests: `fn[i32[](fn[i32(i32)])]` has brackets and parentheses inside both halves, so
 * the split has to count depth. Getting this wrong is a type index that does not exist rather than a
 * wrong answer, but it is the kind of wrong that surfaces four functions away.
 */
/**
 * The funcref type that lives inside a `fn[…]` pair: the same signature with an `anyref` env in front.
 *
 * `design/lang/0002`. A `fn[…]` value is `{funcref, env}`, and the funcref has to accept the env
 * whatever it came from — a plain function's wrapper ignores it, a bound method's casts it to the
 * receiver. One shape for both is what keeps a bound reference interchangeable with every `fn[]`
 * that already exists.
 *
 * Built as a *string* and allocated through the ordinary `sigType`, deliberately: a function's own
 * wasm type comes from the same table via `emittedSig`, so prepending an env there would retype the
 * whole module rather than its function values.
 */
string envSig(string t) {
  string out = "fn[" + sigReturn(t) + "(anyref";
  for (i32 i = 0; i < sigParamCount(t); i++) {
    out = out + "," + sigParamAt(t, i);
  }
  return out + ")]";
}

/**
 * The marker that makes a signature-table entry a **pair struct** rather than a function type.
 *
 * The pair shares that table because the table is allocated lazily during emission and is therefore
 * last — nothing may be appended after it, since an index emitted early would move when it grew.
 * Sharing it keeps the two types a `fn[]` needs allocated together and the index arithmetic
 * untouched. `design/lang/0002` records why this is not a fourth category.
 */
string pairMark() { return "pair:"; }

/** Whether a signature-table entry is a pair struct. */
bool isPairEntry(string t) { return t.len() > 5 && t.slice(0, 5) == pairMark(); }

/** The `fn[…]` a pair entry is the pair for. */
string pairInner(string t) { return t.slice(pairMark().len(), t.len()); }

string sigReturn(string t) {
  i32 depth = 0;
  for (i32 i = 3; i < t.len(); i++) {
    string c = t[i];
    // **`<` nests too.** An instantiation is spelled `Result<i32,string>`, so a signature that
    // mentions one has a comma *inside* a parameter — and a scanner that counts only brackets and
    // parentheses reads `fn[bool(Result<i32,string>)]` as taking two. The function then declares one
    // parameter and its type says two, which wasm reports as a `struct.get` on a number, in a
    // method several functions away. This is what made two type parameters fail and one work.
    if (c == "[" || c == "<") { depth = depth + 1; }
    if (c == "]" || c == ">") { depth = depth - 1; }
    if (c == "(" && depth == 0) { return t.slice(3, i); }
  }
  return "";
}

/** How many parameters a signature has, and the `i`th of them. */
i32 sigParamCount(string t) {
  i32 depth = 0;
  i32 start = -1;
  i32 n = 0;
  bool any = false;
  for (i32 i = 3; i < t.len(); i++) {
    string c = t[i];
    // **`<` nests too.** An instantiation is spelled `Result<i32,string>`, so a signature that
    // mentions one has a comma *inside* a parameter — and a scanner that counts only brackets and
    // parentheses reads `fn[bool(Result<i32,string>)]` as taking two. The function then declares one
    // parameter and its type says two, which wasm reports as a `struct.get` on a number, in a
    // method several functions away. This is what made two type parameters fail and one work.
    if (c == "[" || c == "<") { depth = depth + 1; }
    if (c == "]" || c == ">") { depth = depth - 1; }
    if (c == "(" && depth == 0 && start < 0) {
      start = i;
      depth = depth + 1;
      continue;
    }
    if (start < 0) { continue; }
    if (c == "(") { depth = depth + 1; }
    if (c == ")") {
      depth = depth - 1;
      if (depth == 0) { return any ? n + 1 : 0; }
    }
    if (c == "," && depth == 1) { n = n + 1; }
    if (c != " ") { any = true; }
  }
  return 0;
}

string sigParamAt(string t, i32 want) {
  i32 depth = 0;
  i32 from = -1;
  i32 n = 0;
  for (i32 i = 3; i < t.len(); i++) {
    string c = t[i];
    // **`<` nests too.** An instantiation is spelled `Result<i32,string>`, so a signature that
    // mentions one has a comma *inside* a parameter — and a scanner that counts only brackets and
    // parentheses reads `fn[bool(Result<i32,string>)]` as taking two. The function then declares one
    // parameter and its type says two, which wasm reports as a `struct.get` on a number, in a
    // method several functions away. This is what made two type parameters fail and one work.
    if (c == "[" || c == "<") { depth = depth + 1; }
    if (c == "]" || c == ">") { depth = depth - 1; }
    if (c == "(" && depth == 0 && from < 0) {
      from = i + 1;
      depth = depth + 1;
      continue;
    }
    if (from < 0) { continue; }
    if (c == "(") { depth = depth + 1; }
    if (c == ")") {
      depth = depth - 1;
      if (depth == 0) {
        return n == want ? t.slice(from, i) : "";
      }
    }
    if (c == "," && depth == 1) {
      if (n == want) { return t.slice(from, i); }
      n = n + 1;
      from = i + 1;
    }
  }
  return "";
}

bool isUnsigned(string t) { return t == "u32" || t == "u64"; }

/** Whether a wac type is a float, which decides a whole family of opcodes rather than a suffix. */
bool isFloat(string t) { return t == "f32" || t == "f64"; }

/** `0x7f`, the value type of everything this emitter cannot type. */
i32 wasmI32() { return 127; }

/**
 * A section: its id, then its byte length, then its contents.
 *
 * The length has to be known before the contents are written, which is why a section is built in a
 * buffer of its own and spliced in — the same shape the reference uses and the reason a wasm emitter
 * is a tree of buffers rather than one.
 */
/**
 * Export a function, and remember what it is called.
 *
 * The two belong together: a helper the module exports is a frame a trap can happen in, and the
 * `name` section is built from this table. Exporting without recording is how every helper came out
 * as `wasm-function[147]` [issue 0101].
 */
void exportFunc(B exports, string[] fnName, string nm, i32 idx) {
  exports.name(nm);
  exports.byte(0);          // a function
  exports.u32leb(idx);
  if (idx >= 0 && idx < fnName.len()) { fnName[idx] = nm; }
}

void section(B out, i32 id, B sec) {
  out.byte(id);
  out.u32leb(sec.len);
  out.bytes(sec);
}


/**
 * Where a name lives while a function is being emitted.
 *
 * wasm has no names: a parameter and a local are both an *index*, parameters first, and a call names
 * a function by its index too. So the whole environment is two lists of names whose position is the
 * answer — which is the emitter's version of what the checker's flat name table already is.
 */
export struct Env {
  string[] locals;
  /** Each local's wac type, which is what decides every opcode the local takes part in. */
  string[] localTypes;
  i32 localCount;
  i32 paramCount;
  /**
   * How many wasm labels enclose the statement being emitted, and which of them a `break` leaves.
   *
   * wasm branches by *relative depth*, so `break` has to know how many blocks it sits inside since
   * the one it means. `depth` counts every label pushed; `breakAt` and `continueAt` remember the
   * depth at which the innermost loop's two labels were pushed, and the branch is the difference.
   * Getting it wrong produces a module that validates and jumps somewhere else, which is the reason
   * every one of these is tested by running it.
   */
  i32 depth;
  i32 breakAt;
  i32 continueAt;
  /**
   * Every distinct array type the module uses, and the wasm type index each was given.
   *
   * A wasm array is a *declared* type — `i32[]` is not a value type but a reference to an entry in
   * the type section — so the set has to be known before the section is written, and every use has
   * to name the same index. That is the first thing in this emitter that is not local to one
   * function.
   */
  string[] arrayTypes;
  i32 arrayCount;
  /**
   * Every function *signature* the module names, and the wasm type index each was given.
   *
   * A third kind of declared type, after the arrays and the structs. A function reference's value
   * type is `(ref null $sig)`, so the signature has to be a declared type of its own — separate from
   * the per-function types the code section already emits, which are indexed by function rather than
   * by shape.
   */
  /**
   * Sized for **three entries per `fn[…]`**, not one: the signature, its env shape and its pair —
   * `design/lang/0002`. At 4096 this overflowed on a real program, and an overflowed table answers
   * `sigType` with 0, which is an *array* index: `no signature at index 0 (4372 types)`, dozens of
   * functions from the cause.
   */
  string[] sigTypes;
  i32 sigCount;
  /**
   * The type arguments in force while a template is registered or emitted, and which template.
   *
   * `Vec<T>` is not a type — `Vec<i32>` is — so a template is compiled once **per instantiation**,
   * with `T` standing for its argument throughout. The substitution lives here because
   * `typeOfTyName` already takes the environment, so every place a type can be named goes through
   * it without a parameter being threaded to any of them.
   */
  string[] subFrom;
  string[] subTo;
  i32 subCount;
  /** The instance being built, and the template it is of — `Vec(…)` inside `Vec<T>` means it. */
  string curInst;
  string curGeneric;
  /** Every instantiation the module names, the template each is of, and whether one is new. */
  /** The structs whose defaults are being built, so one that reaches itself stops at a null. */
  string[] building;
  i32 buildingCount;
  string[] instName;
  string[] instOf;
  i32 instCount;
  bool instDirty;
  /**
   * The structs, in the order their type indices were handed out, and their fields flat beside them.
   *
   * A struct is the second declared type and shares the index space with the arrays, so both are
   * collected before the type section is written. The fields are flat — name, type, and which struct
   * owns them — for the same reason every table in this package is: wac has no growable array of
   * arrays, and the index is the answer.
   */
  /** The first construct that stopped a function being emitted, for the caller to report. */
  string blocked;
  /** The return type of the function being emitted, for the `return` statements inside it. */
  string returnType;
  /**
   * Module-level constants, and the expression each one *is*.
   *
   * Scalars are **inlined** at every use rather than given a global, which is what the reference does
   * and is simpler than it sounds: a constant has no identity to preserve, so substituting its
   * initialiser is exactly equivalent. An array constant is a different matter — it has identity, and
   * one array shared by every use is not the same as one array per use — so those stay declined until
   * there is a global section to put them in.
   */
  string[] constNames;
  /** The global index of a constant that needs one, or -1 for an inlined scalar. */
  i32[] constGlobal;
  string[] constTypes;
  /** Nullable because an `Expr` has no default value — this emitter's own checker says so. */
  Expr?[] constInits;
  i32 constCount;
  string[] structNames;
  i32 structCount;
  string[] fieldOwners;
  string[] fieldNames;
  string[] fieldTypes;
  /** Whether each field was written as `T?`, which is the whole of what its default turns on. */
  bool[] fieldNullable;
  i32 fieldCount;
  string[] funcs;
  /** Each function's return type, so a call has one without re-reading the declaration. */
  string[] funcReturns;
  /**
   * Each function's parameter types, flat.
   *
   * Needed for the same reason a field's type is: an argument that is a **literal** takes the type of
   * the slot it fills, and `g(4294967296)` is an `i64` constant or a zero depending on whether that
   * slot is known. Recorded rather than looked up, because a call site has a name and not a
   * declaration.
   */
  string[] funcParamTypes;
  i32[] funcParamAt;
  i32[] funcParamCount;
  i32 funcParamTotal;
  /**
   * Whether each function will be emitted, and what index it will have when it is.
   *
   * These are two different numbers and conflating them was a real bug: a function this emitter
   * cannot do is *skipped*, so the emitted module is a subset, and a call site naming the
   * registration index refers to something that is not there — *"function index #3 is not
   * declared"*. `funcOk` is the subset and `funcIndex` is the renumbering.
   */
  bool[] funcOk;
  i32[] funcIndex;
  i32 funcCount;
  /**
   * Every enum variant: the name it is known by, the enum it belongs to, the tag it carries, and
   * where its payload sits.
   *
   * **An enum is one wasm struct**, not a base type with a subtype per variant. The hierarchy the
   * language describes is what the reference emits; what this rung compares is answers, and a flat
   * struct — a tag in slot 0, then a slot per payload field of every variant in declaration order —
   * gives the same ones with no subtyping in the type section and no cast at any use. A variant is
   * then the *same wasm type* as its enum, which is what makes assigning one to the other free and
   * `match` a comparison rather than a test.
   *
   * The cost is space: a `Rect` carries the slots a `Circle` would have used. That is the trade a
   * language with no unions makes anyway, and nothing here is measuring bytes yet.
   */
  /**
   * Where each linked file begins, as a line number, and every top-level name with the file that
   * declared it.
   *
   * Linking by concatenation put every file's declarations in one pool, and a pool cannot hold two
   * meanings for one name — `sha256.wac` and `sha512.wac` both declare a `K`. What distinguishes
   * them is **where they are**: the blob is the files end to end, so a line number names a file
   * exactly, and every token carries its line. A name declared in the second file is registered
   * under a key of its own, and a reference resolves to the declaration in its *own* file before it
   * resolves to anyone else's — which is the language's rule (a file sees its own names, then what
   * it imported) arrived at from the only direction available here.
   */
  i32[] fileFirstLine;
  i32 fileCount;
  /**
   * Which file imports which, as (from, to) pairs.
   *
   * Needed because "this file's declaration, then anybody's" is not the language's rule and is not
   * even a safe approximation of it: with three files declaring `P`, a file that imported one of
   * them got whichever had registered first, and two structs that used to be one type are now two.
   * The wasm error for that is *"expected (ref null 1), got (ref null 7)"*, which names neither file.
   */
  i32[] importFrom;
  i32[] importTo;
  /**
   * The name each edge brings in, and the name the other file declares it under.
   *
   * The two differ under `import { decode as b64decode }`: the caller writes `b64decode` and no file
   * declares one. Nineteen corpus files are that import.
   */
  string[] importNames;
  string[] importDecls;
  i32 importCount;
  string[] declNames;
  i32[] declFiles;
  string[] declKeys;
  i32 declCount;
  string[] variantNames;
  string[] variantOwners;
  i32[] variantTags;
  /** The first field slot of this variant's payload, and how many slots it has. */
  i32[] variantSlot;
  i32[] variantArity;
  i32 variantCount;
  /**
   * Whether any table filled up.
   *
   * These are fixed arrays, and a table that stops writing while its count keeps rising renumbers
   * everything after it — a call to function #400 reaching #399. Linking made that reachable for the
   * first time: one file never had five hundred functions, and a closure of forty does. So it is
   * recorded and the module is declined by name, rather than emitted with the indices off by one.
   */
  bool full;
  /** Whether any name had to be guessed at — see `keyAt`. A module with one is not emitted. */
  bool ambiguous;
  /** And which name it was, because a category is not a diagnosis. */
  string ambiguousName;

  /**
   * Each struct's parent, or `""` — `struct Rect : Shape` maps to WasmGC's `sub`.
   *
   * Held beside the names rather than folded into the field table, because a subtype's fields are
   * *its parent's followed by its own* and the parent may be declared later in the file. Resolving
   * the chain when a field is asked for costs a lookup and keeps registration order irrelevant.
   */
  string[] structParents;
  /** The parent's name token, kept until every struct is declared and the key can be resolved. */
  i32[] structParentToks;
  /**
   * The program itself, so a walk can find a *declaration* rather than only what was registered.
   *
   * A generic function is the one thing that cannot be registered up front: `mapOption<T, U>` has no
   * instance until a call site says what `T` and `U` are, and it says so by the types of its
   * arguments rather than in writing. The declaration therefore has to be readable from wherever a
   * call is seen, which is several walkers deep and nowhere near the loop over `prog.decls`.
   */
  Program? prog;
  /** Whether this round built an instance's members, which can unblock a walk in the next one. */
  bool instBuilt;
  /**
   * Each function's receiver type, or `""` — the owner of a method declared with `this`.
   *
   * A method is registered with its *declared* parameters, because a call site pushes the object
   * itself and then walks the arguments. A **reference** to one has to say the other thing: its type
   * is `fn[void(Counter)]`, receiver first, since that is the signature of the function that was
   * actually emitted. This is what tells the two apart.
   */
  string[] funcRecv;

  /** A local's wac type, or `""` when the name is not one. */
  string localType(const this, string name) {
    for (i32 i = this.localCount - 1; i >= 0; i--) {
      if (this.locals[i] == name) { return this.localTypes[i]; }
    }
    return "";
  }

  /** The index of a local, or -1. Searched from the end so an inner declaration wins a shadow. */
  i32 localAt(const this, string name) {
    for (i32 i = this.localCount - 1; i >= 0; i--) {
      if (this.locals[i] == name) { return i; }
    }
    return -1;
  }

  i32 funcAt(const this, string name) {
    for (i32 i = 0; i < this.funcCount; i++) {
      if (this.funcs[i] == name) { return i; }
    }
    return -1;
  }

  /**
   * A local with no name, for a value that has to be used twice.
   *
   * A saturating cast reads its operand three times — once to compare against each bound and once to
   * convert — and an expression is not a thing you can evaluate three times. So it is spilled. Named
   * with a character no wac identifier can contain, which is how it cannot collide with a real one.
   *
   * Reused per type rather than allocated per site: the value is dead the moment the sequence that
   * spilled it ends, and one scratch of each width is all any of them needs.
   */
  /**
   * A scratch local for a named role, so two roles cannot share one slot.
   *
   * The plain `scratch` is keyed by type alone, which is right while the only thing spilling is a
   * cast. A compound assignment spills its target *across* the right-hand side, and a cast in there
   * would take the same `i32` slot — so the base and the index of `a[i] += (x as~ i32)` are asked
   * for by name.
   */
  i32 scratchNamed(this, string tag, string ty) {
    string key = " scratch " + tag + " " + ty;
    i32 at = this.localAt(key);
    if (at >= 0) { return at; }
    this.addLocal(key, ty);
    return this.localCount - 1;
  }

  i32 scratch(this, string ty) {
    string key = " scratch " + ty;
    i32 at = this.localAt(key);
    if (at >= 0) { return at; }
    this.addLocal(key, ty);
    return this.localCount - 1;
  }

  /**
   * The wasm type index for an array type, adding it if this is the first sighting.
   *
   * Arrays occupy the first block of indices and structs the second, so a struct declared later
   * cannot renumber an array. Both are known before the section is written, which is what makes a
   * fixed split possible at all.
   */
  i32 arrayType(this, string t) {
    for (i32 i = 0; i < this.arrayCount; i++) {
      if (this.arrayTypes[i] == t) { return i; }
    }
    if (this.arrayCount >= this.arrayTypes.len()) {
      this.ranOut("array types");
      return 0;
    }
    // **The element first, transitively.** `u8[][]`'s element is `u8[]`, which is a declared type of
    // its own and has to exist before anything refers to it. Registering only the outer one meant the
    // inner was created while the section was being *written* — an index past the count already
    // emitted, which wasm reports as "type index out of bounds" and which is the same mistake a field
    // of array type made two slots ago, one level further in.
    string el = elemOf(t);
    if (isArrayType(el)) { this.arrayType(el); }
    this.arrayTypes[this.arrayCount] = t;
    this.arrayCount = this.arrayCount + 1;
    return this.arrayCount - 1;
  }

  /** What a type parameter stands for right now, or `""` — the innermost binding wins. */
  string substituted(const this, string name) {
    for (i32 i = this.subCount - 1; i >= 0; i--) {
      if (this.subFrom[i] == name) { return this.subTo[i]; }
    }
    return "";
  }

  /** Record an instantiation. New ones set `instDirty`, which is what makes registration settle. */
  void instantiate(this, string inst, string of) {
    for (i32 i = 0; i < this.instCount; i++) {
      if (this.instName[i] == inst) { return; }
    }
    if (this.instCount >= this.instName.len()) {
      this.ranOut("generic instantiations");
      return;
    }
    this.instName[this.instCount] = inst;
    this.instOf[this.instCount] = of;
    this.instCount = this.instCount + 1;
    this.instDirty = true;
  }

  /**
   * A signature's type index, which follows the structs — added on first sighting, like an array's.
   *
   * The parameter and return types are registered first and transitively: a signature that mentions
   * `u8[]` is a type that mentions a type, and the inner one has to exist before the section that
   * declares them both is written.
   */
  i32 sigType(this, string t) {
    for (i32 i = 0; i < this.sigCount; i++) {
      if (this.sigTypes[i] == t) { return this.arrayCount + this.structCount + i; }
    }
    if (this.sigCount >= this.sigTypes.len()) {
      this.ranOut("function signatures");
      return 0;
    }
    this.sigTypes[this.sigCount] = t;
    this.sigCount = this.sigCount + 1;
    i32 mine = this.sigCount - 1;
    string r = sigReturn(t);
    if (isArrayType(r)) { this.arrayType(r); }
    if (isFuncrefType(r)) { this.sigType(r); }
    for (i32 i = 0; i < sigParamCount(t); i++) {
      string pt = sigParamAt(t, i);
      if (isArrayType(pt)) { this.arrayType(pt); }
      if (isFuncrefType(pt)) { this.sigType(pt); }
    }
    return this.arrayCount + this.structCount + mine;
  }

  /** A struct's type index, which follows the arrays. */
  /**
   * The struct type index for a `fn[…]` value's `{funcref, env}` pair — `design/lang/0002`.
   *
   * Allocated through `sigType` behind a marker, for the reason `pairMark` gives: the signature table
   * grows lazily during emission, so nothing may sit after it, and sharing it keeps the pair and its
   * env-taking funcref allocated together.
   */
  i32 pairType(this, string t) {
    // The funcref type first, so the struct's field type exists before the struct is written.
    i32 e = this.sigType(envSig(t));
    i32 ei = e - this.arrayCount - this.structCount;
    if (ei >= 0 && ei < this.sigNoPair.len()) { this.sigNoPair[ei] = true; }
    return this.sigType(pairMark() + t);
  }

  /**
   * Give every `fn[…]` already registered its pair, so none is first named while emitting.
   *
   * Run after the pre-pass and before the type section. A `fn[…]` reaches `writeValType` from a
   * local, a field, a parameter or a return, and all of those are registered by then — so sweeping
   * the table catches them all without a second walk of the program that could disagree with the
   * first.
   *
   * The loop re-reads `sigCount` because `pairType` appends: an env shape, which is flagged and
   * skipped, and a pair entry, which is not a funcref type. So it terminates.
   */
  void pairEverySignature(this) {
    for (i32 i = 0; i < this.sigCount; i++) {
      if (i < this.sigNoPair.len() && this.sigNoPair[i]) { continue; }
      string t = this.sigTypes[i];
      if (!isFuncrefType(t)) { continue; }
      this.pairType(t);
    }
  }

  i32 structType(this, string name) {
    string n = this.canonType(name);
    for (i32 i = 0; i < this.structCount; i++) {
      if (this.structNames[i] == n) { return this.arrayCount + i; }
    }
    return -1;
  }

  /** The index of a module-level constant, or -1. */
  i32 constAt(const this, string name) {
    for (i32 i = 0; i < this.constCount; i++) {
      if (this.constNames[i] == name) { return i; }
    }
    return -1;
  }

  bool isStructName(const this, string name) {
    string n = this.canonType(name);
    for (i32 i = 0; i < this.structCount; i++) {
      if (this.structNames[i] == n) { return true; }
    }
    return false;
  }

  /**
   * Whether one struct is the other, or descends from it.
   *
   * A widening needs **no instruction**: a `Rect` reference already is a `Shape` reference to wasm
   * once the type section says `sub`, so the only thing this answers is whether the emitter may stay
   * silent. Nothing narrows implicitly, which is why the question is asked in one direction.
   */
  bool isSubtypeOf(const this, string derived, string base) {
    if (derived == base) { return true; }
    // **`anyref` is above everything**, which is the one relation that needs no chain: a struct, an
    // array, a string and an `i31ref` are all one, and a `funcref` is *not* — function references
    // are their own hierarchy in the format and cannot be stored in an `anyref`.
    if (base == "anyref") { return isArrayType(derived) || derived == "string" ||
                                   this.isStructName(derived) || derived == "i31ref"; }
    string p = this.parentOf(derived);
    return p == "" ? false : this.isSubtypeOf(p, base);
  }

  /**
   * A method's slot, looked up **through the parent chain**.
   *
   * The child's own is found first, which is what makes `override` work — and makes it work the way
   * the language says: dispatch is by the *static* type, because this lookup is handed the type the
   * call site knows and there is no vtable anywhere to disagree with it. Statics do not come this
   * way: `Rect.create` is an error when only `Shape` declares one.
   */
  i32 methodAt(const this, string owner, string name) {
    i32 at = this.funcAt(owner + "." + name);
    if (at >= 0) { return at; }
    string p = this.parentOf(owner);
    return p == "" ? -1 : this.methodAt(p, name);
  }

  /** A struct's parent, or `""`. */
  string parentOf(const this, string owner) {
    for (i32 i = 0; i < this.structCount; i++) {
      if (this.structNames[i] == owner) { return this.structParents[i]; }
    }
    return "";
  }

  /**
   * How many fields a struct inherits — the offset every one of its own fields sits at.
   *
   * **A subtype's fields are its parent's followed by its own**, which is not this emitter's choice:
   * wasm requires a subtype to repeat its supertype's fields in order before appending, so that a
   * `struct.get` compiled against the parent reads the same slot on a child. The whole of inheritance
   * here is that one offset, applied by every accessor below.
   */
  i32 inheritedCount(const this, string owner) {
    string p = this.parentOf(owner);
    return p == "" ? 0 : this.fieldCountOf(p);
  }

  /** Which of a struct's fields this is, in declaration order, or -1. */
  i32 fieldIndex(const this, string owner, string field) {
    i32 base = this.inheritedCount(owner);
    i32 n = 0;
    for (i32 i = 0; i < this.fieldCount; i++) {
      if (this.fieldOwners[i] != owner) { continue; }
      if (this.fieldNames[i] == field) { return base + n; }
      n = n + 1;
    }
    return base == 0 ? -1 : this.fieldIndex(this.parentOf(owner), field);
  }

  /** How many fields a struct has, which decides whether a bare `P()` is a default construction. */
  i32 fieldCountOf(const this, string owner) {
    i32 n = this.inheritedCount(owner);
    for (i32 f = 0; f < this.fieldCount; f++) {
      if (this.fieldOwners[f] == owner) { n = n + 1; }
    }
    return n;
  }

  /** Whether the `i`th field admits null, which decides whether its default is one. */
  bool fieldNullableAt(const this, string owner, i32 i) {
    i32 base3 = this.inheritedCount(owner);
    if (i < base3) { return this.fieldNullableAt(this.parentOf(owner), i); }
    i32 n = base3;
    for (i32 f = 0; f < this.fieldCount; f++) {
      if (this.fieldOwners[f] != owner) { continue; }
      if (n == i) { return this.fieldNullable[f]; }
      n = n + 1;
    }
    return false;
  }

  /** The `i`th field's name, which is what a bind accessor is called after. */
  string fieldNameAt(const this, string owner, i32 i) {
    i32 baseN = this.inheritedCount(owner);
    if (i < baseN) { return this.fieldNameAt(this.parentOf(owner), i); }
    i32 n = baseN;
    for (i32 f = 0; f < this.fieldCount; f++) {
      if (this.fieldOwners[f] != owner) { continue; }
      if (n == i) { return this.fieldNames[f]; }
      n = n + 1;
    }
    return "";
  }

  /** The `i`th field's type, for a positional construction. */
  string fieldTypeAt(const this, string owner, i32 i) {
    i32 base4 = this.inheritedCount(owner);
    if (i < base4) { return this.fieldTypeAt(this.parentOf(owner), i); }
    i32 n = base4;
    for (i32 f = 0; f < this.fieldCount; f++) {
      if (this.fieldOwners[f] != owner) { continue; }
      if (n == i) { return this.fieldTypes[f]; }
      n = n + 1;
    }
    return "";
  }

  /** A function's `i`th parameter type, so an argument knows what slot it fills. */
  string paramTypeAt(const this, i32 at, i32 i) {
    if (at < 0 || at >= this.funcCount || i >= this.funcParamCount[at]) { return ""; }
    i32 slot = this.funcParamAt[at] + i;
    // A flat table that filled up stops *writing* and keeps counting, so the count can outrun what
    // was stored. Reading past it is an out-of-bounds trap in the middle of emitting, which is how a
    // corpus file with more parameters than this had room for showed up.
    if (slot >= this.funcParamTotal) { return ""; }
    return this.funcParamTypes[slot];
  }

  /** Record a function, with its parameters, in the order the calls will index them. */
  void addFunc(this, string name, string ret, string[] ptypes) {
    if (this.funcCount >= this.funcs.len()) {
      this.ranOut("functions");
      return;
    }
    this.funcs[this.funcCount] = name;
    this.funcReturns[this.funcCount] = ret;
    this.funcParamAt[this.funcCount] = this.funcParamTotal;
    this.funcParamCount[this.funcCount] = ptypes.len();
    for (i32 i = 0; i < ptypes.len(); i++) {
      if (this.funcParamTotal >= this.funcParamTypes.len()) {
        // A parameter this table has no room for makes `paramTypeAt` answer `""` for it, and an
        // unknown slot type is how a literal argument becomes an `i32.const` in a reference slot.
        this.ranOut("function parameters");
        break;
      }
      this.funcParamTypes[this.funcParamTotal] = ptypes[i];
      this.funcParamTotal = this.funcParamTotal + 1;
    }
    // Assumed emittable until something says otherwise, which is what the fixed point below removes.
    this.funcOk[this.funcCount] = true;
    this.funcIndex[this.funcCount] = -1;
    this.funcCount = this.funcCount + 1;
  }

  /** A field's wac type, which decides how it is read and what it produces. */
  string fieldType(const this, string owner, string field) {
    for (i32 i = 0; i < this.fieldCount; i++) {
      if (this.fieldOwners[i] == owner && this.fieldNames[i] == field) { return this.fieldTypes[i]; }
    }
    string p2 = this.parentOf(owner);
    return p2 == "" ? "" : this.fieldType(p2, field);
  }

  /**
   * An empty environment, with the capacities in one place rather than in three call sites.
   *
   * They were three identical lists of forty-three arguments, which is how the last two fields added
   * here cost three edits each and one of them was found by a type error rather than by reading.
   */
  /**
   * The callback signatures a host has to supply — one imported dispatcher each.
   *
   * `export i32 g(fn[i32(i32)] cb)` cannot be called from JavaScript at all without one: a host
   * function has no way into wac, and the module the reference emits imports `wac.cb0` for exactly
   * this. Collected before anything is numbered, because **an import comes first in the function
   * index space** and every index this emitter computes is measured from it. `issues/lang/0094`.
   */
  string[] cbSigs;
  i32 cbSigCount;

  /**
   * The type each field was *written* with, kept until every declaration exists.
   *
   * A field's type is resolved by name, and a name from another file can only be resolved once that
   * file's declarations are registered — which is not true while this pass is walking. The parent
   * chain has had this treatment since it was written (`structParentToks`); a field's type
   * needed it for the same reason and did not have it, so `struct Repo { FsType fs; }` — where
   * `FsType` is `import { Fs as FsType }` — resolved to nothing and fell back to `i32`.
   * `issues/lang/0097`, `spec/cases/0096`.
   */
  Ty?[] fieldTys;

  /**
   * What each file in the link order was called, by file index.
   *
   * Only the boundary needs it: a monomorphisation's bind name is the reference's, and the reference
   * qualifies a template by its declaring file. Everything else here is keyed by `declare`, which
   * needs no path at all. `issues/lang/0089`.
   */
  string[] filePaths;

  /**
   * Why each function was declined, or `""`.
   *
   * A decline cascades — `Shell.create` is declined because `runScript` is, which is declined
   * because `runList` is — and the report named only the first hop, which is the least useful end
   * of the chain. Recorded per function so a message can carry the reason underneath it.
   */
  string[] funcWhy;
  /** The reason the last `canEmit` gave, which is how `settleEmittable` learns it. */
  string lastWhy;

  /**
   * `--checked`: add/sub/mul trap instead of wrapping.
   *
   * Whole-module, as the reference has it — the flag is the build's, not a type's — and off by
   * default, where the bytes must be exactly what they were.
   */
  bool checked;

  /**
   * Coverage instrumentation: a counter per branch point, and the table that says what each is.
   *
   * `covCount` is assigned as the points are discovered — emission order *is* the numbering, which
   * is why the table is built in the same walk rather than derived afterwards. Global 0 holds the
   * counters when this is on, so every constant's global index shifts by one, exactly as an import
   * shifts every function's.
   */
  bool coverage;
  i32 covCount;
  string covTable;

  /** The funcref signatures handed out, one `$bind$callref_<j>` each. */
  string[] outSigs;
  i32 outSigCount;

  /**
   * A monomorphisation's other names — the spellings that collapse onto one instance here.
   *
   * `T?` and `T` are the same *wasm* type, so `Pending<u8[]?>` and `Pending<u8[]>` are one
   * instantiation to this emitter, which is right for emission and wrong at the boundary: a host
   * asks for `Pending$u8ArrOpt` by name and there is nothing of that name to answer with. The
   * identity stays collapsed — two structs with one layout would be a worse lie — and the metadata
   * carries the alias instead, so the glue can offer both names for the one class [issue 0106].
   */
  string[] aliasOf;
  string[] aliasName;
  i32 aliasCount;

  /**
   * Which table ran out, when one did.
   *
   * `full` alone means "this module was declined", and every caller then reported the *consequence*
   * — a decline chain seven calls deep, or an import that was said not to be supplied. Four separate
   * capacity limits were found in one night that way, each of them looking like a different bug.
   * Saying which table is the difference between a mystery and a number to change.
   */
  string fullWhy;

  /**
   * Trace mode: coverage's machinery recording an ordered *journal* rather than counts.
   *
   * It is `coverage` with two differences, and it is declared here rather than beside it because the
   * constructor is positional and a field in the middle renumbers every argument after it.
   *
   *   - a point appends `(site, value)` to the log instead of incrementing a counter, and
   *   - every array **index** is a point too, with the index as its value.
   *
   * The second is what the mode is for: a secret-dependent branch is a leak that branch coverage
   * sees, and a secret-dependent *index* — `SBOX[key]` — has no branch at all and is how AES keys
   * have been recovered from cache timing since 2005. `harness/ctTrace.ts` compares two runs.
   */
  bool trace;

  /** How many i32 slots the journal gets, or 0 for the default. `issues/lang/0059`. */
  i32 traceSlots;

  /** How many of the blob's declarations are the entry's, or -1 for a single file. */
  i32 entryDecls;

  /**
   * The `fn[…]` wrappers, built as each function is emitted — `design/lang/0002`.
   *
   * Two buffers rather than a list of anything, because they are appended to `funcs` and `code`
   * whole once every other helper is written: a wrapper's index has to fall after all of them.
   *
   * Filled from `emitFunction`, which is the one place every emitted function passes through — so
   * the set is exactly the emitted functions and the order is exactly the emission order. A previous
   * attempt built this list from `funcCount`/`funcIndex` instead, which is different bookkeeping that
   * lines up most of the time; `emit.wac` already carries a comment about the fifty-seven invalid
   * modules the same mistake produced somewhere else.
   */
  /**
   * Which signature entries are env-shaped and must **not** be given a pair of their own.
   *
   * `envSig(t)` is itself a `fn[…]`, so a sweep that pairs every funcref entry would pair it, then
   * pair *its* env-shape, without end. A flag rather than a test on the string: `fn[bool(anyref)]`
   * is a real user type — `Shell.askInterrupt` is exactly that — so "first parameter is anyref"
   * cannot tell the two apart.
   */
  bool[] sigNoPair;
  B wrapFuncs;
  B wrapCode;
  i32 wrapCount;
  /** The bound wrappers — the same, with the env cast to a receiver instead of dropped. */
  B boundFuncs;
  B boundCode;
  /** Where they start, so a bound reference can name one. */
  i32 boundAt;
  /** Where the wrappers start, so a `ref.func` site can name one. Set before any function is emitted. */
  i32 wrapAt;
  /**
   * `__fmod`, with `__fmodf` immediately after it — wasm has no `f64.rem`, so `%` on a float is a
   * call rather than an instruction. Set before any function is emitted, for the same reason
   * `wrapAt` is: `emitBinary` needs it while walking an expression. `issues/lang/0135`.
   */
  i32 fmodAt;
  /**
   * Every lambda in the program, in the order **one** walk found them — `design/lang/0002` tier two.
   *
   * A lambda is hoisted into an ordinary function, so it has to be counted before the function
   * section is sized, and found again when it is emitted. Those must not be two walks: a lambda
   * counted in one order and emitted in another names the wrong function index, which the module
   * reports as a validation failure or, worse, does not report at all and calls the wrong body. So
   * `findLambdas` runs once, assigns each its index, and stores what emission needs here — emission
   * reads by index and cannot disagree with a walk it does not perform.
   *
   * Last fields on purpose: `Env` is built positionally, and appending is the only edit to it that
   * cannot silently land a value in another field's slot.
   */
  Param[][] lambdaParams;
  Stmt[][] lambdaBodies;
  /**
   * Each lambda's emitted signature, or `""` when the walk could not tell what it is.
   *
   * A hoisted lambda is a function, so its `fn[…]` has to be in the type section — and `declTypes`
   * is snapshotted before any body is emitted. So the signature is due in the pre-pass, which is why
   * the walk carries a wanted type down the way `emitExprAt` does. `""` means the position is one the
   * walk does not yet type, and the module declines by name rather than guessing.
   */
  string[] lambdaSigs;
  /**
   * Where each lambda is written, so the emitter can find its index **without walking again**.
   *
   * The expression site has to know which lambda it is looking at. Counting them as emission goes is
   * a second walk that has to agree with the first, which is the failure this whole design avoids —
   * a divergence names the wrong function index silently. Identity would settle it, but wacc has no
   * `is` on an array (`a test for x on a i32[]`), so the key is the position: a line and a column
   * name exactly one expression in a linked program, and both walks read them from the same node.
   */
  i32[] lambdaLine;
  i32[] lambdaCol;
  /**
   * Which instantiation this lambda belongs to, or `""` for one in ordinary code.
   *
   * **A line and a column name exactly one expression in a linked program** — which stops being true
   * inside a generic, because a generic is emitted once per instantiation and the same expression is
   * emitted N times, each closing over a different `T`. That is the whole of `issues/lang/0142`, and
   * this is the missing part of the key: `Env.curInst` already says which instantiation the emitter
   * is in, maintained by `pushSubstitution`, so the walk and emission agree on it for free and no
   * call site of `lambdaAtPos` has to change.
   */
  string[] lambdaInst;
  i32 lambdaCount;
  /**
   * The emission ordinal of the first hoisted lambda — the number of ordinary functions before them.
   *
   * A lambda *is* an ordinary function, emitted right after the declared ones, so its wrapper is at
   * `wrapAt + lambdaFirst + i` by the same arithmetic every other wrapper uses.
   */
  i32 lambdaFirst;
  /**
   * A name-to-type scope the lambda walk keeps as it goes — `design/lang/0002` tier two.
   *
   * The walk runs in the pre-pass, before any function's locals exist: those are built per body
   * during emission. But a local's type is *written down* — `Var` carries it — so the walk can
   * maintain the scope itself, which is what lets it type an assignment target, and what will let it
   * work out a lambda's free variables and their types when capture lands. Both are due in the
   * pre-pass because both end up as types, and the table may not grow after `declTypes`.
   *
   * A stack: `walkCount` is saved on entry to a block or a lambda and restored on the way out, so a
   * name goes out of scope exactly where it should and shadowing works by the later entry winning.
   */
  string[] walkNames;
  string[] walkTypes;
  /** Where each name in scope was declared — a parameter has no `Var`, and records -1. */
  i32[] walkDeclLine;
  i32[] walkDeclCol;
  i32 walkCount;
  /**
   * What each lambda captures: the names its body reads that it did not declare — `design/lang/0002`.
   *
   * A flat table, with `lambdaCapAt[li]` and `lambdaCapCount[li]` naming each lambda's run. These
   * become the fields of the generated struct that a capturing lambda carries in its env, which is
   * why they are collected here: the struct is a type, and the type table may not grow after
   * `declTypes` is taken.
   *
   * A name counts as captured when it resolves *below* the lambda's own scope mark — that is, to
   * something declared outside it. Its own parameters and locals are above the mark and are not
   * captures; a name that resolves nowhere is a function, a struct or a constant, not a local, and
   * is not captured either.
   */
  string[] capNames;
  string[] capTypes;
  i32[] lambdaCapCount;
  /**
   * The lambdas currently being walked, innermost last, with the scope mark each one opened at.
   *
   * A **stack**, not a single frame, because capture is transitive: an inner lambda reading a name
   * from outside the *outer* lambda makes the outer one capture it too — it has to, since the outer
   * is what constructs the inner's environment. With one frame the outer reported no captures at all
   * for `() => { i32 b = 2; fn[i32()] h = () => a + b; return h(); }`, which would have emitted a
   * capture struct with no `a` in it and read a field that was never stored.
   */
  /** Where the function currently being walked is, so a captured parameter can be keyed by it. */
  i32 walkFuncLine;
  i32 walkFuncCol;
  i32[] walkLambdaStack;
  i32[] walkMarkStack;
  i32 walkLambdaDepth;
  /**
   * The lambda whose hoisted body is being emitted, or -1.
   *
   * A captured name is not a local of the hoisted function: it is a field of the capture struct the
   * function receives as its receiver, so it is emitted as `local.get 0` and a `struct.get`. This is
   * how the `Ident` case knows to do that rather than look for a local that does not exist — which is
   * what it did for one commit, emitting nothing and leaving the stack short.
   */
  i32 emittingLambda;
  /**
   * Every name assigned anywhere in the function being walked, and which lambdas capture one.
   *
   * **Capture is by value today, and by value is not what `design/lang/0002` decided.** The two agree
   * exactly while nothing writes the captured name: read-only capture is identical either way, and a
   * write is where they diverge — the lambda's write unseen outside, the enclosing function's unseen
   * inside. Measured, not assumed: both writing shapes answered 1 where reference semantics wants 42.
   *
   * So a lambda capturing a name that is written, from either side, is declined rather than emitted
   * with the wrong meaning. Reference semantics needs a cell per captured local, and the cell has to
   * be threaded through the *enclosing* function's own reads and writes, which is the part that
   * changes code the lambda is not in. Until that exists, this is the honest half.
   */
  string[] assignedNames;
  i32 assignedCount;
  bool[] lambdaWrites;
  /**
   * Which lambdas capture a **parameter**, which has no declaration to promote to a cell.
   *
   * A captured local becomes a cell at its `Var`; a parameter arrives already in its slot, so making
   * it a cell means building one at function entry and rewriting every use — which is not done. Until
   * it is, such a lambda is declined: the capture record's fields are cell types now, so handing one
   * a raw parameter would be an invalid module rather than a wrong answer.
   */
  bool[] lambdaCapturesParam;
  /**
   * Captured **parameters**, keyed by the position of the function that declares them.
   *
   * A captured local becomes a cell at its `Var`; a parameter has no `Var`, so its cell is built at
   * entry instead — and the emitter needs to know which of a function's parameters need one while it
   * is emitting that function. The same position key the lambdas and the promoted declarations use,
   * for the same reason: both walks read it from the same node.
   */
  /**
   * Each generic struct's type-parameter names, comma-joined — `Slot` → `T`, `Map` → `K,V`.
   *
   * The walk needs them to read a method's parameter types in the caller's world: `paramTypeAt`
   * answers in the template's letters, and turning `fn[T(i32)]` into `fn[i32(i32)]` means knowing
   * that `T` is the first parameter. Recorded in the same pass that finds the lambdas, from the
   * declarations that pass already walks. `issues/lang/0141`.
   */
  /**
   * Whether a lambda was seen inside a **generic** declaration — `issues/lang/0142`.
   *
   * A generic is emitted once per instantiation, so a lambda inside one is *N* hoisted functions
   * rather than one, and the position key this design rests on is the same for every instantiation.
   * Until that is solved they are unsupported — and unsupported has to mean *declined*, not emitted:
   * the walk skipped generic bodies, nothing asked whether they were emittable, and the module came
   * back with a lambda's instructions missing and a short stack.
   */
  bool lambdaInGeneric;
  string[] genericOwner;
  string[] genericParams;
  i32 genericCount;

  /** The `i`th type-parameter name of a generic, or `""`. */
  string genericParamAt(const this, string owner, i32 at) {
    for (i32 g = 0; g < this.genericCount; g++) {
      if (this.genericOwner[g] != owner) { continue; }
      i32 n = 0;
      i32 start = 0;
      string ps = this.genericParams[g];
      u8[] a = ps.toBytes();
      for (i32 i = 0; i <= a.len(); i++) {
        if (i == a.len() || a[i] == 44) {
          if (n == at) { return ps.slice(start, i); }
          n = n + 1;
          start = i + 1;
        }
      }
      return "";
    }
    return "";
  }

  i32[] paramCellLine;
  i32[] paramCellCol;
  string[] paramCellName;
  i32 paramCellCount;

  void noteParamCell(this, i32 line, i32 col, string name) {
    for (i32 i = 0; i < this.paramCellCount; i++) {
      if (this.paramCellLine[i] == line && this.paramCellCol[i] == col
          && this.paramCellName[i] == name) { return; }
    }
    if (this.paramCellCount >= this.paramCellName.len()) { return; }
    this.paramCellLine[this.paramCellCount] = line;
    this.paramCellCol[this.paramCellCount] = col;
    this.paramCellName[this.paramCellCount] = name;
    this.paramCellCount = this.paramCellCount + 1;
  }

  bool paramNeedsCell(const this, i32 line, i32 col, string name) {
    for (i32 i = 0; i < this.paramCellCount; i++) {
      if (this.paramCellLine[i] == line && this.paramCellCol[i] == col
          && this.paramCellName[i] == name) { return true; }
    }
    return false;
  }
  /**
   * Where each captured local is *declared*, so the emitter can promote it to a cell.
   *
   * Keyed by the declaration's line and column rather than by name, because a name is only unique
   * within a scope and the emitter meets declarations one at a time. It is the same key the lambdas
   * themselves use, and for the same reason: both walks read it from the same node, so they cannot
   * disagree about which declaration is meant.
   *
   * This is the mapping `design/lang/0002` records as the missing link. The walk indexes by lambda
   * and emission indexes by function, and a declaration's position is the one thing both can name —
   * which avoids a function-ordinal table that emission would have to be trusted to keep in step.
   */
  i32[] promotedLine;
  i32[] promotedCol;
  i32 promotedCount;
  /**
   * Which local slots hold a **cell** rather than a value — `design/lang/0002` tier two.
   *
   * Parallel to `locals`. `localTypes` keeps the *value* type, which is what makes this tractable:
   * all eight of its consumers go on answering "n is an i32", and only the four sites that touch the
   * slot itself consult this — the locals vector, the read, the write, and the declaration.
   */
  bool[] localCell;

  /** Whether the local at `i` is a promoted cell. */
  bool localIsCell(const this, i32 at) {
    return at >= 0 && at < this.localCell.len() && this.localCell[at];
  }

  /** Record that the declaration at this position is captured, so it becomes a cell. */
  void notePromoted(this, i32 line, i32 col) {
    for (i32 i = 0; i < this.promotedCount; i++) {
      if (this.promotedLine[i] == line && this.promotedCol[i] == col) { return; }
    }
    if (this.promotedCount >= this.promotedLine.len()) { return; }
    this.promotedLine[this.promotedCount] = line;
    this.promotedCol[this.promotedCount] = col;
    this.promotedCount = this.promotedCount + 1;
  }

  /** Whether the declaration at this position is captured by some lambda. */
  bool isPromoted(const this, i32 line, i32 col) {
    for (i32 i = 0; i < this.promotedCount; i++) {
      if (this.promotedLine[i] == line && this.promotedCol[i] == col) { return true; }
    }
    return false;
  }

  /** Note that `name` is assigned somewhere in this function. */
  void noteAssigned(this, string name) {
    for (i32 i = 0; i < this.assignedCount; i++) {
      if (this.assignedNames[i] == name) { return; }
    }
    if (this.assignedCount >= this.assignedNames.len()) { return; }
    this.assignedNames[this.assignedCount] = name;
    this.assignedCount = this.assignedCount + 1;
  }

  bool isAssigned(const this, string name) {
    for (i32 i = 0; i < this.assignedCount; i++) {
      if (this.assignedNames[i] == name) { return true; }
    }
    return false;
  }

  /** The index of `name` among lambda `li`'s captures, or -1. */
  i32 captureAt(const this, i32 li, string name) {
    if (li < 0) { return -1; }
    i32 from = li * capsPerLambda();
    for (i32 c = 0; c < this.lambdaCapCount[li]; c++) {
      if (this.capNames[from + c] == name) { return c; }
    }
    return -1;
  }

  /**
   * Note that `name` was read, for every enclosing lambda that did not declare it.
   *
   * Walking the stack outward and stopping at the first lambda whose scope contains the name: any
   * lambda opened *after* the declaration has it from outside and must carry it, and one opened
   * before declared it itself.
   */
  void noteRead(this, string name) {
    i32 at = -1;
    for (i32 i = this.walkCount - 1; i >= 0; i--) {
      if (this.walkNames[i] == name) { at = i; break; }
    }
    if (at < 0) { return; }
    bool captured = false;
    for (i32 d = 0; d < this.walkLambdaDepth; d++) {
      if (this.walkMarkStack[d] > at) {
        this.noteCapture(this.walkLambdaStack[d], name, this.walkTypes[at]);
        captured = true;
      }
    }
    // The declaration this name came from becomes a cell. A parameter records -1 and is skipped:
    // it has no `Var` to promote, and needs a cell made at function entry instead — the piece that
    // is still missing.
    if (captured && this.walkDeclLine[at] >= 0) {
      this.notePromoted(this.walkDeclLine[at], this.walkDeclCol[at]);
    }
    if (captured && this.walkDeclLine[at] < 0) {
      this.noteParamCell(this.walkFuncLine, this.walkFuncCol, name);
    }
  }

  /** Record a capture, ignoring one already recorded for this lambda. */
  void noteCapture(this, i32 li, string name, string ty) {
    i32 from = li * capsPerLambda();
    i32 n = this.lambdaCapCount[li];
    for (i32 i = 0; i < n; i++) {
      if (this.capNames[from + i] == name) { return; }
    }
    // **A slab per lambda, not one flat run.** A flat table assumes each lambda's captures are
    // contiguous, and nesting breaks that: reading a name inside an inner lambda appends to the
    // inner's run *and* the outer's, alternately, so the runs interleave and every count after the
    // first names the wrong entries. The nested case reported `a` for both lambdas and lost `b`.
    if (n >= capsPerLambda()) { this.ranOut("captures in one lambda"); return; }
    this.capNames[from + n] = name;
    this.capTypes[from + n] = ty;
    this.lambdaCapCount[li] = n + 1;
  }

  /** The type of `name` in the walk's scope, innermost first, or `""`. */
  string walkTypeOf(const this, string name) {
    for (i32 i = this.walkCount - 1; i >= 0; i--) {
      if (this.walkNames[i] == name) { return this.walkTypes[i]; }
    }
    return "";
  }

  /** Bring a name into the walk's scope. Silently full is fine: it only ever loses a wanted type. */
  void walkDeclare(this, string name, string ty) { this.walkDeclareAt(name, ty, -1, -1); }

  /** The same, remembering where the declaration is, so a capture can promote it to a cell. */
  void walkDeclareAt(this, string name, string ty, i32 line, i32 col) {
    if (this.walkCount >= this.walkNames.len()) { return; }
    this.walkNames[this.walkCount] = name;
    this.walkTypes[this.walkCount] = ty;
    this.walkDeclLine[this.walkCount] = line;
    this.walkDeclCol[this.walkCount] = col;
    this.walkCount = this.walkCount + 1;
  }

  /** The index of the lambda written at `line`:`col`, or -1 — how emission finds its own. */
  /**
   * Whether this instantiation\'s lambdas are already recorded.
   *
   * `findLambdasInInstances` runs twice — before the emittability fixpoint so it can answer, and
   * after it because that is where the last instantiations appear — and this is what stops the
   * second run recording a second copy of everything the first found. No new table: an entry
   * *carries* its instantiation, so the answer is already in `lambdaInst`.
   *
   * An instantiation with no lambdas at all answers false both times and is walked twice, which
   * records nothing twice and costs a traversal nobody notices.
   */
  bool lambdasRecordedFor(const this, string inst) {
    for (i32 i = 0; i < this.lambdaCount; i++) {
      if (this.lambdaInst[i] == inst) { return true; }
    }
    return false;
  }

  i32 lambdaAtPos(const this, i32 line, i32 col) {
    for (i32 i = 0; i < this.lambdaCount; i++) {
      // The instantiation is part of the key — see `lambdaInst`. `curInst` is `""` outside a generic,
      // so ordinary code compares equal to the entries the plain walk recorded.
      if (this.lambdaLine[i] == line && this.lambdaCol[i] == col &&
          this.lambdaInst[i] == this.curInst) { return i; }
    }
    return -1;
  }

  /** Record the first table to fill; the first is the one that caused the rest. */
  void ranOut(this, string what) { this.declineFor("the emitter ran out of room for " + what); }

  /**
   * Decline this module, saying why.
   *
   * `full` is the flag every caller already reads, so this sets it — the field is named for its
   * first cause and means "declined" in practice. What matters is that a reason travels with it:
   * without one, a caller reports whichever *declaration* looks unsatisfiable, and the reader ends
   * up chasing the seventh call in a chain rather than the cause.
   */
  void declineFor(this, string why) {
    this.full = true;
    if (this.fullWhy == "") { this.fullWhy = why; }
  }

  /** Record that `spelled` is another way of writing the instantiation `identity`. */
  void noteAlias(this, string identity, string spelled) {
    if (identity == spelled) { return; }
    for (i32 i = 0; i < this.aliasCount; i++) {
      if (this.aliasOf[i] == identity && this.aliasName[i] == spelled) { return; }
    }
    if (this.aliasCount >= this.aliasOf.len()) { return; }
    this.aliasOf[this.aliasCount] = identity;
    this.aliasName[this.aliasCount] = spelled;
    this.aliasCount = this.aliasCount + 1;
  }

  Env create() {
    return Env(string[2048](), string[2048](), 0, 0, 0, -1, -1, string[1024](), 0, string[16384](), 0,
               string[256](), string[256](), 0, "", "", string[64](), 0, string[512](), string[512](), 0, false,
               "", "",
               string[512](), i32[512](), string[512](), Expr?[512](), 0,
               string[1024](), 0,
               string[16384](), string[16384](), string[16384](), bool[16384](), 0,
               string[4096](), string[4096](), string[16384](), i32[4096](), i32[4096](), 0,
               bool[4096](), i32[4096](), 0,
               i32[1024](), 0, i32[4096](), i32[4096](), string[4096](), string[4096](), 0,
               string[8192](), i32[8192](), string[8192](), 0,
               string[2048](), string[2048](), i32[2048](), i32[2048](), i32[2048](), 0, false, false, "",
               string[1024](), i32[1024](), null, false, string[4096](),
               string[256](), 0, Ty?[16384](), string[1024](), string[16384](), "", false,
               false, 0, "", string[256](), 0,
               string[256](), string[256](), 0, "", false, 0, -1,
               bool[16384](), B.create(), B.create(), 0, B.create(), B.create(), 0, 0, 0,
               Param[][1024](fill: Param[]()), Stmt[][1024](fill: Stmt[]()),
               string[1024](fill: ""), i32[1024](), i32[1024](), string[1024](fill: ""), 0, 0,
               string[4096](fill: ""), string[4096](fill: ""), i32[4096](), i32[4096](), 0,
               string[32768](fill: ""), string[32768](fill: ""), i32[1024](),
               0, 0, i32[64](), i32[64](), 0, -1, string[4096](fill: ""), 0, bool[1024](), bool[1024](),
               false, string[1024](fill: ""), string[1024](fill: ""), 0,
               i32[4096](), i32[4096](), string[4096](fill: ""), 0,
               i32[4096](), i32[4096](), 0, bool[4096]());
  }

  /** Which linked file a line belongs to; 0 when nothing was linked. */
  i32 fileOf(const this, i32 line) {
    i32 at = 0;
    for (i32 i = 0; i < this.fileCount; i++) {
      if (this.fileFirstLine[i] <= line) { at = i; }
    }
    return at;
  }

  /**
   * Register a top-level name, and answer with the key everything else will use for it.
   *
   * The first declaration of a name keeps the name itself, so a single-file module — and every
   * reference in every file that imported this one — is unchanged. A second file declaring the same
   * name gets a key nothing else can spell.
   */
  string declare(this, string name, i32 line) {
    i32 f = this.fileOf(line);
    bool taken = false;
    for (i32 i = 0; i < this.declCount; i++) {
      if (this.declNames[i] == name) { taken = true; }
    }
    string key = name;
    if (taken) { key = name + "@" + numText(f); }
    if (this.declCount >= this.declNames.len()) { this.ranOut("declarations"); }
    if (this.declCount < this.declNames.len()) {
      this.declNames[this.declCount] = name;
      this.declFiles[this.declCount] = f;
      this.declKeys[this.declCount] = key;
      this.declCount = this.declCount + 1;
    }
    return key;
  }

  /**
   * Is this name declared in more than one file?
   *
   * The key may carry the `@<file>` a second declaration was given, and the question is about the
   * *name* — so both `S` and `S@2` answer yes when two modules declare an `S`. What the bind helpers
   * do with that is qualify both of them by their file rather than leave the first one holding a
   * name that would mean either [issue 0100].
   */
  bool ambiguousDecl(this, string key) {
    string bare = key;
    i32 at = key.indexOf("@");
    if (at > 0) { bare = key.slice(0, at); }
    i32 n = 0;
    for (i32 i = 0; i < this.declCount; i++) {
      if (this.declNames[i] == bare) { n = n + 1; }
    }
    return n > 1;
  }

  /**
   * The key a name means when it is *used* at this line: this file's declaration, or anyone's.
   *
   * The fallback is deliberately permissive — a file here can see a name it never imported — which
   * is the same trade linking by concatenation already made, and safe in the same direction: this
   * emitter accepts more than the language does and the checker one rung down says no.
   */
  string keyAt(this, string name, i32 line) {
    // **A local shadows every file in the module, so it is not an ambiguous global.** Callers reach
    // here speculatively — `ch.toBytes()` asks whether `ch` names a type before deciding it does not
    // — and a speculative question whose answer is discarded must not leave the module unemittable.
    if (this.localAt(name) >= 0) { return name; }
    i32 f = this.fileOf(line);
    // This file's own declaration first — shadowing, as the language has it.
    for (i32 i = 0; i < this.declCount; i++) {
      if (this.declNames[i] == name && this.declFiles[i] == f) { return this.declKeys[i]; }
    }
    // Then **the import that names it**. `import { p } from "./a.wac"` says where `p` comes from,
    // exactly, and using it is the difference between resolving a name and guessing at it — this is
    // the language's own rule rather than an approximation of it.
    for (i32 e = 0; e < this.importCount; e++) {
      if (this.importFrom[e] != f || this.importNames[e] != name) { continue; }
      for (i32 i = 0; i < this.declCount; i++) {
        if (this.declNames[i] == this.importDecls[e] && this.declFiles[i] == this.importTo[e]) {
          return this.declKeys[i];
        }
      }
    }
    // Then a file this one imports, whatever it named — a type reached through another type is not
    // in anybody's import list, and **only if exactly one of them has it**, since the file-level
    // answer is a guess whenever two of them do.
    string imported = "";
    i32 importedCandidates = 0;
    for (i32 i = 0; i < this.declCount; i++) {
      if (this.declNames[i] != name) { continue; }
      for (i32 e = 0; e < this.importCount; e++) {
        if (this.importFrom[e] != f || this.importTo[e] != this.declFiles[i]) { continue; }
        if (imported != this.declKeys[i]) { importedCandidates = importedCandidates + 1; }
        imported = this.declKeys[i];
      }
    }
    if (importedCandidates > 1) {
      this.ambiguous = true;
      if (this.ambiguousName == "") { this.ambiguousName = name; }
    }
    if (imported != "") { return imported; }
    // And then anyone — but **only when there is one candidate**. Reaching a name a file neither
    // declares nor imports is the permissive part of linking, and it is safe exactly while the
    // answer is unambiguous. With two files declaring `P`, picking either is a guess, and the guess
    // shows up as *"expected (ref null 1), got (ref null 7)"* in a third file that mentions neither.
    string found = "";
    i32 candidates = 0;
    for (i32 i = 0; i < this.declCount; i++) {
      if (this.declNames[i] != name) { continue; }
      if (found != this.declKeys[i]) { candidates = candidates + 1; }
      found = this.declKeys[i];
    }
    if (candidates > 1) {
      this.ambiguous = true;
      if (this.ambiguousName == "") { this.ambiguousName = name; }
    }
    return found == "" ? name : found;
  }

  /** The enum a variant belongs to, or `""` — which is also the question "is this a variant". */
  string enumOf(const this, string variant) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantNames[i] == variant) { return this.variantOwners[i]; }
    }
    return "";
  }

  /** Whether a name is an enum's own name, which is what a construction is qualified by. */
  bool isEnumName(const this, string name) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantOwners[i] == name) { return true; }
    }
    return false;
  }

  /** Where a variant is in the table, so its tag, slot and arity come from one lookup. */
  /**
   * The key of `owner`'s variant written `written`, or `""`.
   *
   * **A variant is resolved inside its enum, not through the file.** `Kind.Tree` asked the name
   * table what `Tree` meant and got `packages/git/src/tree.wac`'s *struct* — the key a second
   * declaration of a name is given — so the qualified form stopped being a variant construction at
   * all, and the walk fell through to reading `Kind` as a value: *unresolved name Kind*. The `@` in
   * a shadowed key cannot appear in an identifier, so matching the prefix is exact.
   * `spec/cases/0099`.
   */
  string variantKeyIn(const this, string owner, string written) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantOwners[i] != owner) { continue; }
      if (this.variantNames[i] == written) { return this.variantNames[i]; }
      if (this.variantNames[i].len() > written.len() &&
          this.variantNames[i].slice(0, written.len() + 1) == written + "@") {
        return this.variantNames[i];
      }
    }
    return "";
  }

  i32 variantAt(const this, string variant) {
    for (i32 i = 0; i < this.variantCount; i++) {
      if (this.variantNames[i] == variant) { return i; }
    }
    return -1;
  }

  /**
   * A type name as the *type section* knows it: a variant and its enum are one struct.
   *
   * Everywhere a wac type name reaches wasm — a local's declaration, a field, a parameter — it goes
   * through here first, so `Circle c` and `Shape s` are the same wasm type and neither needs a cast
   * to become the other.
   */
  string canonType(const this, string name) {
    string e = this.enumOf(name);
    return e == "" ? name : e;
  }

  void addLocal(this, string name, string ty) {
    if (this.localCount >= this.locals.len()) {
      this.ranOut("locals in one function");
      return;
    }
    this.locals[this.localCount] = name;
    this.localTypes[this.localCount] = ty;
    if (this.localCount < this.localCell.len()) { this.localCell[this.localCount] = false; }
    this.localCount = this.localCount + 1;
  }
}

/** Whether a declaration is a function this slice can emit. */
bool emittable(Decl d) {
  match (d.kind) {
    case Func(nameTok, returnType, params, body, exported, typeParams): {
      return typeParams.len() == 0;
    }
    else: { return false; }
  }
}

/** Every array type a body mentions, whether as a local's type or as something it constructs. */
void collectArrayTypes(Env env, u8[] src, Lexed lexed, Stmt[] body) {
  for (i32 i = 0; i < body.len(); i++) {
    match (body[i].kind) {
      case Var(type, nameTok, init, isConst): {
        registerNamed(env, typeOfTyName(env, src, lexed, type));
        collectArrayTypesOfExpr(env, src, lexed, init);
      }
      // **The expressions too.** This walk looked only at what a `var` *declared*, so a type named
      // by a construction, a cast or an argument was invisible until the moment it was emitted —
      // which is one type past the end of a section already written.
      case ExprStmt(e2): { collectArrayTypesOfExpr(env, src, lexed, e2); }
      case Return(value): {
        if (!(value is null)) { collectArrayTypesOfExpr(env, src, lexed, value!); }
      }
      case Assign(target, op, rhs): { collectArrayTypesOfExpr(env, src, lexed, rhs); }
      case Block(inner): { collectArrayTypes(env, src, lexed, inner); }
      case If(cond, then, els): {
        collectArrayTypesOfExpr(env, src, lexed, cond);
        collectArrayTypes(env, src, lexed, then);
        collectArrayTypes(env, src, lexed, els);
      }
      case While(cond, inner): {
        collectArrayTypesOfExpr(env, src, lexed, cond);
        collectArrayTypes(env, src, lexed, inner);
      }
      case DoWhile(inner, cond): {
        collectArrayTypesOfExpr(env, src, lexed, cond);
        collectArrayTypes(env, src, lexed, inner);
      }
      case For(init, cond, update, inner): {
        if (!(init is null)) { collectArrayTypes(env, src, lexed, Stmt[](init!)); }
        if (!(cond is null)) { collectArrayTypesOfExpr(env, src, lexed, cond!); }
        if (!(update is null)) { collectArrayTypes(env, src, lexed, Stmt[](update!)); }
        collectArrayTypes(env, src, lexed, inner);
      }
      case Switch(subject, cases): {
        collectArrayTypesOfExpr(env, src, lexed, subject);
        for (i32 c = 0; c < cases.len(); c++) {
          if (!(cases[c].value is null)) {
            collectArrayTypesOfExpr(env, src, lexed, cases[c].value!);
          }
          collectArrayTypes(env, src, lexed, cases[c].body);
        }
      }
      // **An arm is a block.** The enum spec says five separate walks were missing this case, and
      // each failure was a type or a name reachable only through an arm — invisible here, and
      // reported by wasm as something else entirely.
      case Match(subject, arms): {
        collectArrayTypesOfExpr(env, src, lexed, subject);
        for (i32 a = 0; a < arms.len(); a++) { collectArrayTypes(env, src, lexed, arms[a].body); }
      }
      else: { }
    }
  }
}

/**
 * Every local a body declares, in the order wasm will number them.
 *
 * Collected before anything is emitted, exactly as the checker collects names before walking a body,
 * and for a related reason: the locals *declaration* comes before the code that uses them, so the
 * count has to be known first. Nested blocks contribute theirs — wasm has one flat frame per
 * function, whatever the language's scopes look like.
 */
void collectLocals(Env env, u8[] src, Lexed lexed, Stmt[] body) {
  for (i32 i = 0; i < body.len(); i++) {
    match (body[i].kind) {
      case Var(type, nameTok, init, isConst): {
        env.addLocal(tokenTextOf(src, lexed, nameTok), typeOfTyName(env, src, lexed, type));
      }
      case Block(inner): { collectLocals(env, src, lexed, inner); }
      case If(cond, then, els): {
        collectLocals(env, src, lexed, then);
        collectLocals(env, src, lexed, els);
      }
      case While(cond, inner): { collectLocals(env, src, lexed, inner); }
      case DoWhile(inner, cond): { collectLocals(env, src, lexed, inner); }
      case For(init, cond, update, inner): {
        if (!(init is null)) {
          match (init!.kind) {
            case Var(type, nameTok, ini, isConst): {
              env.addLocal(tokenTextOf(src, lexed, nameTok), typeOfTyName(env, src, lexed, type));
            }
            else: { }
          }
        }
        collectLocals(env, src, lexed, inner);
      }
      // An arm's *bindings* are not collected here — they are added while the arm is emitted and
      // retired after it, which is what makes them arm-scoped. Its `var`s are ordinary locals and
      // have to be, or a declaration inside an arm has no slot and every use of it reads whatever
      // slot 0 happens to hold.
      case Match(subject, arms): {
        for (i32 a = 0; a < arms.len(); a++) { collectLocals(env, src, lexed, arms[a].body); }
      }
      else: { }
    }
  }
}

/** The last `/` in a path, or -1 — the one piece of path arithmetic everything else here needs. */
i32 lastSlash(string path) {
  for (i32 i = path.len() - 1; i >= 0; i--) {
    if (path[i] == "/") { return i; }
  }
  return -1;
}

/**
 * The file an import names, resolved against the file that wrote it.
 *
 * Only the two spellings a wac import uses — `./x.wac` and `../y/z.wac` — because a path with no
 * prefix is not a file import at all but a capability, and those are declined by name.
 */
export string resolveImport(string from, string rel) {
  string dir = from.slice(0, lastSlash(from) + 1);
  string r = rel;
  for (i32 guard = 0; guard < 64; guard++) {
    if (r.len() >= 2 && r.slice(0, 2) == "./") {
      r = r.slice(2, r.len());
      continue;
    }
    if (r.len() >= 3 && r.slice(0, 3) == "../") {
      r = r.slice(3, r.len());
      // Up one: drop the trailing slash, then everything after the one before it.
      dir = dir.slice(0, dir.len() - 1);
      dir = dir.slice(0, lastSlash(dir) + 1);
      continue;
    }
    return joinDir(dir, r);
  }
  return joinDir(dir, r);
}

/**
 * `dir` (which ends in `/`, or is empty) followed by `r`, with one separator between them.
 *
 * Concatenating them plainly doubles the slash when the path is already rooted: `/main.wac`
 * importing `"/c.wac"` resolved to `//c.wac`, which is a key no file in the program map has. Nothing
 * reported that, because a name whose file never resolved is a name this checker does not know, and
 * unknown is silence — so an entire imported file went missing quietly, and the spec's own
 * `§wac-modconst-import-p7fm2wj` was accepted for want of the file that would have refused it.
 */
string joinDir(string dir, string r) {
  if (dir.len() > 0 && r.len() > 0 && dir.slice(dir.len() - 1, dir.len()) == "/"
      && r.slice(0, 1) == "/") {
    return dir + r.slice(1, r.len());
  }
  return dir + r;
}

/**
 * `core`'s declarations, which ship inside the compiler rather than living in a file.
 *
 * `import { Read } from core;` is not a path — `core` is one thing everywhere, because wac has
 * nominal types and no closures, so two declarations of a shape are two types and no adapter can
 * join them across a repository boundary. The reference embeds this text; so does this, and for the
 * same reason: a capability import is then an ordinary declaration and nothing downstream of the
 * linker has to know it was special.
 *
 * Kept to the declarations. The comments in `compiler/wacCore.ts` are the argument for the type
 * existing, and are not what a compiler needs.
 */
export string coreSource() {
  return "export enum Read {\n" +
         "  Data(u8[] bytes),\n" +
         "  End,\n" +
         "  Failed(string why)\n" +
         "}\n" +
         // **The tree JSX builds**, which is why it is here rather than in a package: the compiler
         // emits the constructor calls, so a tree built in one repository and a renderer in another
         // must name one type or nothing composes — and no author chose the name to be able to fix
         // it. `design/lang/0004`. wacc-only for now; `compiler/README.md` records the omission.
         "export struct Attr {\n" +
         "  string name;\n" +
         "  string value;\n" +
         "}\n" +
         // **`Fragment` is a variant rather than an element with an empty tag**, so that a renderer
         // is *told*: `match` is exhaustive, and a walk written before fragments existed stops
         // compiling with the arm it is missing named. An empty tag would have rendered as `<>`
         // in every renderer that had not heard of them. `design/lang/0006`.
         "export enum Node {\n" +
         "  Element(string tag, Attr[] attrs, Node[] kids),\n" +
         "  Text(string text),\n" +
         "  Fragment(Node[] kids)\n" +
         "}\n";
}

/** A file's text from the table the caller supplied, or `""` when it was not supplied. */
export string sourceOf(string[] paths, string[] sources, string path) {
  for (i32 i = 0; i < paths.len(); i++) {
    if (paths[i] == path) { return sources[i]; }
  }
  return "";
}

/**
 * The entry and everything it imports, transitively, in one buffer with the entry first.
 *
 * **Linking by concatenation**, which is available because of how this emitter already works: every
 * declaration in the module is collected before any function is emitted, so a name declared in
 * another file is reached exactly as one declared further down the same file is. What that gives up
 * is per-file scope — a file here can see a name it never imported — and giving it up is safe in one
 * direction only: this emitter *accepts* more than the language does, and the checker one rung down
 * is what says no. It could not make a program mean something different.
 *
 * The entry goes first so that the decls belonging to it are a prefix, which is what decides who may
 * be exported: the module's exports are the entry's, and an imported file's `export` marks a name as
 * reachable across files rather than as a wasm export.
 *
 * `""` means a file was named that the caller did not supply — the one failure this cannot paper
 * over, since the missing declarations would otherwise look merely undefined.
 */
/** How many newlines a source has, which is what its span in the linked blob costs. */
i32 countLines(string s) {
  u8[] b = s.toBytes();
  i32 n = 0;
  for (i32 i = 0; i < b.len(); i++) {
    if (b[i] == 10) { n = n + 1; }
  }
  return n;
}

string linkFiles(string[] paths, string[] sources, string entry, i32[] starts, i32[] edges,
                 string[] names, string[] filePaths) {
  // **Sized for the largest program here, which is `packages/box` at 168 files and climbing.** These
  // were 256 and 1024, and a program that outgrew them was reported as *"an import of a file that
  // was not supplied"* — the same `return ""` a genuinely missing file takes, so the message named
  // the wrong cause and six of box's programs looked like they had a broken import [issue 0106].
  string[] queue = string[1024]();
  string[] seen = string[1024]();
  // The import edges, by path: a file is imported before it has an index, so the pairs are recorded
  // as they are read and turned into indices once every file has one.
  string[] fromPath = string[8192]();
  string[] toPath = string[8192]();
  string[] edgeName = string[8192]();
  i32 en = 0;
  i32 qn = 1;
  i32 sn = 0;
  queue[0] = entry;
  string out = "";
  i32 outLines = 0;   // newlines in `out`, maintained rather than recounted
  // **Collected, then combined in halves.** `out = out + body` copies everything accumulated so
  // far at every step, so linking n files copies the blob about n/2 times over — 110 MB for
  // `packages/box`'s 170, and 68% of what linking costs now the line recount is gone. Pairing
  // repeatedly copies it log2(n) times instead, about 10 MB for the same input. One entry per
  // file, and the walk below refuses past `seen.len()`, so this is exactly big enough.
  string[] parts = string[1024]();
  i32 partCount = 0;
  for (i32 qi = 0; qi < qn; qi++) {
    string path = queue[qi];
    bool dup = false;
    for (i32 i = 0; i < sn; i++) {
      if (seen[i] == path) { dup = true; }
    }
    if (dup) { continue; }
    if (sn >= seen.len()) { return ""; }
    seen[sn] = path;
    sn = sn + 1;
    string body = path == " core" ? coreSource() : sourceOf(paths, sources, path);
    if (body == "") { return ""; }
    // A newline between files, so a file that ends mid-line cannot join itself to the next one —
    // and the line each file begins on, which is the whole of how a name is scoped to it afterwards.
    // **A running count, not a rescan.** This was `countLines(out)`, which calls `s.toBytes()` on
    // the whole blob so far and walks it — once per file, over a string growing towards a megabyte.
    // `packages/box` links 170 files, so it allocated and scanned about 110 MB to answer 170
    // questions whose answers it already had. The value is identical: `out` only ever grows by
    // `body + "\n"`.
    if (starts.len() > sn) { starts[sn] = outLines + 1; }
    // **And what the file was called.** The line boundaries say which file a declaration came from
    // and nothing said what its name was, which is the whole of what a bind name for a
    // monomorphisation needs: the reference spells `Vec<string>` from `packages/std/src/vec.wac` as
    // `Vec__packages_std_src_vec$string`. `issues/lang/0089`.
    if (filePaths.len() > sn - 1) { filePaths[sn - 1] = path; }
    if (partCount < parts.len()) { parts[partCount] = body + "\n"; partCount = partCount + 1; }
    outLines = outLines + countLines(body) + 1;
    u8[] b = body.toBytes();
    Lexed lexed = lex(b);
    P p = P.create(b, lexed.tokens, lexed.tokenCount);
    Program prog = parseProgram(p);
    for (i32 d = 0; d < prog.decls.len(); d++) {
      match (prog.decls[d].kind) {
        case Import(pathTok, prefixTok, items): {
          // A capability import names no file, so it cannot be resolved into one — it is *carried*
          // instead, under a path no source can spell, which makes it a file to everything below.
          if (prefixTok >= 0) {
            if (tokenTextOf(b, lexed, prefixTok) != "core") { continue; }
            if (qn >= queue.len()) { return ""; }
            queue[qn] = " core";
            qn = qn + 1;
            for (i32 it = 0; it < items.len(); it++) {
              if (en >= fromPath.len()) { continue; }
              fromPath[en] = path;
              toPath[en] = " core";
              edgeName[en] = tokenTextOf(b, lexed, items[it].aliasTok) + " " +
                             tokenTextOf(b, lexed, items[it].nameTok);
              en = en + 1;
            }
            continue;
          }
          string quoted = tokenTextOf(b, lexed, pathTok);
          if (quoted.len() < 2) { continue; }
          if (qn >= queue.len()) { return ""; }
          string target = resolveImport(path, quoted.slice(1, quoted.len() - 1));
          queue[qn] = target;
          qn = qn + 1;
          // The edge is recorded by *path*, and turned into file indices once every file has one:
          // an import often names a file this walk has not reached yet.
          // One edge per *name*, plus one for the file itself, so a type reached through another
          // file's declaration still resolves.
          if (en < fromPath.len()) {
            fromPath[en] = path;
            toPath[en] = target;
            edgeName[en] = "";
            en = en + 1;
          }
          for (i32 it = 0; it < items.len(); it++) {
            if (en >= fromPath.len()) { continue; }
            fromPath[en] = path;
            toPath[en] = target;
            // The alias and the declared name travel together, separated by a space that no
            // identifier can contain — the same trick the synthesized helpers' names use.
            edgeName[en] = tokenTextOf(b, lexed, items[it].aliasTok) + " " +
                           tokenTextOf(b, lexed, items[it].nameTok);
            en = en + 1;
          }
        }
        else: { }
      }
    }
  }
  // Paths to indices, now that `seen` is complete.
  edges[0] = 0;
  for (i32 e = 0; e < en; e++) {
    i32 a = -1;
    i32 b = -1;
    for (i32 i = 0; i < sn; i++) {
      if (seen[i] == fromPath[e]) { a = i; }
      if (seen[i] == toPath[e]) { b = i; }
    }
    if (a < 0 || b < 0) { continue; }
    i32 ec = edges[0];
    // **Losing an edge here is not losing an edge.** `import { Host } from "./host.wac"` is the only
    // thing that says which file `Host` means; drop it and the name falls through to the permissive
    // module-wide lookup, which finds another file's `Backing.Host`, calls the name ambiguous, and
    // declines the whole module. `packages/box` needs 2,236 of these and the table held 2,047, so
    // six programs emitted eight bytes and blamed a call seven levels down [issue 0106]. Failing the
    // link is loud; the quiet `continue` that used to be here is what made it take a night.
    if (ec * 2 + 2 >= edges.len() || ec >= names.len()) { return ""; }
    edges[ec * 2 + 1] = a;
    edges[ec * 2 + 2] = b;
    names[ec] = edgeName[e];
    edges[0] = ec + 1;
  }
  i32 span = partCount;
  while (span > 1) {
    i32 w = 0;
    for (i32 i = 0; i < span; i = i + 2) {
      parts[w] = i + 1 < span ? parts[i] + parts[i + 1] : parts[i];
      w = w + 1;
    }
    span = w;
  }
  out = partCount > 0 ? parts[0] : "";
  return out;
}

/** How many declarations the entry file contributes, which is how far the exports reach. */
i32 declCountOf(string source) {
  u8[] b = source.toBytes();
  Lexed lexed = lex(b);
  P p = P.create(b, lexed.tokens, lexed.tokenCount);
  return parseProgram(p).decls.len();
}

/**
 * A module for the functions this slice understands.
 *
 * Four sections and no more: types, functions, exports, code. No memory, no globals, no tables —
 * none of which an `i32` calculation needs, and each of which is a section that can be added when
 * something needs it rather than because a real module usually has one.
 */
export u8[] emitModule(u8[] src) {
  return emitModuleOf(src, -1, i32[1](), i32[1](), string[1](), string[1]());
}

/**
 * Whether emitting would register a type the section was already sized without.
 *
 * Asked by running the emitter and looking at what came back: a module of eight bytes with nothing
 * else wrong is that case and no other, since every other reason has already been reported by name.
 */
bool grewTypesWhileEmitting(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names) {
  return emitModuleOf(src, entryDecls, starts, edges, names, string[1]()).len() == 8;
}

/**
 * One module from many files: the entry, everything it imports, and nothing else.
 *
 * The caller supplies the files because this compiler is a wasm module and has no filesystem — which
 * is the same reason the reference takes a map rather than a directory. A path it names and the
 * caller did not supply is a bare module rather than a wrong one.
 */
/**
 * The same module instrumented: a counter per branch point, and `__cov_init/_len/_get` to read them.
 *
 * The table saying what each counter *is* comes from `covTableLinked`, which emits the module and
 * throws the bytes away — the numbering is emission order, so the only way to know it is to emit.
 */
export u8[] emitLinkedCovered(string[] paths, string[] sources, string entry) {
  return emitLinkedWith2(paths, sources, entry, false, true, false);
}

/**
 * The same module instrumented for a *trace*: an ordered journal of branches and array indices.
 *
 * Coverage answers "was this reached"; this answers "in what order, and with what index" — which is
 * the question a constant-time check asks, because a secret-dependent index has no branch at all.
 * `harness/ctTrace.ts` runs a function twice with one public input and two secrets and compares.
 */
export u8[] emitLinkedTraced(string[] paths, string[] sources, string entry) {
  return emitLinkedTracedSlots(paths, sources, entry, 0);
}

/**
 * The same, with the journal sized by the caller — `slots` i32s, or 0 for the default.
 *
 * The cost is paid only by an instrumented build, which is why it is the caller's number rather than
 * a larger constant: 2^26 events is half a gigabyte, fine for a deliberate measurement and not for
 * every run. `issues/lang/0059`.
 */
export u8[] emitLinkedTracedSlots(string[] paths, string[] sources, string entry, i32 slots) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return bareModule(); }
  Env env = Env.create();
  env.trace = true;
  env.traceSlots = slots;
  return emitModuleOfInto(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)), starts,
                          edges, names, filePaths, false, true, env);
}

/** `index\tline\tcol\tkind` per point, in counter order. */
export string covTableLinked(string[] paths, string[] sources, string entry) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return ""; }
  Env env = Env.create();
  return covTableOf(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)), starts, edges,
                    names, filePaths, false);
}

/** `index\tline\tcol\tkind\tfile` per point of a *traced* build, which has the index points too. */
export string traceTableLinked(string[] paths, string[] sources, string entry) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return ""; }
  return covTableOf(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)), starts, edges,
                    names, filePaths, true);
}

/**
 * The structs and enums a host can hold, and what it can do with them.
 *
 * The *bind set* — the same types the emitter writes helpers for, because glue for anything else
 * would call a function that is not there. Each line carries the helper's own name as well as the
 * wac one: a monomorphisation binds as `Vec__packages_std_src_vec$string`, and a generator that
 * rebuilt that spelling from the wac name would be reimplementing `mangleType` by eye.
 *
 *     S<TAB>Name<TAB>bindName<TAB>field:type,field:type
 *     E<TAB>Name<TAB>bindName<TAB>Variant:field:type|field:type;Variant:
 *     M<TAB>bindName<TAB>method<TAB>this|static<TAB>ret<TAB>param,param
 */
/**
 * One link, one parse, one settled `Env` — the prefix every walk that *describes* a module rebuilds.
 *
 * `bindTypesLinked`, `exportSigsLinked`, `emitBlockedOf` and the emitter each opened with the same
 * forty lines: allocate the linker's four tables, link, lex, parse, load the file table and the
 * import edges, then `collectDeclarations`, `assignGlobals` and `settleEmittable`. The last of
 * those is a fixed point over every declaration, and a build ran it four times — which is most of
 * what a build costs. `issues/lang/0129` has the measurements.
 */
struct Front {
  Env env;
  u8[] src;
  Lexed lexed;
  Program prog;
  /** The linker's tables, which the blocked walk still reads after the `Env` is built. */
  i32[] starts;
  i32[] edges;
  string[] names;
  i32 entryDecls;
  /** Decided in the prefix and read by codegen, which is the only reason they travel. */
  bool needsStrings;
  bool startNeeded;
}

/** `null` where the callers each used to return `""`: the graph did not link. */
Front? frontOf(string[] paths, string[] sources, string entry) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return null; }
  return frontOfRaw(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)),
                    starts, edges, names, filePaths, false, false, Env.create());
}

export string bindTypesLinked(string[] paths, string[] sources, string entry) {
  Front? f = frontOf(paths, sources, entry);
  if (f is null) { return ""; }
  return bindTypesOf(f!);
}

string bindTypesOf(Front f) {
  Env env = f.env;
  u8[] src = f.src;
  Lexed lexed = f.lexed;
  Program prog = f.prog;

  string[] bindStructs = string[512]();
  i32 n = collectBindStructs(env, src, lexed, prog, bindStructs, env.entryDecls);
  string out = "";
  // **The callbacks, in the order the imports are numbered.** `cb0` is this line's `0`, and a host
  // that supplies its dispatchers in another order would answer the wrong callback. The same walk
  // the emitter uses, so the two cannot drift.
  env.cbSigCount = collectCallbackSigs(env, src, lexed, prog);
  env.outSigCount = collectOutSigs(env, src, lexed, prog, env.outSigs);
  for (i32 j = 0; j < env.outSigCount; j++) {
    string og = env.outSigs[j];
    string line = "O\t" + numText(j) + "\t" + sigReturn(og) + "\t";
    for (i32 i = 0; i < sigParamCount(og); i++) {
      if (i > 0) { line = line + ","; }
      line = line + sigParamAt(og, i);
    }
    out = out + line + "\t" + og + "\n";
  }
  for (i32 j = 0; j < env.cbSigCount; j++) {
    string cb = env.cbSigs[j];
    string line = "C\t" + numText(j) + "\t" + sigReturn(cb) + "\t";
    for (i32 i = 0; i < sigParamCount(cb); i++) {
      if (i > 0) { line = line + ","; }
      line = line + sigParamAt(cb, i);
    }
    out = out + line + "\t" + cb + "\n";
  }
  for (i32 i = 0; i < n; i++) {
    string name = bindStructs[i];
    // **The name the helpers were exported under.** A plain struct keeps its own — `$bind$s_Point_new`
    // — and only a monomorphisation is qualified and mangled. `collectBindStructs` holds no
    // instances, so this set is the plain half; saying `bindTypeSpelling` here would have qualified
    // every one of them and sent the glue looking for helpers nobody exported.
    //
    // The exception is a name two modules declare: those are qualified at the export sites, and
    // this has to say the same thing or the glue looks for a helper that is not there [issue 0100].
    string bind = bindNameFor(env, src, lexed, name);
    if (env.isEnumName(name)) {
      string line = "E\t" + metaTypeSpelling(env, name) + "\t" + bind + "\t";
      bool first = true;
      for (i32 v = 0; v < env.variantCount; v++) {
        if (env.variantOwners[v] != name) { continue; }
        if (!first) { line = line + ";"; }
        first = false;
        line = line + bareVariantName(env.variantNames[v]) + ":";
        for (i32 k = 0; k < env.variantArity[v]; k++) {
          if (k > 0) { line = line + "|"; }
          i32 slot = env.variantSlot[v] + k;
          line = line + payloadFieldName(env.fieldNameAt(name, slot)) + ":" +
                 metaTypeSpelling(env, env.fieldTypeAt(name, slot));
        }
      }
      out = out + line + "\n";
    } else {
      if (!bindableStruct(env, name)) { continue; }
      // `metaTypeSpelling` rather than `metaNameOf`: an instance is a *type*, and each name inside
      // it needs mapping — `Vec<Word@10>` is one key to `metaNameOf` and two names to this
      // [issue 0102].
      string line = "S\t" + metaTypeSpelling(env, name) + "\t" + bind + "\t";
      i32 fc = env.fieldCountOf(name);
      for (i32 f = 0; f < fc; f++) {
        if (f > 0) { line = line + ","; }
        line = line + env.fieldNameAt(name, f) + ":" +
               metaTypeSpelling(env, env.fieldTypeAt(name, f));
      }
      out = out + line + "\n";
    }
      // **The other names this type answers to**, one `A` line each: the identity, then a spelling
    // that collapses onto it. A host written against a compiler that keeps `T?` apart asks for
    // `Pending$u8ArrOpt`; here that is the same class as `Pending$u8Arr`, and saying so is the
    // honest way to answer [issue 0106].
    for (i32 a = 0; a < env.aliasCount; a++) {
      if (env.aliasOf[a] != name) { continue; }
      out = out + "A\t" + metaTypeSpelling(env, name) + "\t" +
            metaTypeSpelling(env, env.aliasName[a]) + "\n";
    }
  // The methods, under the names the module exports them by.
    //
    // **An instance's methods are its template's**, written in terms of type parameters — so the
    // substitution has to be pushed for the signatures to come out as `Setting` rather than as `T`.
    // The owner is the instance key either way, which is what the module registered them under.
    string tpl = isInstance(name) ? templateOf(name) : "";
    for (i32 d = 0; d < prog.decls.len(); d++) {
      match (prog.decls[d].kind) {
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (typeParams.len() > 0) {
            if (tpl == "" || tokenTextOf(src, lexed, nameTok) != tpl) { continue; }
            i32 pushed = pushSubstitution(env, src, lexed, typeParams, name, tpl);
            out = out + methodLines(env, src, lexed, bind, name, methods);
            popSubstitution(env, pushed);
            continue;
          }
          if (nameKeyOf(env, src, lexed, nameTok) != name) { continue; }
          out = out + methodLines(env, src, lexed, bind, name, methods);
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (typeParams.len() > 0) {
            if (tpl == "" || tokenTextOf(src, lexed, nameTok) != tpl) { continue; }
            i32 epushed = pushSubstitution(env, src, lexed, typeParams, name, tpl);
            out = out + methodLines(env, src, lexed, bind, name, methods);
            popSubstitution(env, epushed);
            continue;
          }
          if (nameKeyOf(env, src, lexed, nameTok) != name) { continue; }
          out = out + methodLines(env, src, lexed, bind, name, methods);
        }
        else: { }
      }
    }
  }
  return out;
}

/** One `M` line per method the module actually emitted for this owner. */
string methodLines(Env env, u8[] src, Lexed lexed, string bind, string owner, Method[] methods) {
  string out = "";
  for (i32 m = 0; m < methods.len(); m++) {
    string mn = tokenTextOf(src, lexed, methods[m].nameTok);
    i32 at = env.funcAt(owner + "." + mn);
    if (at < 0 || env.funcIndex[at] < 0) { continue; }
    string line = "M\t" + bind + "\t" + mn + "\t" + (methods[m].hasThis ? "this" : "static") +
                  "\t" + metaTypeOfTy(env, src, lexed, methods[m].returnType) + "\t";
    for (i32 i = 0; i < methods[m].params.len(); i++) {
      if (i > 0) { line = line + ","; }
      line = line + metaTypeOfTy(env, src, lexed, methods[m].params[i].type);
    }
    out = out + line + "\n";
  }
  return out;
}

/**
 * What a host needs to know about a module's exports, as `name\tret\tparam,param` per line.
 *
 * The types are wac's own — `i32`, `string`, `u8[]`, a struct's name — because the generator on the
 * other side decides how each crosses, and only the compiler knows which functions are exported and
 * what they take. This is the half of bindgen that cannot live outside the compiler; the rest is
 * text, and `packages/wacc/tools/waccBindgen.ts` writes it.
 */
export string exportSigsLinked(string[] paths, string[] sources, string entry) {
  Front? f = frontOf(paths, sources, entry);
  if (f is null) { return ""; }
  return exportSigsOf(f!);
}

/**
 * Three of a build's four questions from **one** front end: why anything was declined, then the
 * export signatures, then the bind types, each separated by a line of its own.
 *
 * A build asked for these separately and paid for the whole front end twice — see `frontOf`. The
 * two are wanted together every time (`harness/waccBuild.ts` calls both, one after the other, and
 * hands both to bindgen), so the calls being separate bought nothing.
 *
 * **The two now share an `Env`, which is the whole hazard.** `bindTypesOf` writes to it —
 * `cbSigCount`, `outSigCount`, the bind-struct table — where `exportSigsOf` only reads what
 * `settleEmittable` left. Signatures run first as a matter of defence, the read-only walk before
 * the writing one; that is a choice rather than a requirement, and swapping them was measured to
 * change no output at all. What makes the sharing safe today is that `exportSigsOf` reads nothing
 * `bindTypesOf` writes, and that is a property somebody can break without noticing —
 * `test/describe_wac.test.ts` compares this against the two separate calls for that reason.
 */
export string describeLinked(string[] paths, string[] sources, string entry) {
  Front? f = frontOf(paths, sources, entry);
  // A graph that does not link is not silence: `blockedFiles` says which of the two ways it failed
  // and the other two answer `""`, so the folded form has to fill the same three slots or a build
  // would carry on with no signatures and nothing said.
  if (f is null) { return linkFailure(paths, sources, entry) + describeSep() + describeSep(); }
  // Blocked first: it is the one that gates the build, so it runs against the `Env` exactly as it
  // found it when it had one to itself. The other two are then checked against their standalone
  // answers by `test/describe_wac.test.ts`, which is the only reason to believe this is safe.
  string blocked = blockedOf(f!);
  string sigs = exportSigsOf(f!);
  return blocked + describeSep() + sigs + describeSep() + bindTypesOf(f!);
}

/**
 * What sits between the two halves. A whole line of its own, and not a byte either half can emit:
 * signature lines are `name\tret\tparams` and bind-type lines start with a one-letter tag.
 */
export string describeSep() { return "@@BINDTYPES@@\n"; }

/** A module and everything a build wants said about it, from one front end. */
export struct Built {
  u8[] wasm;
  /** `blockedOf`, `exportSigsOf`, `bindTypesOf`, separated by `describeSep()` — as `describeLinked`. */
  string described;
}

/**
 * The whole of a build's compiler work in one call.
 *
 * `describeFiles` and `emitFiles` each build their own `Front`, so however well the inside is
 * factored a build still paid for two front ends. This is the call that makes it one.
 *
 * **The description walks run before codegen**, because emitting mutates the `Env` heavily and they
 * only read it plus the little `collectCallbackSigs` re-runs that `frontOfRaw` already made
 * idempotent. That the order is safe is not an argument, it is a byte comparison of every emitted
 * module — see `issues/lang/0129`.
 */
export Built buildLinked(string[] paths, string[] sources, string entry) {
  Front? f = frontOf(paths, sources, entry);
  if (f is null) {
    return Built(bareModule(),
                 linkFailure(paths, sources, entry) + describeSep() + describeSep());
  }
  string blocked = blockedOf(f!);
  string sigs = exportSigsOf(f!);
  string types = bindTypesOf(f!);
  return Built(emitModuleOfFront(f!, false, false),
               blocked + describeSep() + sigs + describeSep() + types);
}

string exportSigsOf(Front f) {
  Env env = f.env;
  u8[] src = f.src;
  Lexed lexed = f.lexed;
  Program prog = f.prog;
  i32 entryDecls = env.entryDecls;

  string out = "";
  i32 at = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() > 0) { continue; }
        bool ok = env.funcIndex[at] >= 0;
        at = at + 1;
        if (!ok || !exported) { continue; }
        if (entryDecls >= 0 && d >= entryDecls) { continue; }
        string line = tokenTextOf(src, lexed, nameTok) + "\t" +
                      metaTypeOfTy(env, src, lexed, returnType) + "\t";
        for (i32 i = 0; i < params.len(); i++) {
          if (i > 0) { line = line + ","; }
          line = line + metaTypeOfTy(env, src, lexed, params[i].type);
        }
        out = out + line + "\n";
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 m = 0; m < methods.len(); m++) { at = at + 1; }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 m = 0; m < methods.len(); m++) { at = at + 1; }
      }
      else: { }
    }
  }
  return out;
}

/** `--checked`: the same module with trapping arithmetic. */
export u8[] emitLinkedChecked(string[] paths, string[] sources, string entry) {
  return emitLinkedWith(paths, sources, entry, true);
}

export u8[] emitLinked(string[] paths, string[] sources, string entry) {
  return emitLinkedWith(paths, sources, entry, false);
}

u8[] emitLinkedWith(string[] paths, string[] sources, string entry, bool checked) {
  return emitLinkedWith2(paths, sources, entry, checked, false, false);
}

u8[] emitLinkedWith2(string[] paths, string[] sources, string entry, bool checked, bool covered,
                     bool traced) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return bareModule(); }
  return emitModuleOfWith(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)), starts, edges,
                          names, filePaths, checked, covered, traced);
}

/**
 * Why the **emit** path gave up, which `blockedLinked` cannot say.
 *
 * The two run on different `Env`s: `blockedLinked` asks `frontOf`'s, and emission builds its own in
 * `emitModuleOfWith`. So a decline raised *during* emission is invisible to the blocked walk, which
 * falls back to `grewTypesWhileEmitting` — a check that re-emits and reports "a type this emitter
 * names only while emitting" whenever the result is a bare module, whatever the actual cause was.
 *
 * That message cost four wrong guesses in a row while landing `design/lang/0002` tier two, each one
 * a hypothesis about which type had grown when the real answer was somewhere else entirely. An
 * instrument that says what `env.fullWhy` holds turns that into one reading.
 */
export string emitDeclineLinked(string[] paths, string[] sources, string entry) {
  i32[] starts = i32[1024]();
  i32[] edges = i32[65536]();
  string[] names = string[32768]();
  string[] filePaths = string[1024]();
  string blob = linkFiles(paths, sources, entry, starts, edges, names, filePaths);
  if (blob == "") { return "the graph did not link"; }
  Env env = Env.create();
  emitModuleOfInto(blob.toBytes(), declCountOf(sourceOf(paths, sources, entry)), starts, edges,
                   names, filePaths, false, false, env);
  if (env.fullWhy != "") { return env.fullWhy; }
  if (env.full) { return "declined with no reason recorded"; }
  return "";
}

/**
 * What each lambda in a program captures, as `sig|name:type,name:type` per line.
 *
 * An instrument, for the same reason `emitDeclineLinked` is one: the capture set decides the shape of
 * a generated struct that nothing can see from outside, and a set that is quietly wrong produces a
 * module that still compiles and reads the wrong field. Building the observation first is what turned
 * the emission work from four failed guesses into one reading.
 */
export string lambdaReportLinked(string[] paths, string[] sources, string entry) {
  Front? f = frontOf(paths, sources, entry);
  if (f is null) { return "did not link"; }
  Env env = f!.env;
  string out = "";
  for (i32 li = 0; li < env.lambdaCount; li++) {
    // Position and instantiation first, because together they are the *key* — `issues/lang/0142`.
    // Without the instantiation two copies of one lambda read as one entry repeated, which is
    // exactly the confusion this report exists to settle.
    out = out + numText(env.lambdaLine[li]) + ":" + numText(env.lambdaCol[li]) +
          (env.lambdaInst[li] == "" ? "" : " in " + env.lambdaInst[li]) + " ";
    out = out + (env.lambdaSigs[li] == "" ? "?" : env.lambdaSigs[li]) + "|";
    if (env.lambdaCapCount[li] > 0) {
      i32 st = env.structType(captureStructName(li));
      out = out + (st < 0 ? "NOSTRUCT" : captureStructName(li)) + "=";
    }
    i32 from = li * capsPerLambda();
    for (i32 c = 0; c < env.lambdaCapCount[li]; c++) {
      if (c > 0) { out = out + ","; }
      out = out + env.capNames[from + c] + ":" + env.capTypes[from + c];
    }
    out = out + "\n";
  }
  // The declarations that must become cells, so the mapping is visible before anything depends on
  // it. A capture whose declaration is not listed here would be copied rather than shared.
  out = out + "promoted:";
  for (i32 i = 0; i < env.promotedCount; i++) {
    out = out + " " + numText(env.promotedLine[i]) + ":" + numText(env.promotedCol[i]);
  }
  return out + "\n";
}

/**
 * A captured name, at the point the capture struct is built.
 *
 * Usually an ordinary local of the enclosing function. Inside a lambda that is itself inside another
 * lambda, it may be one of the *outer* lambda's captures instead — which is what transitive capture
 * means in the emitter: the outer carries the name so that it has one to hand to the inner.
 */
void emitExprName(B fb, u8[] src, Lexed lexed, Env env, string name, string ty) {
  // **The cell itself, not what is in it.** This builds the capture record, and the point of the
  // record is that both sides hold the *same* cell — reading through it here would copy the value and
  // give by-value capture, which is what the write gate used to exist to prevent.
  i32 outerCap = env.captureAt(env.emittingLambda, name);
  if (outerCap >= 0) {
    fb.byte(32); fb.u32leb(0);
    fb.byte(251); fb.u32leb(2);
    fb.u32leb(env.structType(captureStructName(env.emittingLambda)));
    fb.u32leb(outerCap);
    return;
  }
  i32 at = env.localAt(name);
  if (at >= 0) { fb.byte(32); fb.u32leb(at); return; }
  env.declineFor("a captured name this emitter could not find: " + name);
}

/**
 * The one-field struct a captured local lives in, so the lambda and the function share one storage.
 *
 * By type rather than by local: two `i32` captures are the same shape, and a type per local would be
 * a type section proportional to the program for no gain. Unwritable, like `$cap$N`.
 */
string cellStructName(string ty) {
  // **The type is mangled into the name, not appended to it.** `"$cell$" + ty` reads back as a type
  // whenever `ty` ends in a suffix the type grammar owns: the cell for a `u8[]` was called
  // `$cell$u8[]`, which every name-to-type path in this emitter parses as *array of `$cell$u8`* — so
  // writing the local\'s valtype registered an array type, after the type section had been sized, and
  // the module was declined with "a type this emitter names only while emitting". Only arrays and
  // nullables were affected; `i32`, `bool`, `string` and every struct captured fine, which is why the
  // gap survived tier two\'s tests.
  //
  // `$a` for `[]` and `$n` for `?`, both unwritable in source, so the name stays one no program can
  // collide with and no longer parses as anything but itself.
  string out = "";
  u8[] tb = ty.toBytes();
  for (i32 i = 0; i < tb.len(); i++) {
    i32 c = tb[i];
    if (c == '[') { continue; }
    if (c == ']') { out = out + "$a"; continue; }
    if (c == '?') { out = out + "$n"; continue; }
    out = out + string.fromCodepoint(c);
  }
  return "$cell$" + out;
}

/**
 * Push the value of a plain name: a capture from the record, or a local, unwrapping a cell either way.
 *
 * Answers whether it emitted anything, so a caller that has further meanings for a bare name — a
 * function reference, a module constant — can go on asking.
 *
 * **Extracted because there were two copies and one of them was wrong.** Reading `n` and writing
 * through `a[i]` both have to unwrap the same cell, and only the read did: `emitLvalue` emitted a bare
 * `local.get`, so inside a lambda it pushed nothing at all for a captured name and outside one it
 * pushed the *cell* where the array belonged. `a[0] = 42` on a captured array trapped, `s.v = 42` on a
 * captured struct silently did nothing, and `a[0]++` silently kept the old value.
 */
bool emitNameValue(B fb, u8[] src, Lexed lexed, Env env, string nm) {
  i32 capIx = env.captureAt(env.emittingLambda, nm);
  if (capIx >= 0) {
    fb.byte(32); fb.u32leb(0);                    // local.get 0 — the capture struct
    fb.byte(251); fb.u32leb(2);                   // struct.get — the cell
    fb.u32leb(env.structType(captureStructName(env.emittingLambda)));
    fb.u32leb(capIx);
    fb.byte(251); fb.u32leb(2);                   // struct.get — the value in it
    fb.u32leb(env.structType(cellStructName(
      env.capTypes[env.emittingLambda * capsPerLambda() + capIx])));
    fb.u32leb(0);
    return true;
  }
  i32 at = env.localAt(nm);
  if (at < 0) { return false; }
  fb.byte(32);
  fb.u32leb(at);
  // A promoted local's slot holds the cell, so reading the name means reading through it.
  if (env.localIsCell(at)) {
    fb.byte(251); fb.u32leb(2);
    fb.u32leb(env.structType(cellStructName(env.localTypes[at])));
    fb.u32leb(0);
  }
  return true;
}

/**
 * Whether a body contains a lambda anywhere — `issues/lang/0142`.
 *
 * Only a *yes or no*, and deliberately so: a lambda inside a generic cannot be recorded, because a
 * generic is emitted once per instantiation and the position key would name all of them at once. The
 * answer is used to decline the module, which is what unsupported has to mean.
 *
 * Reuses the real walk rather than duplicating it — a second traversal that agrees most of the time
 * is the failure this feature has spent the day avoiding. It records into a throwaway `Env`, so
 * nothing it finds reaches the emitter's own tables.
 */
bool bodyHasLambda(u8[] src, Lexed lexed, Stmt[] body) {
  Env scratch = Env.create();
  findLambdas(scratch, src, lexed, body, "");
  return scratch.lambdaCount > 0;
}

/** The base of an instantiation — `Slot<i32>` is `Slot` — or `""` when the name is not one. */
string genericBaseOf(string t) {
  u8[] a = t.toBytes();
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 60) { return t.slice(0, i); }
  }
  return "";
}

/**
 * A type written in a generic's letters, read in the world of one instantiation.
 *
 * `fn[T(i32)]` against `Slot<i32>` is `fn[i32(i32)]`. A whole-word replacement, because a type
 * parameter is a name: `T` inside `Total` is not one, and rewriting it would invent a type.
 * `issues/lang/0141`.
 */
string substGeneric(Env env, string inst, string written) {
  string base = genericBaseOf(inst);
  if (base == "" || written == "") { return written; }
  string out = written;
  for (i32 i = 0; i < 8; i++) {
    string name = env.genericParamAt(base, i);
    if (name == "") { break; }
    out = replaceWord(out, name, typeArgAt(inst, i));
  }
  return out;
}

/** Replace every whole-word occurrence of `name` in `s` — a letter beside it means a different name. */
string replaceWord(string s, string name, string with) {
  u8[] a = s.toBytes();
  u8[] n = name.toBytes();
  if (n.len() == 0) { return s; }
  string out = "";
  i32 i = 0;
  while (i < a.len()) {
    bool hit = i + n.len() <= a.len();
    for (i32 k = 0; hit && k < n.len(); k++) { if (a[i + k] != n[k]) { hit = false; } }
    if (hit && i > 0 && isWordByte(a[i - 1])) { hit = false; }
    if (hit && i + n.len() < a.len() && isWordByte(a[i + n.len()])) { hit = false; }
    if (hit) { out = out + with; i = i + n.len(); }
    else { out = out + s.slice(i, i + 1); i = i + 1; }
  }
  return out;
}

/**
 * A byte that can be part of an identifier, so a match beside one is not a whole word.
 *
 * `i32`, not `u8`: a packed type is an array *element* type in wac and cannot be a parameter — an
 * element reads and writes as an `i32`, which is what the caller is passing.
 */
bool isWordByte(i32 b) {
  return (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 95;
}

/** The generated struct a capturing lambda carries — unwritable, so no source can collide with it. */
string captureStructName(i32 li) { return "$cap$" + numText(li); }

/** How many captures one lambda has room for — a slab each, so nesting cannot interleave them. */
i32 capsPerLambda() { return 32; }

/** A module with nothing in it, for the cases where emitting anything would be a guess. */
u8[] bareModule() {
  u8[] out = u8[8]();
  out[0] = 0;
  out[1] = 97;
  out[2] = 115;
  out[3] = 109;
  out[4] = 1;
  return out;
}

/**
 * `entryDecls` is how many declarations may be exported, or -1 when the source is a single file.
 *
 * The two are the same pipeline: linking happens before this, and what arrives is one buffer either
 * way. The count is the only thing that has to survive the join — an imported file's `export` means
 * "visible to the file that imported me", not "visible to JavaScript".
 */
/**
 * A struct's fields, **its parent's first** — the shape wasm's `sub` requires of a subtype.
 *
 * A subtype does not inherit fields in the format: it repeats them. That is what makes a
 * `struct.get` compiled against `Shape` read the right slot of a `Rect`, and it is the reason the
 * offset in `Env.inheritedCount` is the whole of inheritance here rather than a special case in
 * every accessor.
 */
i32 countStructFields(Env env, string owner) {
  i32 n = 0;
  for (i32 f = 0; f < env.fieldCount; f++) {
    if (env.fieldOwners[f] == owner) { n = n + 1; }
  }
  string p = env.parentOf(owner);
  return p == "" ? n : n + countStructFields(env, p);
}

void writeStructFields(B types, Env env, string owner) {
  string p = env.parentOf(owner);
  if (p != "") { writeStructFields(types, env, p); }
  for (i32 f = 0; f < env.fieldCount; f++) {
    if (env.fieldOwners[f] != owner) { continue; }
    writeValType(types, env, env.fieldTypes[f]);
    types.byte(1);   // mutable, which every wac field is
  }
}

void emitStructFields(B types, Env env, string owner) {
  types.u32leb(countStructFields(env, owner));
  writeStructFields(types, env, owner);
}

u8[] emitModuleOf(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names,
                  string[] filePaths) {
  return emitModuleOfWith(src, entryDecls, starts, edges, names, filePaths, false, false, false);
}

/** The point table for an instrumented build, which only emitting can produce. */
string covTableOf(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names,
                  string[] filePaths, bool traced) {
  Env probe = Env.create();
  probe.trace = traced;
  emitModuleOfInto(src, entryDecls, starts, edges, names, filePaths, false, true, probe);
  return probe.covTable;
}

u8[] emitModuleOfWith(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names,
                      string[] filePaths, bool checked, bool covered, bool traced) {
  Env env = Env.create();
  env.trace = traced;
  return emitModuleOfInto(src, entryDecls, starts, edges, names, filePaths, checked, covered, env);
}

/**
 * The emitter's front end, and now everybody's: link-less half of `frontOf`, taking the `Env` so
 * the coverage path can hand in its own.
 *
 * This was `emitModuleOfInto`'s first sixty lines, and `frontOf` was a second copy of most of them.
 * Copying the emitter's whole prefix into the description walks was measured to leave
 * `describeFiles` byte-identical across all 80 entries, which is what makes one shared version
 * legitimate rather than merely tidy. `issues/lang/0129`.
 *
 * **The emitter's early `if (env.full) return bareModule()` is deliberately not here.** Consumers
 * answer differently for a full table — `blockedOf` reports `env.fullWhy` — and the emitter's own
 * `ambiguous || full` check after settling still catches it.
 */
Front frontOfRaw(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names,
                 string[] filePaths, bool checked, bool covered, Env envIn) {
  Lexed lexed = lex(src);
  P p = P.create(src, lexed.tokens, lexed.tokenCount);
  Program prog = parseProgram(p);

  Env env = envIn;
  env.checked = checked;
  env.coverage = covered;
  env.entryDecls = entryDecls;

  // The file table first: every key handed out below is derived from it, and a registration made
  // before it is loaded would be scoped to file 0 whatever line it is on.
  for (i32 i = 0; i < starts.len(); i++) {
    if (starts[i] == 0) { continue; }
    env.fileFirstLine[env.fileCount] = starts[i];
    if (env.fileCount < env.filePaths.len() && i - 1 < filePaths.len() && i >= 1) {
      env.filePaths[env.fileCount] = filePaths[i - 1];
    }
    env.fileCount = env.fileCount + 1;
  }
  for (i32 e = 0; e < edges[0]; e++) {
    if (env.importCount >= env.importFrom.len()) { continue; }
    env.importFrom[env.importCount] = edges[e * 2 + 1];
    env.importTo[env.importCount] = edges[e * 2 + 2];
    string pair = e < names.len() ? names[e] : "";
    i32 sp = pair.indexOf(" ");
    env.importNames[env.importCount] = sp < 0 ? pair : pair.slice(0, sp);
    env.importDecls[env.importCount] = sp < 0 ? pair : pair.slice(sp + 1, pair.len());
    env.importCount = env.importCount + 1;
  }
  collectDeclarations(env, src, lexed, prog);
  assignGlobals(env, src, lexed);
  // **A helper is a function like any other**, registered before emittability is settled so a call to
  // it is an ordinary call and the renumbering counts it. Named with a space, which no wac identifier
  // can contain, so it cannot collide with anything the source declares.
  // Only when the module has strings at all: the helper names the `i8[]` type, and registering that
  // while the type section is being written is the "index out of bounds" this rung has hit four times.
  // **The helper set.** Four functions nobody wrote, registered together because they are needed
  // together: a module that has strings at all is likely to compare or join them, and an unused one
  // costs a few dozen bytes. `u8[]` is registered here too — `toBytes` names it, and a type has to
  // exist before the section that declares it is written.
  // **The counter array, before anything counts the array table.** Registering it later would leave
  // the array-accessor family's four signatures per type unregistered for this one, and the type
  // section is sized before those are asked for — which the emitter answers by declining the module.
  if (env.coverage) { env.arrayType("i32[]"); }
  bool needsStrings = env.arrayCount > 0 && hasStringType(env);
  if (needsStrings) {
    env.arrayType("u8[]");
    string[] two = string[2]();
    two[0] = "string";
    two[1] = "string";
    env.addFunc(" str_eq", "bool", two);
    string[] two2 = string[2]();
    two2[0] = "string";
    two2[1] = "string";
    env.addFunc(" str_concat", "string", two2);
    string[] one = string[1]();
    one[0] = "string";
    env.addFunc(" str_to_bytes", "u8[]", one);
    string[] one2 = string[1]();
    one2[0] = "u8[]";
    env.addFunc(" str_from_bytes", "string", one2);
    string[] idx = string[2]();
    idx[0] = "string";
    idx[1] = "i32";
    env.addFunc(" str_idx", "string", idx);
    string[] one3 = string[1]();
    one3[0] = "i32";
    env.addFunc(" str_fromcp", "string", one3);
    string[] three = string[3]();
    three[0] = "string";
    three[1] = "i32";
    three[2] = "i32";
    env.addFunc(" str_slice", "string", three);
    string[] two3 = string[2]();
    two3[0] = "string";
    two3[1] = "string";
    env.addFunc(" str_index_of", "i32", two3);
    // **Last, because it is emitted last.** A helper's index is its position in this list, and the
    // order here has to be the order below — registering the comparison in the middle and emitting
    // it at the end made every call after it reach the wrong function.
    string[] cmp2 = string[2]();
    cmp2[0] = "string";
    cmp2[1] = "string";
    env.addFunc(" str_cmp", "i32", cmp2);
  }
  // A **second round** of the two passes: `assignGlobals` asks whether an initialiser is emittable,
  // and the answer can change once the functions it calls have settled. Cheap, and the alternative
  // is a global assigned from a function that was skipped.
  // **Before anything is numbered.** An imported function occupies index 0, so every index below is
  // measured from the number of them. `issues/lang/0094`.
  env.cbSigCount = collectCallbackSigs(env, src, lexed, prog);
  env.outSigCount = collectOutSigs(env, src, lexed, prog, env.outSigs);
  bool startNeeded = needsStartFunction(env, src, lexed);
  if (startNeeded) { env.addFunc(" start", "void", string[0]()); }
  // **Before `settleEmittable`, which is where each function's decline reason is recorded.** Running
  // the lambda walk after it left `unsupportedExpr` naming a count of 0 in a message that had already
  // been composed — the walk was right and the reader was early. `design/lang/0002` tier two.
  findLambdasInProgram(env, src, lexed, prog);
  // **Once before the fixpoint**, so `settleEmittable` can decide whether an instantiation\'s body is
  // emittable — the question is answered out of these tables, and an instantiation whose lambdas are
  // not in them yet is declined as unsupported. Called again below for the ones that appear *during*
  // the fixpoint; see there.
  findLambdasInInstances(env, src, lexed, prog);
  settleEmittable(env, src, lexed, prog);

  // **The generics' lambdas, after the emittability fixpoint** — `issues/lang/0142`.
  //
  // The order is forced, and both halves of the force are real:
  //
  //   - it must follow `settleEmittable`, because that is where the *last* instantiations appear.
  //     `canEmit` walks bodies and resolves types as it goes, and a generic named only inside a
  //     function that turns out to be emittable is registered there and nowhere earlier. A four-line
  //     program with a lambda capturing inside a generic grows the table from one to two right here.
  //   - it must precede the type registration below, because a lambda in a generic needs a capture
  //     struct and cell types *per instantiation*, and the type table may not grow once `declTypes`
  //     is taken.
  //
  // The issue's notes say this ordering forces a split into a cheap presence pass and a real
  // recording pass. It does not: nothing between the two points needs the lambda tables, so the whole
  // walk moves down and there is no second traversal to disagree with the first. What *is* true, and
  // was written into the issue as a correction and was wrong, is that the instantiation set is
  // settled before the plain walk — it is not, and one program measured is one program.
  findLambdasInInstances(env, src, lexed, prog);

  // **A lambda inside a generic is recorded per instantiation**, not declined — `issues/lang/0142`.
  // `findLambdasInInstances` walks each one with its substitution pushed, and `Env.curInst` is part
  // of the key, so the copies are told apart by the same field the emitter reads back.
  // **A struct per capturing lambda, before anything is counted** — `design/lang/0002` tier two.
  // Its fields are what the walk found the lambda reads from outside itself, in that order, and it
  // is the thing the lambda carries in its env. Registered here because it is a type: the table may
  // not grow once `declTypes` is taken, and a struct named while emitting is the guard's whole
  // reason for existing.
  //
  // The name is unwritable on purpose — no source can declare `$cap$0`, so it cannot collide with a
  // program's own struct, and nothing resolves to it by accident.
  for (i32 li = 0; li < env.lambdaCount; li++) {
    if (env.lambdaCapCount[li] == 0) { continue; }
    string cname = captureStructName(li);
    if (env.structCount >= env.structNames.len()) { env.ranOut("structs"); break; }
    env.structNames[env.structCount] = cname;
    env.structParentToks[env.structCount] = -1;
    env.structParents[env.structCount] = "";
    env.structCount = env.structCount + 1;
    i32 from = li * capsPerLambda();
    for (i32 c = 0; c < env.lambdaCapCount[li]; c++) {
      if (env.fieldCount >= env.fieldNames.len()) { env.ranOut("struct fields"); break; }
      env.fieldOwners[env.fieldCount] = cname;
      env.fieldNames[env.fieldCount] = env.capNames[from + c];
      // **The cell, not the value** — which is the whole of reference semantics: the lambda and the
      // enclosing function hold the same one-field struct, so a write through either is seen by both.
      env.fieldTypes[env.fieldCount] = cellStructName(env.capTypes[from + c]);
      env.fieldNullable[env.fieldCount] = false;
      env.fieldCount = env.fieldCount + 1;
    }
    // The cell struct for each captured type, registered once.
    for (i32 c = 0; c < env.lambdaCapCount[li]; c++) {
      string cellName = cellStructName(env.capTypes[from + c]);
      if (env.structType(cellName) >= 0) { continue; }
      if (env.structCount >= env.structNames.len()) { env.ranOut("structs"); break; }
      env.structNames[env.structCount] = cellName;
      env.structParentToks[env.structCount] = -1;
      env.structParents[env.structCount] = "";
      env.structCount = env.structCount + 1;
      if (env.fieldCount >= env.fieldNames.len()) { env.ranOut("struct fields"); break; }
      env.fieldOwners[env.fieldCount] = cellName;
      env.fieldNames[env.fieldCount] = "v";
      env.fieldTypes[env.fieldCount] = env.capTypes[from + c];
      env.fieldNullable[env.fieldCount] = false;
      env.fieldCount = env.fieldCount + 1;
    }
  }

  return Front(env, src, lexed, prog, starts, edges, names, entryDecls, needsStrings, startNeeded);
}

u8[] emitModuleOfInto(u8[] src, i32 entryDecls, i32[] starts, i32[] edges, string[] names,
                      string[] filePaths, bool checked, bool covered, Env envIn) {
  return emitModuleOfFront(
    frontOfRaw(src, entryDecls, starts, edges, names, filePaths, checked, covered, envIn),
    checked, covered);
}

/** Codegen, from a front somebody else built. */
u8[] emitModuleOfFront(Front f, bool checked, bool covered) {
  bool needsStrings = f.needsStrings;
  bool startNeeded = f.startNeeded;
  Env env = f.env;
  u8[] src = f.src;
  Lexed lexed = f.lexed;
  Program prog = f.prog;
  i32 entryDecls = f.entryDecls;
  i32[] starts = f.starts;
  i32[] edges = f.edges;
  string[] names = f.names;
  // Settling walked every function, so an ambiguous name has been reached by now if there is one.
  if (env.ambiguous || env.full) { return bareModule(); }

  B types = B.create();
  B funcs = B.create();
  B exports = B.create();
  B code = B.create();
  i32 count = 0;
  i32 exportCount = 0;
  i32 countAt = 0;

  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() > 0) { continue; }
        if (env.funcIndex[countAt] < 0) { countAt = countAt + 1; continue; }
        countAt = countAt + 1;
        count = count + 1;
        if (exported && (entryDecls < 0 || d < entryDecls)) { exportCount = exportCount + 1; }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 m = 0; m < methods.len(); m++) {
          if (env.funcIndex[countAt] >= 0) { count = count + 1; }
          countAt = countAt + 1;
        }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 m = 0; m < methods.len(); m++) {
          if (env.funcIndex[countAt] >= 0) { count = count + 1; }
          countAt = countAt + 1;
        }
      }
      else: { }
    }
  }
  // **A pre-pass for the array types.** Their entries come first in the type section, so every
  // function type index is offset by however many there are — and the set is only complete once every
  // signature and every local has been looked at. Walking the declarations twice is the cost of a
  // type that has to be declared before it is used.
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() > 0) { continue; }
        string rt = typeOfTyName(env, src, lexed, returnType);
        registerNamed(env, rt);
        for (i32 i = 0; i < params.len(); i++) {
          string pt = typeOfTyName(env, src, lexed, params[i].type);
          registerNamed(env, pt);
        }
        collectArrayTypesIn(env, src, lexed, params, body);
      }
      // A **module-level constant** names a type as surely as a field or a parameter does, and its
      // initialiser can name another. Third time this pre-pass has been found one declaration short:
      // the rule is *every place a type can be named*, and the list is longer than it looks.
      case ConstDecl(nameTok, type, init, exported): {
        string ct = typeOfTyName(env, src, lexed, type);
        registerNamed(env, ct);
        collectArrayTypesOfExpr(env, src, lexed, init);
      }
      // A struct's **fields** name types too, and an array among them has to be registered before the
      // section is written — otherwise `writeValType` hands out an index while writing it, past the
      // count already emitted, and the module refers to a type that is not there. The symptom is
      // *"invalid array index"*, which names the consequence and not the cause.
      // An enum's payloads are fields, and the rule this pre-pass keeps re-learning is *every place a
      // type can be named*. A `Node(i32[] kids)` whose array type is registered while the type
      // section is being written refers to an index that is not there yet.
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 v = 0; v < variants.len(); v++) {
          for (i32 i = 0; i < variants[v].fields.len(); i++) {
            string vt = typeOfTyName(env, src, lexed, variants[v].fields[i].type);
            registerNamed(env, vt);
          }
        }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() > 0) { continue; }
        for (i32 i = 0; i < fields.len(); i++) {
          string ft2 = typeOfTyName(env, src, lexed, fields[i].type);
          registerNamed(env, ft2);
        }
        for (i32 m = 0; m < methods.len(); m++) {
          string mrt = typeOfTyName(env, src, lexed, methods[m].returnType);
          registerNamed(env, mrt);
          for (i32 i = 0; i < methods[m].params.len(); i++) {
            string mpt = typeOfTyName(env, src, lexed, methods[m].params[i].type);
            registerNamed(env, mpt);
          }
          collectArrayTypesIn(env, src, lexed, methods[m].params, methods[m].body);
        }
      }
      else: { }
    }
  }

  // **After every declaration has named its types**, which is the pass above: a `u8[]` that appears
  // only in a signature — `export u8[] echo(u8[] b)` — is registered there and nowhere earlier, so
  // asking before it answered no for exactly the modules a host most wants to call.
  // **Every array an export can carry, not just `u8[]`.** Each one needs three helpers and two
  // signatures, and the count decides every index after them — see `issues/lang/0089`.
  // **Every array a host can hold, and the accessors it needs to hold one.** `_to_mem` and
  // `_from_mem` move bytes, so only a numeric element has them; `string[]` and `u8[][]` had no
  // helpers at all and a host asking for one saw `$bind$arr_u8Arr_new is not a function`.
  i32 arrHelpers = 0;
  for (i32 bi = 0; bi < env.arrayCount; bi++) {
    if (!bindableArray(env, env.arrayTypes[bi])) { continue; }
    arrHelpers = arrHelpers + arrayHelperCount(env, env.arrayTypes[bi]);
  }
  // The structs a host can hold, and how many helpers they need between them. Computed once: the
  // pre-pass that registers signatures and the emission that writes bodies must agree exactly, and
  // an index that disagrees with a count is a call to the wrong function.
  string[] bindStructs = string[512]();
  i32 bindStructCount = collectBindStructs(env, src, lexed, prog, bindStructs, entryDecls);
  // **An enum is a struct in this emitter's tables and not one at the boundary.** `collectBindStructs`
  // finds both, because it asks `isStructName` — which is the right question for reachability and the
  // wrong one for naming. Emitted as a struct family, `enum Shape { Circle(f64 r) }` exported
  // `$bind$s_Shape_get_ tag` and `$bind$s_Shape_get_Circle.r`: two names no host asks for, with a
  // space and a dot in them. The `e_` family below is what bindgen calls. `issues/lang/0089`.
  i32 structHelpers = 0;
  i32 enumHelpers = 0;
  for (i32 si2 = 0; si2 < bindStructCount; si2++) {
    if (env.isEnumName(bindStructs[si2])) {
      enumHelpers = enumHelpers + enumHelperCount(env, bindStructs[si2]);
    } else if (bindableStruct(env, bindStructs[si2])) {
      structHelpers = structHelpers + structHelperCount(env, bindStructs[si2]);
    }
  }

  // The instances, in the order `collectInstances` registered them: after every declaration and
  // **before the helpers**, which is where their indices are. Getting this wrong is not a subtle
  // bug — every call after the first helper reaches the wrong function — and it is why the last
  // attempt at this compiled the corpus into fifty-seven invalid modules while every hand-written
  // case, which had no strings and so no helpers, passed.
  for (i32 ii = 0; ii < env.instCount; ii++) {
  // **Only the ones registration built.** An instance discovered after the fixed point gave up —
  // or one whose template is not in this module — has no members in the tables, and emitting its
  // methods anyway shifts every index after it. The receiver comes out an `i32`, which wasm
  // reports as a `struct.get` on a number several functions later.
  // A function instance builds no type, so it is "built" when its own entry is registered.
  if (!env.isStructName(env.instName[ii]) && env.funcAt(env.instName[ii]) < 0) { continue; }
    for (i32 di = 0; di < prog.decls.len(); di++) {
      match (prog.decls[di].kind) {
        // One function per instance, in the same place in the order its registration put it.
        case Func(nameTok, returnType, params, body, exported, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          if (env.funcIndex[countAt] >= 0) { count = count + 1; }
          countAt = countAt + 1;
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 epushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                         env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            if (env.funcIndex[countAt] >= 0) { count = count + 1; }
            countAt = countAt + 1;
          }
          popSubstitution(env, epushed);
        }
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 pushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                        env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            if (env.funcIndex[countAt] >= 0) { count = count + 1; }
            countAt = countAt + 1;
          }
          popSubstitution(env, pushed);
        }
        else: { }
      }
    }
  }

  // `+ 1` for `$bind$mem_ensure`, which every module carries: the boundary needs it whenever an
  // exported signature moves bytes, and deciding that here would mean asking what a host will bind.
  // **Where each block of functions begins, said once.** The order is fixed — the user's, then the
  // string helpers, then the buffer, the array families, the struct families, and the start function
  // last — and four places used to spell that arithmetic out separately. They disagreed the moment a
  // family was added between them, which arrives as "invalid start func reference" or as a call to
  // the wrong function several dozen instructions later. `issues/lang/0094` adds imports in front of
  // all of it, and wasm numbers imported functions first, so every one of these gains the same term.
  // **A hoisted lambda is an ordinary function**, so it goes in `count` — which is what gives it a
  // wrapper and a bound wrapper for free, since both families are sized `count`. Emitted immediately
  // after the declared functions, so its ordinal is `lambdaFirst + i`. `design/lang/0002` tier two.
  env.lambdaFirst = count;
  count = count + env.lambdaCount;
  i32 stringHelpers = needsStrings ? 9 : 0;
  i32 memHelperAt = env.cbSigCount + count + stringHelpers;
  i32 arrayHelpersAt = memHelperAt + 1;
  i32 structHelpersAt = arrayHelpersAt + arrHelpers;
  // The six bind-string helpers, for a module that has strings at all — the same condition the
  // reference uses, and the same condition the nine internal ones already carry.
  i32 bindStrHelpers = needsStrings ? 6 : 0;
  i32 cbHelpers = env.cbSigCount * (callbackSlots() + 1);
  i32 covHelpers = env.coverage ? 3 : 0;
  i32 outHelpers = env.outSigCount;
  i32 enumHelpersAt = structHelpersAt + structHelpers;
  i32 bindStrHelpersAt = enumHelpersAt + enumHelpers;
  i32 cbHelpersAt = bindStrHelpersAt + bindStrHelpers;
  i32 covHelpersAt = cbHelpersAt + cbHelpers;
  i32 outHelpersAt = covHelpersAt + covHelpers;
  // `__fmod` and `__fmodf` — `issues/lang/0135`. **Always emitted**, not detected: deciding which
  // modules use `%` on a float means a complete expression walk, and an incomplete one names a
  // function index that does not exist, which is silent and catastrophic. Always-emit is correct by
  // construction — the argument `design/lang/0002` settled for the wrappers — and the reference does
  // the same, emitting both unconditionally.
  //
  // **It costs 269 bytes**, measured on `export i32 f() { return 42; }`: 246 bytes before this and
  // 515 after. That is a large fraction of a module that small and a rounding error in any real one
  // (`packages/bls/src/fp.wac` is 153 functions), but it is the honest figure rather than the
  // hundred-ish this was first written as. If it ever matters, the fix is a reachability walk that
  // has to be *complete*, and the paragraph above is why that is harder than it sounds.
  //
  // Placed after `outHelpers` and before the wrappers so that `wrapAt` and `boundAt`, which are
  // published on `env` and read from other code, keep everything variable in front of them.
  i32 fmodHelpers = 2;
  i32 fmodHelpersAt = outHelpersAt + outHelpers;
  env.fmodAt = fmodHelpersAt;
  // One wrapper per emitted function — `design/lang/0002`. `count` is the right number because the
  // wrappers are built inside `emitFunction`, so the two are the same walk rather than two walks that
  // agree.
  i32 wrapHelpers = count;
  i32 wrapHelpersAt = fmodHelpersAt + fmodHelpers;
  env.wrapAt = wrapHelpersAt;
  // The bound wrappers, one per function as well — `design/lang/0002` step 2.
  i32 boundHelpers = count;
  i32 boundHelpersAt = wrapHelpersAt + wrapHelpers;
  env.boundAt = boundHelpersAt;
  i32 startFunctionAt = boundHelpersAt + boundHelpers;
  i32 helpers = stringHelpers + (startNeeded ? 1 : 0) + 1 + arrHelpers + structHelpers +
                enumHelpers + bindStrHelpers + cbHelpers + covHelpers + outHelpers + fmodHelpers +
                wrapHelpers + boundHelpers;
  funcs.u32leb(count + helpers);
  // Built now for its count, appended at the end of the section: every index it names belongs to a
  // function the walk above has already numbered.
  B methodExports = B.create();
  i32 methodExportCount = bindMethodExports(methodExports, env, src, lexed, prog, bindStructs,
                                            bindStructCount);
  exports.u32leb(exportCount + 2 + arrHelpers + structHelpers + enumHelpers + bindStrHelpers +
                 env.cbSigCount + covHelpers + outHelpers + methodExportCount);
  code.u32leb(count + helpers);

  // **Every function's signature, before the section is sized.** They share the table with the
  // `fn[...]` types the source writes, which is the whole point: a function and a reference to it
  // have to name one type index, not two identical ones.
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() > 0) { continue; }
        registerFuncTypes(env, src, lexed, returnType, params, "");
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() > 0) { continue; }
        string owner2 = nameKeyOf(env, src, lexed, nameTok);
        for (i32 m = 0; m < methods.len(); m++) {
          registerFuncTypes(env, src, lexed, methods[m].returnType, methods[m].params,
                                 methods[m].hasThis ? owner2 : "");
        }
      }
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (typeParams.len() > 0) { continue; }
        string eowner2 = nameKeyOf(env, src, lexed, nameTok);
        for (i32 m = 0; m < methods.len(); m++) {
          registerFuncTypes(env, src, lexed, methods[m].returnType, methods[m].params,
                                 methods[m].hasThis ? eowner2 : "");
        }
      }
      else: { }
    }
  }
  // The instances, in the order `collectInstances` registered them: after every declaration and
  // **before the helpers**, which is where their indices are. Getting this wrong is not a subtle
  // bug — every call after the first helper reaches the wrong function — and it is why the last
  // attempt at this compiled the corpus into fifty-seven invalid modules while every hand-written
  // case, which had no strings and so no helpers, passed.
  for (i32 ii = 0; ii < env.instCount; ii++) {
  // **Only the ones registration built.** An instance discovered after the fixed point gave up —
  // or one whose template is not in this module — has no members in the tables, and emitting its
  // methods anyway shifts every index after it. The receiver comes out an `i32`, which wasm
  // reports as a `struct.get` on a number several functions later.
  // A function instance builds no type, so it is "built" when its own entry is registered.
  if (!env.isStructName(env.instName[ii]) && env.funcAt(env.instName[ii]) < 0) { continue; }
    for (i32 di = 0; di < prog.decls.len(); di++) {
      match (prog.decls[di].kind) {
        case Func(nameTok, returnType, params, body, exported, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 fpushed2 = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                          env.instOf[ii]);
          registerFuncTypes(env, src, lexed, returnType, params, "");
          popSubstitution(env, fpushed2);
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 epushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                         env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            registerFuncTypes(env, src, lexed, methods[m].returnType, methods[m].params,
                                   methods[m].hasThis ? env.instName[ii] : "");
          }
          popSubstitution(env, epushed);
        }
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 pushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                        env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            registerFuncTypes(env, src, lexed, methods[m].returnType, methods[m].params,
                                   methods[m].hasThis ? env.instName[ii] : "");
          }
          popSubstitution(env, pushed);
        }
        else: { }
      }
    }
  }

  // Before `declTypes` is taken, or the type section is sized without it and the module is declined
  // — which is what happened first time round, and the emitter said so by returning eight bytes.
  env.sigType("fn[i32(i32)]");
  // Two signatures per array type: `_len` and `_to_mem` both answer an `i32` from one, `_from_mem`
  // answers one from an `i32`.
  for (i32 bi = 0; bi < env.arrayCount; bi++) {
    string bt = env.arrayTypes[bi];
    if (!bindableArray(env, bt)) { continue; }
    string bel = bindElemType(elemOf(bt));
    if (arrNeedsFill(env, elemOf(bt))) {
      env.sigType("fn[" + bt + "(i32," + bel + ")]");
      env.sigType("fn[" + bt + "()]");
    } else {
      env.sigType("fn[" + bt + "(i32)]");
    }
    env.sigType("fn[" + bel + "(" + bt + ",i32)]");
    env.sigType("fn[void(" + bt + ",i32," + bel + ")]");
    env.sigType("fn[i32(" + bt + ")]");
  }
  for (i32 si3 = 0; si3 < bindStructCount; si3++) {
    string sn = bindStructs[si3];
    if (env.isEnumName(sn)) {
      env.sigType("fn[i32(" + sn + ")]");
      for (i32 v = 0; v < env.variantCount; v++) {
        if (env.variantOwners[v] != sn) { continue; }
        string vparams = "";
        for (i32 k = 0; k < env.variantArity[v]; k++) {
          if (k > 0) { vparams = vparams + ","; }
          vparams = vparams + bindFieldType(env.fieldTypeAt(sn, env.variantSlot[v] + k));
        }
        env.sigType("fn[" + sn + "(" + vparams + ")]");
        for (i32 k = 0; k < env.variantArity[v]; k++) {
          env.sigType("fn[" + bindFieldType(env.fieldTypeAt(sn, env.variantSlot[v] + k)) +
                      "(" + sn + ")]");
        }
      }
      continue;
    }
    if (!bindableStruct(env, sn)) { continue; }
    i32 sfc = env.fieldCountOf(sn);
    string sparams = "";
    for (i32 f = 0; f < sfc; f++) {
      if (f > 0) { sparams = sparams + ","; }
      sparams = sparams + bindFieldType(env.fieldTypeAt(sn, f));
    }
    env.sigType("fn[" + sn + "(" + sparams + ")]");
    for (i32 f = 0; f < sfc; f++) {
      string bft = bindFieldType(env.fieldTypeAt(sn, f));
      env.sigType("fn[" + bft + "(" + sn + ")]");
      env.sigType("fn[void(" + sn + "," + bft + ")]");
    }
  }
  // The dispatcher a host supplies, and the selector that answers a funcref of the callback's type.
  for (i32 j = 0; j < env.cbSigCount; j++) {
    env.sigType(env.cbSigs[j]);
    env.sigType(dispatchSig(env.cbSigs[j]));
    env.sigType("fn[" + env.cbSigs[j] + "(i32)]");
  }
  for (i32 j = 0; j < env.outSigCount; j++) {
    env.sigType(env.outSigs[j]);
    env.sigType(callrefSig(env.outSigs[j]));
  }
  if (env.coverage) {
    env.sigType("fn[void()]");
    env.sigType("fn[i32()]");
    env.sigType("fn[i32(i32)]");
  }
  if (startNeeded) { env.sigType("fn[void()]"); }
  if (needsStrings) {
    env.sigType("fn[bool(string,string)]");
    env.sigType("fn[string(string,string)]");
    env.sigType("fn[u8[](string)]");
    env.sigType("fn[string(u8[])]");
    env.sigType("fn[string(string,i32)]");
    env.sigType("fn[string(i32)]");
    env.sigType("fn[string(string,i32,i32)]");
    env.sigType("fn[i32(string,string)]");
    // **The six a host reaches a string through.** `$bind$str_new/_get/_set/_len/_from_mem/_to_mem`,
    // the same set the reference emits beside its own string helpers — a `string` crosses the
    // boundary as an opaque WasmGC reference and these are the only way to read or fill one.
    // Registered here for the reason every other helper is: the type section is sized before any
    // body is written. `issues/lang/0089`.
    env.sigType("fn[string(i32)]");
    env.sigType("fn[i32(string,i32)]");
    env.sigType("fn[void(string,i32,i32)]");
    env.sigType("fn[i32(string)]");
  }

  // **Room is checked again here, because the helpers ask for types too.** `full` was asked before
  // the walk and not after, and every signature above this line was registered since: a table that
  // filled up answers `sigType` with **0**, which is an *array* index, and the module says *"no
  // signature at index 0"* dozens of functions later. Declining is the same answer this emitter
  // gives for everything else it cannot do. Found by `corpusEmit` on `packages/tor/src/relayd.wac`
  // the moment the array family added two signatures per array type.
  if (env.full) { return bareModule(); }

  // **Every `fn[…]` gets its pair before the count is taken** — `design/lang/0002`. `declTypes` is
  // the number the section is sized from, and the guard at the end of this function declines a module
  // whose table grew after it. So the sweep has to be on this side of the snapshot: run after it, and
  // every program with a funcref in it declines with "a type this emitter names only while emitting",
  // which is that guard doing exactly its job.
  // **The signature a capturing lambda's hoisted function actually has**, which is not the one the
  // value has: it takes the capture struct as a receiver in front. Two types per capturing lambda —
  // that signature and the env-taking one its bound wrapper needs — and neither is registered by
  // anything else, because no declaration names them. The instrument said it exactly: "9 counted,
  // 11 wanted".
  for (i32 li = 0; li < env.lambdaCount; li++) {
    if (env.lambdaCapCount[li] == 0 || env.lambdaSigs[li] == "") { continue; }
    string rsig = emittedSigOf(env, src, lexed, sigReturn(env.lambdaSigs[li]),
                               env.lambdaParams[li], captureStructName(li));
    env.sigType(rsig);
    env.sigType(envSig(rsig));
  }

  // **Before the sweep**, so each one gets its pair: a lambda is a `fn[…]` *value*, so the expression
  // site names `pairType(sig)`, and a signature registered after the sweep has no pair — which the
  // guard below reports as "a type this emitter names only while emitting". The fmod helpers below
  // are registered after it precisely because they are the opposite case.
  for (i32 li = 0; li < env.lambdaCount; li++) {
    if (env.lambdaSigs[li] != "") { env.sigType(env.lambdaSigs[li]); }
  }
  env.pairEverySignature();
  // **`__fmod` and `__fmodf`'s signatures, on this side of the snapshot too** — `issues/lang/0135`.
  // They are always emitted, so they are always named, and naming them from `emitFmodHelpers` grows
  // the table after `declTypes` is taken: every program declined with "a type this emitter names only
  // while emitting", which is the guard below working correctly on a mistake made here.
  //
  // After the sweep rather than before it, so neither gets a pair. They are the types of two helpers
  // this module calls directly, never of an `fn[…]` *value*, so a pair for each would be two struct
  // types and two env signatures per module that nothing can reach.
  env.sigType("fn[f64(f64,f64)]");
  env.sigType("fn[f32(f32,f32)]");

  i32 declTypes = env.arrayCount + env.structCount + env.sigCount;
  // Kept apart so the guard at the end of this function can *name* what grew rather than only
  // count it — see there for why a number was not enough.
  i32 declArrays = env.arrayCount;
  i32 declStructs = env.structCount;
  i32 declSigs = env.sigCount;
  // **One recursive group holding every type.** Outside a rec group a type may only refer to one
  // defined *before* it, and an array of a struct refers forward the moment the struct is declared
  // later — which wasm reports as "type index out of bounds" from the type section itself, with no
  // function to name. A rec group makes the whole set mutually visible, which is also why the
  // reference emits exactly one for the same reason.
  types.u32leb(1);
  types.byte(78);   // rec
  types.u32leb(declTypes);
  for (i32 i = 0; i < env.arrayCount; i++) {
    types.byte(94);   // array
    // A **storage type** is a value type or one of the two packed widths — and a value type can be a
    // reference. `u8[][]` is an array whose element is an array, and writing that element as a single
    // byte said `i32`, which is what `array.new` was complaining about four files later.
    string el = elemOf(env.arrayTypes[i]);
    if (el == "i8" || el == "u8") { types.byte(120); }
    else if (el == "i16" || el == "u16") { types.byte(119); }
    else { writeValType(types, env, el); }
    types.byte(1);    // mutable, which every wac array is
  }
  for (i32 i = 0; i < env.structCount; i++) {
    // **Every struct is written as an open subtype**, with a supertype list of one or of none.
    // A type is *final* by default and a final type cannot be extended, so a parent has to be
    // declared open before its child exists — and since a parent is only known to be one by
    // reading its children, declaring all of them open is the answer that needs no second pass.
    types.byte(80);   // sub
    string parent = env.structParents[i];
    types.u32leb(parent == "" ? 0 : 1);
    if (parent != "") { types.u32leb(env.structType(parent)); }
    types.byte(95);   // struct
    // Its parent's fields come first, in order, because that is what makes a `struct.get` compiled
    // against the parent read the right slot of a child.
    emitStructFields(types, env, env.structNames[i]);
  }

  // The signatures, after the structs and before the per-function types. A function reference's
  // value type points here; the type the *code section* gives each function is a different entry
  // with the same shape, and wasm's structural equality is what lets a `ref.func` of one be stored
  // in a local declared as the other.
  for (i32 i = 0; i < env.sigCount; i++) {
    string sig = env.sigTypes[i];
    // **A pair, not a function.** `fn[…]` values are `{funcref, env}` — `design/lang/0002` — and the
    // pair shares this table behind a marker because the table is grown lazily and so must stay last.
    // Two fields, both mutable-free: the env-taking funcref, then the env itself as `anyref`.
    if (isPairEntry(sig)) {
      string inner = pairInner(sig);
      types.byte(95);            // struct
      types.u32leb(2);
      types.byte(99);            // (ref null $envSig)
      types.i32leb(env.sigType(envSig(inner)));
      types.byte(0);             // immutable
      types.byte(110);           // anyref
      types.byte(0);             // immutable
      continue;
    }
    types.byte(96);
    types.u32leb(sigParamCount(sig));
    for (i32 pi = 0; pi < sigParamCount(sig); pi++) {
      writeValType(types, env, sigParamAt(sig, pi));
    }
    string r = sigReturn(sig);
    types.u32leb(r == "void" ? 0 : 1);
    if (r != "void") { writeValType(types, env, r); }
  }

  // **From the import count, like every other index.** This counter is the *export's* view of a
  // function's position and it is kept separately from `funcIndex`, so shifting one shifted only
  // half of them: every exported function named a wasm function `cbSigCount` places earlier than
  // itself. With one callback signature that is a trampoline, so `call1(f)` called the dispatcher
  // with the funcref where an `i32` belongs — a JS type error at the boundary, if the arity happened
  // to match, and a wrong answer if it did not. `issues/lang/0094`.
  i32 index = env.cbSigCount;
  i32 emitAt = 0;
  for (i32 d = 0; d < prog.decls.len(); d++) {
    match (prog.decls[d].kind) {
      case EnumDecl(nameTok, variants, exported, methods, typeParams): {
        if (typeParams.len() > 0) { continue; }
        string eowner = nameKeyOf(env, src, lexed, nameTok);
        for (i32 m = 0; m < methods.len(); m++) {
          if (env.funcIndex[emitAt] < 0) { emitAt = emitAt + 1; continue; }
          emitAt = emitAt + 1;
          emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                       "", methods[m].returnType, methods[m].params, methods[m].body,
                       methods[m].hasThis ? eowner : "", index, declTypes, methods[m].nameTok);
          index = index + 1;
        }
      }
      case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
        if (typeParams.len() > 0) { continue; }
        string owner = nameKeyOf(env, src, lexed, nameTok);
        for (i32 m = 0; m < methods.len(); m++) {
          if (env.funcIndex[emitAt] < 0) { emitAt = emitAt + 1; continue; }
          emitAt = emitAt + 1;
          emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                       "", methods[m].returnType, methods[m].params, methods[m].body,
                       methods[m].hasThis ? owner : "", index, declTypes, methods[m].nameTok);
          index = index + 1;
        }
      }
      case Func(nameTok, returnType, params, body, exported, typeParams): {
        if (typeParams.len() > 0) { continue; }
        if (env.funcIndex[emitAt] < 0) { emitAt = emitAt + 1; continue; }
        emitAt = emitAt + 1;
        emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                     exported && (entryDecls < 0 || d < entryDecls)
                       ? tokenTextOf(src, lexed, nameTok) : "",
                     returnType, params, body, "", index, declTypes, nameTok);
        index = index + 1;
      }
      else: { }
    }
  }

  // The instances, in the order `collectInstances` registered them: after every declaration and
  // **before the helpers**, which is where their indices are. Getting this wrong is not a subtle
  // bug — every call after the first helper reaches the wrong function — and it is why the last
  // attempt at this compiled the corpus into fifty-seven invalid modules while every hand-written
  // case, which had no strings and so no helpers, passed.
  for (i32 ii = 0; ii < env.instCount; ii++) {
  // **Only the ones registration built.** An instance discovered after the fixed point gave up —
  // or one whose template is not in this module — has no members in the tables, and emitting its
  // methods anyway shifts every index after it. The receiver comes out an `i32`, which wasm
  // reports as a `struct.get` on a number several functions later.
  // A function instance builds no type, so it is "built" when its own entry is registered.
  if (!env.isStructName(env.instName[ii]) && env.funcAt(env.instName[ii]) < 0) { continue; }
    for (i32 di = 0; di < prog.decls.len(); di++) {
      match (prog.decls[di].kind) {
        // **Never exported.** An instance's name is not a name anybody wrote, and two modules that
        // happened to infer the same one would collide on it.
        case Func(nameTok, returnType, params, body, exported, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          if (env.funcIndex[emitAt] < 0) { emitAt = emitAt + 1; continue; }
          emitAt = emitAt + 1;
          i32 fpushed3 = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                          env.instOf[ii]);
          emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                       "", returnType, params, body, "", index, declTypes, nameTok);
          popSubstitution(env, fpushed3);
          index = index + 1;
        }
        case EnumDecl(nameTok, variants, exported, methods, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 epushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                         env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            if (env.funcIndex[emitAt] < 0) {
              emitAt = emitAt + 1;
              continue;
            }
            emitAt = emitAt + 1;
            emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                         "", methods[m].returnType, methods[m].params, methods[m].body,
                         methods[m].hasThis ? env.instName[ii] : "", index, declTypes,
                         methods[m].nameTok);
            index = index + 1;
          }
          popSubstitution(env, epushed);
        }
        case StructDecl(nameTok, parentTok, fields, methods, exported, isConst, typeParams): {
          if (typeParams.len() == 0) { continue; }
          if (tokenTextOf(src, lexed, nameTok) != env.instOf[ii]) { continue; }
          i32 pushed = pushSubstitution(env, src, lexed, typeParams, env.instName[ii],
                                        env.instOf[ii]);
          for (i32 m = 0; m < methods.len(); m++) {
            if (env.funcIndex[emitAt] < 0) {
              emitAt = emitAt + 1;
              continue;
            }
            emitAt = emitAt + 1;
            emitFunction(types, funcs, exports, code, src, lexed, env, prog,
                         "", methods[m].returnType, methods[m].params, methods[m].body,
                         methods[m].hasThis ? env.instName[ii] : "", index, declTypes,
                         methods[m].nameTok);
            index = index + 1;
          }
          popSubstitution(env, pushed);
        }
        else: { }
      }
    }
  }

  // The helper, last, so every index the source could name is already assigned.
  if (needsStrings) {
    emitStringEquals(types, funcs, code, env, index, declTypes);
    emitStringConcat(types, funcs, code, env, index + 1, declTypes);
    emitBytesCopy(types, funcs, code, env, index + 2, declTypes, "u8[]", "i8[]");
    emitBytesCopy(types, funcs, code, env, index + 3, declTypes, "i8[]", "u8[]");
    emitStringIndex(types, funcs, code, env, index + 4, declTypes);
    emitStringFromCp(funcs, code, env);
    emitStringSlice(funcs, code, env);
    emitStringIndexOf(funcs, code, env);
    emitStringCompare(funcs, code, env);
  }
  // **The string builtins occupy nine indices and this loop does not advance `index` itself**, so the
  // lambdas below would start on top of them. They did, and the wrapper for the first lambda called
  // whatever the string block had put there: `$fn$102 … not enough arguments on the stack`.
  index = index + stringHelpers;
  // **The hoisted lambdas, after the string builtins** — `design/lang/0002` tier two,
  // `issues/lang/0138`.
  //
  // Not immediately after the declared functions, which is where they were and which produced modules
  // that failed to load. `assignGlobals` numbers every *registered* function consecutively, and the
  // nine string builtins are registered by `addFunc`, so they are numbered right after the user's —
  // while `count` includes the lambdas and `memHelperAt` is `cbSigCount + count + stringHelpers`. Put
  // the lambdas first and ` str_eq` is numbered at an index the lambda occupies, so every string
  // comparison in the module calls one function early. It named `Socket.fromLoopback` and `reasonOf`,
  // which is what a wrong index looks like: a failure in a function that has nothing to do with the
  // feature.
  //
  // Unregistered functions have to come after every registered one, and that is the whole rule.
  // Their ordinals are `lambdaFirst + li`, which is what `emitLambdaPair` relies on to name the right
  // wrapper, and emitting them here is what makes that true: `emitFunctionOf` builds each wrapper as
  // it goes, so the wrappers stay exactly the emitted functions in emission order.
  //
  // The signature is the one the walk recorded — the `fn[…]` the lambda is *used as*, not one rebuilt
  // from its parameters — so the hoisted function's type and the pair's type are the same string by
  // construction rather than by agreement.
  for (i32 li = 0; li < env.lambdaCount; li++) {
    string lsig = env.lambdaSigs[li];
    if (lsig == "") { continue; }
    // Its own line and column, which the walk recorded — a lambda has no name token, and the entry
    // coverage point needs a position rather than a token. Passing -1 read `lexed.tokens[-…]`.
    // **The capture struct is the receiver**, which is what makes tier one's bound wrapper carry it:
    // that wrapper already casts an env to a receiver and calls, so a capturing lambda needs no new
    // machinery, only the other of the two wrapper families.
    string recv = env.lambdaCapCount[li] > 0 ? captureStructName(li) : "";
    i32 wasEmitting = env.emittingLambda;
    env.emittingLambda = li;
    // **In the world it was written in.** A lambda hoisted out of a generic still says `T` in its
    // body, and `curInst` is also what `lambdaAtPos` matches on — so a nested lambda looked up while
    // this one is being emitted finds the right copy. See `pushInstSubstitution`.
    i32 lpushed = env.lambdaInst[li] == ""
      ? 0
      : pushInstSubstitution(env, src, lexed, prog, env.lambdaInst[li]);
    emitFunctionOf(types, funcs, exports, code, src, lexed, env, prog, "", sigReturn(lsig),
                   env.lambdaParams[li], env.lambdaBodies[li], recv, index, declTypes,
                   env.lambdaLine[li], env.lambdaCol[li]);
    if (lpushed > 0) { popSubstitution(env, lpushed); }
    env.emittingLambda = wasEmitting;
    index = index + 1;
  }

  emitMemEnsure(funcs, code, env);
  // In `arrayTypes` order, which is the order the exports below name them in — a helper's index is
  // its position among the helpers and nothing else.
  for (i32 bi = 0; bi < env.arrayCount; bi++) {
    string bt = env.arrayTypes[bi];
    if (!bindableArray(env, bt)) { continue; }
    emitArrayAccessors(funcs, code, env, bt);
    if (!isBulkArray(bt)) { continue; }
    emitArrToMem(funcs, code, env, bt);
    emitArrFromMem(funcs, code, env, bt);
  }
  for (i32 si4 = 0; si4 < bindStructCount; si4++) {
    if (env.isEnumName(bindStructs[si4])) { continue; }
    if (!bindableStruct(env, bindStructs[si4])) { continue; }
    emitStructHelpers(funcs, code, env, bindStructs[si4]);
  }
  for (i32 si6 = 0; si6 < bindStructCount; si6++) {
    if (!env.isEnumName(bindStructs[si6])) { continue; }
    emitEnumHelpers(funcs, code, env, bindStructs[si6]);
  }
  if (needsStrings) { emitStringBindHelpers(funcs, code, env); }
  for (i32 j = 0; j < env.cbSigCount; j++) {
    emitCallbackHelpers(funcs, code, env, j, cbHelpersAt + j * (callbackSlots() + 1));
  }
  if (env.coverage) { emitCoverageHelpers(funcs, code, env); }
  for (i32 j = 0; j < env.outSigCount; j++) { emitCallrefHelper(funcs, code, env, env.outSigs[j]); }
  emitFmodHelpers(funcs, code, env, fmodHelpersAt);
  // The wrappers last, so their indices start at `wrapHelpersAt` — after every other helper — and the
  // bound ones after those.
  funcs.bytes(env.wrapFuncs);
  code.bytes(env.wrapCode);
  funcs.bytes(env.boundFuncs);
  code.bytes(env.boundCode);

  B out = B.create();
  // `\0asm`, then version 1 as four little-endian bytes.
  out.byte(0);
  out.byte(97);
  out.byte(115);
  out.byte(109);
  out.byte(1);
  out.byte(0);
  out.byte(0);
  out.byte(0);
  B globals = B.create();
  i32 globalCount = 0;
  for (i32 i = 0; i < env.constCount; i++) {
    if (env.constGlobal[i] >= 0) { globalCount = globalCount + 1; }
  }
  globals.u32leb(globalCount + (env.coverage ? 1 : 0));
  if (env.coverage) {
    // `i32[]`, mutable, one slot per point — `array.new_default` over a constant length is a
    // constant expression, so the counters exist before any code runs and `__cov_init` only has to
    // clear them.
    writeValType(globals, env, "i32[]");
    globals.byte(1);
    globals.byte(65); globals.i32leb(env.trace ? traceSlotsOf(env) : env.covCount);
    globals.byte(251); globals.u32leb(7); globals.u32leb(env.arrayType("i32[]"));
    globals.byte(11);
  }
  // **From where the constants' indices start**, which is one along when the counter array has taken
  // global 0. Writing from zero left every constant's entry unwritten — the section then ended early
  // and the next byte was read as a value type.
  i32 firstConst = env.coverage ? 1 : 0;
  for (i32 g = firstConst; g < globalCount + firstConst; g++) {
    for (i32 i = 0; i < env.constCount; i++) {
      if (env.constGlobal[i] != g) { continue; }
      writeValType(globals, env, env.constTypes[i]);
      bool here = !(env.constInits[i] is null) && isConstExpr(src, lexed, env, env.constInits[i]!);
      // Immutable is what a `const` is, and what it can be only when its value can be written here.
      // The rest are mutable and null until the start function has run, which is the one moment
      // anything is allowed to write them.
      globals.byte(here ? 0 : 1);
      if (here) {
        emitExprAt(globals, src, lexed, env, env.constInits[i]!, env.constTypes[i]);
      }
      if (!here) { emitDefault(globals, env, env.constTypes[i]); }
      globals.byte(11);  // end of the initialiser expression
    }
  }

  // The start function goes last, so every index the constants can name is already assigned.
  if (startNeeded) {
    env.localCount = 0;
    env.paramCount = 0;
    // **After `$bind$mem_ensure`, so one past where it used to be.** The start function is emitted
    // last and numbered by hand, and adding a helper in front of it without moving this produced
    // *"invalid start func reference"* — the index named a function that is now the buffer helper.
    emitStartFunction(funcs, code, src, lexed, env,
                      startFunctionAt, declTypes);
  }

  // **The type section is written before the code that names types.** If emitting a body registered
  // one more — an array, a struct, a signature — every index after it is a lie, and the module names
  // a type it does not have: *"no signature at index 353 (353 types)"*. Rather than emit that, the
  // module is declined, which is the same answer the walk gives for everything it cannot do.
  if (env.arrayCount + env.structCount + env.sigCount != declTypes) {
    // **Which type, not how many.** This said "N counted, M wanted" and nothing else, and the
    // difference was always 1 — a number that narrows the cause to every type the program has. The
    // first program to trip it after `design/lang/0002` tier two landed (a lambda capturing an
    // array) cost a bisection down to a four-line case to learn the word `u8[]`, which the emitter
    // knew all along. Three counts kept apart above turn that into one reading.
    string grew = "";
    // Named by table as well as by name: `$cell$u8[]` ends in `[]`, so which table it landed in is
    // the difference between "the cell struct was registered late" and "something read the cell's
    // name as an array type", and the two have nothing to do with each other.
    for (i32 gi = declArrays; gi < env.arrayCount; gi++) { grew = grew + " array " + env.arrayTypes[gi]; }
    for (i32 gi = declStructs; gi < env.structCount; gi++) { grew = grew + " struct " + env.structNames[gi]; }
    for (i32 gi = declSigs; gi < env.sigCount; gi++) { grew = grew + " sig " + env.sigTypes[gi]; }
    env.declineFor("a type was registered while a body was being emitted, after the type section " +
                   "had been sized: " + numText(declTypes) + " counted, " +
                   numText(env.arrayCount + env.structCount + env.sigCount) + " wanted —" + grew);
    return bareModule();
  }

  // **The staging buffer, and the two names a host reaches it by.** One page to start with;
  // `$bind$mem_ensure` grows it. Emitted for every module rather than only where a signature moves
  // bytes, because which signatures a host will bind is not something the emitter can know.
  B mem = B.create();
  mem.u32leb(1);      // one memory
  mem.byte(0);        // no maximum
  mem.u32leb(1);      // one page to begin with

  // Every function this module has: the imported dispatchers, its own, and the helpers. The helpers
  // fill it as their exports are written; the rest is filled where the section is emitted.
  string[] fnName = string[env.cbSigCount + count + helpers](fill: "");

  exports.name("$bind$mem");
  exports.byte(2);    // a memory
  exports.u32leb(0);
  i32 helperBase = memHelperAt;
  exportFunc(exports, fnName, "$bind$mem_ensure", helperBase);
  i32 bulkAt = arrayHelpersAt;
  for (i32 bi = 0; bi < env.arrayCount; bi++) {
    string bt = env.arrayTypes[bi];
    if (!bindableArray(env, bt)) { continue; }
    string el = elemOf(bt);
    string sfx = bindArrSuffix(el);
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_new", bulkAt);
    bulkAt = bulkAt + 1;
    if (arrNeedsFill(env, el)) {
      exportFunc(exports, fnName, "$bind$arr_" + sfx + "_new0", bulkAt);
      bulkAt = bulkAt + 1;
    }
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_get", bulkAt);
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_set", bulkAt + 1);
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_len", bulkAt + 2);
    bulkAt = bulkAt + 3;
    if (!isBulkArray(bt)) { continue; }
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_to_mem", bulkAt);
    exportFunc(exports, fnName, "$bind$arr_" + sfx + "_from_mem", bulkAt + 1);
    bulkAt = bulkAt + 2;
  }
  for (i32 si5 = 0; si5 < bindStructCount; si5++) {
    string sn2 = bindStructs[si5];
    if (env.isEnumName(sn2)) { continue; }
    if (!bindableStruct(env, sn2)) { continue; }
    exportFunc(exports, fnName, "$bind$s_" + bindNameFor(env, src, lexed, sn2) + "_new", bulkAt);
    bulkAt = bulkAt + 1;
    i32 sfc2 = env.fieldCountOf(sn2);
    for (i32 f = 0; f < sfc2; f++) {
      string fn2 = env.fieldNameAt(sn2, f);
      exportFunc(exports, fnName, "$bind$s_" + bindNameFor(env, src, lexed, sn2) + "_get_" + fn2, bulkAt);
      exportFunc(exports, fnName, "$bind$s_" + bindNameFor(env, src, lexed, sn2) + "_set_" + fn2, bulkAt + 1);
      bulkAt = bulkAt + 2;
    }
  }
  // In the order `emitEnumHelpers` writes them, for each enum in turn.
  for (i32 si7 = 0; si7 < bindStructCount; si7++) {
    string en2 = bindStructs[si7];
    if (!env.isEnumName(en2)) { continue; }
    exportFunc(exports, fnName, "$bind$e_" + bindNameFor(env, src, lexed, en2) + "_tag", bulkAt);
    bulkAt = bulkAt + 1;
    for (i32 v = 0; v < env.variantCount; v++) {
      if (env.variantOwners[v] != en2) { continue; }
      string vn2 = bareVariantName(env.variantNames[v]);
      exportFunc(exports, fnName, "$bind$e_" + bindNameFor(env, src, lexed, en2) + "_" + vn2 + "_new", bulkAt);
      bulkAt = bulkAt + 1;
      for (i32 k = 0; k < env.variantArity[v]; k++) {
        exportFunc(exports, fnName,
                   "$bind$e_" + bindNameFor(env, src, lexed, en2) + "_" + vn2 + "_get_" +
                   payloadFieldName(env.fieldNameAt(en2, env.variantSlot[v] + k)), bulkAt);
        bulkAt = bulkAt + 1;
      }
    }
  }
  // In the order `emitStringBindHelpers` writes them.
  if (needsStrings) {
    exportFunc(exports, fnName, "$bind$str_new", bindStrHelpersAt);
    exportFunc(exports, fnName, "$bind$str_get", bindStrHelpersAt + 1);
    exportFunc(exports, fnName, "$bind$str_set", bindStrHelpersAt + 2);
    exportFunc(exports, fnName, "$bind$str_len", bindStrHelpersAt + 3);
    exportFunc(exports, fnName, "$bind$str_to_mem", bindStrHelpersAt + 4);
    exportFunc(exports, fnName, "$bind$str_from_mem", bindStrHelpersAt + 5);
  }

  for (i32 j = 0; j < env.cbSigCount; j++) {
    // **The trampolines are named without being exported**, which is why this is not `exportFunc`.
    // One per slot per signature — sixteen each — and they were the whole of what the name section
    // still left as `wasm-function[N]`: a host's callback runs *inside* one, so a trap in a function
    // the host passed in reported the only frame with no name on it. `$bind$tramp_<j>_<k>` is what
    // the reference calls them. [issue 0101]
    for (i32 k = 0; k < callbackSlots(); k++) {
      i32 at = cbHelpersAt + j * (callbackSlots() + 1) + k;
      if (at >= 0 && at < fnName.len()) {
        fnName[at] = "$bind$tramp_" + numText(j) + "_" + numText(k);
      }
    }
    exportFunc(exports, fnName, "$bind$fnref_" + numText(j), cbHelpersAt + j * (callbackSlots() + 1) + callbackSlots());
  }
  for (i32 j = 0; j < env.outSigCount; j++) {
    exportFunc(exports, fnName, "$bind$callref_" + numText(j), outHelpersAt + j);
  }
  if (env.coverage) {
    exportFunc(exports, fnName, "__cov_init", covHelpersAt);
    exportFunc(exports, fnName, "__cov_len", covHelpersAt + 1);
    exportFunc(exports, fnName, "__cov_get", covHelpersAt + 2);
  }
  // **The two float-remainder helpers, named and not exported** — the same standing as the wrappers
  // below and as `__wac_start`. A trap cannot happen inside them, but `%` on a float is now a *call*,
  // so they are a frame anyone reading a stack will meet; `names.test.ts` found them the moment they
  // existed, reporting "2 of 153 unnamed" against `packages/bls/src/fp.wac`. `issues/lang/0135`.
  if (fmodHelpersAt >= 0 && fmodHelpersAt + 1 < fnName.len()) {
    fnName[fmodHelpersAt] = "__fmod";
    fnName[fmodHelpersAt + 1] = "__fmodf";
  }
  // **The hoisted lambdas.** Named for where they were written, which is the only thing that
  // distinguishes one from another — a lambda has no name in the source, and two in one function are
  // told apart by position and nothing else. `names.test.ts` found these the moment the repository
  // contained its first file with lambdas in it, reporting "7 of 270 unnamed" and naming `str_cmp` as
  // the function before the run, which is exactly where they sit. `design/lang/0002` tier two.
  for (i32 li = 0; li < env.lambdaCount; li++) {
    // `lambdaFirst` is the count of declared functions, and the lambdas sit after the string builtins
    // — so their index carries that term too. Naming them without it overwrote the builtins' names.
    i32 lat = env.cbSigCount + env.lambdaFirst + stringHelpers + li;
    if (lat < 0 || lat >= fnName.len()) { continue; }
    fnName[lat] = "$lambda$" + numText(env.lambdaLine[li]) + ":" + numText(env.lambdaCol[li]);
  }
  // **The wrappers, named after what they wrap.** Every function in this module has a name — the test
  // that says so exists because a trap inside an unnamed one reports `wasm-function[N]` and nothing
  // else. A wrapper is the frame a call *through a `fn[…]` value* lands in, so it is exactly the
  // frame somebody debugging a callback will be looking at. `design/lang/0002`.
  for (i32 wi = 0; wi < wrapHelpers; wi++) {
    i32 wat = wrapHelpersAt + wi;
    if (wat < 0 || wat >= fnName.len()) { continue; }
    i32 target = env.cbSigCount + wi;
    fnName[wat] = target < fnName.len() && fnName[target] != ""
      ? "$fn$" + fnName[target]
      : "$fn$" + numText(wi);
  }
  for (i32 bi = 0; bi < boundHelpers; bi++) {
    i32 bat = boundHelpersAt + bi;
    if (bat < 0 || bat >= fnName.len()) { continue; }
    i32 btarget = env.cbSigCount + bi;
    fnName[bat] = btarget < fnName.len() && fnName[btarget] != ""
      ? "$bound$" + fnName[btarget]
      : "$bound$" + numText(bi);
  }
  // **The start function, named and not exported.** Nothing calls it — the engine does, before the
  // first export runs — so a trap while a module constant is being built reported the frame with no
  // name in it, in the 96 modules of this repository that have one. It is wac's own: the reference
  // emits no start section at all, having no module-level constants to initialise.
  if (startNeeded && startFunctionAt >= 0 && startFunctionAt < fnName.len()) {
    fnName[startFunctionAt] = "__wac_start";
  }
  exports.bytes(methodExports);

  section(out, 1, types);
  // **The imports, if any.** A module that takes no host function has no import section at all, so
  // everything that instantiated with nothing supplied still does.
  if (env.cbSigCount > 0) {
    B imports = B.create();
    imports.u32leb(env.cbSigCount);
    for (i32 j = 0; j < env.cbSigCount; j++) {
      imports.name("wac");
      imports.name("cb" + numText(j));
      imports.byte(0);                                  // a function
      imports.u32leb(env.sigType(dispatchSig(env.cbSigs[j])));
    }
    section(out, 2, imports);
  }
  section(out, 3, funcs);
  section(out, 5, mem);
  // The counter array is a global too, so a module with no constants still has a globals section
  // when it is instrumented — without which `global.get 0` names nothing.
  if (globalCount > 0 || env.coverage) { section(out, 6, globals); }
  section(out, 7, exports);
  if (startNeeded) {
    B st = B.create();
    st.u32leb(startFunctionAt);
    section(out, 8, st);
  }
  // **Every function declared as referenceable.** `ref.func` on a function that no element segment
  // mentions is *"undeclared function reference"* — a rule that exists so an engine knows which
  // functions can escape, and that costs one segment listing them all.
  if (count + helpers > 0) {
    B elems = B.create();
    elems.u32leb(1);
    elems.byte(3);    // declarative
    elems.byte(0);    // elemkind: funcref
    elems.u32leb(count + helpers);
    for (i32 i = 0; i < count + helpers; i++) { elems.u32leb(env.cbSigCount + i); }
    section(out, 9, elems);
  }
  section(out, 10, code);

  // **The `name` custom section**, last, after everything the format orders. Without it a trap in
  // this module is `wasm-function[147]`, and the number moves whenever anything before it does — and
  // for a program using a feature only this compiler has, there is no reference build to read
  // instead [issue 0101].
  {
    i32 total = fnName.len();
    // The imported dispatchers, one per callback signature, named for the signature they serve: four
    // identical `cb` frames in a profile are worth no more than none.
    for (i32 j = 0; j < env.cbSigCount && j < total; j++) {
      fnName[j] = "wac.cb" + numText(j) + " " + env.cbSigs[j];
    }
    // The module's own functions, under the key they were registered by — which carries the file for
    // a name two modules both declare, and `Owner.method` for a method. A builtin's key begins with a
    // space so that nothing written in wac can collide with it; a stack trace has no such problem and
    // reads better without it.
    for (i32 i = 0; i < env.funcCount; i++) {
      i32 idx = env.funcIndex[i];
      if (idx < 0 || idx >= total) { continue; }
      if (fnName[idx] != "") { continue; }          // an export already named it
      string nm = env.funcs[i];
      while (nm.len() > 0 && nm.slice(0, 1) == " ") { nm = nm.slice(1, nm.len()); }
      fnName[idx] = nm;
    }
    i32 named = 0;
    for (i32 i = 0; i < total; i++) { if (fnName[i] != "") { named = named + 1; } }
    if (named > 0) {
      B map = B.create();
      map.u32leb(named);
      for (i32 i = 0; i < total; i++) {
        if (fnName[i] == "") { continue; }
        map.u32leb(i);
        map.name(fnName[i]);
      }
      B names = B.create();
      names.name("name");
      names.byte(1);                    // the function-name subsection
      names.u32leb(map.len);
      names.bytes(map);
      section(out, 0, names);
    }
  }

  // **The standard `producers` section: which compiler made this.** Two compilers build this
  // repository, their output differs by a fifth in size, and an artefact that does not say which one
  // made it leaves "what built this page" answered by whatever the environment was when somebody ran
  // the command — `issues/lang/0103`. The format is the WebAssembly tool convention rather than one
  // invented here, so `wasm-objdump` and anything else that already reads it does.
  {
    B pr = B.create();
    pr.name("producers");
    pr.u32leb(1);            // one field
    pr.name("processed-by");
    pr.u32leb(1);            // one (value, version) pair
    pr.name("wacc");
    pr.name("");             // no version: this compiler has no number to give yet
    section(out, 0, pr);
  }

  u8[] result = u8[out.len]();
  for (i32 i = 0; i < out.len; i++) { result[i] = out.data[i]; }
  return result;
}

/** A token's text, which the emitter needs for an export's name and for every lookup. */
export string tokenTextOf(u8[] src, Lexed lexed, i32 t) {
  if (t < 0) { return ""; }
  i32 start = lexed.tokens[t * tokenStride() + 1];
  i32 len = lexed.tokens[t * tokenStride() + 2];
  u8[] out = u8[len]();
  for (i32 i = 0; i < len; i++) { out[i] = src[start + i]; }
  return string.fromBytes(out);
}

/** A declared type's name, enough to tell `void` from a value. */
string typeOfTyName(Env env, u8[] src, Lexed lexed, Ty t) {
  match (t.kind) {
    case Prim(tok): {
      return tokenTextOf(src, lexed, tok);
    }
    case Named(tok, typeArgs): {
      string raw = tokenTextOf(src, lexed, tok);
      // **`anyref` and `i31ref` are spelled as identifiers and declared by nobody.** The lexer has
      // no keyword for them, so they arrive here looking like a type name to resolve — and
      // resolution would go hunting for a declaration in the file, find none, and answer `""`,
      // which is how `i31ref x = …` came out as a bare `i32`.
      if (raw == "anyref" || raw == "i31ref") { return raw; }
      // A **type parameter** stands for its argument wherever it appears — a field's type, a
      // method's parameter, an array's element, a local inside a body.
      string bound = env.substituted(raw);
      if (bound != "") { return bound; }
      // Spelled with arguments, a name is an **instantiation**: registered on sight, compiled once.
      if (typeArgs.len() > 0) {
        string inst = raw + "<";
        // **The same arguments as the author wrote them**, kept beside the identity. They differ
        // only where a `?` was erased, and that difference is the one a host can see: it asks for
        // `Pending$u8ArrOpt`, which this emitter would otherwise have no name for at all.
        string spelled = raw + "<";
        for (i32 i = 0; i < typeArgs.len(); i++) {
          string at = typeOfTyName(env, src, lexed, typeArgs[i]);
          if (at == "") { return ""; }
          if (i > 0) { inst = inst + ","; spelled = spelled + ","; }
          inst = inst + at;
          spelled = spelled + at + (isNullableTy(typeArgs[i]) ? "?" : "");
        }
        inst = inst + ">";
        spelled = spelled + ">";
        env.instantiate(inst, raw);
        env.noteAlias(inst, spelled);
        return inst;
      }
      // Inside a template's own body its bare name is the instance being compiled: `Vec(T[](), 0)`
      // in `Vec<T>.create` builds a `Vec<i32>` when `T` is `i32`.
      if (raw == env.curGeneric && env.curInst != "") { return env.curInst; }
      // **The key, not the name.** Two linked files may each declare a `K`, and what tells them
      // apart is the line this one is written on.
      return env.keyAt(raw, tokenLine(lexed, tok));
    }
    // An array spells itself from the element out, exactly as the checker's `typeOfTy` does. Left
    // out, every array type came back as the empty string — the type section had no array entry, the
    // local was declared an `i32`, and the module asked for an array of whatever was on the stack.
    // A "" that means *unknown* propagates silently, which is the cost of using it for two things.
    case Arr(elem): {
      string inner = typeOfTyName(env, src, lexed, elem);
      return inner == "" ? "" : inner + "[]";
    }
    // **`T?` is `T`**, which is free here for the reason `array.new_default` forced two slots ago:
    // every reference this emitter writes is the nullable `0x63`, so a type that admits null and one
    // that does not are already the same wasm type and the difference is the checker's to keep. A
    // nullable *primitive* is not — there is no null `i32` — and comes back unspelled.
    // `fn[i32(i32, u8[])]` — spelled canonically, since the string *is* the identity: two spellings
    // of one signature have to reach the same type index or a value of one cannot be called as the
    // other.
    case Funcref(ret, params): {
      string r = typeOfTyName(env, src, lexed, ret);
      if (r == "") { return ""; }
      string out = "fn[" + r + "(";
      for (i32 i = 0; i < params.len(); i++) {
        string pt = typeOfTyName(env, src, lexed, params[i]);
        if (pt == "") { return ""; }
        if (i > 0) { out = out + ","; }
        out = out + pt;
      }
      return out + ")]";
    }
    case Nullable(inner): {
      match (inner.kind) {
        // A nullable **primitive** has no representation — there is no null `i32` — except that
        // `string` is a primitive by spelling and a reference by nature, so `string?` is a string.
        case Prim(tok): {
          string pn = tokenTextOf(src, lexed, tok);
          // **`anyref` and `i31ref` are references too**, and they lex as primitives — which is how
          // `anyref? interruptCtx;` became a field of no type at all, and `Shell.create` came back
          // as *a null in a slot of no known type* for the whole of `packages/sh`. A `string` was
          // already excepted here for exactly this reason; there are three such names, not one.
          // `spec/cases/0098`.
          return pn == "string" || pn == "anyref" || pn == "i31ref" ? pn : "";
        }
        else: { return typeOfTyName(env, src, lexed, inner); }
      }
    }
  }
}

/** Statements, in order. */
/**
 * The variant an arm names, within the enum it is matching on.
 *
 * A template's variants belong to its **instances**: `Some` in `Option<i32>` and `Some` in
 * `Option<string>` are two variants with one name, so an instance registers its own under a name
 * that carries the instance with it. Every place an arm's text becomes a variant comes through here
 * with the enum in hand — which is the only place that knows which `Some` is meant.
 */
string armVariant(Env env, u8[] src, Lexed lexed, i32 tok, string en) {
  string raw = tokenTextOf(src, lexed, tok);
  if (isInstance(en)) { return en + "." + raw; }
  // **Within this enum**, not within the file. Two enums in one module may each have an `Ok` — one
  // module here has an `Opened.Ok` and a `Found.Ok` — and resolving the arm by file scope finds
  // whichever was declared first, which is a different enum's variant with the same spelling.
  for (i32 i = 0; i < env.variantCount; i++) {
    if (env.variantOwners[i] != en) { continue; }
    string vk = env.variantNames[i];
    if (vk == raw) { return vk; }
    // A name two files declare is keyed with the file that declared it, so the arm's text is a
    // prefix of the key rather than the key.
    if (vk.len() > raw.len() && vk.slice(0, raw.len() + 1) == raw + "@") { return vk; }
  }
  return env.keyAt(raw, tokenLine(lexed, tok));
}

/**
 * The variant a `Enum.Variant` names, or `""` when the member is an ordinary field access.
 *
 * `Shape.Point` and `p.x` are the same node — a member of something — and only the table can tell
 * them apart: the object is a bare name that is an *enum*, and the member is one of its variants.
 */
/**
 * Where a method called on `t` is declared.
 *
 * A **payload-less variant used as a value** types as the variant — `Shape.Point` is a `Shape.Point`
 * and not a `Shape` — and an enum's methods are registered on the enum. So `Shape.Point.isFlat()`
 * asked for `isFlat` on `Shape.Point`, found nothing, and the emitter declined by name: *no method
 * Point.isFlat*. The reference compiles it. `issues/lang/0121`.
 *
 * The variant type is the right answer everywhere else — it is what lets a field access on a narrowed
 * value pick a slot without a match — so this widens the *lookup* rather than the type: ask the
 * variant, and if it has nothing, ask the enum that owns it.
 */
i32 methodOn(Env env, string t, string name) {
  i32 at = env.methodAt(t, name);
  if (at >= 0) { return at; }
  string owner = env.enumOf(t);
  return owner == "" ? -1 : env.methodAt(owner, name);
}

string variantOfMemberAt(u8[] src, Lexed lexed, Env env, Expr obj, i32 nameTok, string want) {
  match (obj.kind) {
    case Ident(tok): {
      // `Option.Some(3)` names a **template**, and which instance it is comes from the slot — the
      // same rule `Vec.create()` follows, because the instantiation is not in the call either way.
      if (isInstance(want) && templateOf(want) == tokenTextOf(src, lexed, tok)) {
        string vw = want + "." + tokenTextOf(src, lexed, nameTok);
        return env.enumOf(vw) == want ? vw : "";
      }
      string on = nameKeyOf(env, src, lexed, tok);
      if (!env.isEnumName(on)) { return ""; }
      return env.variantKeyIn(on, tokenTextOf(src, lexed, nameTok));
    }
    else: { return ""; }
  }
}

/** The same question with no slot in hand, which is every use but a template's. */
string variantOfMember(u8[] src, Lexed lexed, Env env, Expr obj, i32 nameTok) {
  return variantOfMemberAt(src, lexed, env, obj, nameTok, "");
}

/**
 * Which slot a field access on an enum value means: -1 for none, -2 for more than one.
 *
 * A value whose static type is a *variant* asks that variant. A value still typed as the enum — the
 * subject of an arm that did not narrow, since narrowing is a shadowed binding rather than a
 * retyping — asks every variant, and the answer is only usable if exactly one has the field. Two
 * variants with a field of the same name are a real shape (`Add(i32 lhs)`, `Sub(i32 lhs)`) and the
 * honest answer there is to decline rather than to pick the first.
 */
i32 enumSlot(Env env, string ty, string field) {
  string en = env.canonType(ty);
  if (env.enumOf(ty) != "") { return env.fieldIndex(en, ty + "." + field); }
  i32 found = -1;
  for (i32 i = 0; i < env.variantCount; i++) {
    if (env.variantOwners[i] != en) { continue; }
    i32 at = env.fieldIndex(en, env.variantNames[i] + "." + field);
    if (at < 0) { continue; }
    if (found >= 0 && found != at) { return -2; }
    found = at;
  }
  return found;
}

/**
 * A value of `t` that means nothing, for the payload slots a variant does not use.
 *
 * `struct.new` wants every field on the stack, and a `Circle` has to put *something* in `Rect`'s
 * two. A reference field takes a null — which is why every reference this emitter writes is the
 * nullable `0x63` and not `0x64`, a decision made one slot ago for arrays and paid off here.
 */
/**
 * A null of the right type — which is a different question from a default, and was the same one
 * until `S()` had to produce a `""` rather than a trap. `null` written in the source means this;
 * a slot nobody wrote into means `emitDefault`.
 */
void emitNull(B fb, Env env, string t) {
  // The two the format names rather than the module declares: `ref.null` takes a heap type, and
  // theirs is a single byte where a struct's is an index.
  if (t == "anyref") { fb.byte(208); fb.byte(110); return; }
  if (t == "i31ref") { fb.byte(208); fb.byte(108); return; }
  if (t == "string") { fb.byte(208); fb.i32leb(env.arrayType("i8[]")); return; }
  if (isArrayType(t)) { fb.byte(208); fb.i32leb(env.arrayType(t)); return; }
  if (isFuncrefType(t)) { fb.byte(208); fb.i32leb(env.pairType(t)); return; }
  if (env.isStructName(t)) { fb.byte(208); fb.i32leb(env.structType(t)); return; }
  emitDefault(fb, env, t);
}

/**
 * The value a slot holds when nothing is written into it — which for a reference is **not null**.
 *
 * `string`'s default is `""`, an array's is an empty one, and a struct's is a struct whose fields
 * are all defaulted in turn. `S()` and `string[3]()` are both spec'd to produce those, and emitting
 * `ref.null` for them typechecked and then trapped on the first `.len()`.
 *
 * A struct that reaches itself is the one case that must stop: a field of a struct's own type has
 * to be nullable for the type to be inhabitable at all, so `null` is its right answer and the guard
 * below is not an approximation.
 */
void emitDefault(B fb, Env env, string t) {
  // **A default `anyref` is null**, unlike a string or a struct: there is no value of the top type
  // to build, and an `anyref[3]()` is three empty slots by the same argument that makes a nullable
  // field's default a null.
  if (t == "anyref" || t == "i31ref") { emitNull(fb, env, t); return; }
  if (t == "string") {
    fb.byte(65);
    fb.i32leb(0);
    fb.byte(251);
    fb.u32leb(7);   // array.new_default — an empty i8[], which is ""
    fb.u32leb(env.arrayType("i8[]"));
    return;
  }
  if (isArrayType(t)) {
    fb.byte(65);
    fb.i32leb(0);
    fb.byte(251);
    fb.u32leb(7);
    fb.u32leb(env.arrayType(t));
    return;
  }
  if (env.isStructName(t)) {
    string canon = env.canonType(t);
    for (i32 i = 0; i < env.buildingCount; i++) {
      if (env.building[i] == canon) {
        fb.byte(208);
        fb.i32leb(env.structType(t));
        return;
      }
    }
    // An enum has no default — a tag of 0 is a variant, and choosing one would be inventing a
    // value the source did not write.
    if (env.isEnumName(canon)) {
      fb.byte(208);
      fb.i32leb(env.structType(t));
      return;
    }
    if (env.buildingCount < env.building.len()) {
      env.building[env.buildingCount] = canon;
      env.buildingCount = env.buildingCount + 1;
    }
    i32 n = env.fieldCountOf(canon);
    for (i32 i = 0; i < n; i++) {
      // A field written `N?` defaults to null; one written `N` defaults to a defaulted `N`.
      if (env.fieldNullableAt(canon, i)) {
        emitNull(fb, env, env.fieldTypeAt(canon, i));
        continue;
      }
      emitDefault(fb, env, env.fieldTypeAt(canon, i));
    }
    fb.byte(251);
    fb.u32leb(0);   // struct.new
    fb.u32leb(env.structType(t));
    env.buildingCount = env.buildingCount - 1;
    return;
  }
  if (isFuncrefType(t)) { fb.byte(208); fb.i32leb(env.pairType(t)); return; }
  i32 v = valType(t);
  if (v == 126) { fb.byte(66); fb.i64leb(0); return; }
  if (v == 125) { fb.byte(67); fb.f32bits(0.0); return; }
  if (v == 124) { fb.byte(68); fb.f64bits(0.0); return; }
  fb.byte(65);
  fb.i32leb(0);
}

/** `Shape.Circle(2.0)` — the tag, the payload in its own slots, and a default in everyone else's. */
void emitVariantNew(B fb, u8[] src, Lexed lexed, Env env, string vname, Expr?[] args) {
  i32 vi = env.variantAt(vname);
  if (vi < 0) { return; }
  string en = env.variantOwners[vi];
  i32 n = env.fieldCountOf(en);
  fb.byte(65);
  fb.i32leb(env.variantTags[vi]);
  for (i32 slot = 1; slot < n; slot++) {
    i32 k = slot - env.variantSlot[vi];
    string ft = env.fieldTypeAt(en, slot);
    if (k >= 0 && k < env.variantArity[vi] && k < args.len()) {
      if (!(args[k] is null)) {
        emitExprAt(fb, src, lexed, env, args[k]!, ft);
        continue;
      }
    }
    emitNull(fb, env, ft);
  }
  fb.byte(251);
  fb.u32leb(0);   // struct.new
  fb.u32leb(env.structType(en));
}

/**
 * Which variant `Node.Element` is, or `-1` when the program never imported the tree.
 *
 * **By owner, not by name.** A variant is recorded under its own declared name — `Element` — and a
 * name two files declare is keyed, so neither `"Element"` nor `"Node.Element"` finds it reliably.
 * The owner is the enum, which is what makes this unambiguous: a program with its own `Element`
 * variant on its own enum does not collide with core's.
 */
/** Which variant `Node.Fragment` is, found the same way and for the same reason as `Element`. */
i32 jsxFragmentVariant(Env env) {
  for (i32 i = 0; i < env.variantCount; i++) {
    string owner = env.variantOwners[i];
    bool isNode = owner == "Node" || (owner.len() > 5 && owner.slice(0, 5) == "Node@");
    string vn = env.variantNames[i];
    bool isFragment = vn == "Fragment" || (vn.len() > 9 && vn.slice(0, 9) == "Fragment@");
    if (isNode && isFragment) { return i; }
  }
  return -1;
}

i32 jsxElementVariant(Env env) {
  for (i32 i = 0; i < env.variantCount; i++) {
    string owner = env.variantOwners[i];
    bool isNode = owner == "Node" || (owner.len() > 5 && owner.slice(0, 5) == "Node@");
    string vn = env.variantNames[i];
    bool isElement = vn == "Element" || (vn.len() > 8 && vn.slice(0, 8) == "Element@");
    if (isNode && isElement) { return i; }
  }
  return -1;
}

/**
 * `<div class="a">{kid}</div>` — the tree, written where types are strings.
 *
 * This is the whole of why the node survives to the emitter: `Node`, `Attr`, `Node[]` and `Attr[]`
 * are named here without a token existing for any of them, which is what the parser could not do.
 * The shape is `emitVariantNew`'s — a tag constant, one value per slot, `struct.new` — with the
 * three values built rather than taken from expressions.
 */
/**
 * `<Card title="x">kid</Card>` — a component, which is `Card { title: "x" }.render(Node[](kid))`.
 *
 * Written as the two instructions that desugaring is rather than by building an AST: the attributes
 * are put back in **declaration order** exactly as a named construction is (wasm's `struct.new`
 * takes fields in order and knows nothing about names), the receiver is pushed first because that is
 * what a method is here, and the children are the one argument. `design/lang/0005`.
 */
void emitJsxComponent(B fb, u8[] src, Lexed lexed, Env env, string comp,
                      JsxAttr[] attrs, Expr[] kids) {
  i32 nf = env.fieldCountOf(comp);
  for (i32 i = 0; i < nf; i++) {
    bool wrote = false;
    for (i32 j = 0; j < attrs.len(); j++) {
      if (env.fieldIndex(comp, tokenTextOf(src, lexed, attrs[j].nameTok)) != i) { continue; }
      emitExprAt(fb, src, lexed, env, attrs[j].value, env.fieldTypeAt(comp, i));
      wrote = true;
    }
    // An attribute that was not written is null, exactly as an omitted field of a named construction
    // is — the same rule, because this is one.
    if (!wrote) { emitNull(fb, env, env.fieldTypeAt(comp, i)); }
  }
  fb.byte(251);
  fb.u32leb(0);   // struct.new — the component, in declaration order
  fb.u32leb(env.structType(comp));
  emitJsxKids(fb, src, lexed, env, kids);
  i32 at = env.methodAt(comp, "render");
  if (at < 0 || env.funcIndex[at] < 0) { return; }
  fb.byte(16);    // call
  fb.u32leb(env.funcIndex[at]);
}

void emitJsx(B fb, u8[] src, Lexed lexed, Env env, i32 tagTok, JsxAttr[] attrs, Expr[] kids) {
  i32 vi = jsxElementVariant(env);
  // **A fragment**: no tag, no attributes, and its children where an element's would be.
  if (tagTok < 0) {
    i32 fi = jsxFragmentVariant(env);
    if (fi < 0) { return; }
    string fen = env.variantOwners[fi];
    i32 nfrag = env.fieldCountOf(fen);
    fb.byte(65);
    fb.i32leb(env.variantTags[fi]);
    for (i32 slot = 1; slot < nfrag; slot++) {
      i32 k = slot - env.variantSlot[fi];
      if (k == 0) { emitJsxKids(fb, src, lexed, env, kids); continue; }
      emitNull(fb, env, env.fieldTypeAt(fen, slot));
    }
    fb.byte(251);
    fb.u32leb(0);   // struct.new
    fb.u32leb(env.structType(fen));
    return;
  }
  // **A tag that names a struct in scope is a component**, resolved by the same key every other name
  // goes through — so a `Card` two files declare is the one this file can see. `design/lang/0005`.
  string comp = nameKeyOf(env, src, lexed, tagTok);
  if (env.isStructName(comp) && env.methodAt(comp, "render") >= 0) {
    emitJsxComponent(fb, src, lexed, env, comp, attrs, kids);
    return;
  }
  if (vi < 0) { return; }
  string en = env.variantOwners[vi];
  i32 n = env.fieldCountOf(en);
  fb.byte(65);
  fb.i32leb(env.variantTags[vi]);
  for (i32 slot = 1; slot < n; slot++) {
    i32 k = slot - env.variantSlot[vi];
    if (k == 0) { emitRawString(fb, env, tokenTextOf(src, lexed, tagTok)); continue; }
    if (k == 1) { emitJsxAttrs(fb, src, lexed, env, attrs); continue; }
    if (k == 2) { emitJsxKids(fb, src, lexed, env, kids); continue; }
    emitNull(fb, env, env.fieldTypeAt(en, slot));
  }
  fb.byte(251);
  fb.u32leb(0);   // struct.new
  fb.u32leb(env.structType(en));
}

/** A `string` from text the source did not quote — a tag name, or an attribute's name. */
void emitRawString(B fb, Env env, string text) {
  u8[] bytes = text.toBytes();
  for (i32 i = 0; i < bytes.len(); i++) {
    fb.byte(65);
    fb.i32leb(bytes[i]);
  }
  fb.byte(251);
  fb.u32leb(8);   // array.new_fixed
  fb.u32leb(env.arrayType("i8[]"));
  fb.u32leb(bytes.len());
}

/** `Attr[](Attr("class", "a"), …)`, one `struct.new` per attribute. */
void emitJsxAttrs(B fb, u8[] src, Lexed lexed, Env env, JsxAttr[] attrs) {
  for (i32 i = 0; i < attrs.len(); i++) {
    emitRawString(fb, env, tokenTextOf(src, lexed, attrs[i].nameTok));
    emitExprAt(fb, src, lexed, env, attrs[i].value, "string");
    fb.byte(251);
    fb.u32leb(0);   // struct.new
    fb.u32leb(env.structType("Attr"));
  }
  fb.byte(251);
  fb.u32leb(8);     // array.new_fixed
  fb.u32leb(env.arrayType("Attr[]"));
  fb.u32leb(attrs.len());
}

/**
 * `Node.Text("hello")` from a span of the source.
 *
 * **Trimmed at the ends, kept in the middle** — `design/lang/0004`'s one chosen rule rather than
 * derived one: `<p> hello  world </p>` is `Text("hello  world")`. A run that is only whitespace is
 * still emitted here; the parser is what decides whether to keep it, because only the parser knows
 * whether it sat between two elements.
 */
void emitJsxText(B fb, u8[] src, Env env, i32 startOff, i32 endOff) {
  // The whitespace rule is `jsxTrim` in `ast.wac`, because the parser applies the same one to decide
  // whether a run is a child at all.
  JsxSpan span = jsxTrim(src, startOff, endOff);
  i32 from = span.from;
  i32 to = span.to;
  i32 vi = jsxTextVariant(env);
  if (vi < 0) { return; }
  string en = env.variantOwners[vi];
  i32 n = env.fieldCountOf(en);
  fb.byte(65);
  fb.i32leb(env.variantTags[vi]);
  for (i32 slot = 1; slot < n; slot++) {
    i32 k = slot - env.variantSlot[vi];
    if (k == 0) {
      for (i32 i = from; i < to; i++) {
        fb.byte(65);
        fb.i32leb(src[i]);
      }
      fb.byte(251);
      fb.u32leb(8);   // array.new_fixed
      fb.u32leb(env.arrayType("i8[]"));
      fb.u32leb(to - from);
      continue;
    }
    emitNull(fb, env, env.fieldTypeAt(en, slot));
  }
  fb.byte(251);
  fb.u32leb(0);     // struct.new
  fb.u32leb(env.structType(en));
}

/** `Node.Text`, found the same way `Node.Element` is: by owner, because a name may be keyed. */
i32 jsxTextVariant(Env env) {
  for (i32 i = 0; i < env.variantCount; i++) {
    string owner = env.variantOwners[i];
    bool isNode = owner == "Node" || (owner.len() > 5 && owner.slice(0, 5) == "Node@");
    string vn = env.variantNames[i];
    bool isText = vn == "Text" || (vn.len() > 5 && vn.slice(0, 5) == "Text@");
    if (isNode && isText) { return i; }
  }
  return -1;
}

/** `Node[](…)` — every child is already a `Node`, including a nested element. */
void emitJsxKids(B fb, u8[] src, Lexed lexed, Env env, Expr[] kids) {
  for (i32 i = 0; i < kids.len(); i++) {
    emitExprAt(fb, src, lexed, env, kids[i], "Node");
  }
  fb.byte(251);
  fb.u32leb(8);     // array.new_fixed
  fb.u32leb(env.arrayType("Node[]"));
  fb.u32leb(kids.len());
}

/** The tag of the value on the stack, which is what every arm and every `is` compares. */
void emitTagOf(B fb, Env env, i32 subj, string en) {
  fb.byte(32);
  fb.u32leb(subj);
  fb.byte(251);
  fb.u32leb(2);   // struct.get
  fb.u32leb(env.structType(en));
  fb.u32leb(0);
}

/**
 * An arm's names: its payload bindings, and the narrowed subject.
 *
 * Both are **added while the body is emitted and retired after it**, which is possible only because
 * the locals *declaration* is written once the body is finished. That makes the shadowing lexical
 * for free: a binding is found before an outer local of the same name because `localAt` searches
 * backwards, and retiring the entry by renaming it — rather than by dropping it — keeps the wasm
 * slot and its type, which the declaration list still has to describe.
 */
void emitArmNames(B fb, u8[] src, Lexed lexed, Env env, i32 subj, string vn, i32[] bindingToks,
                  Expr subject) {
  i32 vi = env.variantAt(vn);
  if (vi < 0) { return; }
  string en = env.variantOwners[vi];
  for (i32 b = 0; b < bindingToks.len(); b++) {
    if (b >= env.variantArity[vi]) { continue; }
    string bn = tokenTextOf(src, lexed, bindingToks[b]);
    if (bn == "_") { continue; }
    env.addLocal(bn, env.fieldTypeAt(en, env.variantSlot[vi] + b));
    i32 at = env.localCount - 1;
    fb.byte(32);
    fb.u32leb(subj);
    fb.byte(251);
    fb.u32leb(2);
    fb.u32leb(env.structType(en));
    fb.u32leb(env.variantSlot[vi] + b);
    fb.byte(33);
    fb.u32leb(at);
  }
  // **Narrowing is a binding, not a retyping** — the spec says so, and it is also the only version
  // this emitter could implement: the subject keeps its wasm type either way, and what the arm needs
  // is a *name* whose wac type is the variant, so `s.width` resolves to one slot rather than to
  // whichever variant declared that field first.
  match (subject.kind) {
    case Ident(tok): {
      env.addLocal(tokenTextOf(src, lexed, tok), vn);
      i32 sh = env.localCount - 1;
      fb.byte(32);
      fb.u32leb(subj);
      fb.byte(33);
      fb.u32leb(sh);
    }
    else: { }
  }
}

/** Retire every name an arm introduced, keeping the slots it declared. */
void retireFrom(Env env, i32 from) {
  for (i32 i = from; i < env.localCount; i++) { env.locals[i] = " gone"; }
}

/**
 * `match` as a statement: a comparison chain on the tag, each arm nested in the previous one's else.
 *
 * Nesting rather than a block-and-branch per arm is what makes `break` mean the enclosing **loop**,
 * which is what the language says an arm's `break` does and the one place `match` differs from
 * `switch`. An `if` is a label like any other, so `env.depth` counts every one of them or a `break`
 * three arms deep branches to the wrong place — and validates while doing it.
 */
void emitMatchStmt(B fb, u8[] src, Lexed lexed, Env env, Expr subject, Arm[] arms) {
  string en = env.canonType(typeOfE(src, lexed, env, subject));
  if (!env.isEnumName(en)) { return; }
  env.addLocal(" match", en);
  i32 subj = env.localCount - 1;
  emitExprAt(fb, src, lexed, env, subject, en);
  fb.byte(33);
  fb.u32leb(subj);
  // **The `else` arm is the default wherever it is written**, and this chain used to emit each arm
  // where it stood — so an `else` written *first* had its body emitted unconditionally and no `case`
  // was ever reached. `typeOfE` in this file has exactly that shape, which is why the compiler this
  // compiler emits could not type a call: every one of them took the default.
  i32 elseAt = -1;
  i32 cases = 0;
  for (i32 a = 0; a < arms.len(); a++) {
    if (arms[a].variantTok < 0) { elseAt = a; } else { cases = cases + 1; }
  }
  i32 opened = 0;
  i32 done = 0;
  for (i32 a = 0; a < arms.len(); a++) {
    if (a == elseAt) { continue; }
    string vn = armVariant(env, src, lexed, arms[a].variantTok, en);
    emitTagOf(fb, env, subj, en);
    fb.byte(65);
    fb.i32leb(env.variantTags[env.variantAt(vn)]);
    fb.byte(70);   // i32.eq
    fb.byte(4);
    fb.byte(64);
    env.depth = env.depth + 1;
    opened = opened + 1;
    i32 saved = env.localCount;
    // **Every arm is a decision.** A `match` with five variants is five branches, and this compiler
    // recorded none of them — 125 in `packages/fs` alone. `issues/lang/0112`, and its point is the
    // one worth repeating: a construct that stops being instrumented makes the number go *up*.
    covPoint(fb, env, "case", tokenLine(lexed, arms[a].variantTok),
             tokenCol(lexed, arms[a].variantTok));
    emitArmNames(fb, src, lexed, env, subj, vn, arms[a].bindingToks, subject);
    emitBody(fb, src, lexed, env, arms[a].body);
    retireFrom(env, saved);
    done = done + 1;
    // The rest of the chain — and the default, if there is one — goes in this arm's `else`.
    if (done < cases || elseAt >= 0) { fb.byte(5); }
  }
  if (elseAt >= 0) {
    // An `else` arm is an arm: the reference records one and so does this, or a `match` with a
    // catch-all reports every branch but the one that catches.
    covPoint(fb, env, "case", tokenLine(lexed, arms[elseAt].variantTok),
             tokenCol(lexed, arms[elseAt].variantTok));
    emitBody(fb, src, lexed, env, arms[elseAt].body);
  }
  for (i32 i = 0; i < opened; i++) {
    fb.byte(11);
    env.depth = env.depth - 1;
  }
}

/**
 * `match` as an expression, where every arm leaves a value.
 *
 * The **last arm is not tested**. An `if` that produces a value must have an else branch, and the
 * match is exhaustive, so the final arm is that branch: the test would be a comparison whose answer
 * is already known, and without it there is nowhere to put the value.
 */
void emitMatchExpr(B fb, u8[] src, Lexed lexed, Env env, Expr subject, Arm[] arms, string want) {
  string en = env.canonType(typeOfE(src, lexed, env, subject));
  if (!env.isEnumName(en) || arms.len() == 0) { return; }
  string rt = "";
  for (i32 a = 0; a < arms.len(); a++) {
    if (arms[a].value is null) { continue; }
    if (rt != "") { continue; }
    i32 saved = pushArmNames(src, lexed, env, arms[a], subject);
    rt = typeOfE(src, lexed, env, arms[a].value!);
    env.localCount = saved;
  }
  if (rt == "") { rt = want; }
  env.addLocal(" match", en);
  i32 subj = env.localCount - 1;
  emitExprAt(fb, src, lexed, env, subject, en);
  fb.byte(33);
  fb.u32leb(subj);
  // The same reordering as the statement form, and for the same reason. What differs is which arm
  // is *untested*: an `if` that produces a value must have an else branch, so the default goes there
  // — and where there is no default, the last case does, since the match is exhaustive.
  i32 elseAt = -1;
  i32 cases = 0;
  for (i32 a = 0; a < arms.len(); a++) {
    if (arms[a].variantTok < 0) { elseAt = a; } else { cases = cases + 1; }
  }
  i32 opened = 0;
  i32 done = 0;
  for (i32 a = 0; a < arms.len(); a++) {
    if (a == elseAt) { continue; }
    done = done + 1;
    bool tail = elseAt < 0 && done == cases;
    string vn = armVariant(env, src, lexed, arms[a].variantTok, en);
    if (!tail) {
      emitTagOf(fb, env, subj, en);
      fb.byte(65);
      fb.i32leb(env.variantTags[env.variantAt(vn)]);
      fb.byte(70);
      fb.byte(4);
      writeValType(fb, env, rt);
      env.depth = env.depth + 1;
      opened = opened + 1;
    }
    i32 saved = env.localCount;
    // The expression form's arms are decisions too — the statement form's are recorded in
    // `emitMatchStmt`, and a `match` used for its value is the commoner of the two in this codebase.
    covPoint(fb, env, "case", tokenLine(lexed, arms[a].variantTok),
             tokenCol(lexed, arms[a].variantTok));
    emitArmNames(fb, src, lexed, env, subj, vn, arms[a].bindingToks, subject);
    if (!(arms[a].value is null)) { emitExprAt(fb, src, lexed, env, arms[a].value!, rt); }
    retireFrom(env, saved);
    if (!tail) { fb.byte(5); }
  }
  if (elseAt >= 0 && !(arms[elseAt].value is null)) {
    covPoint(fb, env, "case", tokenLine(lexed, arms[elseAt].variantTok),
             tokenCol(lexed, arms[elseAt].variantTok));
    emitExprAt(fb, src, lexed, env, arms[elseAt].value!, rt);
  }
  for (i32 i = 0; i < opened; i++) {
    fb.byte(11);
    env.depth = env.depth - 1;
  }
}

/**
 * A statement list, which is exactly a **scope**.
 *
 * The locals a block declares are added as its `var`s are emitted and retired when it ends — by
 * renaming rather than by dropping, since the slot they claimed still has to be declared in the
 * function's header. That is the whole of block scoping: two blocks declaring `k` at two types are
 * two locals, `localAt` searches backwards so the inner one shadows, and neither can see the other.
 *
 * It replaces a pre-pass that collected every local in the function by name, which could not tell
 * the two `k`s apart and declined the function rather than get it wrong.
 */
void emitBody(B fb, u8[] src, Lexed lexed, Env env, Stmt[] body) {
  i32 saved = env.localCount;
  for (i32 i = 0; i < body.len(); i++) { emitStmt(fb, src, lexed, env, body[i]); }
  retireFrom(env, saved);
}

/**
 * One statement.
 *
 * `if` and `while` are wasm's structured control flow rather than jumps, which is the one place the
 * emitted shape is *simpler* than the language's: a `while` is a `block` wrapping a `loop`, the
 * condition inverted and branching out of the block, the body branching back to the loop's top. The
 * two labels are relative — 1 is the block, 0 is the loop — and getting them the wrong way round
 * produces a module that validates and hangs, which is why both are tested by running.
 */
void emitStmt(B fb, u8[] src, Lexed lexed, Env env, Stmt s) {
  match (s.kind) {
    case Var(type, nameTok, init, isConst): {
      string vt = typeOfTyName(env, src, lexed, type);
      emitExprAt(fb, src, lexed, env, init, vt);
      // **A captured local is born in a cell.** The walk recorded which declarations are captured, by
      // position — so the value just emitted goes straight into a one-field struct and the slot holds
      // that. Everything else about the local is unchanged, including its type as far as every
      // expression naming it is concerned.
      bool cell = env.isPromoted(s.line, s.col);
      if (cell) {
        fb.byte(251); fb.u32leb(0);                   // struct.new $cell$T
        fb.u32leb(env.structType(cellStructName(vt)));
      }
      // **Declared here, not in a pre-pass.** The slot belongs to this statement, so a second `var`
      // of the same name is a second slot rather than a collision.
      env.addLocal(tokenTextOf(src, lexed, nameTok), vt);
      if (cell && env.localCount - 1 < env.localCell.len()) {
        env.localCell[env.localCount - 1] = true;
      }
      fb.byte(33);   // local.set
      fb.u32leb(env.localCount - 1);
    }
    case Assign(rawTarget, op, rhs): {
      Lvalue target = peelLv(rawTarget);
      match (target.kind) {
        case LField(base, nameTok): {
          string ot3 = typeOfLv(src, lexed, env, base);
          if (!env.isStructName(ot3)) { return; }
          string fname = tokenTextOf(src, lexed, nameTok);
          i32 slot = env.enumOf(ot3) != "" || env.isEnumName(ot3)
            ? enumSlot(env, ot3, fname) : env.fieldIndex(ot3, fname);
          string fty = env.enumOf(ot3) != "" || env.isEnumName(ot3)
            ? env.fieldTypeAt(env.canonType(ot3), slot) : env.fieldType(ot3, fname);
          i32 kf = lexed.tokens[op * tokenStride()];
          // **`p.x += 1` is a read, an operator and a write**, and this arm had none of the first two:
          // it emitted the assignment and dropped the operator, so the field was *replaced* by the
          // right-hand side. It validated, so nothing caught it — the field ended up an `i32` either
          // way — and no differential case had ever compounded into anything but a local.
          if (kf != kAssign()) {
            i32 b = env.scratchNamed("cmpbase", ot3);
            emitLvalue(fb, src, lexed, env, base);
            fb.byte(34);            // local.tee, so the base is evaluated once
            fb.u32leb(b);
            fb.byte(32);
            fb.u32leb(b);
            fb.byte(251);
            fb.u32leb(2);           // struct.get — the current value
            fb.u32leb(env.structType(ot3));
            fb.u32leb(slot);
            // **A shift's amount is converted, not assumed** — the same rule the binary operator
            // follows, and the compound form did not: `b.v <<= n` with an `i64` field and an `i32`
            // amount emitted `i64.shl` with an `i32` on the stack and the module would not load.
            // `emitExprAt` steers a *literal*; a typed local ignores it and arrives as itself, which
            // is why this is `emitAt`. `issues/lang/0117`.
            if (isShiftAssign(kf)) { emitAt(fb, src, lexed, env, rhs, fty); }
            else { emitExprAt(fb, src, lexed, env, rhs, fty); }
            emitCompound(fb, env, kf, fty);
            fb.byte(251);
            fb.u32leb(5);
            fb.u32leb(env.structType(ot3));
            fb.u32leb(slot);
            return;
          }
          emitLvalue(fb, src, lexed, env, base);
          emitExprAt(fb, src, lexed, env, rhs, fty);
          fb.byte(251);
          fb.u32leb(5);   // struct.set
          fb.u32leb(env.structType(ot3));
          fb.u32leb(slot);
        }
        case LIndex(base, index): {
          // The array and the index are pushed before the value, which is the order `array.set`
          // wants and the reverse of how the statement reads.
          string bt = typeOfLv(src, lexed, env, base);
          i32 ki = lexed.tokens[op * tokenStride()];
          // The same read-apply-write as a field, and the same bug: `a[i] += 1` was `a[i] = 1`. Both
          // operands are spilled first so that `a` and `i` are evaluated once and in source order.
          if (ki != kAssign()) {
            i32 ab = env.scratchNamed("cmparr", bt);
            i32 ix = env.scratchNamed("cmpidx", "i32");
            emitLvalue(fb, src, lexed, env, base);
            fb.byte(33);
            fb.u32leb(ab);
            emitAt(fb, src, lexed, env, index, "i32");
            fb.byte(33);
            fb.u32leb(ix);
            fb.byte(32); fb.u32leb(ab);
            fb.byte(32); fb.u32leb(ix);
            fb.byte(32); fb.u32leb(ab);
            fb.byte(32); fb.u32leb(ix);
            emitArrayGet(fb, env, bt);
            emitAt(fb, src, lexed, env, rhs, elemOf(bt));
            emitCompound(fb, env, ki, elemOf(bt));
            fb.byte(251);
            fb.u32leb(14);   // array.set
            fb.u32leb(env.arrayType(bt));
            return;
          }
          emitLvalue(fb, src, lexed, env, base);
          emitAt(fb, src, lexed, env, index, "i32");
          emitAt(fb, src, lexed, env, rhs, elemOf(bt));
          fb.byte(251);
          fb.u32leb(14);   // array.set
          fb.u32leb(env.arrayType(bt));
        }
        case LIdent(tok): {
          string name = tokenTextOf(src, lexed, tok);
          // **Writing a captured name, from inside the lambda.** It has no local — it is a cell in
          // the capture record — so without this the assignment found nothing and emitted nothing,
          // and the write was simply lost. That is what made `() => { n = 42; }` still answer 1 after
          // the enclosing side already had reference semantics.
          i32 wcap = env.captureAt(env.emittingLambda, name);
          if (wcap >= 0) {
            string wty = env.capTypes[env.emittingLambda * capsPerLambda() + wcap];
            i32 wk = lexed.tokens[op * tokenStride()];
            fb.byte(32); fb.u32leb(0);                  // the capture record
            fb.byte(251); fb.u32leb(2);                 // its cell
            fb.u32leb(env.structType(captureStructName(env.emittingLambda)));
            fb.u32leb(wcap);
            if (wk != kAssign()) {
              fb.byte(32); fb.u32leb(0);
              fb.byte(251); fb.u32leb(2);
              fb.u32leb(env.structType(captureStructName(env.emittingLambda)));
              fb.u32leb(wcap);
              fb.byte(251); fb.u32leb(2);
              fb.u32leb(env.structType(cellStructName(wty)));
              fb.u32leb(0);
            }
            if (isShiftAssign(wk)) { emitAt(fb, src, lexed, env, rhs, wty); }
            else { emitExprAt(fb, src, lexed, env, rhs, wty); }
            if (wk != kAssign()) { emitCompound(fb, env, wk, wty); }
            fb.byte(251); fb.u32leb(5);                 // struct.set
            fb.u32leb(env.structType(cellStructName(wty)));
            fb.u32leb(0);
            return;
          }
          i32 at = env.localAt(name);
          if (at < 0) { return; }
          i32 k = lexed.tokens[op * tokenStride()];
          string at2 = env.localTypes[at];
          // **A promoted local is written through its cell**, so the slot is pushed first and the
          // value stored into the struct rather than into the slot. `design/lang/0002` tier two: this
          // is the write that a lambda holding the same cell sees.
          bool cell = env.localIsCell(at);
          if (cell) { fb.byte(32); fb.u32leb(at); }
          if (k != kAssign()) {
            // `n += 1` is `n = n + 1` with the operator spelled into the assignment, so the target is
            // pushed first and the compound operator applied to the pair.
            fb.byte(32);
            fb.u32leb(at);
            if (cell) {
              fb.byte(251); fb.u32leb(2);
              fb.u32leb(env.structType(cellStructName(at2)));
              fb.u32leb(0);
            }
          }
          // See the field case above: a shift's amount is converted rather than assumed.
          if (isShiftAssign(k)) { emitAt(fb, src, lexed, env, rhs, at2); }
          else { emitExprAt(fb, src, lexed, env, rhs, at2); }
          if (k != kAssign()) { emitCompound(fb, env, k, at2); }
          if (cell) {
            fb.byte(251); fb.u32leb(5);               // struct.set
            fb.u32leb(env.structType(cellStructName(at2)));
            fb.u32leb(0);
            return;
          }
          fb.byte(33);
          fb.u32leb(at);
        }
        else: { }
      }
    }
    case Return(value): {
      // The **function's** return type, which a `return` is the one statement that needs and the only
      // one that had no way to know: `return 1;` in an `i64` function is an `i64` constant, and
      // emitting it at the literal's own guess made seven corpus files invalid at once.
      if (!(value is null)) { emitExprAt(fb, src, lexed, env, value!, env.returnType); }
      fb.byte(15);   // return
    }
    case If(cond, then, els): {
      emitExpr(fb, src, lexed, env, cond);
      fb.byte(4);    // if
      fb.byte(64);   // blocktype: nothing
      env.depth = env.depth + 1;
      covPoint(fb, env, "then", s.line, s.col);
      // **`if (s is Circle)` makes `s` a `Circle` inside the block**, which the checker does by
      // shadowing the binding and this had no equivalent of at all. A field access was declined —
      // `untyped member` — and a method call was worse: it resolved against the *declared* type, so
      // an `override` was not called and the answer was silently the parent's. `issues/lang/0116`.
      //
      // The same shadow, in the emitter's own terms: a fresh local of the narrowed type, cast once
      // at the top of the block, under the same name — and `localAt` searches backwards, so the
      // inner one wins for exactly as long as it is alive.
      i32 savedNarrow = env.localCount;
      narrowInto(fb, src, lexed, env, cond);
      emitBody(fb, src, lexed, env, then);
      retireFrom(env, savedNarrow);
      if (els.len() > 0) {
        fb.byte(5);  // else
        covPoint(fb, env, "else", s.line, s.col);
        emitBody(fb, src, lexed, env, els);
      }
      // **An `else` a host can tell apart from a missing one.** wasm needs no `else` arm for an
      // `if` with none, but a coverage reader does: a point that never fires and a branch that was
      // never written are different facts about a program.
      if (els.len() == 0 && env.coverage) {
        fb.byte(5);
        covPoint(fb, env, "else", s.line, s.col);
      }
      fb.byte(11);   // end
      env.depth = env.depth - 1;
    }
    case While(cond, inner): {
      emitLoop(fb, src, lexed, env, cond, inner, null);
    }
    case DoWhile(inner, cond): {
      // The body runs before the condition is asked, so the test moves to the bottom: the loop
      // branches back only while it holds, and there is no jump out at the top to write.
      i32 savedB = env.breakAt;
      i32 savedC = env.continueAt;
      fb.byte(2);
      fb.byte(64);
      env.depth = env.depth + 1;
      env.breakAt = env.depth;
      fb.byte(3);
      fb.byte(64);
      env.depth = env.depth + 1;
      // The same inner block as `for`, so `continue` lands on the condition rather than skipping it.
      fb.byte(2);
      fb.byte(64);
      env.depth = env.depth + 1;
      env.continueAt = env.depth;
      emitBody(fb, src, lexed, env, inner);
      fb.byte(11);
      env.depth = env.depth - 1;
      emitExpr(fb, src, lexed, env, cond);
      fb.byte(13);
      fb.u32leb(0);
      fb.byte(11);
      fb.byte(11);
      env.depth = env.depth - 2;
      env.breakAt = savedB;
      env.continueAt = savedC;
    }
    case For(init, cond, update, inner): {
      // **The loop's own scope.** `for (i32 i = …)` beside an outer `i` is two locals, and the
      // init is emitted outside the body — so without this the loop's `i` stayed in the enclosing
      // scope and `localAt` found it afterwards, since it searches backwards. The spec has a case
      // for exactly this and it read 10 where the outer `i` was 99.
      i32 savedFor = env.localCount;
      if (!(init is null)) { emitStmt(fb, src, lexed, env, init!); }
      emitLoop(fb, src, lexed, env, cond is null ? null : cond, inner, update);
      retireFrom(env, savedFor);
    }
    case Break: {
      fb.byte(12);
      fb.u32leb(env.depth - env.breakAt);
    }
    case Continue: {
      fb.byte(12);
      fb.u32leb(env.depth - env.continueAt);
    }
    case Trap: { fb.byte(0); }
    case Switch(subject, cases): {
      // A chain of comparisons rather than a jump table. `br_table` is what the reference emits and
      // is an optimisation of exactly this — the values a canonical form would have to normalise
      // anyway, and the answers are what this rung compares.
      i32 savedS = env.breakAt;
      fb.byte(2);
      fb.byte(64);
      env.depth = env.depth + 1;
      env.breakAt = env.depth;
      string st = typeOfE(src, lexed, env, subject);
      for (i32 i = 0; i < cases.len(); i++) {
        if (cases[i].value is null) { continue; }
        emitExprAt(fb, src, lexed, env, subject, st);
        emitExprAt(fb, src, lexed, env, cases[i].value!, st);
        emitBinary(fb, env, kEq(), st);
        fb.byte(4);
        fb.byte(64);
        env.depth = env.depth + 1;
        covPoint(fb, env, "case", cases[i].line, cases[i].col);
        emitBody(fb, src, lexed, env, cases[i].body);
        // **Leave the switch when an arm has run.** A wac `case` is a block and not a label, so
        // nothing falls out of it — and this emitted the arms as a chain of `if`s with the default
        // *after* them, unconditionally. A later case did not run, because its comparison failed;
        // the default ran every time. `packages/json` wrote every escape twice and `"a\"b"` came
        // back as `"a\""b"`: the `case '"'` arm pushed `\"` and then `default` pushed the byte
        // again. The branch is to the block this statement opened, which is where `break` goes too.
        // `spec/cases/0089`.
        fb.byte(12);
        fb.u32leb(env.depth - env.breakAt);
        env.depth = env.depth - 1;
        fb.byte(11);
      }
      for (i32 i = 0; i < cases.len(); i++) {
        if (!(cases[i].value is null)) { continue; }
        covPoint(fb, env, "case", cases[i].line, cases[i].col);
        emitBody(fb, src, lexed, env, cases[i].body);
      }
      fb.byte(11);
      env.depth = env.depth - 1;
      env.breakAt = savedS;
    }
    case IncrStmt(rawTarget, op): {
      Lvalue target = peelLv(rawTarget);
      // `i++` is the commonest `for` update in the language and had **no arm here at all**, so the
      // update emitted nothing and the loop never advanced. It did not fail: it validated and span,
      // and the test hung rather than reporting — which is the failure mode this rung's oracle was
      // chosen to catch and the one it cannot report politely.
      match (target.kind) {
        case LIdent(tok): {
          // `n++` on a captured name, from inside the lambda — the same read-modify-write through the
          // cell as the assignment above. Without it the increment found no local and emitted
          // nothing, so a captured counter stayed put while every other mutation worked.
          i32 icap = env.captureAt(env.emittingLambda, tokenTextOf(src, lexed, tok));
          if (icap >= 0) {
            string ity = env.capTypes[env.emittingLambda * capsPerLambda() + icap];
            i32 capT = env.structType(captureStructName(env.emittingLambda));
            i32 cellT = env.structType(cellStructName(ity));
            fb.byte(32); fb.u32leb(0);
            fb.byte(251); fb.u32leb(2); fb.u32leb(capT); fb.u32leb(icap);
            fb.byte(32); fb.u32leb(0);
            fb.byte(251); fb.u32leb(2); fb.u32leb(capT); fb.u32leb(icap);
            fb.byte(251); fb.u32leb(2); fb.u32leb(cellT); fb.u32leb(0);
            if (valType(ity) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
            emitBinary(fb, env, lexed.tokens[op * tokenStride()] == kInc() ? kPlus() : kMinus(), ity);
            fb.byte(251); fb.u32leb(5); fb.u32leb(cellT); fb.u32leb(0);
            return;
          }
          i32 at = env.localAt(tokenTextOf(src, lexed, tok));
          if (at < 0) { return; }
          string t = env.localTypes[at];
          // `i++` on a promoted local reads through the cell and writes back through it — the same
          // shape as the compound assignment above, and the reason a `for` counter that a lambda
          // captures still advances.
          bool cell = env.localIsCell(at);
          if (cell) { fb.byte(32); fb.u32leb(at); }
          fb.byte(32);
          fb.u32leb(at);
          if (cell) {
            fb.byte(251); fb.u32leb(2);
            fb.u32leb(env.structType(cellStructName(t)));
            fb.u32leb(0);
          }
          if (valType(t) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
          emitBinary(fb, env, lexed.tokens[op * tokenStride()] == kInc() ? kPlus() : kMinus(), t);
          if (cell) {
            fb.byte(251); fb.u32leb(5);
            fb.u32leb(env.structType(cellStructName(t)));
            fb.u32leb(0);
            return;
          }
          fb.byte(33);
          fb.u32leb(at);
        }
        // **And the same for a field**, which this arm did not have — so `this.pos++` emitted
        // nothing at all, and `lex.wac`'s cursor never advanced. That is a lexer that validates and
        // loops for ever, and it is what the bootstrap found in its first minute: 336 corpus files
        // and three and a half thousand generated programs had never incremented a field.
        case LField(base, nameTok): {
          string ot4 = typeOfLv(src, lexed, env, base);
          if (!env.isStructName(ot4)) { return; }
          string fn4 = tokenTextOf(src, lexed, nameTok);
          i32 slot4 = env.enumOf(ot4) != "" || env.isEnumName(ot4)
            ? enumSlot(env, ot4, fn4) : env.fieldIndex(ot4, fn4);
          string ft4 = env.enumOf(ot4) != "" || env.isEnumName(ot4)
            ? env.fieldTypeAt(env.canonType(ot4), slot4) : env.fieldType(ot4, fn4);
          i32 b4 = env.scratchNamed("incbase", ot4);
          emitLvalue(fb, src, lexed, env, base);
          fb.byte(34);
          fb.u32leb(b4);
          fb.byte(32);
          fb.u32leb(b4);
          fb.byte(251);
          fb.u32leb(2);
          fb.u32leb(env.structType(ot4));
          fb.u32leb(slot4);
          if (valType(ft4) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
          emitBinary(fb, env, lexed.tokens[op * tokenStride()] == kInc() ? kPlus() : kMinus(), ft4);
          fb.byte(251);
          fb.u32leb(5);
          fb.u32leb(env.structType(ot4));
          fb.u32leb(slot4);
        }
        case LIndex(base, index): {
          string bt4 = typeOfLv(src, lexed, env, base);
          if (!isArrayType(bt4)) { return; }
          string et4 = elemOf(bt4);
          i32 a4 = env.scratchNamed("incarr", bt4);
          i32 i4 = env.scratchNamed("incidx", "i32");
          emitLvalue(fb, src, lexed, env, base);
          fb.byte(33); fb.u32leb(a4);
          emitAt(fb, src, lexed, env, index, "i32");
          fb.byte(33); fb.u32leb(i4);
          fb.byte(32); fb.u32leb(a4);
          fb.byte(32); fb.u32leb(i4);
          fb.byte(32); fb.u32leb(a4);
          fb.byte(32); fb.u32leb(i4);
          emitArrayGet(fb, env, bt4);
          if (valType(et4) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
          emitBinary(fb, env, lexed.tokens[op * tokenStride()] == kInc() ? kPlus() : kMinus(), et4);
          fb.byte(251);
          fb.u32leb(14);
          fb.u32leb(env.arrayType(bt4));
        }
        else: { }
      }
    }
    case Match(subject, arms): { emitMatchStmt(fb, src, lexed, env, subject, arms); }
    case Block(inner): { emitBody(fb, src, lexed, env, inner); }
    case ExprStmt(e) : {
      // A call for its effect — and if it *does* return something, the value has to go somewhere.
      // wasm's stack is not a suggestion: a function that leaves one is ill-typed at its end, which
      // is what *"expected 0 elements on the stack"* was saying about six corpus files.
      emitExpr(fb, src, lexed, env, e);
      // `""` is *unknown* and `"void"` is *nothing* — two different answers that both mean "no value
      // to drop", and treating the second as a value dropped one that was never pushed.
      string st = typeOfE(src, lexed, env, e);
      if (st != "" && st != "void") { fb.byte(26); }   // drop
    }
  }
}

/**
 * The shape `while` and `for` share: a block wrapping a loop, the condition at the top.
 *
 * `for`'s update runs before the branch back, which is what makes `continue` land on it rather than
 * skip it — the one place the two forms differ, and the reason they are one function.
 */
void emitLoop(B fb, u8[] src, Lexed lexed, Env env, Expr? cond, Stmt[] inner, Stmt? update) {
  i32 savedB = env.breakAt;
  i32 savedC = env.continueAt;
  fb.byte(2);
  fb.byte(64);   // block — what `break` leaves
  env.depth = env.depth + 1;
  env.breakAt = env.depth;
  fb.byte(3);
  fb.byte(64);   // loop — what `continue` returns to
  env.depth = env.depth + 1;
  env.continueAt = env.depth;
  if (!(cond is null)) {
    emitExpr(fb, src, lexed, env, cond!);
    fb.byte(69);   // i32.eqz — leave when the condition fails
    fb.byte(13);
    fb.u32leb(1);
  }
  // **A third block, around the body.** `continue` has to reach the update rather than skip it, so it
  // cannot branch to the loop's own label — it leaves an inner block whose end is where the update
  // begins. Branching to the loop instead is a `for` that never advances: the module validates, the
  // answer never comes, and the test *hangs* rather than failing. Which is what it did.
  fb.byte(2);
  fb.byte(64);
  env.depth = env.depth + 1;
  env.continueAt = env.depth;
  covPoint(fb, env, "loop", cond is null ? 0 : cond!.line, cond is null ? 0 : cond!.col);
  emitBody(fb, src, lexed, env, inner);
  fb.byte(11);
  env.depth = env.depth - 1;
  if (!(update is null)) { emitStmt(fb, src, lexed, env, update!); }
  fb.byte(12);
  fb.u32leb(0);
  fb.byte(11);
  fb.byte(11);
  env.depth = env.depth - 2;
  env.breakAt = savedB;
  env.continueAt = savedC;
}

/** The operator of a compound assignment, which is the binary one with the `=` taken off. */
void emitCompound(B fb, Env env, i32 k, string t) {
  // `s += x` is a concatenation, which is a call rather than an instruction — the same helper the
  // expression form uses, so the two spellings cannot drift apart.
  if (t == "string" && k == kPlusEq()) {
    i32 cc = env.funcAt(" str_concat");
    if (cc < 0 || env.funcIndex[cc] < 0) { return; }
    fb.byte(16);
    fb.u32leb(env.funcIndex[cc]);
    return;
  }
  // **All eleven**, by name. Four of them were written as raw numbers 58 to 61, which covered the
  // arithmetic and silently ignored the bitwise ones — `result ^= x` emitted its two operands and no
  // operator, leaving a value on the stack that wasm noticed at the end of the function.
  if (k == kPlusEq()) { emitBinary(fb, env, kPlus(), t); }
  if (k == kMinusEq()) { emitBinary(fb, env, kMinus(), t); }
  if (k == kStarEq()) { emitBinary(fb, env, kStar(), t); }
  if (k == kSlashEq()) { emitBinary(fb, env, kSlash(), t); }
  if (k == kPercentEq()) { emitBinary(fb, env, kPercent(), t); }
  if (k == kAndEq()) { emitBinary(fb, env, kAnd(), t); }
  if (k == kOrEq()) { emitBinary(fb, env, kOr(), t); }
  if (k == kCaretEq()) { emitBinary(fb, env, kCaret(), t); }
  if (k == kShlEq()) { emitBinary(fb, env, kShl(), t); }
  if (k == kShrEq()) { emitBinary(fb, env, kShr(), t); }
  if (k == kShrUEq()) { emitBinary(fb, env, kShrU(), t); }
}

/**
 * An expression, in the order wasm wants it: operands, then the operator.
 *
 * `&&` and `||` are the exception, and the reason is that they **short-circuit**: they cannot be two
 * operands and an opcode, because the right one may not be evaluated at all. Each becomes an `if`
 * with a value type — the one place this emitter writes a block that produces something.
 */
/**
 * `x++` and `++x` **as expressions**, which is what `spec/spec/operators.md` says they are.
 *
 * The difference between the two is only *when* the value is taken, so both forms are the same
 * instructions in a different order rather than two implementations. The base of a field or an
 * element is put in a scratch and read twice from there: `f().x++` must call `f` once, and an
 * emitter that reaches for `emitLvalue` a second time calls it twice.
 */
void emitIncrExpr(B fb, u8[] src, Lexed lexed, Env env, Lvalue rawTarget, i32 op, bool prefix) {
  Lvalue target = peelLv(rawTarget);
  i32 kind = lexed.tokens[op * tokenStride()] == kInc() ? kPlus() : kMinus();
  match (target.kind) {
    // Peeled above, so this cannot arrive — but the language wants every variant named.
    case LUnwrap(base): { emitIncrExpr(fb, src, lexed, env, base, op, prefix); }
    case LIdent(tok): {
      i32 at = env.localAt(tokenTextOf(src, lexed, tok));
      if (at < 0) { return; }
      string t = env.localTypes[at];
      fb.byte(32); fb.u32leb(at);
      if (prefix) {
        if (valType(t) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
        emitBinary(fb, env, kind, t);
        fb.byte(34); fb.u32leb(at);        // local.tee — the new value is the answer
        return;
      }
      fb.byte(32); fb.u32leb(at);          // the old value stays underneath
      if (valType(t) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
      emitBinary(fb, env, kind, t);
      fb.byte(33); fb.u32leb(at);
    }
    case LField(base, nameTok): {
      string ot = typeOfLv(src, lexed, env, base);
      if (!env.isStructName(ot)) { return; }
      string fname = tokenTextOf(src, lexed, nameTok);
      bool en = env.enumOf(ot) != "" || env.isEnumName(ot);
      i32 slot = en ? enumSlot(env, ot, fname) : env.fieldIndex(ot, fname);
      string ft = en ? env.fieldTypeAt(env.canonType(ot), slot) : env.fieldType(ot, fname);
      i32 b = env.scratchNamed("iebase", ot);
      i32 v = env.scratchNamed("ieval", ft);
      emitLvalue(fb, src, lexed, env, base);
      fb.byte(33); fb.u32leb(b);
      if (!prefix) {
        fb.byte(32); fb.u32leb(b);
        fb.byte(251); fb.u32leb(2); fb.u32leb(env.structType(ot)); fb.u32leb(slot);
      }
      fb.byte(32); fb.u32leb(b);
      fb.byte(32); fb.u32leb(b);
      fb.byte(251); fb.u32leb(2); fb.u32leb(env.structType(ot)); fb.u32leb(slot);
      if (valType(ft) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
      emitBinary(fb, env, kind, ft);
      if (prefix) { fb.byte(34); fb.u32leb(v); }
      fb.byte(251); fb.u32leb(5); fb.u32leb(env.structType(ot)); fb.u32leb(slot);
      if (prefix) { fb.byte(32); fb.u32leb(v); }
    }
    case LIndex(base, index): {
      string bt = typeOfLv(src, lexed, env, base);
      if (!isArrayType(bt)) { return; }
      string et = elemOf(bt);
      i32 a = env.scratchNamed("iearr", bt);
      i32 i = env.scratchNamed("ieidx", "i32");
      i32 v2 = env.scratchNamed("ieval", et);
      emitLvalue(fb, src, lexed, env, base);
      fb.byte(33); fb.u32leb(a);
      emitAt(fb, src, lexed, env, index, "i32");
      fb.byte(33); fb.u32leb(i);
      if (!prefix) {
        fb.byte(32); fb.u32leb(a);
        fb.byte(32); fb.u32leb(i);
        emitArrayGet(fb, env, bt);
      }
      fb.byte(32); fb.u32leb(a);
      fb.byte(32); fb.u32leb(i);
      fb.byte(32); fb.u32leb(a);
      fb.byte(32); fb.u32leb(i);
      emitArrayGet(fb, env, bt);
      if (valType(et) == 126) { fb.byte(66); fb.i64leb(1); } else { fb.byte(65); fb.i32leb(1); }
      emitBinary(fb, env, kind, et);
      if (prefix) { fb.byte(34); fb.u32leb(v2); }
      fb.byte(251); fb.u32leb(14); fb.u32leb(env.arrayType(bt));
      if (prefix) { fb.byte(32); fb.u32leb(v2); }
    }
  }
}

void emitExpr(B fb, u8[] src, Lexed lexed, Env env, Expr e) {
  emitExprAt(fb, src, lexed, env, e, "");
}

/**
 * An expression, told what type the slot it fills is.
 *
 * Only a literal needs it — everything else knows its own type — but a literal can be anywhere, so
 * the wanted type is passed down every arm rather than special-cased at the few places one is likely.
 */
void emitExprAt(B fb, u8[] src, Lexed lexed, Env env, Expr e, string want) {
  match (e.kind) {
    // **A lambda is its hoisted function's wrapper, with a null env** — `design/lang/0002` tier two.
    // Identical to `emitFuncPair` except for which wrapper: a lambda has no declaration to look up,
    // so it is found by the position key the walk recorded, which is the one thing both walks read
    // from the same node and therefore cannot disagree about.
    //
    // The env is null because capture is not built yet. That is the *whole* of what remains: the
    // pair, the wrapper, the hoisted body and the signature are all here, and a capturing lambda
    // differs only by carrying a generated struct where this carries `ref.null any`.
    case Lambda(params, body): {
      i32 li = env.lambdaAtPos(e.line, e.col);
      if (li < 0 || env.lambdaSigs[li] == "") {
        env.declineFor("a lambda whose type this emitter could not work out");
        return;
      }
      if (env.lambdaCapCount[li] > 0) {
        // **Capturing: the bound wrapper, and the capture struct as the env.** The struct is built
        // here, in the enclosing function, where the captured names *are* locals — which is the whole
        // reason this works: the values are read at the point the lambda is created.
        fb.byte(210);                                   // ref.func <bound wrapper>
        fb.u32leb(env.boundAt + env.lambdaFirst + li);
        i32 from = li * capsPerLambda();
        for (i32 c = 0; c < env.lambdaCapCount[li]; c++) {
          emitExprName(fb, src, lexed, env, env.capNames[from + c], env.capTypes[from + c]);
        }
        fb.byte(251); fb.u32leb(0);                     // struct.new — the capture record
        fb.u32leb(env.structType(captureStructName(li)));
        fb.byte(251); fb.u32leb(0);                     // struct.new — the pair
        fb.u32leb(env.pairType(env.lambdaSigs[li]));
        return;
      }
      fb.byte(210);                                     // ref.func <wrapper>
      fb.u32leb(env.wrapAt + env.lambdaFirst + li);
      fb.byte(208); fb.byte(110);                       // ref.null any — nothing captured
      fb.byte(251); fb.u32leb(0);                       // struct.new
      fb.u32leb(env.pairType(env.lambdaSigs[li]));
    }
    case IntLit(tok): {
      // A literal is emitted at the type its **context** wants, which is the same fact the checker
      // states as "a literal is polymorphic over a family": `i64 x = 1;` needs `i64.const`, and the
      // `1` says nothing about that.
      i64 v = parseInt(tokenTextOf(src, lexed, tok));
      if (valType(want) == 126) { fb.byte(66); fb.i64leb(v); return; }
      if (want == "f32") { fb.byte(67); fb.f32bits(v as~ f32); return; }
      if (want == "f64") { fb.byte(68); fb.f64bits(v as~ f64); return; }
      fb.byte(65);
      fb.i32leb(v as@ i32);
    }
    case FloatLit(tok): {
      f64 v = floatLit(tokenTextOf(src, lexed, tok));
      if (want == "f32") { fb.byte(67); fb.f32bits(v as~ f32); return; }
      fb.byte(68);
      fb.f64bits(v);
    }
    case BoolLit(value): {
      fb.byte(65);
      fb.i32leb(value ? 1 : 0);
    }
    case Jsx(tagTok, closeTok, attrs, kids): {
      emitJsx(fb, src, lexed, env, tagTok, attrs, kids);
      return;
    }
    case JsxText(startOff, endOff): {
      emitJsxText(fb, src, env, startOff, endOff);
      return;
    }
    case StrLit(tok): {
      // The bytes, then `array.new_fixed`. A literal's token spans the quotes, so the span is walked
      // rather than taken whole, and the four escapes wac's own sources use are resolved on the way.
      u8[] bytes = stringLiteralBytes(src, lexed, tok);
      for (i32 i = 0; i < bytes.len(); i++) {
        fb.byte(65);
        fb.i32leb(bytes[i]);
      }
      fb.byte(251);
      fb.u32leb(8);   // array.new_fixed
      fb.u32leb(env.arrayType("i8[]"));
      fb.u32leb(bytes.len());
    }
    case Cast(op, operand, target): {
      string from = typeOfE(src, lexed, env, operand);
      string to = typeOfTyName(env, src, lexed, target);
      // **A literal has no type of its own, so it takes the slot's** — and the slot here is the
      // cast's own target, which made `42 as! i31ref` a conversion from `i31ref` to `i31ref`: no
      // instructions at all, and an `i32` left where a reference belonged. A cast *into* a reference
      // is the one place the operand's want cannot be the target.
      string want2 = from == "" ? to : from;
      if (to == "i31ref" && from == "") { want2 = "i32"; }
      // **A float literal being converted is still a float.** With no type of its own it took the
      // cast's target, so `1.5 as~ i32` emitted the literal *as an `i32`* and then converted `i32`
      // to `i32` — nothing at all — leaving an `f64` where the function had promised an `i32`. Every
      // spelling of it was a module that would not load: `1.5 as~ i32`, `1.5 as@ i32`,
      // `-2.3 as@ i32`, `1.0e300 as@ i32`. `f64` here and the conversion does the work, except into
      // a float target, where the target's own width is the right slot. `issues/lang/0117`.
      if (from == "" && isFloatLiteral(operand) && to != "f32" && to != "f64") { want2 = "f64"; }
      emitExprAt(fb, src, lexed, env, operand, want2);
      emitCast(fb, env, want2, to, tokenKindOf(lexed, op));
    }
    case Ident(tok): {
      string nm = tokenTextOf(src, lexed, tok);
      // **A captured name comes from the receiver, not from a local.** Checked before `localAt`,
      // because the hoisted function has no local of that name at all — and after the lambda's own
      // parameters would be found, which they are not, since a capture is by definition a name the
      // lambda did not declare.
      if (emitNameValue(fb, src, lexed, env, nm)) { return; }
      i32 at = env.localAt(nm);
      if (at < 0) { nm = nameKeyOf(env, src, lexed, tok); }
      // A function's **name**, used as a value, is a reference to it. Nothing else in the language
      // spells this — there is no `&f` — so a bare name that is neither a local nor a constant and
      // *is* a function is the whole of the syntax.
      if (env.constAt(nm) < 0) {
        i32 fr = env.funcAt(nm);
        if (fr >= 0 && env.funcIndex[fr] >= 0) {
          emitFuncPair(fb, env, fr, want);
          return;
        }
      }
      // A module-level constant, substituted. A local wins a name clash because it is nearer, which
      // is why this is asked second.
      i32 ci = env.constAt(nm);
      if (ci < 0) { return; }
      // A constant with identity lives in a global and is *read*; a scalar has none and is
      // substituted. One array shared by every use is the whole difference between the two.
      if (env.constGlobal[ci] >= 0) {
        fb.byte(35);   // global.get
        fb.u32leb(env.constGlobal[ci]);
        return;
      }
      if (env.constInits[ci] is null) { return; }
      emitExprAt(fb, src, lexed, env, env.constInits[ci]!, env.constTypes[ci]);
    }
    case Unary(op, operand): {
      i32 k = lexed.tokens[op * tokenStride()];
      if (k == kBang()) {
        emitExpr(fb, src, lexed, env, operand);
        fb.byte(69);   // i32.eqz
        return;
      }
      string ut = typeOfE(src, lexed, env, operand);
      if (ut == "") { ut = want; }
      if (k == kMinus()) {
        // A float *has* a negation instruction; an integer does not, and is a subtraction from zero.
        if (isFloat(ut)) {
          emitExprAt(fb, src, lexed, env, operand, ut);
          fb.byte(ut == "f32" ? 140 : 154);
          return;
        }
        if (valType(ut) == 126) { fb.byte(66); fb.i32leb(0); }
        else { fb.byte(65); fb.i32leb(0); }
        emitExprAt(fb, src, lexed, env, operand, ut);
        fb.byte(valType(ut) == 126 ? 125 : 107);
        return;
      }
      if (k == kTilde()) {
        emitExprAt(fb, src, lexed, env, operand, ut);
        if (valType(ut) == 126) { fb.byte(66); fb.i32leb(-1); fb.byte(133); }
        else { fb.byte(65); fb.i32leb(-1); fb.byte(115); }
        return;
      }
    }
    case Binary(op, left, right): {
      i32 k = lexed.tokens[op * tokenStride()];
      if (k == kAndAnd() || k == kOrOr()) {
        emitExpr(fb, src, lexed, env, left);
        fb.byte(4);
        fb.byte(wasmI32());   // if, producing an i32
        if (k == kAndAnd()) {
          // **The right-hand side of a short circuit is a branch**, and it had no point — so a
          // coverage report called `a && b` covered when only `a` had ever been true, and a
          // constant-time trace could not see a secret deciding whether `b` runs at all. The
          // reference records `and-rhs`/`or-rhs`; this is the same point under the same name.
          covPoint(fb, env, "and-rhs", right.line, right.col);
          emitExpr(fb, src, lexed, env, right);
          fb.byte(5);
          fb.byte(65);
          fb.i32leb(0);
        } else {
          fb.byte(65);
          fb.i32leb(1);
          fb.byte(5);
          covPoint(fb, env, "or-rhs", right.line, right.col);
          emitExpr(fb, src, lexed, env, right);
        }
        fb.byte(11);
        return;
      }
      string ot0 = operandType(src, lexed, env, left, right);
      if (ot0 == "string" && k == kPlus()) {
        i32 cc = env.funcAt(" str_concat");
        if (cc < 0 || env.funcIndex[cc] < 0) { return; }
        emitExpr(fb, src, lexed, env, left);
        emitExpr(fb, src, lexed, env, right);
        fb.byte(16);
        fb.u32leb(env.funcIndex[cc]);
        return;
      }
      // `<`, `<=`, `>`, `>=` on strings are the helper's answer against zero — which is how the
      // comparison stays one definition rather than four.
      if (ot0 == "string" &&
          (k == kLt() || k == kLe() || k == kGt() || k == kGe())) {
        i32 cc2 = env.funcAt(" str_cmp");
        if (cc2 < 0 || env.funcIndex[cc2] < 0) { return; }
        emitExpr(fb, src, lexed, env, left);
        emitExpr(fb, src, lexed, env, right);
        fb.byte(16);
        fb.u32leb(env.funcIndex[cc2]);
        fb.byte(65);
        fb.i32leb(0);
        if (k == kLt()) { fb.byte(72); }
        if (k == kLe()) { fb.byte(76); }
        if (k == kGt()) { fb.byte(74); }
        if (k == kGe()) { fb.byte(78); }
        return;
      }
      if (ot0 == "string" && (k == kEq() || k == kNe())) {
        i32 eq = env.funcAt(" str_eq");
        if (eq < 0 || env.funcIndex[eq] < 0) { return; }
        emitExpr(fb, src, lexed, env, left);
        emitExpr(fb, src, lexed, env, right);
        fb.byte(16);
        fb.u32leb(env.funcIndex[eq]);
        // `!=` is the same comparison, negated — which is one instruction rather than a second helper.
        if (k == kNe()) { fb.byte(69); }
        return;
      }
      string ot = operandType(src, lexed, env, left, right);
      // When **both** operands are literals there is no type to take from them, and the slot is the
      // only thing that knows: `0.0 / 0.0` in an `f64` return is an `f64` division. Without this the
      // operands went out as `f64` and the operator as `i32.div_s` — the two halves of one expression
      // disagreeing, because they asked different things.
      //
