i64 p5(i32 a, i32 b, i32 c, i32 d, i32 e) { return (p4(a, b, c, d) << 8) | (e as i64); }
i64 p6(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f) {
  return (p5(a, b, c, d, e) << 8) | (f as i64);
}
i64 p7(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f, i32 g) {
  return (p6(a, b, c, d, e, f) << 8) | (g as i64);
}
i64 p8(i32 a, i32 b, i32 c, i32 d, i32 e, i32 f, i32 g, i32 h) {
  return (p7(a, b, c, d, e, f, g) << 8) | (h as i64);
}

/** The keyword kind for an identifier span, or `kIdent` if it is not a keyword. */
i32 keywordKind(u8[] src, i32 start, i32 len) {
  if (len < 2 || len > 8) { return kIdent(); }
  i64 v = packSpan(src, start, len);

  if (len == 2) {
    if (v == p2('i', 'f')) { return kIf(); }
    if (v == p2('d', 'o')) { return kDo(); }
    if (v == p2('i', 's')) { return kIs(); }
    if (v == p2('a', 's')) { return kAs(); }
    if (v == p2('f', 'n')) { return kFn(); }
    return kIdent();
  }
  if (len == 3) {
    if (v == p3('f', 'o', 'r')) { return kFor(); }
    if (v == p3('n', 'o', 't')) { return kNot(); }
    return kIdent();
  }
  if (len == 4) {
    if (v == p4('e', 'l', 's', 'e')) { return kElse(); }
    if (v == p4('c', 'a', 's', 'e')) { return kCase(); }
    if (v == p4('t', 'r', 'u', 'e')) { return kTrue(); }
    if (v == p4('n', 'u', 'l', 'l')) { return kNull(); }
    if (v == p4('v', 'o', 'i', 'd')) { return kVoid(); }
    if (v == p4('t', 'h', 'i', 's')) { return kThis(); }
    if (v == p4('t', 'r', 'a', 'p')) { return kTrap(); }
    if (v == p4('e', 'n', 'u', 'm')) { return kEnum(); }
    return kIdent();
  }
  if (len == 5) {
    if (v == p5('w', 'h', 'i', 'l', 'e')) { return kWhile(); }
    if (v == p5('b', 'r', 'e', 'a', 'k')) { return kBreak(); }
    if (v == p5('f', 'a', 'l', 's', 'e')) { return kFalse(); }
    if (v == p5('c', 'o', 'n', 's', 't')) { return kConst(); }
    if (v == p5('m', 'a', 't', 'c', 'h')) { return kMatch(); }
    return kIdent();
  }
  if (len == 6) {
    if (v == p6('i', 'm', 'p', 'o', 'r', 't')) { return kImport(); }
    if (v == p6('e', 'x', 'p', 'o', 'r', 't')) { return kExport(); }
    if (v == p6('s', 't', 'r', 'u', 'c', 't')) { return kStruct(); }
    if (v == p6('s', 'w', 'i', 't', 'c', 'h')) { return kSwitch(); }
    if (v == p6('r', 'e', 't', 'u', 'r', 'n')) { return kReturn(); }
    return kIdent();
  }
  if (len == 7) {
    if (v == p7('d', 'e', 'f', 'a', 'u', 'l', 't')) { return kDefault(); }
    return kIdent();
  }
  if (v == p8('c', 'o', 'n', 't', 'i', 'n', 'u', 'e')) { return kContinue(); }
  if (v == p8('o', 'v', 'e', 'r', 'r', 'i', 'd', 'e')) { return kOverride(); }
  return kIdent();
}

// ── Lexer ─────────────────────────────────────────────────────────────────────

/**
 * Lexer state.
 *
 * Held in a struct rather than as locals because the reference's closures over
 * `pos`/`line`/`col` have no equivalent: wac has no closures, so every helper takes
 * the state explicitly.
 */
struct Lexer {
  u8[] src;
  i32 pos;
  i32 line;
  i32 col;

  i32 peek(const this, i32 offset) {
    i32 at = this.pos + offset;
    if (at >= this.src.len()) { return -1; }   // -1 rather than 0: NUL is a real byte
    return this.src[at];
  }

  /**
   * Consume one byte, keeping `line` and `col` right.
   *
   * `col` counts UTF-16 code units so positions match the reference: continuation
   * bytes (0x80..0xBF) add nothing, a 4-byte lead adds two because it becomes a
   * surrogate pair, and anything else adds one.
   */
  i32 advance(this) {
    i32 c = this.src[this.pos];
    this.pos++;
    if (c == '\n') {
      this.line++;
      this.col = 1;
    } else if (c >= 0x80 && c < 0xC0) {
      // continuation byte: part of a character already counted
    } else if (c >= 0xF0) {
      this.col += 2;
    } else {
      this.col++;
    }
    return c;
  }

  bool atEnd(const this) { return this.pos >= this.src.len(); }
}

// ── Emitting ──────────────────────────────────────────────────────────────────
//
// The output arrays are pre-sized and written by index, so these take the Lexed
// value and mutate it rather than returning a new one.

void emit(Lexed out, i32 kind, i32 start, i32 len, i32 line, i32 col) {
  i32 at = out.tokenCount * tokenStride();
  out.tokens[at] = kind;
  out.tokens[at + 1] = start;
  out.tokens[at + 2] = len;
  out.tokens[at + 3] = line;
  out.tokens[at + 4] = col;
  out.tokenCount++;
}

void fail(Lexed out, i32 code, i32 line, i32 col) {
  i32 at = out.errorCount * errorStride();
  if (at + errorStride() > out.errors.len()) { return; }   // errors are capped
  out.errors[at] = code;
  out.errors[at + 1] = line;
  out.errors[at + 2] = col;
  out.errorCount++;
}

// ── Pieces ────────────────────────────────────────────────────────────────────

void skipSpaceAndComments(Lexer lx, Lexed out) {
  while (!lx.atEnd()) {
    i32 c = lx.peek(0);
    if (isSpace(c)) {
      lx.advance();
    } else if (c == '/' && lx.peek(1) == '/') {
      while (!lx.atEnd() && lx.peek(0) != '\n') { lx.advance(); }
    } else if (c == '/' && lx.peek(1) == '*') {
      i32 startLine = lx.line;
      i32 startCol = lx.col;
      lx.advance();
      lx.advance();
      bool closed = false;
      while (!lx.atEnd() && !closed) {
        if (lx.peek(0) == '*' && lx.peek(1) == '/') {
          lx.advance();
          lx.advance();
          closed = true;
        } else {
          lx.advance();
        }
      }
      if (!closed) { fail(out, errUnterminatedComment(), startLine, startCol); }
    } else {
      return;
    }
  }
}

/**
 * A string literal. The span kept is the whole literal including both quotes, so
 * a consumer can re-scan the escapes; the reference stores the decoded value
 * instead, and the differential test decodes the span to compare.
 */
void lexString(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;
  lx.advance();                       // opening quote
  bool closed = false;
  while (!lx.atEnd() && !closed) {
    i32 c = lx.peek(0);
    if (c == '"') {
      lx.advance();
      closed = true;
    } else if (c == '\\') {
      lx.advance();
      if (lx.atEnd()) { break; }
      i32 esc = lx.advance();
      if (esc != 'n' && esc != 't' && esc != 'r' && esc != '\\'
          && esc != '"' && esc != '0' && esc != '\'') {
        fail(out, errUnknownEscape(), startLine, startCol);
      }
    } else {
      lx.advance();
    }
  }
  if (!closed) { fail(out, errUnterminatedString(), startLine, startCol); }
  emit(out, kString(), start, lx.pos - start, startLine, startCol);
}

/**
 * A character literal, emitted as an `int` whose span is the literal. The
 * reference emits the decimal codepoint as the token's text; the value is
 * recovered from the span by `tokenCodepoint`.
 */
void lexChar(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;
  lx.advance();                       // opening quote

  if (lx.atEnd()) {
    fail(out, errUnterminatedChar(), startLine, startCol);
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }
  if (lx.peek(0) == '\'') {
    lx.advance();
    fail(out, errEmptyChar(), startLine, startCol);
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }

  if (lx.peek(0) == '\\') {
    lx.advance();
    if (lx.atEnd()) {
      fail(out, errUnterminatedChar(), startLine, startCol);
      emit(out, kInt(), start, lx.pos - start, startLine, startCol);
      return;
    }
    i32 esc = lx.advance();
    if (esc != 'n' && esc != 't' && esc != 'r' && esc != '\\'
        && esc != '"' && esc != '0' && esc != '\'') {
      fail(out, errUnknownEscape(), startLine, startCol);
    }
  } else {
    // One character, however many bytes it takes.
    lx.advance();
    while (!lx.atEnd() && lx.peek(0) >= 0x80 && lx.peek(0) < 0xC0) {
      lx.advance();
    }
  }

  if (lx.atEnd()) {
    fail(out, errUnterminatedChar(), startLine, startCol);
  } else if (lx.peek(0) == '\'') {
    lx.advance();
  } else {
    // More than one character before the closing quote.
    while (!lx.atEnd() && lx.peek(0) != '\'' && lx.peek(0) != '\n') { lx.advance(); }
    if (!lx.atEnd() && lx.peek(0) == '\'') { lx.advance(); }
    fail(out, errCharTooLong(), startLine, startCol);
  }
  emit(out, kInt(), start, lx.pos - start, startLine, startCol);
}

void lexNumber(Lexer lx, Lexed out, i32 startLine, i32 startCol) {
  i32 start = lx.pos;

  if (lx.peek(0) == '0' && (lx.peek(1) == 'x' || lx.peek(1) == 'X')) {
    lx.advance();
    lx.advance();
    while (!lx.atEnd() && (isHexDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
    return;
  }

  while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }

  // A decimal point, an exponent, or both — either marks the literal a float. The reference stopped
  // requiring the point in wac issue 0018, and the differential test compares token for token, so
  // this has to move with it.
  if (lx.peek(0) == '.' && isDigit(lx.peek(1))) {
    lx.advance();
    while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
    takeExponent(lx);
    emit(out, kFloat(), start, lx.pos - start, startLine, startCol);
  } else if (takeExponent(lx)) {
    emit(out, kFloat(), start, lx.pos - start, startLine, startCol);
  } else {
    emit(out, kInt(), start, lx.pos - start, startLine, startCol);
  }
}

/**
 * Consume an exponent if one is really there, reporting whether it was.
 *
 * `1e` and `1electron` are an integer followed by an identifier, not malformed floats, so the digits
 * after `e` are what decides — checking for `e` alone would swallow the identifier.
 */
bool takeExponent(Lexer lx) {
  if (lx.peek(0) != 'e' && lx.peek(0) != 'E') { return false; }
  bool signed = lx.peek(1) == '+' || lx.peek(1) == '-';
  i32 digitAt = signed ? 2 : 1;
  if (!isDigit(lx.peek(digitAt))) { return false; }
  lx.advance();
  if (signed) { lx.advance(); }
  while (!lx.atEnd() && (isDigit(lx.peek(0)) || lx.peek(0) == '_')) { lx.advance(); }
  return true;
}

/**
 * `as`, `as!`, `as~` and `as@` — the one place an identifier can grow a suffix, so
 * it is handled where the identifier is recognised rather than with the operators.
 */
i32 identOrKeyword(Lexer lx, i32 start, i32 len) {
  i32 kind = keywordKind(lx.src, start, len);
  if (kind != kAs()) { return kind; }
  i32 c = lx.peek(0);
  if (c == '!') { lx.advance(); return kAsBang(); }
  if (c == '~') { lx.advance(); return kAsTilde(); }
  if (c == '@') { lx.advance(); return kAsAt(); }
  return kAs();
}

// ── Operators ─────────────────────────────────────────────────────────────────
//
// One function per lead byte, longest match first. Split out from the main loop
// because wac has no fallthrough and no multi-byte switch, so a single `switch`
// over the lead byte with nested prefix tests is the shape that stays readable.

/** The kind for an operator starting at the current position, consuming its bytes. */
i32 lexOperator(Lexer lx) {
  i32 c = lx.advance();

  if (c == '+') {
    if (lx.peek(0) == '+') { lx.advance(); return kInc(); }
    if (lx.peek(0) == '=') { lx.advance(); return kPlusEq(); }
    return kPlus();
  }
  if (c == '-') {
    if (lx.peek(0) == '-') { lx.advance(); return kDec(); }
    if (lx.peek(0) == '=') { lx.advance(); return kMinusEq(); }
    return kMinus();
  }
  if (c == '*') {
    if (lx.peek(0) == '=') { lx.advance(); return kStarEq(); }
    return kStar();
  }
  if (c == '/') {
    if (lx.peek(0) == '=') { lx.advance(); return kSlashEq(); }
    return kSlash();
  }
  if (c == '%') {
    if (lx.peek(0) == '=') { lx.advance(); return kPercentEq(); }
    return kPercent();
  }
  if (c == '=') {
    if (lx.peek(0) == '=') { lx.advance(); return kEq(); }
    // `=>` before `=`, and after `==`, which is the only ordering that lexes all three: `a == b`
    // must not become `=` then `>`, and `a >= b` is reached by the `>` branch below rather than here.
    if (lx.peek(0) == '>') { lx.advance(); return kFatArrow(); }
    return kAssign();
  }
  if (c == '!') {
    if (lx.peek(0) == '=') { lx.advance(); return kNe(); }
    return kBang();
  }
  if (c == '<') {
    if (lx.peek(0) == '<') {
      lx.advance();
      if (lx.peek(0) == '=') { lx.advance(); return kShlEq(); }
      return kShl();
    }
    if (lx.peek(0) == '=') { lx.advance(); return kLe(); }
    return kLt();
  }
  if (c == '>') {
    if (lx.peek(0) == '>') {
      lx.advance();
      if (lx.peek(0) == '>') {
        lx.advance();
        if (lx.peek(0) == '=') { lx.advance(); return kShrUEq(); }
        return kShrU();
      }
      if (lx.peek(0) == '=') { lx.advance(); return kShrEq(); }
      return kShr();
    }
    if (lx.peek(0) == '=') { lx.advance(); return kGe(); }
    return kGt();
  }
  if (c == '&') {
    if (lx.peek(0) == '&') { lx.advance(); return kAndAnd(); }
    if (lx.peek(0) == '=') { lx.advance(); return kAndEq(); }
    return kAnd();
  }
  if (c == '|') {
    if (lx.peek(0) == '|') { lx.advance(); return kOrOr(); }
    if (lx.peek(0) == '=') { lx.advance(); return kOrEq(); }
    return kOr();
  }
  if (c == '^') {
    if (lx.peek(0) == '=') { lx.advance(); return kCaretEq(); }
    return kCaret();
  }
  if (c == '~') { return kTilde(); }
  if (c == '(') { return kLparen(); }
  if (c == ')') { return kRparen(); }
  if (c == '{') { return kLbrace(); }
  if (c == '}') { return kRbrace(); }
  if (c == '[') { return kLbrack(); }
  if (c == ']') { return kRbrack(); }
  if (c == ';') { return kSemi(); }
  if (c == ':') { return kColon(); }
  if (c == ',') { return kComma(); }
  if (c == '.') { return kDot(); }
  if (c == '?') { return kQuestion(); }
  if (c == '@') { return kAt(); }

  return -1;   // not an operator: the caller reports it
}

// ── JSX modes ─────────────────────────────────────────────────────────────────
//
// Everything above this line reads wac the same way wherever it is in the file.
// JSX is the exception: `it's here` between two tags is nine characters of text,
// and the same bytes in wac are a character literal that swallows the closing tag.
// So the lexer has three modes and a stack to say which one it is in.
//
//   normal   wac, as always
//   tag      inside `<name …`, up to the `>` or `/>` that ends it — still wac,
//            because an attribute is a name, a string or `{expr}`
//   text     an element's children: a run of text ends at `{` or at a `<` that
//            starts a tag, and nothing inside it begins a string, a character
//            literal or a comment
//
// **A `<` in normal mode starts a tag exactly where it could not be the less-than
// operator** — where the token before it cannot end an expression. `a < b`, `f(x) < 2`
// and `Vec<i32>` all follow something that can; `return <div/>`, `f(<b/>)` and
// `x = <p/>` do not. That is why no program without JSX can lex differently than it
// did: every `<` in one of them follows an expression.
//
// The modes nest, so they are a stack rather than a variable: `<div a={f(<b/>)}>`
// is tag → normal → tag, and each level has to remember what to go back to.

i32 mNormal() { return 0; }
i32 mTag()    { return 1; }
i32 mText()   { return 2; }

/** Inside `<name …`. `num` bit 1 means it began `</`, bit 0 that a `/` has been seen. */
i32 cTag()  { return 0; }
/** Inside an element's children. */
i32 cElem() { return 1; }
/** Inside `{ … }`, with `num` counting the braces still open. */
i32 cExpr() { return 2; }

/**
 * The mode stack: `(kind, ret, num)` per entry, where `ret` is the mode to restore.
 *
 * Sized by the caller from a count of the bytes that can push one, so it cannot
 * overflow: every push consumes a distinct `<`, `{` or `>`.
 */
struct Modes {
  i32[] stk;
  i32 sp;
  i32 mode;

  void push(this, i32 kind, i32 ret, i32 num) {
    i32 at = this.sp * 3;
    if (at + 3 > this.stk.len()) { return; }
    this.stk[at] = kind;
    this.stk[at + 1] = ret;
    this.stk[at + 2] = num;
    this.sp++;
  }

  i32 topKind(const this) { return this.sp == 0 ? -1 : this.stk[(this.sp - 1) * 3]; }
  i32 topRet(const this)  { return this.sp == 0 ? mNormal() : this.stk[(this.sp - 1) * 3 + 1]; }
  i32 topNum(const this)  { return this.sp == 0 ? 0 : this.stk[(this.sp - 1) * 3 + 2]; }
  void setTopNum(this, i32 v) { if (this.sp > 0) { this.stk[(this.sp - 1) * 3 + 2] = v; } }
  void pop(this) { if (this.sp > 0) { this.sp--; } }
}

/** How many entries the stack can need: one per byte that can push one. */
i32 modeDepth(u8[] src) {
  i32 count = 0;
  for (i32 i = 0; i < src.len(); i++) {
    i32 c = src[i];
    if (c == '<' || c == '{' || c == '>') { count++; }
  }
  return count + 8;
}

/**
 * Whether a token of this kind can end an expression.
 *
 * This is the whole discriminator between `<` the operator and `<` the tag, so it is
 * written as what it means rather than as a list of the places JSX may appear: the
 * second would have to be revisited every time the grammar gains a position, and
 * this does not. `!` is here because wac's unwrap is postfix — `s! < n` compares.
 */
bool endsExpression(i32 kind) {
  return kind == kIdent() || kind == kInt() || kind == kFloat() || kind == kString()
      || kind == kRparen() || kind == kRbrack() || kind == kRbrace()
      || kind == kTrue() || kind == kFalse() || kind == kNull() || kind == kThis()
      || kind == kInc() || kind == kDec() || kind == kBang();
}

/**
 * Whether `<` at the current position opens or closes a tag rather than being text.
 *
 * `>` is here for the fragment `<>…</>`, which is a tag with no name — and it is why `<p>1 < 2</p>`
 * still works while `<p>a <> b</p>` does not: what follows the `<` is the whole of the question.
 */
bool startsTag(Lexer lx, i32 offset) {
  i32 c = lx.peek(offset);
  return c == '/' || c == '>' || isIdentStart(c);
}

/**
 * Move the mode machine, given the operator just emitted.
 *
 * Only operators move it — a string, a number or an identifier never changes which
 * language is being read — so this is called from one place.
 */
void jsxAfterOperator(Modes md, Lexer lx, i32 kind, i32 prevKind) {
  if (md.mode == mNormal()) {
    if (kind == kLt() && !endsExpression(prevKind) && startsTag(lx, 0)) {
      md.push(cTag(), mNormal(), 0);
      md.mode = mTag();
      return;
    }
    // The braces of a spliced expression, counted so the *matching* one leaves it.
    if (md.topKind() == cExpr()) {
      if (kind == kLbrace()) { md.setTopNum(md.topNum() + 1); return; }
      if (kind == kRbrace()) {
        md.setTopNum(md.topNum() - 1);
        if (md.topNum() <= 0) {
          i32 ret = md.topRet();
          md.pop();
          md.mode = ret;
        }
      }
    }
    return;
  }
  if (md.mode == mTag()) {
    if (kind == kLbrace()) { md.push(cExpr(), mTag(), 1); md.mode = mNormal(); return; }
    if (kind == kSlash()) { md.setTopNum(md.topNum() | 1); return; }
    if (kind == kGt()) {
      i32 num = md.topNum();
      i32 ret = md.topRet();
      md.pop();
      if ((num & 2) != 0) {
        // `</name>`: this element's children end, and the mode is whatever enclosed it.
        if (md.topKind() == cElem()) {
          i32 outer = md.topRet();
          md.pop();
          md.mode = outer;
        } else {
          md.mode = ret;   // a closing tag with nothing open: the parser reports it
        }
      } else if ((num & 1) != 0) {
        md.mode = ret;     // `<name/>`
      } else {
        md.push(cElem(), ret, 0);
        md.mode = mText();
      }
    }
  }
}

// ── Entry point ───────────────────────────────────────────────────────────────

/**
 * Tokenize `src`.
 *
 * Output arrays are sized from the input: at most one token per byte, and errors
 * capped at a fraction of that since a pathological input would otherwise allocate
 * a triple per byte.
 */
export Lexed lex(u8[] src) {
  i32 n = src.len();
  i32 maxErrors = n / 4 + 8;
  Lexed out = Lexed(
    i32[(n + 1) * tokenStride()](), 0,
    i32[maxErrors * errorStride()](), 0
  );
  Lexer lx = Lexer(src, 0, 1, 1);
  Modes md = Modes(i32[modeDepth(src) * 3](), 0, mNormal());

  while (true) {
    // **Text first, and no whitespace skipping**: in an element's children a space is
    // content, and `//` is two characters of a URL rather than a comment.
    if (md.mode == mText()) {
      if (lx.atEnd()) { break; }
      i32 textLine = lx.line;
      i32 textCol = lx.col;
      i32 textStart = lx.pos;
      i32 c0 = lx.peek(0);
      if (c0 == '{') {
        lx.advance();
        emit(out, kLbrace(), textStart, 1, textLine, textCol);
        md.push(cExpr(), mText(), 1);
        md.mode = mNormal();
        continue;
      }
      if (c0 == '<' && startsTag(lx, 1)) {
        bool closing = lx.peek(1) == '/';
        lx.advance();
        emit(out, kLt(), textStart, 1, textLine, textCol);
        md.push(cTag(), mText(), closing ? 2 : 0);
        md.mode = mTag();
        continue;
      }
      // A run. It ends at `{` or at a `<` that starts a tag — so `1 < 2` between tags
      // is text, which is the one place this is kinder than the JSX it copies.
      while (!lx.atEnd()) {
        i32 c = lx.peek(0);
        if (c == '{') { break; }
        if (c == '<' && startsTag(lx, 1)) { break; }
        lx.advance();
      }
      emit(out, kJsxText(), textStart, lx.pos - textStart, textLine, textCol);
      continue;
    }

    skipSpaceAndComments(lx, out);
    if (lx.atEnd()) { break; }

    i32 startLine = lx.line;
    i32 startCol = lx.col;
    i32 c = lx.peek(0);

    if (c == '"') {
      lexString(lx, out, startLine, startCol);
    } else if (c == '\'') {
      lexChar(lx, out, startLine, startCol);
    } else if (isDigit(c)) {
      lexNumber(lx, out, startLine, startCol);
    } else if (isIdentStart(c)) {
      i32 start = lx.pos;
      while (!lx.atEnd() && isIdentPart(lx.peek(0))) { lx.advance(); }
      i32 len = lx.pos - start;
      i32 kind = identOrKeyword(lx, start, len);
      // The cast suffixes lengthen the span, so it is measured after.
      emit(out, kind, start, lx.pos - start, startLine, startCol);
    } else {
      i32 start = lx.pos;
      // Read before emitting: what the token *before* this one was is what says whether
      // a `<` is an operator.
      i32 prevKind = out.tokenCount == 0
        ? -1
        : out.tokens[(out.tokenCount - 1) * tokenStride()];
      i32 kind = lexOperator(lx);
      if (kind < 0) {
        fail(out, errUnexpectedChar(), startLine, startCol);
      } else {
        emit(out, kind, start, lx.pos - start, startLine, startCol);
        jsxAfterOperator(md, lx, kind, prevKind);
      }
    }
  }

  emit(out, kEof(), n, 0, lx.line, lx.col);
  return out;
}

// ── Flat accessors for the host ───────────────────────────────────────────────
//
// bindgen cannot marshal a struct, so the host gets the arrays directly. Trimmed to
// the used length, since `lex` over-allocates from the source size.

export i32[] lexTokens(u8[] src) {
  Lexed r = lex(src);
  i32 n = r.tokenCount * tokenStride();
  i32[] out = i32[n]();
  for (i32 i = 0; i < n; i++) {
    out[i] = r.tokens[i];
  }
  return out;
}

export i32[] lexErrors(u8[] src) {
  Lexed r = lex(src);
  i32 n = r.errorCount * errorStride();
  i32[] out = i32[n]();
  for (i32 i = 0; i < n; i++) {
    out[i] = r.errors[i];
  }
  return out;
}
// ── What a literal denotes, in one place ─────────────────────────────────────
//
// The emitter needs a float literal's value to write a constant, and the checker needs it to decide
// whether the constant fits. When each read the text itself they disagreed — `f32 x = 1_0e38;` is
// out of range and the checker's reader stopped at the underscore, saw `1`, and let it through.
//
// The reference learned this first: `compiler/wacFloatLit.ts` exists because its emitter, checker
// and constant evaluator each called `parseFloat` and `parseFloat("1_000.5")` is `1` — its issue
// 0044. It can then delegate to a host that converts correctly; there is no such host here, so the
// conversion is written out below, and the reason for one copy is the same either way.

//
// `spec/spec/types.md` says a literal rounds to *nearest*, and nearest is not something floating
// point can be asked for while it is doing the asking: scaling a mantissa by ten repeatedly rounds
// at every step, and `1e300` came out a unit in the last place away. So the value is computed
// exactly — as one integer over another — and rounded once, at the end, where the answer is decided.
//
// The integers are base-2^16 limbs in an `i32[]`, which keeps every product inside an `i32` and
// makes the whole of this ordinary arithmetic. `10^350` is seventy-three limbs; a literal with eight
// hundred digits is under two hundred. Nothing here allocates per digit.

/** How many limbs a big integer is using — its length with the leading zeros dropped. */
i32 bigLen(i32[] a, i32 n) {
  i32 k = n;
  while (k > 0 && a[k - 1] == 0) { k = k - 1; }
  return k;
}

/** Its width in bits, which is what the alignment below is really asking about. */
i32 bigBits(i32[] a, i32 n) {
  i32 k = bigLen(a, n);
  if (k == 0) { return 0; }
  i32 top = a[k - 1];
  i32 bits = 0;
  while (top > 0) {
    bits = bits + 1;
    top = top >> 1;
  }
  return (k - 1) * 16 + bits;
}

/** `a = a * m + add`, with `m` and `add` small enough that a limb's product stays in an `i32`. */
i32 bigMulSmall(i32[] a, i32 n, i32 m, i32 add) {
  i32 carry = add;
  for (i32 i = 0; i < n; i++) {
    i32 cur = a[i] * m + carry;
    a[i] = cur & 65535;
    carry = cur >> 16;
  }
  i32 k = n;
  while (carry > 0) {
    if (k >= a.len()) { return k; }
    a[k] = carry & 65535;
    carry = carry >> 16;
    k = k + 1;
  }
  return k;
}

/** `a = a << k`, which is how the two sides are aligned before the division. */
i32 bigShl(i32[] a, i32 n, i32 k) {
  if (k == 0) { return n; }
  i32 limbs = k / 16;
  i32 bits = k % 16;
  i32 len = n + limbs + 1;
  if (len > a.len()) { len = a.len(); }
  for (i32 i = len - 1; i >= 0; i--) {
    i32 lo = i - limbs;
    i32 hi = lo - 1;
    i32 v = 0;
    if (lo >= 0 && lo < n) { v = (a[lo] << bits) & 65535; }
    if (bits > 0 && hi >= 0 && hi < n) { v = v | (a[hi] >> (16 - bits)); }
    a[i] = v;
  }
  return len;
}

/** -1, 0 or 1, comparing two big integers by magnitude. */
i32 bigCmp(i32[] a, i32 na, i32[] b, i32 nb) {
  i32 ka = bigLen(a, na);
  i32 kb = bigLen(b, nb);
  if (ka != kb) { return ka < kb ? 0 - 1 : 1; }
  for (i32 i = ka - 1; i >= 0; i--) {
    if (a[i] != b[i]) { return a[i] < b[i] ? 0 - 1 : 1; }
  }
  return 0;
}

/** `a = a - b`, where `a >= b`. */
void bigSub(i32[] a, i32 na, i32[] b, i32 nb) {
  i32 borrow = 0;
  for (i32 i = 0; i < na; i++) {
    i32 sub = borrow;
    if (i < nb) { sub = sub + b[i]; }
    i32 cur = a[i] - sub;
    if (cur < 0) {
      cur = cur + 65536;
      borrow = 1;
    } else {
      borrow = 0;
    }
    a[i] = cur;
  }
}

/**
 * The `f64` nearest to `digits × 10^exp10`, with ties to even — the bits, rather than the number.
 *
 * Assembling the pattern rather than computing the value is the point: every step above is integer
 * arithmetic, and the one rounding that happens is the one the specification names.
 */
f64 decimalToF64(u8[] digits, i32 count, i32 exp10) {
  i32[] num = i32[400]();
  i32[] den = i32[400]();
  num[0] = 0;
  den[0] = 1;
  i32 nn = 1;
  i32 dn = 1;
  bool any = false;
  for (i32 i = 0; i < count; i++) {
    nn = bigMulSmall(num, nn, 10, digits[i] - 48);
    if (digits[i] != 48) { any = true; }
  }
  if (!any) { return 0.0; }

  // `digits × 10^e` is one side or the other, exactly: a positive exponent multiplies the numerator
  // and a negative one the denominator, and neither is ever approximated.
  i32 e = exp10;
  while (e > 0) {
    nn = bigMulSmall(num, nn, 10, 0);
    e = e - 1;
  }
  while (e < 0) {
    dn = bigMulSmall(den, dn, 10, 0);
    e = e + 1;
  }

  // **Align so the quotient is in [1, 2), then take fifty-three of its bits.** The loop below
  // produces one bit per turn from the top, which is only the quotient's binary expansion while the
  // ratio starts in that interval — aligning it into [2^52, 2^53) instead makes the first turn
  // subtract the whole of the leading bit and every turn after it produce a zero. Every answer came
  // out an exact power of two, which is what that looks like from outside.
  i32 exp2 = 0;
  i32 diff = bigBits(num, nn) - bigBits(den, dn);
  if (diff > 0) {
    dn = bigShl(den, dn, diff);
    exp2 = exp2 + diff;
  }
  if (diff < 0) {
    nn = bigShl(num, nn, 0 - diff);
    exp2 = exp2 + diff;
  }
  if (bigCmp(num, nn, den, dn) < 0) {
    nn = bigShl(num, nn, 1);
    exp2 = exp2 - 1;
  }

  // **A subnormal is taken to a fixed place rather than to a fixed width.** Its last bit weighs
  // 2^-1074 whatever its leading bit is, so the count of bits shrinks as the exponent falls.
  i32 want = 53;
  if (exp2 < 0 - 1022) { want = exp2 + 1075; }
  if (want < 0) { want = 0; }

  i64 q = 0;
  for (i32 b = 0; b < want; b++) {
    q = q * 2;
    if (bigCmp(num, nn, den, dn) >= 0) {
      bigSub(num, nn, den, dn);
      q = q + 1;
    }
    nn = bigShl(num, nn, 1);
  }
  // One more bit decides the rounding and whatever is left over decides a tie — half to even.
  i32 roundBit = 0;
  if (bigCmp(num, nn, den, dn) >= 0) {
    bigSub(num, nn, den, dn);
    roundBit = 1;
  }
  bool sticky = bigLen(num, nn) > 0;
  if (roundBit == 1 && (sticky || (q & 1) == 1)) { q = q + 1; }

  if (want < 53) {
    // The subnormal pattern *is* the integer: a mantissa of 2^52 with a zero exponent field is
    // read as the smallest normal, which is exactly what rounding up to it should produce.
    return f64.fromBits(q as@ u64);
  }
  // A carry out of the mantissa is a larger exponent, not a wider mantissa.
  // Two to the fifty-third is one past the top of the mantissa: rounding that far is a carry.
  if (q >= 9007199254740992) {
    q = q / 2;
    exp2 = exp2 + 1;
  }
  i64 biased = (exp2 + 1023) as i64;
  if (biased >= 2047) { return f64.fromBits(9218868437227405312 as@ u64); }
  if (biased <= 0) { return 0.0; }
  // The implicit bit is two to the **fifty-second**, not the fifty-third. Taking the larger one
  // away made the mantissa negative, which borrows from the exponent — so every answer came out
  // exactly half of itself, which is a wrong number that looks like a rounding bug.
  return f64.fromBits((biased * 4503599627370496 + (q - 4503599627370496)) as@ u64);
}

/**
 * A float literal's value, exactly.
 *
 * The text is split into its digits and a decimal exponent, and the arithmetic is left to
 * `decimalToF64`, which does it in integers. Underscores are separators wherever they appear —
 * `1_000.5` read as `1` before anyone looked, which is the third literal spelling to be silently
 * wrong here after `0xff` and `' '`.
 */
export f64 floatLit(string s) {
  u8[] a = s.toBytes();
  u8[] digits = u8[a.len() + 1]();
  i32 count = 0;
  i32 frac = 0;
  i32 i = 0;
  while (i < a.len()) {
    i32 c = a[i];
    if (c == 95) {
      i = i + 1;
      continue;
    }
    if (c < 48 || c > 57) { break; }
    digits[count] = c;
    count = count + 1;
    i = i + 1;
  }
  if (i < a.len() && a[i] == 46) {
    i = i + 1;
    while (i < a.len()) {
      i32 c2 = a[i];
      if (c2 == 95) {
        i = i + 1;
        continue;
      }
      if (c2 < 48 || c2 > 57) { break; }
      digits[count] = c2;
      count = count + 1;
      frac = frac + 1;
      i = i + 1;
    }
  }
  i32 exp = 0;
  bool neg = false;
  if (i < a.len() && (a[i] == 101 || a[i] == 69)) {
    i = i + 1;
    if (i < a.len() && (a[i] == 43 || a[i] == 45)) {
      neg = a[i] == 45;
      i = i + 1;
    }
    while (i < a.len()) {
      i32 c3 = a[i];
      if (c3 == 95) {
        i = i + 1;
        continue;
      }
      if (c3 < 48 || c3 > 57) { break; }
      exp = exp * 10 + (c3 - 48);
      i = i + 1;
    }
  }
  i32 e10 = (neg ? 0 - exp : exp) - frac;
  // Past these the answer is zero or infinity whatever the digits are, and the exact path would be
  // asked for a power of ten with three thousand digits in it.
  if (e10 > 400) { e10 = 400; }
  if (e10 < 0 - 400) { e10 = 0 - 400; }
  return decimalToF64(digits, count, e10);
}

/**
 * A decimal integer literal's value, at `i64`.
 *
 * Accumulated wide even when the target is narrow, because the literal's *text* says nothing about
 * which it is: `4294967296` in an `i64` slot is a real value and parsing into an `i32` made it zero.
 * The narrowing happens at the point the constant is written, where the target is known.
 */
/**
 * The scalar a character literal denotes: an escape, or the UTF-8 sequence spelled between quotes.
 *
 * The escapes are the ones the language writes — and `\'`, which no string literal needs and every
 * character literal of a quote does.
 */
export i64 charValue(u8[] a) {
  if (a[1] == 92) {
    i32 e = a[2];
    if (e == 110) { return 10; }    // \n
    if (e == 116) { return 9; }     // \t
    if (e == 114) { return 13; }    // \r
    if (e == 48) { return 0; }      // \0
    if (e == 92) { return 92; }
    if (e == 39) { return 39; }
    if (e == 34) { return 34; }
    return e as i64;
  }
  // Otherwise a UTF-8 sequence, decoded from its lead byte exactly as `str_idx` decodes one.
  i32 b0 = a[1];
  if (b0 < 128) { return b0 as i64; }
  if (b0 < 224 && a.len() >= 4) {
    return (((b0 & 31) * 64) + (a[2] & 63)) as i64;
  }
  if (b0 < 240 && a.len() >= 5) {
    return (((b0 & 15) * 4096) + ((a[2] & 63) * 64) + (a[3] & 63)) as i64;
  }
  if (a.len() >= 6) {
    return (((b0 & 7) * 262144) + ((a[2] & 63) * 4096) + ((a[3] & 63) * 64) + (a[4] & 63)) as i64;
  }
  return 0;
}

/**
 * The value of an integer literal's text — decimal, hex, separators, and a character literal.
 *
 * Moved here from the emitter so the *checker* can ask too: whether `4294967296` fits an `i32` is a
 * question about the literal, and a second parser to answer it is a second parser to disagree with.
 */
export i64 parseInt(string s) {
  u8[] a = s.toBytes();
  i64 v = 0;
  // **A character literal is an integer literal**, and it arrives here as its own text — `'a'`,
  // quotes and all. Reading digits out of that gives 0, which is not a decline but a *wrong answer*:
  // `isSpace(c)` became `c == 0`, and the lexer this compiler is part of skipped nothing and
  // tokenised nothing. Every literal in the sweep was a number, again, which is the third time that
  // sentence has been written here.
  if (a.len() >= 3 && a[0] == 39) { return charValue(a); }
  // **Hex and separators.** Reading decimal digits and stopping at anything else made `0xff` into 0
  // and `1_000` into 1 — a *wrong answer* rather than a decline, which is the failure mode this rung
  // exists to catch and which no differential case had, because every literal in them was plain.
  if (a.len() > 2 && a[0] == 48 && (a[1] == 120 || a[1] == 88)) {
    for (i32 i = 2; i < a.len(); i++) {
      i32 c = a[i];
      if (c == 95) { continue; }
      i32 d = -1;
      if (c >= 48 && c <= 57) { d = c - 48; }
      if (c >= 97 && c <= 102) { d = c - 87; }
      if (c >= 65 && c <= 70) { d = c - 55; }
      if (d < 0) { break; }
      v = v * 16 + d as i64;
    }
    return v;
  }
  for (i32 i = 0; i < a.len(); i++) {
    if (a[i] == 95) { continue; }
    if (a[i] < 48 || a[i] > 57) { break; }
    v = v * 10 + (a[i] - 48) as i64;
  }
  return v;
}
// The manifest a native host reads, written by the compiler rather than about it.
//
// `packages/platform/native.ts` derives this from wacc's metadata wire and writes the JSON — which
// is why `native/v8` can compile wac in one file but cannot yet *rebuild the file it carries*: the
// module it emits is correct and the section that makes a module self-describing is TypeScript.
// This is that half, in wac. `design/lang/0003` step 4.
//
// **Byte-identical output, not merely equivalent.** The two derivations are checked against each
// other with `cmp` — `packages/wacc/test/manifest.test.ts` — and a manifest that only *parsed* the
// same would leave the rebuilt seed a different file from the built one, so the interesting question
// (is this the same artefact?) would have no cheap answer. That is why the layout below reproduces
// `JSON.stringify(m, null, 2)` exactly, down to `[]` for an empty array.
//
// **What is not here: the walk.** The manifest is a function of the two wires the compiler already
// answers with (`bindTypesLinked`, `exportSigsLinked`) and the module's own export section. Nothing
// in this file knows how a struct is bound or how callbacks are numbered; it rearranges what the
// emitter said. A second copy of *that* would be the thing that drifts.

/**
 * The `$bind$` exports a module has, in the order it exports them.
 *
 * **The module is the authority on its own spelling.** A monomorphisation binds as
 * `Vec__packages_std_src_vec$string`, and a host that rebuilt that name from the wac one would be
 * reimplementing `mangleType` by eye. The method helpers (`$bind$m_`, `$bind$sm_`) are left out
 * because the manifest names those against the struct that owns them.
 */
export string[] bindExportsOf(u8[] wasm) {
  string[] out = string[4096](fill: "");
  i32 n = 0;
  if (wasm.len() < 8) { return exactlyN(out, 0); }
  i32 at = 8;
  while (at < wasm.len()) {
    i32 id = wasm[at];
    at = at + 1;
    i32 size = ulebAt(wasm, at);
    at = at + ulebWidth(wasm, at);
    i32 end = at + size;
    if (end > wasm.len()) { return exactlyN(out, n); }
    // Section 7 is the export section: a count, then `name`, kind, index for each.
    if (id == 7) {
      i32 p = at;
      i32 count = ulebAt(wasm, p);
      p = p + ulebWidth(wasm, p);
      for (i32 i = 0; i < count; i++) {
        i32 len = ulebAt(wasm, p);
        p = p + ulebWidth(wasm, p);
        u8[] name = u8[len]();
        for (i32 k = 0; k < len; k++) { name[k] = wasm[p + k]; }
        p = p + len;
        p = p + 1;                        // the kind byte
        p = p + ulebWidth(wasm, p);       // the index
        string s = string.fromBytes(name);
        if (s.len() > 6 && s.slice(0, 6) == "$bind$" && !startsWith(s, "$bind$m_")
            && !startsWith(s, "$bind$sm_") && n < out.len()) {
          out[n] = s;
          n = n + 1;
        }
      }
    }
    at = end;
  }
  return exactlyN(out, n);
}

bool startsWith(string s, string p) {
  return s.len() >= p.len() && s.slice(0, p.len()) == p;
}

string[] exactlyN(string[] xs, i32 n) {
  string[] out = string[n](fill: "");
  for (i32 i = 0; i < n; i++) { out[i] = xs[i]; }
  return out;
}

i32 ulebAt(u8[] bytes, i32 at) {
  i32 value = 0;
  i32 shift = 0;
  i32 i = at;
  while (i < bytes.len()) {
    i32 b = bytes[i];
    value = value | ((b & 0x7f) << shift);
    i = i + 1;
    if ((b & 0x80) == 0) { return value; }
    shift = shift + 7;
    if (shift > 28) { return value; }
  }
  return value;
}

i32 ulebWidth(u8[] bytes, i32 at) {
  i32 i = at;
  while (i < bytes.len()) {
    if ((bytes[i] & 0x80) == 0) { return i - at + 1; }
    i = i + 1;
  }
  return 1;
}

/**
 * Split on `sep`, ignoring one inside brackets.
 *
 * A type can hold the separator: `Map<u8[],i32>` is one field type with a comma in it, and a plain
 * split turns `index:Map<u8[],i32>` into a field of type `Map<u8[]` and a second called `i32>`.
 */
export string[] splitTop(string text, string sep) {
  string[] out = string[countOf(text, sep) + 1](fill: "");
  i32 n = 0;
  i32 depth = 0;
  string cur = "";
  for (i32 i = 0; i < text.len(); i++) {
    string ch = text.slice(i, i + 1);
    if (ch == "<" || ch == "[" || ch == "(") { depth = depth + 1; }
    else if (ch == ">" || ch == "]" || ch == ")") { depth = depth - 1; }
    if (ch == sep && depth == 0) {
      if (n < out.len()) { out[n] = cur; n = n + 1; }
      cur = "";
      continue;
    }
    cur = cur + ch;
  }
  if (n < out.len()) { out[n] = cur; n = n + 1; }
  return exactlyN(out, n);
}

/** The cells of one tab-separated line. Plain: a tab cannot be inside a type. */
string[] cells(string line) {
  return splitOn(line, "\t");
}

/**
 * How many pieces a split will produce, counted before allocating one.
 *
 * **Sized from what fills it.** These arrays held 64 and 256, which is plenty for a line's cells and
 * nowhere near enough for the lines of a metadata wire — and an overflowing write was dropped, so a
 * struct simply had no methods and the manifest was *shorter* rather than wrong-looking. A truncated
 * list reads exactly like a short one.
 */
i32 countOf(string text, string sep) {
  i32 n = 0;
  for (i32 i = 0; i < text.len(); i++) {
    if (text.slice(i, i + 1) == sep) { n = n + 1; }
  }
  return n;
}

string[] splitOn(string text, string sep) {
  string[] out = string[countOf(text, sep) + 1](fill: "");
  i32 n = 0;
  string cur = "";
  for (i32 i = 0; i < text.len(); i++) {
    string ch = text.slice(i, i + 1);
    if (ch == sep) {
      if (n < out.len()) { out[n] = cur; n = n + 1; }
      cur = "";
      continue;
    }
    cur = cur + ch;
  }
  if (n < out.len()) { out[n] = cur; n = n + 1; }
  return exactlyN(out, n);
}

string cellAt(string[] cs, i32 i) { return i < cs.len() ? cs[i] : ""; }

/** A JSON string literal. The names here are identifiers and types, and this assumes nothing. */
string quoted(string s) {
  string out = "\"";
  for (i32 i = 0; i < s.len(); i++) {
    string ch = s.slice(i, i + 1);
    if (ch == "\"") { out = out + "\\\""; }
    else if (ch == "\\") { out = out + "\\\\"; }
    else if (ch == "\n") { out = out + "\\n"; }
    else if (ch == "\t") { out = out + "\\t"; }
    else { out = out + ch; }
  }
  return out + "\"";
}

/** `n` levels of two-space indent, which is what `JSON.stringify(m, null, 2)` writes. */
string pad(i32 n) {
  string out = "";
  for (i32 i = 0; i < n; i++) { out = out + "  "; }
  return out;
}

/** `["a", "b"]` on one line is not what `stringify` does — each element gets a line. */
string jsonStrings(string[ ] xs, i32 depth) {
  if (xs.len() == 0) { return "[]"; }
  string out = "[\n";
  for (i32 i = 0; i < xs.len(); i++) {
    out = out + pad(depth + 1) + quoted(xs[i]) + (i + 1 < xs.len() ? ",\n" : "\n");
  }
  return out + pad(depth) + "]";
}

/** A type as the manifest spells it: an empty return is `void`. */
string orVoid(string t) { return t == "" ? "void" : t; }

/**
 * The manifest for a module, given the compiler's own description of it.
 *
 * `wire` is `bindTypesLinked`, `sigs` is `exportSigsLinked`, `wasm` is the module — read for its
 * export names only. `wasmName` is the file the manifest sits beside, and `grants` is the bitmask
 * `platform.wac` uses: 1 read, 2 write, 4 net, 8 env.
 */
export string manifestOf(u8[] wasm, string wire, string sigs, string entry, string wasmName,
                         i32 grants) {
  string out = "{\n";
  out = out + pad(1) + "\"version\": 1,\n";
  out = out + pad(1) + "\"entry\": " + quoted(entry) + ",\n";
  out = out + pad(1) + "\"wasm\": " + quoted(wasmName) + ",\n";
  out = out + pad(1) + "\"grants\": {\n";
  out = out + pad(2) + "\"read\": " + ((grants & 1) != 0 ? "true" : "false") + ",\n";
  out = out + pad(2) + "\"write\": " + ((grants & 2) != 0 ? "true" : "false") + ",\n";
  out = out + pad(2) + "\"env\": " + ((grants & 8) != 0 ? "true" : "false") + ",\n";
  out = out + pad(2) + "\"net\": " + ((grants & 4) != 0 ? "true" : "false") + ",\n";
  out = out + pad(2) + "\"run\": " + ((grants & 16) != 0 ? "true" : "false") + "\n";
  out = out + pad(1) + "},\n";
  out = out + pad(1) + "\"callbacks\": " + callbacksJson(wire) + ",\n";
  out = out + pad(1) + "\"bind\": " + bindJson(wasm) + ",\n";
  out = out + pad(1) + "\"structs\": " + structsJson(wire) + ",\n";
  out = out + pad(1) + "\"exports\": " + exportsJson(sigs) + "\n";
  return out + "}\n";
}

/**
 * The callbacks, in the order `wac.cb<j>` is numbered.
 *
 * `slots` is 16 because both compilers write that many trampolines per signature — `callbackSlots()`
 * in `emit.wac` — and a host that registers a seventeenth dies a long way from the cause.
 */
string callbacksJson(string wire) {
  string[] lines = splitOn(wire, "\n");
  string out = "";
  i32 n = 0;
  for (i32 i = 0; i < lines.len(); i++) {
    if (!startsWith(lines[i], "C\t")) { continue; }
    string[] c = cells(lines[i]);
    string index = cellAt(c, 1);
    string params = cellAt(c, 3);
    if (n > 0) { out = out + ",\n"; }
    out = out + pad(2) + "{\n";
    out = out + pad(3) + "\"field\": " + quoted("cb" + index) + ",\n";
    out = out + pad(3) + "\"helper\": " + quoted("$bind$fnref_" + index) + ",\n";
    out = out + pad(3) + "\"type\": " + quoted(cellAt(c, 4)) + ",\n";
    out = out + pad(3) + "\"params\": " + jsonStrings(params == "" ? string[0](fill: "")
                                                     : splitTop(params, ","), 3) + ",\n";
    out = out + pad(3) + "\"ret\": " + quoted(orVoid(cellAt(c, 2))) + ",\n";
    out = out + pad(3) + "\"slots\": 16\n";
    out = out + pad(2) + "}";
    n = n + 1;
  }
  if (n == 0) { return "[]"; }
  return "[\n" + out + "\n" + pad(1) + "]";
}

/** The exports a host needs by name — the memory and the string helpers, as the module spells them. */
string bindJson(u8[] wasm) {
  string[] names = bindExportsOf(wasm);
  if (names.len() == 0) { return "{}"; }
  string out = "{\n";
  for (i32 i = 0; i < names.len(); i++) {
    string key = names[i].slice(6, names[i].len());
    out = out + pad(2) + quoted(key) + ": " + quoted(names[i])
        + (i + 1 < names.len() ? ",\n" : "\n");
  }
  return out + pad(1) + "}";
}

/**
 * The structs and enums the boundary carries, with an alias for each second spelling.
 *
 * `Pending<u8[]?>` and `Pending<u8[]>` are one wasm type — a nullable reference and a reference are
 * the same slot — so the emitter registers one and records the other as an alias. A host asks by
 * name, so each alias becomes a second entry pointing at the same bind stem, which is true rather
 * than a workaround: they are the same type reached by two names.
 */
string structsJson(string wire) {
  string[] lines = splitOn(wire, "\n");
  // Two passes rather than a growing list of structs: one to render each type, one to render the
  // aliases against the text already produced. The rendering needs the owner's methods, which arrive
  // on later lines, so the walk collects per type first.
  string[] names = string[512](fill: "");
  string[] binds = string[512](fill: "");
  string[] kinds = string[512](fill: "");
  string[] payloads = string[512](fill: "");
  i32 count = 0;
  for (i32 i = 0; i < lines.len(); i++) {
    string[] c = cells(lines[i]);
    string tag = cellAt(c, 0);
    if (tag != "S" && tag != "E") { continue; }
    if (count >= names.len()) { continue; }
    names[count] = cellAt(c, 1);
    binds[count] = cellAt(c, 2);
    kinds[count] = tag;
    payloads[count] = cellAt(c, 3);
    count = count + 1;
  }
  string out = "";
  i32 n = 0;
  for (i32 t = 0; t < count; t++) {
    if (n > 0) { out = out + ",\n"; }
    out = out + oneStruct(names[t], binds[t], kinds[t], payloads[t], lines);
    n = n + 1;
  }
  // `A <identity> <spelling>`: the same class under another name, unless that name is already a
  // class of its own.
  for (i32 i = 0; i < lines.len(); i++) {
    if (!startsWith(lines[i], "A\t")) { continue; }
    string[] c = cells(lines[i]);
    string of = cellAt(c, 1);
    string alias = cellAt(c, 2);
    bool taken = false;
    for (i32 t = 0; t < count; t++) { if (names[t] == alias) { taken = true; } }
    if (taken) { continue; }
    for (i32 t = 0; t < count; t++) {
      if (names[t] != of) { continue; }
      if (n > 0) { out = out + ",\n"; }
      out = out + oneStruct(alias, binds[t], kinds[t], payloads[t], lines);
      n = n + 1;
    }
  }
  if (n == 0) { return "[]"; }
  return "[\n" + out + "\n" + pad(1) + "]";
}

string oneStruct(string name, string bind, string kind, string payload, string[] lines) {
  string out = pad(2) + "{\n";
  out = out + pad(3) + "\"name\": " + quoted(name) + ",\n";
  out = out + pad(3) + "\"bind\": " + quoted(bind) + ",\n";
  out = out + pad(3) + "\"fields\": " + fieldsJson(kind == "S" ? payload : "", 3) + ",\n";
  out = out + pad(3) + "\"methods\": " + methodsJson(bind, lines) + ",\n";
  out = out + pad(3) + "\"variants\": " + variantsJson(kind == "E" ? payload : "", bind) + "\n";
  return out + pad(2) + "}";
}

/** `field:type,field:type` — a struct's fields in construction order. */
string fieldsJson(string payload, i32 depth) {
  if (payload == "") { return "[]"; }
  string[] fs = splitTop(payload, ",");
  string out = "[\n";
  for (i32 i = 0; i < fs.len(); i++) {
    i32 at = fs[i].indexOf(":");
    string fname = at < 0 ? fs[i] : fs[i].slice(0, at);
    string ftype = at < 0 ? "" : fs[i].slice(at + 1, fs[i].len());
    out = out + pad(depth + 1) + "{\n";
    out = out + pad(depth + 2) + "\"name\": " + quoted(fname) + ",\n";
    out = out + pad(depth + 2) + "\"type\": " + quoted(ftype) + "\n";
    out = out + pad(depth + 1) + "}" + (i + 1 < fs.len() ? ",\n" : "\n");
  }
  return out + pad(depth) + "]";
}

/** `M <bind> <method> this|static <ret> <params>` — the methods of the type that owns them. */
string methodsJson(string bind, string[] lines) {
  string out = "";
  i32 n = 0;
  for (i32 i = 0; i < lines.len(); i++) {
    if (!startsWith(lines[i], "M\t")) { continue; }
    string[] c = cells(lines[i]);
    if (cellAt(c, 1) != bind) { continue; }
    bool hasThis = cellAt(c, 3) == "this";
    string params = cellAt(c, 5);
    if (n > 0) { out = out + ",\n"; }
    out = out + pad(4) + "{\n";
    out = out + pad(5) + "\"name\": " + quoted(cellAt(c, 2)) + ",\n";
    out = out + pad(5) + "\"isStatic\": " + (hasThis ? "false" : "true") + ",\n";
    out = out + pad(5) + "\"params\": " + jsonStrings(params == "" ? string[0](fill: "")
                                                     : splitTop(params, ","), 5) + ",\n";
    out = out + pad(5) + "\"ret\": " + quoted(orVoid(cellAt(c, 4))) + ",\n";
    out = out + pad(5) + "\"export\": "
        + quoted("$bind$" + (hasThis ? "m_" : "sm_") + bind + "_" + cellAt(c, 2)) + "\n";
    out = out + pad(4) + "}";
    n = n + 1;
  }
  if (n == 0) { return "[]"; }
  return "[\n" + out + "\n" + pad(3) + "]";
}

/** `Variant:field:type|field:type;Variant:` — a variant's payload, and how to build one. */
string variantsJson(string payload, string bind) {
  if (payload == "") { return "[]"; }
  string[] vs = splitTop(payload, ";");
  string out = "[\n";
  for (i32 i = 0; i < vs.len(); i++) {
    i32 at = vs[i].indexOf(":");
    string vname = at < 0 ? vs[i] : vs[i].slice(0, at);
    string rest = at < 0 ? "" : vs[i].slice(at + 1, vs[i].len());
    out = out + pad(4) + "{\n";
    out = out + pad(5) + "\"name\": " + quoted(vname) + ",\n";
    out = out + pad(5) + "\"fields\": " + variantFields(rest, 5) + ",\n";
    out = out + pad(5) + "\"make\": " + quoted("$bind$e_" + bind + "_" + vname + "_new") + "\n";
    out = out + pad(4) + "}" + (i + 1 < vs.len() ? ",\n" : "\n");
  }
  return out + pad(3) + "]";
}

/** A variant's payload is `|`-separated, because `,` is already inside a type. */
string variantFields(string rest, i32 depth) {
  if (rest == "") { return "[]"; }
  string[] fs = splitTop(rest, "|");
  string out = "[\n";
  for (i32 i = 0; i < fs.len(); i++) {
    i32 at = fs[i].indexOf(":");
    string fname = at < 0 ? fs[i] : fs[i].slice(0, at);
    string ftype = at < 0 ? "" : fs[i].slice(at + 1, fs[i].len());
    out = out + pad(depth + 1) + "{\n";
    out = out + pad(depth + 2) + "\"name\": " + quoted(fname) + ",\n";
    out = out + pad(depth + 2) + "\"type\": " + quoted(ftype) + "\n";
    out = out + pad(depth + 1) + "}" + (i + 1 < fs.len() ? ",\n" : "\n");
  }
  return out + pad(depth) + "]";
}

/** `name<TAB>ret<TAB>params` — what a host may call, the `$bind$` helpers excluded. */
string exportsJson(string sigs) {
  string[] lines = splitOn(sigs, "\n");
  string out = "";
  i32 n = 0;
  for (i32 i = 0; i < lines.len(); i++) {
    if (lines[i] == "") { continue; }
    string[] c = cells(lines[i]);
    string name = cellAt(c, 0);
    if (startsWith(name, "$bind$")) { continue; }
    string params = cellAt(c, 2);
    if (n > 0) { out = out + ",\n"; }
    out = out + pad(2) + "{\n";
    out = out + pad(3) + "\"name\": " + quoted(name) + ",\n";
    out = out + pad(3) + "\"params\": " + jsonStrings(params == "" ? string[0](fill: "")
                                                     : splitTop(params, ","), 3) + ",\n";
    out = out + pad(3) + "\"ret\": " + quoted(orVoid(cellAt(c, 1))) + "\n";
    out = out + pad(2) + "}";
    n = n + 1;
  }
  if (n == 0) { return "[]"; }
  return "[\n" + out + "\n" + pad(1) + "]";
}

/**
 * The module with its manifest **inside it**, as a custom section named `wac.manifest`.
 *
 * A module that describes itself is one artefact rather than two, which is what lets `spawn` take
 * wasm: a program handed bytes can run them without a second file it has no way to find. A custom
 * section is the format's own extension point — id 0, a name, and bytes nobody else reads.
 */
export u8[] withManifestSection(u8[] wasm, string manifest) {
  u8[] name = "wac.manifest".toBytes();
  u8[] body = manifest.toBytes();
  u8[] nameLen = uleb(name.len());
  i32 payload = nameLen.len() + name.len() + body.len();
  u8[] size = uleb(payload);
  u8[] out = u8[wasm.len() + 1 + size.len() + payload]();
  i32 at = 0;
  for (i32 i = 0; i < wasm.len(); i++) { out[at + i] = wasm[i]; }
  at = at + wasm.len();
  out[at] = 0;                                     // a custom section
  at = at + 1;
  for (i32 i = 0; i < size.len(); i++) { out[at + i] = size[i]; }
  at = at + size.len();
  for (i32 i = 0; i < nameLen.len(); i++) { out[at + i] = nameLen[i]; }
  at = at + nameLen.len();
  for (i32 i = 0; i < name.len(); i++) { out[at + i] = name[i]; }
  at = at + name.len();
  for (i32 i = 0; i < body.len(); i++) { out[at + i] = body[i]; }
  return out;
}

/** The format's own integer encoding, which is the only reason this needs any code at all. */
u8[] uleb(i32 n) {
  u8[] buf = u8[5]();
  i32 len = 0;
  i32 v = n;
  bool more = true;
  while (more) {
    i32 b = v & 0x7f;
    v = v >>> 7;
    if (v != 0) { b = b | 0x80; }
    buf[len] = b;
    len = len + 1;
    more = v != 0;
  }
  u8[] out = u8[len]();
  for (i32 i = 0; i < len; i++) { out[i] = buf[i]; }
  return out;
}
// The wac parser, in wac. Port of compiler/wacParse.ts.
//
// Recursive descent over the token array the lexer produces, building the sum-type
// AST in ast.wac. Structured as a `P` struct threaded through every function, since
// wac has no closures to capture the position the way the reference does.
//
// The reference takes positions at very specific points — a binary node's position is
// its *operator*, a ternary's is the `?`, not the start of the condition — and this
// mirrors that exactly, because the differential test compares them. Where a `pos()`
// call looks oddly placed here, it is placed where the reference places it.
//
// Scope so far: types, the whole expression precedence ladder, and lvalues.
// Statements and declarations are next; `parseExprEntry` is the tested entry point
// until then.

import { Ty, TyKind, tyPrim, tyNamed, tyArr, tyNullable, tyFuncref,
  Expr, ExprKind, NamedArg, Lvalue, LvalueKind,
  Stmt, StmtKind, Case, Arm, JsxAttr,
  Decl, DeclKind, Param, Field, Method, Variant, ImportItem, Program, jsxTrim } from "./ast.wac";
import { tokenStride } from "./lex.wac";
import { kindName } from "./kinds.wac";
import {
  kInt, kFloat, kString, kIdent, kEof, kTrue, kFalse, kNull, kVoid, kFn, kThis,
  kIs, kNot, kAs, kAsBang, kAsTilde, kAsAt,
  kConst, kExport, kIf, kElse, kWhile, kFor, kDo, kSwitch, kCase, kDefault,
  kReturn, kBreak, kContinue, kTrap, kStruct, kEnum, kMatch, kImport,
  kOverride, kAssign,
  kPlusEq, kMinusEq, kStarEq, kSlashEq, kPercentEq,
  kAndEq, kOrEq, kCaretEq, kShlEq, kShrEq, kShrUEq,
  kPlus, kMinus, kStar, kSlash, kPercent, kEq, kNe,
  kLt, kLe, kGt, kGe, kAndAnd, kOrOr, kBang, kAnd, kOr, kCaret, kTilde,
  kShl, kShr, kShrU, kInc, kDec,
  kLparen, kRparen, kLbrace, kRbrace, kLbrack, kRbrack,
  kSemi, kColon, kComma, kDot, kQuestion, kJsxText, kFatArrow,
} from "./kinds.wac";

/** Parse errors, as (code, line, col) triples like the lexer's. */
export i32 perrExpected()    { return 20; }
export i32 perrBadType()     { return 21; }
export i32 perrBadPrimary()  { return 22; }
export i32 perrBadLvalue()   { return 23; }
export i32 perrTopLevel()    { return 24; }
export i32 perrFieldName()   { return 25; }
export i32 perrMethodName()  { return 26; }
export i32 perrCtorBrace()   { return 27; }
export i32 perrFnArray()     { return 28; }

export struct P {
  u8[] src;
  i32[] toks;      // flat quintuples from lex
  i32 tokCount;
  i32 at;          // token index
  i32[] errors;    // (code, line, col) triples
  /**
   * The operands of each error, one per triple — `expected ';', found 'i32'`.
   *
   * The parser is where most diagnostics come from: of the 604 the spec's refused programs provoke,
   * 349 are its, and every one of them used to read *expected a different token here*. `expect`
   * knows both halves of that sentence and simply had nowhere to put them.
   */
  string[] errorNotes;
  /** How wide each error's token is, so a diagnostic can underline the whole of it. */
  i32[] errorWidths;
  i32 errorCount;

  P create(u8[] src, i32[] toks, i32 tokCount) {
    return P(src, toks, tokCount, 0, i32[192](), string[64](), i32[64](), 0);
  }

  // ── Token access ────────────────────────────────────────────────────────────
  //
  // Reading past the end yields the eof token rather than trapping, which is what
  // lets every lookahead below be written without a bounds check.

  i32 idx(const this, i32 offset) {
    i32 i = this.at + offset;
    if (i >= this.tokCount) { return this.tokCount - 1; }
    return i;
  }

  i32 kindAt(const this, i32 offset) {
    return this.toks[this.idx(offset) * tokenStride()];
  }
  i32 startAt(const this, i32 offset) {
    return this.toks[this.idx(offset) * tokenStride() + 1];
  }
  i32 lenAt(const this, i32 offset) {
    return this.toks[this.idx(offset) * tokenStride() + 2];
  }
  i32 lineAt(const this, i32 offset) {
    return this.toks[this.idx(offset) * tokenStride() + 3];
  }
  i32 colAt(const this, i32 offset) {
    return this.toks[this.idx(offset) * tokenStride() + 4];
  }

  /** Absolute token index — what the AST stores. */
  i32 abs(const this, i32 offset) { return this.idx(offset); }

  bool at1(const this, i32 kind) { return this.kindAt(0) == kind; }
  bool at2(const this, i32 kind, i32 offset) { return this.kindAt(offset) == kind; }

  /** Consume the current token, returning its absolute index. */
  i32 advance(this) {
    i32 i = this.at;
    if (this.at < this.tokCount - 1) { this.at++; }
    return i;
  }

  bool eat(this, i32 kind) {
    if (this.at1(kind)) { this.advance(); return true; }
    return false;
  }

  i32 expect(this, i32 kind) {
    if (this.at1(kind)) { return this.advance(); }
    this.failWith(perrExpected(),
                  "expected '" + kindName(kind) + "', found '" + this.textAt(0) + "'");
    return this.at;
  }

  /** How wide the token at the cursor is, which is how much of the line a diagnostic underlines. */
  i32 widthAt(const this, i32 offset) {
    i32 len = this.toks[this.idx(offset) * tokenStride() + 2];
    return len > 0 ? len : 1;
  }

  /** The source text of a token near the cursor, for a diagnostic that has to quote it. */
  string textAt(const this, i32 offset) {
    i32 t = this.idx(offset);
    i32 start = this.toks[t * tokenStride() + 1];
    i32 len = this.toks[t * tokenStride() + 2];
    if (len <= 0) { return kindName(this.toks[t * tokenStride()]); }
    u8[] out = u8[len]();
    for (i32 i = 0; i < len; i++) { out[i] = this.src[start + i]; }
    return string.fromBytes(out);
  }

  /**
   * Every parse error is at a token, so every one of them can at least say which token.
   *
   * `expect` says both halves; the other thirty-odd sites know only what they were looking at, and
   * naming it is the difference between *expected an expression* and *expected an expression, found
   * `;`* — which of the two is on the line the reader is staring at.
   */
  void fail(this, i32 code) {
    this.failWith(code, "found '" + this.textAt(0) + "'");
  }

  /** The same, with the operands the parser was refusing over. */
  void failWith(this, i32 code, string note) {
    i32 slot = this.errorCount * 3;
    if (slot + 3 > this.errors.len()) { return; }
    this.errors[slot] = code;
    this.errors[slot + 1] = this.lineAt(0);
    this.errors[slot + 2] = this.colAt(0);
    if (this.errorCount < this.errorNotes.len()) { this.errorNotes[this.errorCount] = note; }
    if (this.errorCount < this.errorWidths.len()) { this.errorWidths[this.errorCount] = this.widthAt(0); }
    this.errorCount++;
  }
}

/**
 * True when the current token is a keyword.
 *
 * The kinds `kImport`..`kMatch` are the keyword block and are contiguous, so this is a
 * range test rather than a list. `kinds.wac` says every kind after a removed one moves
 * down, which keeps that true — and the differential test is what noticed last time.
 */
bool atKeyword(P p) {
  i32 k = p.kindAt(0);
  return k >= kImport() && k <= kMatch();
}

/**
 * The token of a name in a declaration, or -1, recording a diagnostic either way.
 *
 * Ported from the reference's `declName`: a keyword where a name belongs is *consumed*,
 * so that one mistake yields one error at the declaration rather than a cascade through
 * the rest of it. The consumption is the part that matters here — the diagnostics are
 * compared by position, and leaving the keyword in place would put every following error
 * somewhere else.
 */
i32 declName(P p, i32 code) {
  if (p.at1(kIdent())) { return p.advance(); }
  p.fail(code);
  if (atKeyword(p)) { return p.advance(); }
  return -1;
}

// ── Growable lists ────────────────────────────────────────────────────────────
//
// One of these per element type, because there are no generics. They are identical
// but for the type name, and this is the clearest measurement of that gap in the
// repo so far: a parser needs a list of every AST node type it collects, and there
// is no way to write the pattern once. Scratch slots are nullable so an unwritten
// slot is null rather than a default-constructed node with an invalid tag.

struct ExprList {
  Expr?[] items;
  i32 n;

  ExprList create() { return ExprList(Expr?[4](), 0); }

  void push(this, Expr e) {
